export interface ProductionPipelineOptions {
  workspaceRoot: string;
  characterVoiceProfiles?: readonly CharacterVoiceProfile[];
  worker: WorkerClient;
  screenwriterAgent?: ScreenwriterAgent;
  directorAgent?: VisualDirectorAgent;
  publishCopyWriter?: PublishCopyWriter;
  assetProviders?: VisualAssetProviderCapability[];
  providerRuntimeMetadata?: ProductionProviderRuntimeMetadata[];
  visualReviewAgent?: VisualReviewAgent;
  visualReviewAgents?: VisualReviewAgent[];
  assetSemanticRanker?: AssetSemanticRanker;
  referenceGrammarAgent?: ReferenceGrammarAgent;
  referenceVideoRoot?: string;
  /** joint-v1 创作规划的角色绑定：真实构思 agent 与其宿主 provider（如 deepseek/openai）。 */
  treatmentAgents?: Array<{ providerId: string; agent: CreativeTreatmentAgent }>;
  /** 简报的独立复核绑定：与构思同一候选合同，只审不产，裁决只作建议。 */
  briefAuditAgents?: Array<{ providerId: string; agent: BriefAuditAgent }>;
  /** 崩溃窗口注入点：图完成/正式产物登记后抛错，用于恢复语义测试；生产不得配置。 */
  /** 仅测试注入的规划崩溃窗口：真实子进程测试用硬 kill，不用 throw 代替进程死亡。 */
  planningFailpoints?: {
    afterGraph?: () => void;
    afterArtifacts?: () => void;
    /** commit 结束标记写入后、run CAS 保存前：外部 commit 只是 prepared 证据。 */
    afterCommit?: () => void;
    /** 闭包播种 checkpoint 成功后、执行记录落盘前：模型 provenance 必须随 checkpoint 存活。 */
    afterSeed?: () => void;
  };
  /** 只供隔离进程测试：时长事务的三处耐久边界。 */
  durationChangeFailpoints?: {
    afterAccepted?: () => Promise<void> | void;
    afterGraph?: () => Promise<void> | void;
    afterContinued?: () => Promise<void> | void;
    afterRunSaved?: () => Promise<void> | void;
  };
  /** 仅声音计划持久化故障测试使用；生产装配不得配置。 */
  narrationPlanFailpoints?: {
    afterAdoptionReservation?: () => Promise<void> | void;
    afterAdoptionCheckpoint?: () => Promise<void> | void;
    afterConfirmationGenerationLock?: () => Promise<void> | void;
    beforePreviewGenerationLock?: () => Promise<void> | void;
  };
  /** 仅声音本地排轨的真实独立进程崩溃测试使用；生产装配不得配置。 */
  narrationRelayoutFailpoints?: {
    afterReservation?: () => Promise<void> | void;
    afterWorkerCompletion?: () => Promise<void> | void;
    afterAdoptionCheckpoint?: () => Promise<void> | void;
  };
  /** 仅隔离持久化测试装配；生产不配置，也不触发外部请求。 */
  reviewContinuationFailpoints?: {
    afterAccepted?: () => Promise<void> | void;
    afterEvidence?: () => Promise<void> | void;
    afterDecisionCheckpoint?: () => Promise<void> | void;
    afterObservationCheckpoint?: () => Promise<void> | void;
  };
  clock?: () => string;
  idFactory?: (prefix: string) => string;
  executionLeaseHeartbeatMs?: number;
  /** 执行租约过期窗口（默认 30s）：真实进程崩溃测试据此等待真实过期，不手工删锁。 */
  executionLeaseStaleMs?: number;
}

