export class ProductionPipeline {
  private readonly runsRoot: string;
  private readonly store: FileRunStore;
  private readonly clock: () => string;
  private readonly idFactory: (prefix: string) => string;

  constructor(private readonly options: ProductionPipelineOptions) {
    this.runsRoot = path.join(options.workspaceRoot, "runs");
    this.store = new FileRunStore(this.runsRoot);
    this.clock = options.clock ?? (() => new Date().toISOString());
    this.idFactory = options.idFactory ?? ((prefix) => `${prefix}-${randomUUID()}`);
  }

  /**
   * F03/D05：与图内 validateEditedDraft 同一阶段合同（逐字同源），供命令边界在登记前
   * 校验当前稿。校验失败是"人可处理的字段问题"，不是制作失败——调用方把它转成保留
   * 停点的拒绝，而不是节点 failed。
   * CR3（2026-10-05 复审）：本次新补/改动的选择先核“本制作有效来源集合”（遵从原执行
   * 路径 director.assetProviderIds，非路由旧路径按 providers.assets 口径），再核目录
   * 存在与 acquisition 交付类型兼容。全局目录里有、本制作未选的服务不得经手动补字段
   * 进入稿件；只查改动字段，不给旧有效稿追加新硬门。
   */
  private assertTreatmentProviderSelectionsCompatible(brief: ProductionBrief, currentDocument: unknown, nextDocument: Record<string, unknown>): void {
    const changes = retrievalProviderSelectionChanges(currentDocument, nextDocument);
    if (!changes.length) return;
    const catalog = new Map((this.options.assetProviders ?? []).map((provider) => [provider.id, provider]));
    const configuredIds = new Set(brief.director?.assetProviderIds ?? [brief.providers.assets]);
    for (const change of changes) {
      if (change.to === null) continue; // 清空成缺项由上面的结构校验拒绝。
      if (!configuredIds.has(change.to)) {
        throw new HumanDecisionConflictError(
          `第 ${change.index + 1} 项选择的画面服务（${change.to}）不在本制作已配置的画面来源里；请在本次制作可选的来源中重新选择，或先在本制作的制作设置里选择该来源。已保存内容与讨论不受影响。`,
        );
      }
      const provider = catalog.get(change.to);
      const allowedDelivery = change.acquisition === "pipeline_generated"
        ? ["generated_image", "generated_video"]
        : ["stock_image", "stock_video"];
      if (!provider || !provider.deliveryTypes.some((deliveryType) => allowedDelivery.includes(deliveryType))) {
        throw new HumanDecisionConflictError(
          `第 ${change.index + 1} 项选择的画面服务（${change.to}）不在本制作可用的对应画面来源目录里，或与该素材的取得方式不匹配；请重新选择。已保存内容与讨论不受影响。`,
        );
      }
    }
  }

  private assertCreativeStageDocumentExecutable(
    brief: ProductionBrief,
    stage: "treatment" | "script" | "director",
    document: unknown,
    upstreamScript: unknown,
    purpose?: "draft",
  ): void {
    if (stage === "script") {
      const draft = (purpose === "draft" ? validateScriptDraftStructure : validateScriptDraft)(document, {
        ...durationIntentFor(brief),
        presentationMode: brief.presentationMode ?? "narration",
        requireCanonFacts: Boolean(brief.seriesContext),
      });
      if (brief.rework) reworkAffectedScenePositions({
        findings: brief.rework.findings,
        ...(brief.rework.previousScript ? {
          previousScenes: brief.rework.previousScript.scenes, previousCharacters: brief.rework.previousScript.characters,
          previousGlobalIntent: scriptReworkGlobalIntent(brief.rework.previousScript),
          currentGlobalIntent: scriptReworkGlobalIntent(draft),
        } : {}),
        ...(brief.rework.previousDirectorPlan ? { previousShots: brief.rework.previousDirectorPlan.shots } : {}),
        currentScenes: draft.scenes, currentCharacters: isCharacterScript(draft) ? draft.characters : undefined,
        ...(brief.rework.affectedScenePositions !== undefined
          ? { affectedScenePositions: brief.rework.affectedScenePositions }
          : {}),
      });
      return;
    }
    if (stage === "director") {
      const scriptDocument = (upstreamScript ?? {}) as { scenes?: unknown; viewerPromise?: unknown; characters?: unknown };
      const validate = purpose === "draft" && brief.durationPolicy === "content-led-v1" ? validateVisualDirectorDraft : validateVisualDirectorPlan;
      const plan = validate(document, visualDirectorPlanValidation(
        brief,
        parseDirectorScenes(scriptDocument),
        this.options.assetProviders ?? [],
        this.options.providerRuntimeMetadata ?? [],
        optionalOutputString(scriptDocument.viewerPromise),
      ));
      if (brief.rework) reworkAffectedScenePositions({
        findings: brief.rework.findings,
        ...(brief.rework.previousScript ? { previousScenes: brief.rework.previousScript.scenes, previousCharacters: brief.rework.previousScript.characters } : {}),
        ...(brief.rework.previousDirectorPlan ? {
          previousShots: brief.rework.previousDirectorPlan.shots,
          previousGlobalIntent: brief.rework.previousDirectorPlan.visualBible,
          currentGlobalIntent: plan.visualBible,
        } : {}),
        currentScenes: parseDirectorScenes(scriptDocument), currentCharacters: scriptDocument.characters,
        currentShots: plan.shots,
        ...(brief.rework.affectedScenePositions !== undefined
          ? { affectedScenePositions: brief.rework.affectedScenePositions }
          : {}),
      });
      return;
    }
    parseCreativeTreatment(document, treatmentSuppliedSources(brief).map((source) => source.sourceId));
  }

  async start(input: unknown): Promise<WorkflowRun<ProductionBrief>> {
    const dispatched = await this.dispatch(input);
    return dispatched.completion;
  }

  async dispatch(input: unknown, listener?: ProductionRunListener): Promise<DispatchedProductionRun> {
    const parsedBrief = parseBrief(input);
    assertProductionVisualReviewReady(parsedBrief, this.options);
    const executionBrief = normalizeUnavailableVisualReview(parsedBrief, this.options);
    const brief: ProductionBrief = {
      ...executionBrief,
      taskContractDigests: { ...REQUIRED_CODEX_TASK_CONTRACT_DIGESTS },
    };
    const registry = this.createRegistry(brief);
    const runId = this.idFactory("run");
    let created = false;
    let executionLease: ExecutionLeaseHandle | undefined;
    let resolveCreated!: () => void;
    let rejectCreated!: (error: unknown) => void;
    const firstCheckpoint = new Promise<void>((resolve, reject) => {
      resolveCreated = resolve;
      rejectCreated = reject;
    });
    const runner = new WorkflowRunner({
      providers: registry,
      clock: this.clock,
      idFactory: (prefix) => prefix === "run" ? runId : this.idFactory(prefix),
      shouldPause: () => this.consumePauseRequest(runId),
      checkpoint: async (run) => {
        const productionRun = run as WorkflowRun<ProductionBrief>;
        if (!created) {
          executionLease = await this.acquireExecutionLease(runId);
          try {
            await this.assertExecutionLease(executionLease);
            await this.store.create(run);
            created = true;
          } catch (error) {
            await this.releaseExecutionLease(executionLease);
            throw error;
          }
          await notifyListener(listener, productionRun);
          resolveCreated();
          return;
        }
        await this.assertExecutionLease(executionLease);
        await this.captureOptionalReviewDiagnostics(productionRun);
        await this.store.checkpoint(run);
        await notifyListener(listener, productionRun);
      },
    });
    const completion = runner.run(this.createWorkflow(brief), brief);
    void completion.catch((error: unknown) => {
      if (!created) {
        rejectCreated(error);
      }
    });
    await firstCheckpoint;
    const completionWithLeaseRelease = completion.then(
      async (run) => {
        if (run.status !== "paused") await rm(this.pauseRequestPath(runId), { force: true });
        await this.releaseExecutionLease(executionLease);
        return run;
      },
      async (error: unknown) => {
        await rm(this.pauseRequestPath(runId), { force: true });
        await this.releaseExecutionLease(executionLease);
        throw error;
      },
    );
    // C1：若停在报价等待且制作范围授权完全覆盖当前报价，由宿主派生子凭证自动继续；
    // 未覆盖（无授权/方案变化/超范围/余额不足）保持人工等待，不改变既有逐请求授权语义。
    const dispatched: DispatchedProductionRun = { runId, completion: completionWithLeaseRelease };
    return this.continueCoveredSpendApproval(runId, dispatched, listener);
  }

  async show(runId: string): Promise<WorkflowRun<ProductionBrief>> {
    const run = await this.store.load<ProductionBrief>(runId);
    const brief = parsePersistedBrief(run.initialInput);
    return new WorkflowRunner({ clock: this.clock, idFactory: this.idFactory })
      .hydrateLegacyVersionStates(
        this.createWorkflow(brief, { allowUnavailableProviders: true }),
        withPersistedBrief(run, brief),
        { allowVersionMismatch: true },
      );
  }

  async loadPersisted(runId: string): Promise<WorkflowRun<ProductionBrief>> {
    return this.store.load<ProductionBrief>(runId);
  }

  async list(): Promise<WorkflowRun<ProductionBrief>[]> {
    return this.store.list<ProductionBrief>();
  }

  async readPaidExecutionReceipts(runId: string): Promise<NodeExecutionReceipt[]> {
    const run = await this.store.load<ProductionBrief>(runId);
    const receipts = structuredClone(run.executionReceipts ?? []);
    const missingSpend = receipts.filter((receipt) => receipt.nodeId === "assets" && receipt.requestId
      && receipt.billing === "metered"
      && receipt.actualCostSource !== "provider_reported" && receipt.actualCostSource !== "manual_reconciled");
    if (missingSpend.length === 0) return receipts;
    const ledger = await inspectPaidAssetLedger(path.join(this.runsRoot, runId, "nodes", "assets"));
    for (const receipt of missingSpend) {
      const items = ledger.filter((item) => item.operationId === receipt.requestId
        && item.executorProviderId === receipt.providerId);
      if (items.length === 0 || paidAssetOperationNeedsManualReconciliation(items)
        || items.some((item) => item.state === "submitted" || item.state === "unknown")) continue;
      const settlement = paidAssetSettlement(items);
      if (settlement.meteredAttemptCount === 0) continue;
      // 恢复回执只含本次新增，展示须按同操作的完整已知账本累计；不回写 run 或服务商账本。
      Object.assign(receipt, settlement, { actualCostSource: "configured_rate",
        parameters: { ...receipt.parameters, paidAssetLedgerCumulative: true } });
    }
    return receipts;
  }

  async readDocumentExecutionReceipts(runId: string): Promise<DocumentExecutionReceipt[]> {
    await this.store.load(runId);
    const receipts: DocumentExecutionReceipt[] = [];
    for (const nodeId of ["reference-grammar", "publish-package"]) {
      for (const command of await new DocumentCommandStore(this.store.runDirectory(runId), nodeId).list()) {
        if (!command.prepared && !command.execution && !command.failureDetails) continue;
        const trace = command.execution?.trace;
        const count = trace?.modelAttemptCount ?? command.failureDetails?.modelAttemptCount;
        const binding = command.prepared?.brokerBinding;
        receipts.push({
          nodeId, requestId: command.prepared?.requestId ?? `document-${command.commandId}`,
          capability: "model.execute", providerId: trace?.providerId ?? command.failureDetails?.providerId ?? binding?.providerId ?? "unknown",
          providerLabel: command.action === "revise" ? "主动文字修订" : "主动文字审计",
          modelId: trace?.modelId ?? command.failureDetails?.modelId ?? binding?.modelId ?? "unknown",
          transport: "unix_socket", billing: "unverified",
          status: command.execution ? "succeeded" : command.state === "failed" ? "failed" : "unknown",
          startedAt: command.createdAt,
          ...(command.completedAt || command.execution || command.state === "failed"
            ? { finishedAt: command.completedAt ?? command.updatedAt } : {}),
          parameters: {
            accountingSource: "document_operation", billingPending: true,
            modelCallCount: count ?? 0, modelCallCountKnown: count !== undefined && !command.priorRequests?.length,
            brokerTaskCount: 1 + (command.priorRequests?.length ?? 0),
            ...(trace?.structuredRepairCount !== undefined ? { brokerStructuredRepairCount: trace.structuredRepairCount } : {}),
            ...(trace?.providerWaitMs !== undefined ? { providerWaitMs: trace.providerWaitMs } : {}),
            ...(trace?.queueWaitMs !== undefined ? { queueWaitMs: trace.queueWaitMs } : {}),
          },
        });
      }
    }
    return receipts;
  }

  async readModelExecutionFacts(runId: string): Promise<ModelExecutionProjection> {
    const run = await this.store.load(runId);
    const result: ModelExecutionProjection = { facts: [], issues: [], currentOperationIds: {} };
    for (const node of run.nodeRuns) {
      if (node.operationRequestId) result.currentOperationIds[node.nodeId] = node.operationRequestId;
      const checkpoints = await readNodeAccountingCheckpoints(this.runsRoot, runId, node.nodeId,
        (issue) => result.issues.push(`${node.nodeId}:${issue}`));
      for (const checkpoint of checkpoints) {
        const source = `checkpoint:${node.nodeId}:${String(checkpoint.storageKey ?? checkpoint.key)}`;
        const facts = projectCheckpointExecutions(node.nodeId, checkpoint, source);
        result.facts.push(...facts);
        if (!facts.length && (safeCount(isObjectRecord(checkpoint.phaseAttempts) ? checkpoint.phaseAttempts.produce : 0)
          + safeCount(isObjectRecord(checkpoint.phaseAttempts) ? checkpoint.phaseAttempts.audit : 0) > 0)) result.issues.push(`${source}:missing_request_identity`);
      }
    }
    for (const receipt of await readCreativeDiscussionExecutions(this.runsRoot, runId)) {
      result.facts.push(projectRequestExecution({ nodeId: "creative-planning", requestId: receipt.requestId,
        operationId: receipt.workflowOperationRequestId, purpose: "discussion", state: receipt.state,
        trace: receipt.trace, evidenceSource: `discussion:${receipt.commandId}` }));
    }
    for (const nodeId of ["reference-grammar", "publish-package"]) {
      try {
        for (const command of await new DocumentCommandStore(this.store.runDirectory(runId), nodeId).list()) {
          for (const prior of command.priorRequests ?? []) result.facts.push(projectRequestExecution({
            nodeId, requestId: prior.requestId, purpose: "document", state: "unknown", binding: prior,
            operationId: command.commandId, evidenceSource: `document:${command.commandId}:prior`,
          }));
          if (!command.prepared) continue;
          result.facts.push(projectRequestExecution({ nodeId, requestId: command.prepared.requestId,
            purpose: `document_${command.action}`, operationId: command.commandId,
            state: command.execution ? "completed" : command.error?.stage === "not_accepted" ? "not_accepted"
              : command.error?.stage === "completed_failure" ? "completed_failure"
                : command.error?.stage === "uncertain" ? "accepted_unknown" : "unknown",
            trace: command.execution?.trace ?? command.failureDetails, binding: command.prepared.brokerBinding,
            // createdAt是命令创建，未必模型开始；不挪用为请求墙钟起点。
            evidenceSource: `document:${command.commandId}`,
          }));
        }
      } catch { result.issues.push(`${nodeId}:document_evidence_unreadable`); }
    }
    const audioDirectory = path.join(this.store.runDirectory(runId), ".audio-review-requests");
    let audioFiles: string[] = [];
    try { audioFiles = (await readdir(audioDirectory)).filter((name) => name.endsWith(".json")
      && ![".input.json", ".recovery.json"].some((suffix) => name.endsWith(suffix))); }
    catch (error) { if (!hasCode(error, "ENOENT")) result.issues.push("audio:evidence_unreadable"); }
    for (const name of audioFiles) {
      try {
        const value: unknown = JSON.parse(await readFile(path.join(audioDirectory, name), "utf8"));
        if (!isObjectRecord(value) || typeof value.requestId !== "string") throw new Error("Invalid audio evidence.");
        const completed = value.version === "video-factory/audio-review-result-v1";
        const failure = value.version === "video-factory/audio-review-failure-v1";
        if (name !== `${value.requestId}${completed ? ".result" : failure ? ".failure" : ""}.json`) throw new Error("Audio identity mismatch.");
        result.facts.push(projectRequestExecution({ nodeId: "visual-review", requestId: value.requestId,
          purpose: "audio", evidenceSource: `audio:${name}`, trace: value.trace ?? value.failureDetails,
          binding: completed || failure ? { providerId: value.modelId, modelId: value.modelId } : value.brokerBinding,
          state: value.requestState === "not_accepted" ? "not_accepted" : value.requestState === "settled" ? "completed_failure"
            : completed ? "completed" : isObjectRecord(value.failureDetails) && value.failureDetails.accepted === true
              || ["accepted", "running", "accepted_unknown"].includes(String(value.taskFact)) ? "accepted_unknown" : "unknown",
        }));
      } catch { result.issues.push(`audio:${name}:invalid_evidence`); }
    }
    result.facts = mergeModelExecutionFacts(result.facts);
    return result;
  }

  async readTextExecutionUsage(runId: string): Promise<Array<{
    nodeId: string; providerId: string; modelId: string; modelCallCount: number;
  }>> {
    const run = await this.store.load(runId);
    const usage = [];
    // 复核也发生在参考分析、选片、审片与发布等节点；按实际节点读取既有证据，
    // 不能只统计创作规划，或为了补展示而回写历史回执。
    for (const nodeId of new Set(run.nodeRuns.map((node) => node.nodeId))) {
      const checkpoints = await readNodeAccountingCheckpoints(this.runsRoot, runId, nodeId);
      const discussions = nodeId === "creative-planning" ? await readCreativeDiscussionExecutions(this.runsRoot, runId) : [];
      const summary = summarizePlanningCheckpoints(checkpoints, discussions);
      if (!summary?.modelCallCount) continue;
      const traces = checkpoints.flatMap((checkpoint) => [
        ...(Array.isArray(checkpoint.completed) ? checkpoint.completed.flatMap((item) => isObjectRecord(item) ? [item.candidateTrace, item.auditTrace] : []) : []),
        ...(isObjectRecord(checkpoint.pendingCandidate) ? [checkpoint.pendingCandidate.candidateTrace] : []),
      ]).filter(isObjectRecord);
      const providers = [...new Set(traces.flatMap((trace) => typeof trace.providerId === "string" ? [trace.providerId] : []))];
      const models = [...new Set(traces.flatMap((trace) => typeof trace.modelId === "string" ? [trace.modelId] : []))];
      usage.push({ nodeId, providerId: providers.join("、") || "unknown", modelId: models.join("、") || "unknown", modelCallCount: summary.modelCallCount });
    }
    return usage;
  }

  async remove(runId: string): Promise<void> {
    // Studio持有maintenance lease；这里只核恢复屏障，不能重复获取同一租约。
    assertNoPendingDurationChange(await this.store.load<ProductionBrief>(runId));
    await this.store.remove(runId);
  }

  async requestPause(runId: string): Promise<void> {
    const run = await this.store.load<ProductionBrief>(runId);
    assertNoPendingDurationChange(run);
    if (!["running", "awaiting_spend_approval", "approval_invalidated"].includes(run.status)) {
      throw new Error(`Run '${runId}' cannot be paused from status '${run.status}'.`);
    }
    await writeFile(this.pauseRequestPath(runId), `${JSON.stringify({ requestedAt: this.clock() })}\n`, "utf8");
    const latest = await this.store.load<ProductionBrief>(runId);
    if (!["running", "awaiting_spend_approval", "approval_invalidated"].includes(latest.status)) {
      throw new Error(`Run '${runId}' can no longer be paused.`);
    }
  }

  async clearPauseRequest(runId: string): Promise<void> {
    assertNoPendingDurationChange(await this.store.load<ProductionBrief>(runId));
    await rm(this.pauseRequestPath(runId), { force: true });
  }

  async pauseRequested(runId: string): Promise<boolean> {
    try {
      await stat(this.pauseRequestPath(runId));
      return true;
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return false;
      throw error;
    }
  }

  async withRunMaintenanceLease<T>(runIds: string[], action: () => Promise<T>): Promise<T> {
    const ids = [...new Set(runIds)].sort();
    const leases: ExecutionLeaseHandle[] = [];
    try {
      for (const runId of ids) {
        leases.push(await this.acquireExecutionLease(runId));
      }
      for (const lease of leases) await this.assertExecutionLease(lease);
      return await action();
    } finally {
      for (const lease of leases.reverse()) {
        await this.releaseExecutionLease(lease);
      }
    }
  }

  async recoverInterruptedRuns(options: { leaseStaleAfterMs?: number } = {}): Promise<number> {
    const leaseStaleAfterMs = options.leaseStaleAfterMs ?? this.options.executionLeaseStaleMs ?? DEFAULT_EXECUTION_LEASE_STALE_MS;
    const interrupted = (await this.store.list<ProductionBrief>())
      .filter((run) => run.status === "pending" || run.status === "running");
    let recovered = 0;
    for (const run of interrupted) {
      if (run.creativeReviewOperations?.some(operation => operation.durationChange && operation.status === "running")) continue;
      if (await this.hasFreshExecutionLease(run.id, leaseStaleAfterMs)) continue;
      let creativeRecoveryRequest: unknown;
      let recoveryLease: ExecutionLeaseHandle | undefined;
      try {
        recoveryLease = await this.acquireExecutionLease(run.id);
        await this.assertExecutionLease(recoveryLease);
        const current = await this.store.load<ProductionBrief>(run.id);
        // 列表扫描到取得租约之间，原执行者可能已完成并停在人工/费用确认。
        // 只恢复锁内仍在执行的状态，不能用旧快照给已完成的停点追加失败节点。
        if (current.status !== "pending" && current.status !== "running") continue;
        creativeRecoveryRequest = current.nodeRuns.some((node) => (
          node.nodeId === "creative-planning" && (node.status === "running" || node.status === "pending")
        ))
          ? [...(current.creativeReviewOperations ?? [])].reverse().find((operation) => (
              (operation.status === "running" || operation.status === "unknown")
              && isObjectRecord(operation.request)
            ))?.request
          : undefined;
        // 批准已落盘、后继尚未开始的W3不是一次未知生成；保留原受理命令供显式接续。
        if (current.status === "running" && !current.nodeRuns.some(node => node.status === "running")
          && current.reviewContinuationOperations?.some(operation => operation.status === "accepted"
            && current.decisions.some(decision => decision.commandId === operation.commandId && decision.action === "approve"))) {
          continue;
        }
        await this.store.update<ProductionBrief>(run.id, async (current) => {
          const finishedAt = this.clock();
          const runningNodeIndex = current.nodeRuns.findIndex((node) => node.status === "running");
          const pendingNodeIndex = runningNodeIndex < 0
            ? current.nodeRuns.findIndex((node) => node.status === "pending")
            : -1;
          const activeNodeIndex = runningNodeIndex >= 0 ? runningNodeIndex : pendingNodeIndex;
          const nodeRuns = current.nodeRuns.map((node) => ({ ...node }));
          if (activeNodeIndex >= 0) {
            const interruptedNode = nodeRuns[activeNodeIndex]!;
            nodeRuns[activeNodeIndex] = {
              ...interruptedNode,
              status: "failed",
              interrupted: true,
              ...(interruptedNode.spendAuthorizationId ? { outcomeUncertain: true } : {}),
              finishedAt,
              error: INTERRUPTED_RUN_ERROR,
            };
          } else {
            const completedNodeIds = new Set(nodeRuns.map((node) => node.nodeId));
            const interruptedNodeId = productionNodeIds(current.initialInput).find((nodeId) => !completedNodeIds.has(nodeId))
              ?? "publish-package";
            nodeRuns.push({
              nodeId: interruptedNodeId,
              status: "failed",
              startedAt: finishedAt,
              finishedAt,
              artifactIds: [],
              qualityGateResults: [],
              error: INTERRUPTED_RUN_ERROR,
            });
          }
          return {
            ...current,
            revision: current.revision + 1,
            status: "failed",
            finishedAt,
            nodeRuns,
          };
        });
      } catch (error) {
        if (error instanceof RunLockedError) continue;
        throw error;
      } finally {
        await this.releaseExecutionLease(recoveryLease);
      }
      recovered += 1;
      if (creativeRecoveryRequest) {
        try {
          const dispatched = await this.dispatchCreativeReviewCommand(
            run.id,
            creativeRecoveryRequest as unknown as ProductionCreativeReviewCommandDraft,
          );
          void dispatched.completion.catch(() => undefined);
        } catch {
          // 已把原 run 如实标为 interrupted/failed；恢复证据损坏或当前配置不再可用时保持
          // 可诊断失败，不构造新 commandId，也不阻断其它历史 run 的启动恢复。
        }
      }
    }
    return recovered;
  }

  private async acquireExecutionLease(runId: string, allowedDurationCommandId?: string): Promise<ExecutionLeaseHandle> {
    const leasePath = this.executionLeasePath(runId);
    await mkdir(path.dirname(leasePath), { recursive: true });
    const handle: ExecutionLeaseHandle = {
      runId,
      path: leasePath,
      token: randomUUID(),
      active: true,
    };
    const requestedHeartbeatMs = this.options.executionLeaseHeartbeatMs ?? DEFAULT_EXECUTION_LEASE_HEARTBEAT_MS;
    // stale 窗口可按 options 缩短（进程崩溃测试用真实过期恢复，不手工删锁）；生产保持默认。
    const staleMs = this.options.executionLeaseStaleMs ?? DEFAULT_EXECUTION_LEASE_STALE_MS;
    const heartbeatMs = Math.max(1_000, Math.min(requestedHeartbeatMs, staleMs / 2));
    const lockPath = this.executionLeaseLockPath(runId);
    const lockRemoval = { acquired: false, force: false };
    try {
      const release = await lockFile(handle.path, {
        realpath: false,
        lockfilePath: lockPath,
        stale: staleMs,
        update: heartbeatMs,
        retries: 0,
        fs: executionLeaseFileSystem(handle, lockPath, lockRemoval),
        onCompromised: (error) => {
          handle.failure = executionLeaseLostError(runId, error);
          handle.active = false;
        },
      });
      lockRemoval.acquired = true;
      handle.release = async (removeLock) => {
        lockRemoval.force = removeLock;
        await release();
      };
    } catch (error) {
      if (hasCode(error, "ELOCKED")) throw new RunLockedError(runId);
      throw error;
    }
    const temporary = `${handle.path}.tmp-${process.pid}-${randomUUID()}`;
    try {
      await writeFile(temporary, executionLeasePayload(handle.token), { encoding: "utf8", flag: "wx", mode: 0o600 });
      await rename(temporary, handle.path);
      await rm(temporary, { force: true });
      try { assertNoPendingDurationChange(await this.store.load(runId), allowedDurationCommandId); }
      catch (error) { if (!hasCode(error, "ENOENT")) throw error; }
      return handle;
    } catch (error) {
      const release = handle.release;
      if (release) await release(true).catch(() => undefined);
      await rm(temporary, { force: true }).catch(() => undefined);
      throw error;
    }
  }

  private async assertExecutionLease(handle: ExecutionLeaseHandle | undefined): Promise<void> {
    if (!handle) throw new Error("Execution lease was not acquired.");
    if (handle.failure) throw handle.failure;
    try {
      const current = JSON.parse(await readFile(handle.path, "utf8")) as { token?: unknown };
      if (!handle.active || current.token !== handle.token) {
        handle.failure = executionLeaseLostError(handle.runId);
        handle.active = false;
        throw handle.failure;
      }
    } catch (error) {
      if (handle.failure) throw handle.failure;
      handle.failure = executionLeaseLostError(handle.runId, error);
      handle.active = false;
      throw handle.failure;
    }
  }

  private async releaseExecutionLease(handle: ExecutionLeaseHandle | undefined): Promise<void> {
    if (!handle) return;
    handle.active = false;
    let ownsMetadata = false;
    try {
      const current = JSON.parse(await readFile(handle.path, "utf8")) as { token?: unknown };
      ownsMetadata = current.token === handle.token;
    } catch (error) {
      if (!hasCode(error, "ENOENT") && !(error instanceof SyntaxError)) throw error;
    }
    const release = handle.release;
    if (!ownsMetadata) {
      if (release) await release(false).catch((error) => {
        if (!hasCode(error, "ERELEASED")) throw error;
      });
      return;
    }
    await rm(handle.path, { force: true });
    if (release) {
      await release(true).catch((error) => {
        if (!hasCode(error, "ERELEASED")) throw error;
      });
    }
  }

  private async hasFreshExecutionLease(runId: string, staleAfterMs: number): Promise<boolean> {
    try {
      return await checkFileLock(this.executionLeasePath(runId), {
        realpath: false,
        lockfilePath: this.executionLeaseLockPath(runId),
        stale: staleAfterMs,
      });
    } catch {
      return false;
    }
  }

  private executionLeasePath(runId: string): string {
    return path.join(this.runsRoot, runId, ".execution-lease.json");
  }

  private executionLeaseLockPath(runId: string): string {
    return `${this.executionLeasePath(runId)}.lock`;
  }

  async decide(runId: string, decision: HumanDecisionDraft): Promise<WorkflowRun<ProductionBrief>> {
    const dispatched = await this.dispatchDecision(runId, decision);
    return dispatched.completion;
  }

  async dispatchDecision(
    runId: string,
    decision: HumanDecisionDraft,
    listener?: ProductionRunListener,
  ): Promise<DispatchedProductionRun> {
    return this.dispatchPersistedTransition(runId, async (previous, checkpoint) => {
      const commandId = decision.commandId?.trim();
      const requestDigest = commandId ? contentSha256({ ...decision, commandId }) : undefined;
      const replay = commandId ? previous.reviewContinuationOperations?.find(operation => operation.commandId === commandId) : undefined;
      if (replay) {
        if (replay.requestDigest !== requestDigest) throw new HumanDecisionConflictError(`Review continuation command '${commandId}' was already used with different content.`);
        if (replay.status === "applied" && previous.status !== "running") return { replay: previous };
        if (previous.decisions.some(item => item.commandId === commandId)) {
          // 决定已耐久但下一停点尚未落盘：接续本地链，不重新签字。
          if (previous.status === "running") {
            const brief = parsePersistedBrief(previous.initialInput);
            const runner = new WorkflowRunner({ providers: this.createRegistry(brief), clock: this.clock,
              idFactory: this.idFactory, checkpoint: async run => {
                const operation = run.reviewContinuationOperations!.find(item => item.commandId === commandId)!;
                const resultStop = run.nodeRuns.find(node => node.status === "needs_human" && node.intervention);
                if (run.status !== "running" && run.status !== "pending") {
                  operation.status = "applied"; operation.finishedAt ??= this.clock();
                  operation.resultRunRevision = run.revision;
                  if (resultStop?.intervention) {
                    operation.resultInterventionId = resultStop.intervention.id;
                    if (resultStop.intervention.evidenceId) operation.resultEvidenceId = resultStop.intervention.evidenceId;
                  }
                }
                await this.captureOptionalReviewDiagnostics(run as WorkflowRun<ProductionBrief>);
                await this.store.checkpoint(run);
                await notifyListener(listener, run as WorkflowRun<ProductionBrief>);
              } });
            const continued = await runner.continuePersistedDecision(this.createWorkflow(brief), withExecutableBrief(previous, brief), commandId!);
            return { replay: continued };
          }
          if (previous.status === "failed") return { replay: previous };
          replay.status = "applied";
          replay.finishedAt = this.clock();
          replay.resultRunRevision = previous.revision;
          const resultStop = previous.nodeRuns.find(node => node.status === "needs_human" && node.intervention);
          if (resultStop?.intervention) {
            replay.resultInterventionId = resultStop.intervention.id;
            if (resultStop.intervention.evidenceId) replay.resultEvidenceId = resultStop.intervention.evidenceId;
          }
          await this.store.checkpoint(previous);
          return { replay: previous };
        }
      }
      if (!Number.isSafeInteger(decision.expectedRunRevision) || decision.expectedRunRevision !== previous.revision) {
        throw new StaleRunRevisionError(runId, decision.expectedRunRevision ?? -1, previous.revision);
      }
      const brief = parsePersistedBrief(previous.initialInput);
      const activeInterventionNode = previous.nodeRuns.find(
        (node) => node.intervention?.id === decision.interventionId,
      );
      if (!activeInterventionNode || activeInterventionNode.status !== "needs_human") {
        throw new HumanDecisionConflictError(`你查看的确认点已经变化，请刷新页面后再确认。（intervention '${decision.interventionId}' is not active）`);
      }
      if (activeInterventionNode.intervention?.kind === "creative_review") {
        throw new Error(
          "Creative review cannot use the generic decision endpoint; use the stage confirmation command.",
        );
      }
      if (activeInterventionNode.nodeId === "visual-review"
        && await this.bindSettledVisualReviewGate(previous)) {
        // 旧停点缺少风险证据身份：先补齐可见停点，让用户重新确认，不替旧请求签字。
        return { ...previous, revision: previous.revision + 1, updatedAt: this.clock() };
      }
      if (decision.action === "approve" && activeInterventionNode.nodeId === "final-review"
        && isUnconfiguredVisualFirstCut(brief) && !finalReviewEvidenceId(activeInterventionNode)
        && decision.reviewEvidenceId == null) {
        // 旧首版停点没有风险快照：此动作只重新核对本地交付，绝不替用户签字。
        // 用正式重跑合同更新final-review版本/失效后代，保留全部音画与原模型操作。
        await currentInternalDeliveryEvidence(previous, brief, this.store.runDirectory(runId));
        const workflow = this.createWorkflow(brief);
        const evidenceRefresh = { ...workflow, nodes: workflow.nodes.map(node => node.id === "final-review"
          ? { ...node, mode: "automatic" as const } : node) };
        const runner = new WorkflowRunner({ providers: this.createRegistry(brief), clock: this.clock,
          idFactory: this.idFactory, checkpoint: run => checkpoint(run as WorkflowRun<ProductionBrief>) });
        // execute仍强制返回needs_human；automatic在此仅允许本地证据重新计算。
        return runner.rerunFromNode(evidenceRefresh, withExecutableBrief(previous, brief), "final-review");
      }
      if (decision.action === "approve"
        && brief.audioMode !== "native_av"
        && activeInterventionNode.nodeId === (brief.providers.visualReview ? "asset-source-review" : "assets")
        && (brief.presentationMode === "character_drama"
          || previous.artifacts.some((artifact) => artifact.kind === "narration_plan" && artifact.provenance?.providerId === "creator-narration-plan-v1"))) {
        const context = await this.narrationPlanContext(previous);
        const currentPlan = previous.artifacts.find((artifact) => artifact.kind === "narration_plan"
          && artifact.provenance?.providerId === "creator-narration-plan-v1"
          && context.parentArtifactIds.every((id) => artifact.parentArtifactIds?.includes(id)));
        if (!currentPlan) throw new HumanDecisionConflictError("旁白方案的原稿或画面已变化，请重新查看并采用连贯旁白方案，再继续配音。");
      }
      if (activeInterventionNode.intervention?.kind === "source_review_retry"
        && decision.action !== "reject"
        && decision.acceptIncomplete !== true) {
        // 试片审查还没完成：普通批准/调整都等于跳过审查；只有明确承担已知
        // incomplete 风险的动作才可沿同一恢复链继续，未知付费/来源风险仍只能停住。
        throw new HumanDecisionConflictError(
          "试片审查还没完成，不能跳过审查继续制作。请重试审查（复用已生成画面），或终止本次制作。",
        );
      }
      if (activeInterventionNode.intervention?.kind === "source_review_retry"
        && decision.acceptIncomplete === true) {
        if (activeInterventionNode.intervention.reviewStatus !== "incomplete"
          || activeInterventionNode.intervention.providerOutcomeKnown !== true
          || !activeInterventionNode.intervention.evidenceId
          || decision.action !== "approve"
          || decision.reviewEvidenceId !== activeInterventionNode.intervention.evidenceId) {
          throw new HumanDecisionConflictError("当前试片审查不是可承担风险的 incomplete 状态，只能补查或终止。");
        }
      }
      // 证据按「停点 × 证据域」显式分派，不用 ?? 链兜底：源试片停点只认源证据，
      // 消费成片审片证据的停点（视觉审片/终审/发布包）只认当前有效 rendered 证据，
      // 其余停点不因历史成片报告存在而被迫携带无关证据（EB-01）。
      const sourceReviewStop = activeInterventionNode.intervention?.kind === "source_review_decision"
        || activeInterventionNode.intervention?.kind === "source_review_retry";
      const renderedReviewStop = ["visual-review", "final-review", "publish-package"]
        .includes(activeInterventionNode.nodeId);
      const requiresRenderedDispositions = ["visual-review", "final-review"].includes(activeInterventionNode.nodeId);
      const visualDelivery = currentVisualReviewDelivery(previous);
      const effectiveVisualEvidenceId = visualReviewScopeEvidenceId(visualDelivery);
      const currentReviewEvidenceId = sourceReviewStop
        ? sourceReviewEvidenceId(activeInterventionNode)
        : renderedReviewStop && activeInterventionNode.intervention?.continuationScope === "rendered_video_optional_review"
          // F04：续看停点的当前证据就是宿主诊断身份（原请求事实仍在待核，没有报告 scope）。
          ? (typeof activeInterventionNode.intervention?.evidenceId === "string"
            ? activeInterventionNode.intervention.evidenceId : null)
          : renderedReviewStop && effectiveVisualEvidenceId !== null
            ? effectiveVisualEvidenceId
            : activeInterventionNode.nodeId === "visual-review" && incompleteVisualDeliveryProof(visualDelivery)
              ? activeInterventionNode.intervention?.evidenceId ?? null
            : activeInterventionNode.nodeId === "final-review"
              ? finalReviewEvidenceId(activeInterventionNode)
              : null;
      // 报告已存在却解析不出有效的 rendered_video 证据范围，是状态损坏：不能让 null == null 放行。
      if (renderedReviewStop && !sourceReviewStop
        && effectiveVisualEvidenceId === null
        && isObjectRecord(visualDelivery) && isObjectRecord(visualDelivery.report)) {
        throw new HumanDecisionConflictError("当前视觉审片报告缺少有效的成片证据范围，不能放行；请补查现有成片或重跑审片。");
      }
      // 源试片停点：intervention 自带的证据身份必须与当前源交付一致，防止旧页面对新试片结果放行。
      if (sourceReviewStop) {
        const declaredEvidenceId = activeInterventionNode.intervention?.evidenceId;
        if (typeof declaredEvidenceId === "string"
          && /^[a-f0-9]{64}$/.test(declaredEvidenceId)
          && declaredEvidenceId !== currentReviewEvidenceId) {
          throw new HumanDecisionConflictError("Human decision is not bound to the current review evidence.");
        }
      }
      if (decision.reviewEvidenceId !== currentReviewEvidenceId) {
        throw new HumanDecisionConflictError("Human decision is not bound to the current review evidence.");
      }
      if (decision.action === "approve" && activeInterventionNode.nodeId === "visual-review"
        && incompleteVisualDeliveryProof(visualDelivery)
        && activeInterventionNode.intervention?.continuationScope !== "rendered_video_optional_review") {
        if (decision.acceptIncomplete !== true) {
          throw new HumanDecisionConflictError("这次审片没有有效结论，请明确接受未复核风险后再进入人工终审。");
        }
        const evidence = await currentInternalDeliveryEvidence(previous, brief, this.store.runDirectory(runId));
        if (contentSha256(evidence) !== currentReviewEvidenceId) {
          throw new HumanDecisionConflictError("当前成片或审查证据已变化，请重新查看后再确认。");
        }
      }
      if (decision.action === "approve" && activeInterventionNode?.nodeId === "final-review") {
        if (activeInterventionNode.intervention?.reviewStatus === "incomplete" && decision.acceptIncomplete !== true) {
          // 机器复核无结论：放行必须显式承担未复核风险，不能把普通批准当成风险签字。
          throw new HumanDecisionConflictError("机器复核未取得有效结论；请明确接受未复核风险，或先补查/重新审查当前成片。");
        }
        await assertPersistedFinalApprovalReady(previous, brief, activeInterventionNode, this.options, this.store.runDirectory(runId));
      }
      // 成片审片和终审保留原表态；文案仍绑当前成片证据，但不重复签字。
      if (activeInterventionNode.nodeId === "publish-package") validateReviewDispositions(decision.reviewDispositions);
      if (decision.action === "approve" && requiresRenderedDispositions) {
        assertFinalReviewDispositions(visualDelivery, decision.reviewDispositions);
      }
      const optionalApproval = decision.action === "approve"
        && activeInterventionNode.intervention?.continuationScope === "rendered_video_optional_review";
      if (optionalApproval && (!commandId || decision.acceptIncomplete !== true)) {
        throw new HumanDecisionConflictError("这次人工风险确认必须携带独立操作编号，并明确接受未复核风险。");
      }
      if (optionalApproval && activeInterventionNode.nodeId === "visual-review") {
        // 宿主诊断不是永久通行证：每次采用前重核当前媒体，不能签字后才发现坏文件。
        await currentInternalDeliveryEvidence(previous, brief, this.store.runDirectory(runId));
      }
      // 客户端不能提供历史签字身份；只在当前证据与逐条表态都已校验后由宿主取快照。
      const basis = decision.action === "approve" && requiresRenderedDispositions && decision.reviewDispositions?.length
        ? reviewDecisionBasis(previous) : undefined;
      let boundDecision: HumanDecisionDraft & { reviewDispositionBasis?: string } = { ...decision };
      delete boundDecision.reviewDispositionBasis;
      if (activeInterventionNode.nodeId === "publish-package") delete boundDecision.reviewDispositions;
      if (basis) boundDecision.reviewDispositionBasis = basis;
      if (decision.action === "approve"
        && activeInterventionNode.intervention?.boundary === "node-complete"
        && (activeInterventionNode.nodeId === "publish-package" || activeInterventionNode.nodeId === "reference-grammar")) {
        const versionId = activeInterventionNode.outputState?.effectiveVersionId;
        if (!versionId || decision.contentVersionId !== versionId) {
          throw new HumanDecisionConflictError("这份文字交付的版本已经变化，请刷新并阅读当前稿后再采用。");
        }
        const output = effectiveNodeOutput(activeInterventionNode);
        const rawReview = isObjectRecord(output?.contentReview) ? output.contentReview : undefined;
        const status = rawReview?.status === "passed" || rawReview?.status === "has_suggestions"
          ? rawReview.status : "not_audited";
        const hasSuggestions = Array.isArray(rawReview?.suggestions) && rawReview.suggestions.length > 0;
        if (status === "not_audited" && decision.acceptUnauditedContent !== true) {
          throw new HumanDecisionConflictError("当前文字版本未审计；请明确选择采用本版（未审计）。");
        }
        if (hasSuggestions && decision.acceptContentSuggestions !== true) {
          throw new HumanDecisionConflictError("当前文字版本有内容建议；请明确选择保留建议仍采用。");
        }
        boundDecision = { ...boundDecision, contentVersionId: versionId, contentAuditStatus: status };
      }
      const registry = this.createRegistry(brief);
      const acceptedBase = structuredClone(previous);
      if (optionalApproval && commandId && !replay) {
        const visualProof = currentVisualReviewDelivery(previous);
        const proofArtifact = isObjectRecord(visualProof)
          ? previous.artifacts.find(artifact => artifact.id === visualProof.optionalReviewEvidenceArtifactId) : undefined;
        const proof = proofArtifact?.data as OptionalReviewContinuationEvidence | undefined;
        if (!proof) throw new HumanDecisionConflictError("这次确认缺少当前成片的宿主风险证明，请重新查看。");
        acceptedBase.reviewContinuationOperations = [...(previous.reviewContinuationOperations ?? []), {
          commandId, requestDigest: requestDigest!, actor: decision.actor,
          action: activeInterventionNode.nodeId === "final-review" ? "approve_internal_delivery" : "enter_manual_review",
          nodeId: "visual-review", target: { artifactId: proof.target.artifactId, versionId: proof.target.versionId, sha256: proof.target.sha256 },
          targetRunRevision: previous.revision, resultEvidenceId: currentReviewEvidenceId!,
          status: "accepted", acceptedAt: this.clock(),
        }];
        // 回执同revision落盘；已有执行租约排除了并发写者，不提前消耗人工确认点。
        await this.store.checkpoint(acceptedBase);
        await this.options.reviewContinuationFailpoints?.afterAccepted?.();
      }
      let decisionCheckpointObserved = false;
      const decisionCheckpoint = async (run: WorkflowRun<ProductionBrief>) => {
        const operation = commandId ? run.reviewContinuationOperations?.find(item => item.commandId === commandId) : undefined;
        if (operation && run.decisions.some(item => item.commandId === commandId)) {
          const resultStop = run.nodeRuns.find(node => node.status === "needs_human" && node.intervention);
          if (run.status !== "running" && run.status !== "pending") {
            operation.resultRunRevision = run.revision;
            if (resultStop?.intervention) {
              operation.resultInterventionId = resultStop.intervention.id;
              if (resultStop.intervention.evidenceId) operation.resultEvidenceId = resultStop.intervention.evidenceId;
            }
          }
          await checkpoint(run);
          if (!decisionCheckpointObserved) {
            decisionCheckpointObserved = true;
            await this.options.reviewContinuationFailpoints?.afterDecisionCheckpoint?.();
          }
          if (run.status !== "running" && run.status !== "pending") {
            operation.status = "applied";
            operation.finishedAt ??= this.clock();
          }
        }
        await checkpoint(run);
      };
      const runner = new WorkflowRunner({
        providers: registry,
        clock: this.clock,
        idFactory: this.idFactory,
        checkpoint: (run) => decisionCheckpoint(run as WorkflowRun<ProductionBrief>),
        shouldPause: () => this.consumePauseRequest(runId),
      });
      const definition = this.createWorkflow(brief);
      const approvingLocalRelayout = decision.action === "approve"
        && activeInterventionNode.nodeId === "voice"
        && isObjectRecord(effectiveNodeOutput(activeInterventionNode)?.relayoutAdoption);
      // 本地排轨采用会把 render 及审片后代真实标为 stale，并另建声音试听停点。
      // 用户批准时在同一正式决定事务内把这些后代转回 pending，再由 resume 继续；不能
      // 先落一次批准、再另起 revision 调 resumeStale，否则一笔命令会跨两个 CAS 版本。
      // 首次配音的普通声音停点没有 relayoutAdoption，不走这条专用恢复。
      const resumeBase = approvingLocalRelayout
        ? prepareLocalRelayoutApprovalRun(acceptedBase, definition)
        : acceptedBase;
      return runner.resume(definition, withExecutableBrief(resumeBase, brief), boundDecision);
    }, listener);
  }

  async confirmCreativeReview(
    runId: string,
    draft: ProductionCreativeReviewConfirmationDraft,
  ): Promise<WorkflowRun<ProductionBrief>> {
    const dispatched = await this.dispatchCreativeReviewCommand(runId, { ...draft, action: "confirm" });
    return dispatched.completion;
  }

  async dispatchCreativeReviewConfirmation(
    runId: string,
    draft: ProductionCreativeReviewConfirmationDraft,
    listener?: ProductionRunListener,
  ): Promise<DispatchedProductionRun> {
    return this.dispatchCreativeReviewCommand(runId, { ...draft, action: "confirm" }, listener);
  }

  async dispatchCreativeReviewCommand(
    runId: string,
    draft: ProductionCreativeReviewCommandDraft,
    listener?: ProductionRunListener,
  ): Promise<DispatchedProductionRun> {
    const normalizedActor = draft.actor.trim();
    const normalizedCommandId = draft.commandId.trim();
    const requestDigest = contentSha256({ ...draft, commandId: normalizedCommandId, actor: normalizedActor });
    return this.dispatchPersistedTransition(runId, async (previous, checkpoint, notifyPersisted) => {
      const existingOperation = previous.creativeReviewOperations?.find(
        (operation) => operation.commandId === normalizedCommandId,
      );
      if (existingOperation) {
        if (existingOperation.requestDigest !== requestDigest) {
          throw new Error(`Creative review command '${normalizedCommandId}' was already used with different content.`);
        }
        if (existingOperation.durationChange) {
          if (existingOperation.status === "completed") {
            await notifyPersisted(previous);
            return { replay: previous };
          }
          return { replay: await this.applyCreativeDurationCommand(previous, draft, requestDigest, notifyPersisted, existingOperation) };
        }
        if ((existingOperation.status !== "running" && existingOperation.status !== "unknown")
          || existingOperation.resume === undefined) {
          return { replay: previous };
        }
        const resume = parseCreativeReviewResume(existingOperation.resume);
        if (resume.commandId !== existingOperation.commandId
          || resume.stage !== existingOperation.stage
          || resume.action !== existingOperation.action) {
          throw new Error(`Creative review command '${normalizedCommandId}' has inconsistent recovery evidence.`);
        }
        if (resume.action === "audit_current") {
          const node = previous.nodeRuns.find(item => item.nodeId === "creative-planning");
          const review = isObjectRecord(node?.output) ? node.output.creativeReview as CreativeReviewState | undefined : undefined;
          const current = review?.stages[resume.stage];
          const sourceVersion = existingOperation.request?.baseDraftVersionId;
          if (review?.activeStage !== resume.stage || current?.phase !== "waiting_user"
            || review.reviewRevision !== resume.expectedReviewRevision || current.currentDraft?.sha256 !== resume.baseDraftSha256
            || typeof sourceVersion === "string" && current.currentDraft.versionId !== sourceVersion) {
            return { replay: await this.observeDetachedCreativeAudit(previous, existingOperation, checkpoint) };
          }
        }
        if (resume.action === "discuss" || resume.action === "revise") {
          const saved = await readCreativeDiscussionPrepared(this.runsRoot, runId, normalizedCommandId);
          if (saved.length === 0) {
            // 既有命令的附属记录缺失不代表从未发送；恢复入口不能重造信封。
            // 只登记本地缺证据诊断，保留原命令和有效稿的独立决定出口。
            const node = previous.nodeRuns.find(item => item.nodeId === "creative-planning");
            const output = isObjectRecord(node?.output) ? node.output : undefined;
            const review = output?.creativeReview as CreativeReviewState | undefined;
            const detail = "原讨论/修改缺少可核的请求快照，结果和费用仍待核实，不会重新发送。当前稿已保留，你仍可手动修改、采用或返回。";
            const current = review?.stages[resume.stage];
            const updateDiagnostic = review && current && creativeConsultationSourceIsCurrent(previous, resume)
              && current.continuation?.detail !== detail;
            if (existingOperation.status === "unknown" && !updateDiagnostic) return { replay: previous };
            const result = {
              ...previous, revision: previous.revision + 1,
              creativeReviewOperations: previous.creativeReviewOperations!.map(operation => operation.commandId === normalizedCommandId
                ? { ...operation, status: "unknown" as const } : operation),
              nodeRuns: previous.nodeRuns.map(item => updateDiagnostic && item === node ? {
                ...item, output: { ...output, creativeReview: {
                  ...review, stages: { ...review.stages, [resume.stage]: { ...current, continuation: {
                    status: "unknown" as const, reasonCode: "discussion_recovery_evidence_missing", detail,
                    auditOperationId: creativeDiscussionRequestId(runId, normalizedCommandId),
                    commandId: normalizedCommandId, source: "manual" as const, recordedAt: this.clock(),
                  } } },
                } },
              } : item),
            };
            await checkpoint(result);
            return result;
          }
          if (!creativeConsultationSourceIsCurrent(previous, resume, saved[0])) {
            // 已由用户处理的旧命令不再进入规划图：重放图会替换/复活当前停点甚至触发后继。
            // 此处仅观察原物理请求，把结果归原命令，当前稿/阶段/确认逐字保留。
            let execution: CodexTaskExecution<CreativeDiscussionResult> | undefined;
            let facts: CreativeConsultationFacts | undefined;
            try { execution = await observeSavedCreativeDiscussion(saved); }
            catch (error) { facts = classifyCreativeConsultationError(error); }
            await recordCreativeDiscussionExecution(this.runsRoot, runId, {
              workflowOperationRequestId: creativeDiscussionRequestId(runId, normalizedCommandId),
              commandId: normalizedCommandId, requestId: creativeDiscussionRequestId(runId, normalizedCommandId), stage: resume.stage,
              state: execution ? "completed" : discussionExecutionStateFor(facts!.fact),
              ...(execution ? { result: execution.output, ...(execution.trace ? { trace: execution.trace } : {}) } : { factReason: facts!.reason, candidates: facts!.candidates }),
            });
            if (!execution && existingOperation.status === (facts!.fact === "failed" ? "failed" : facts!.fact === "not_accepted" ? "not_accepted" : "unknown")) return { replay: previous };
            const result = { ...previous, revision: previous.revision + 1, creativeReviewOperations: previous.creativeReviewOperations!.map(operation => operation.commandId === normalizedCommandId
              ? { ...operation, status: execution ? "completed" as const : facts!.fact === "failed" ? "failed" as const : facts!.fact === "not_accepted" ? "not_accepted" as const : "unknown" as const,
                  ...(execution ? { resultDisposition: "recorded_not_applied" as const, result: execution.output, finishedAt: this.clock() } : {}) }
              : operation) };
            await checkpoint(result);
            return result;
          }
        }
        const brief = parsePersistedBrief(previous.initialInput);
        const node = previous.nodeRuns.find((candidate) => candidate.nodeId === "creative-planning");
        if (!node) throw new Error("Creative review recovery cannot find the creative-planning node.");
      const recoveryIntervention: NonNullable<NodeRun["intervention"]> = {
          id: node.intervention?.id ?? `creative-review-recovery-${normalizedCommandId}`,
          nodeId: "creative-planning",
          kind: "creative_review" as const,
          reason: "正在恢复同一条创作讨论或确认命令。",
          requiredAction: "approve" as const,
        options: ["approve", "request_changes"],
          createdAt: existingOperation.acceptedAt,
          continuation: {
            stage: resume.stage,
            reviewRevision: resume.expectedReviewRevision,
            draftSha256: resume.baseDraftSha256,
          },
        };
        const recoveryBase: WorkflowRun<ProductionBrief> = {
          ...previous,
          status: "needs_human",
          nodeRuns: previous.nodeRuns.map((candidate) => candidate.nodeId === "creative-planning"
            ? {
                ...candidate,
                status: "needs_human",
                intervention: recoveryIntervention,
                ...(candidate.output === undefined ? {} : { output: candidate.output }),
              }
            : candidate),
          interventions: [
            ...previous.interventions.filter((intervention) => intervention.nodeId !== "creative-planning"),
            recoveryIntervention,
          ],
        };
        delete recoveryBase.finishedAt;
        const runner = new WorkflowRunner({
          providers: this.createRegistry(brief),
          clock: this.clock,
          idFactory: this.idFactory,
          checkpoint: (run) => checkpoint(run as WorkflowRun<ProductionBrief>),
          shouldPause: () => this.consumePauseRequest(runId),
        });
        const result = await runner.continueWaitingNode(
          this.createWorkflow(brief, { creativeReviewResume: resume }),
          withExecutableBrief(recoveryBase, brief),
          "creative-planning",
          {
            commandId: normalizedCommandId,
            action: resume.action,
            requestDigest,
            status: "running",
            acceptedAt: existingOperation.acceptedAt,
          },
        );
        result.creativeReviewOperations = (result.creativeReviewOperations ?? []).map((operation) => (
          operation.commandId === normalizedCommandId
            ? {
                ...operation,
                status: creativeReviewOperationStatus(result, resume),
                ...creativeReviewOperationDetail(result, resume),
                finishedAt: this.clock(),
                ...((resume.action === "discuss" || resume.action === "revise") && creativeReviewOperationStatus(result, resume) === "completed"
                  ? { resultDisposition: creativeConsultationResultDisposition(result, resume) ?? "applied" }
                  : {}),
              }
            : operation
        ));
        await checkpoint(result);
        return result;
      }
      await this.syncObservedCreativeAuditHistory(previous);
      if (!Number.isSafeInteger(draft.expectedRunRevision) || draft.expectedRunRevision !== previous.revision) {
        throw new StaleRunRevisionError(runId, draft.expectedRunRevision, previous.revision);
      }
      if (!normalizedCommandId || !normalizedActor) {
        throw new Error("Creative review confirmation requires commandId and actor.");
      }
      const node = previous.nodeRuns.find((candidate) => candidate.nodeId === "creative-planning");
      const continuation = node?.intervention?.continuation;
      if (previous.status !== "needs_human"
        || node?.status !== "needs_human"
        || node.intervention?.kind !== "creative_review"
        || !continuation) {
        throw new Error(`Run '${runId}' is not waiting for a creative review confirmation.`);
      }
      if (continuation.stage !== draft.stage
        || continuation.reviewRevision !== draft.expectedReviewRevision
        || continuation.draftSha256 !== draft.baseDraftSha256) {
        throw new Error("Creative review confirmation is stale or belongs to another stage draft.");
      }
      const nodeReview = isObjectRecord(node.output) && isObjectRecord(node.output.creativeReview)
        ? node.output.creativeReview : undefined;
      const actualPurpose = draft.stage === "director"
        ? nodeReview?.directorReviewPurpose === "direction" ? "direction" : "material_plan"
        : undefined;
      if (draft.reviewPurpose !== undefined && draft.reviewPurpose !== actualPurpose) {
        throw new Error("Creative review confirmation is stale or belongs to another director decision.");
      }
      const currentStageReview = isObjectRecord(nodeReview?.stages) ? nodeReview.stages[draft.stage] : undefined;
      const currentDraft = isObjectRecord(currentStageReview) && isObjectRecord(currentStageReview.currentDraft) ? currentStageReview.currentDraft : undefined;
      if (previous.initialInput.durationPolicy === "content-led-v1"
        && (draft.action === "confirm" || draft.action === "update_duration") && !draft.baseDraftVersionId) {
        throw new HumanDecisionConflictError("采用或修改时长要求必须指明当前稿件版本，请保留输入并重新查看当前稿。");
      }
      if (draft.baseDraftVersionId !== undefined && draft.baseDraftVersionId !== currentDraft?.versionId) {
        throw new HumanDecisionConflictError("当前稿件版本已改变，请重新查看；不会将旧输入套到新版本。");
      }
      const pendingOperations = previous.creativeReviewOperations?.filter(operation => operation.status === "running" || operation.status === "unknown") ?? [];
      for (const operation of pendingOperations) {
        if (operation.action !== "discuss" && operation.action !== "revise") continue; // 原audit规则不在此重写。
        const proof = independentCreativeConsultationActions(previous, operation);
        if (!proof || !(draft.action === "edit_draft" || draft.action === "confirm" || draft.action === "return_to_stage" || draft.action === "update_duration")) {
          throw new HumanDecisionConflictError("原讨论请求尚未核清；请查询原请求，或在有效当前稿上手动修改、采用、返回。不会重新发送模型任务。");
        }
      }
      if (draft.action === "confirm" && (draft.acknowledgeRepair === true || draft.acknowledgeIncomplete === true) && draft.expectedCheckIdentity === undefined) {
        // "仍然确认"复用他看过的那一条复核，所以命令必须自己说出是哪一条。这里曾经替他造一个
        // identity：造出来的那个必然对不上记录里的那个，绑定就退化成一个永远失败的空检查，
        // 报错还把人指向"没有独立复核"这种错误方向。
        throw new Error("确认已经看过的复核意见时必须指明那一条复核的编号。");
      }
      if (draft.action === "confirm" && (draft.acknowledgeRepair === true || draft.acknowledgeIncomplete === true)
        && recordedCreativeCheckIdentity(node, continuation.stage) !== draft.expectedCheckIdentity) {
        // 就在命令边界上证明他手上的编号就是记录里那一条。放进去让图来拒的话，形态会变成
        // "这个节点失败了"——整条制作直接 failed，而他只是拿着一个过期的页面按了按钮。
        // 图里那道同样的比对仍然保留：它守的是从 checkpoint 直接恢复的那条路。
        throw new Error("你确认的那一条独立复核意见已经不是当前这一条了，请重新查看当前的复核意见再确认。");
      }
      if (draft.action === "confirm") {
        const check = currentCreativeCheck(node, continuation.stage, continuation.draftSha256);
        if (draft.durationAmendment) {
          if (draft.acknowledgeUnaudited !== true) throw new HumanDecisionConflictError("变更时长要求后是新的未审版本，请明确同意按新要求采用当前稿。");
          if (check && draft.expectedCheckIdentity !== check.checkIdentity) throw new HumanDecisionConflictError("请确认你看到的原版本审计意见，不能复用其他复核编号。");
          if (!check && (draft.acknowledgeRepair || draft.acknowledgeIncomplete || draft.expectedCheckIdentity)) throw new HumanDecisionConflictError("原版本没有这些审计意见，请重新查看当前稿。");
          if (check?.status === "incomplete" && draft.acknowledgeIncomplete !== true) throw new HumanDecisionConflictError("原版本审计未完成，需明确承担该风险。");
          if (check && check.status !== "incomplete" && check.verdict !== "pass" && draft.acknowledgeRepair !== true) throw new HumanDecisionConflictError("原版本仍有修改建议，需明确选择保留建议仍采用。");
        } else if (draft.acknowledgeUnaudited === true) {
          if (check || draft.acknowledgeRepair || draft.acknowledgeIncomplete || draft.expectedCheckIdentity) {
            throw new HumanDecisionConflictError("本版已有审计意见，或未审采用与其他确认不兼容；请刷新后重新选择。");
          }
        } else if (!check) {
          throw new HumanDecisionConflictError("本版还没有审计结论。请先审计当前版本，或显式选择未审采用。");
        } else if (check.status === "incomplete" && draft.acknowledgeIncomplete !== true) {
          throw new HumanDecisionConflictError("本版审计未取得结论；请显式承担风险，或重新审计。");
        } else if (check.status !== "incomplete" && check.verdict !== "pass" && draft.acknowledgeRepair !== true) {
          throw new HumanDecisionConflictError("本版审计有修改建议；请先修改，或明确选择保留建议仍采用。");
        }
      }
      const brief = parsePersistedBrief(previous.initialInput);
      if (brief.workflowFeatures?.creativeReview !== "user-confirmed-v1") {
        throw new Error("This run does not use the user-confirmed creative review workflow.");
      }
      if (draft.action === "update_duration" || draft.action === "confirm" && draft.durationAmendment) {
        return { replay: await this.applyCreativeDurationCommand(previous, draft, requestDigest, notifyPersisted) };
      }
      // F03/D05（2026-10-02 执行包）：不可执行稿的确认在命令边界拒绝并保留人工停点，
      // 不让图层校验异常把节点打成 failed（那会再次丢掉工作台）。只覆盖稿自身的
      // 三阶段都在命令边界核对必需结构；目录漂移同样是可修正问题，不消耗当前停点。
      if (draft.action === "confirm") {
        const currentStage = isObjectRecord(nodeReview?.stages)
          ? (nodeReview!.stages as Record<string, unknown>)[draft.stage] : undefined;
        const stageDocument = isObjectRecord(currentStage) ? currentStage.currentDocument : undefined;
        if (stageDocument !== undefined && stageDocument !== null) {
          try {
            const stages = isObjectRecord(nodeReview?.stages) ? nodeReview.stages : undefined;
            const scriptStage = stages && isObjectRecord(stages.script) ? stages.script : undefined;
            this.assertCreativeStageDocumentExecutable(brief, draft.stage, stageDocument,
              scriptStage?.currentDocument ?? scriptDocument ?? null);
          } catch (error) {
            if (error instanceof PlanContractError && ["duration_commitment_conflict", "execution_capability_conflict"].includes(error.code)) {
              throw new HumanDecisionConflictError(`${error.message} 当前稿件和讨论已保留，尚未采用，也不会生成下游素材。`);
            }
            const message = error instanceof Error ? error.message : String(error);
            // CLOUD-11/P5.1：缺画面服务字段给结构化人话定位，不把英文 path 当主说明；
            // 原诊断仍作为技术详情保留。决策不由此驱动，只改善可读性。
            const issues = draft.stage === "treatment" ? missingRetrievalProviderIssues(stageDocument) : [];
            const humanDetail = issues.length
              ? issues.map((issue) => `第 ${issue.index + 1} 项素材安排还没选择画面服务`).join("；")
              : message;
            throw new HumanDecisionConflictError(
              `当前稿件缺必需结构，先修改再采用：${humanDetail}。当前稿件和讨论已保留，请在素材安排里补齐后保存。技术详情：${message}`,
            );
          }
        }
      }
      // 人工改稿在登记命令前先守返工范围：图内再次校验是恢复路径的防线，但若仅在那里
      // 拒绝，WorkflowRunner 会把一次越界编辑记为节点失败，用户失去原停点。
      const rawStageReview = isObjectRecord(nodeReview?.stages) ? nodeReview.stages[draft.stage] : undefined;
      const stageReview: Record<string, unknown> | undefined = isObjectRecord(rawStageReview) ? rawStageReview : undefined;
      if (draft.action === "adopt_proposal") {
        const proposal = Array.isArray(stageReview?.proposals)
          ? stageReview.proposals.find(item => isObjectRecord(item) && item.proposalId === draft.proposalId) : undefined;
        try { assertCreativeProposalBase(proposal, currentDraft, brief.durationPolicy === "content-led-v1"); }
        catch {
          throw new HumanDecisionConflictError("这份候选所依据的稿件版本已经改变或缺少版本身份，不能直接替换当前稿。候选原文仍可查看，请以当前稿为基础编辑保存。");
        }
      }
      const scopedDocument = draft.action === "edit_draft" ? draft.document
        : draft.action === "adopt_proposal" && Array.isArray(stageReview?.proposals)
          ? stageReview.proposals.find((proposal) => isObjectRecord(proposal) && proposal.proposalId === draft.proposalId)
            ?.document
          : draft.action === "undo_draft" ? stageReview?.previousDocument : undefined;
      // P5.3（2026-10-05 云端修复包）：treatment 的非法编辑（缺必需结构）同样在命令边界
      // 拒绝并保留停点——图内 validateEditedDraft 仍是恢复防线，但它抛错会把节点打成
      // failed，用户失去工作台。P5.2：本次新补/改动的 retrievalProviderId 在同一边界与
      // run 的可选画面来源核对 acquisition 兼容（deliveryTypes）；只查改动字段，不把
      // “目录现在不可用”扩成旧有效稿的新硬门。
      if (draft.action === "edit_draft" && draft.stage === "treatment" && isObjectRecord(draft.document)) {
        try {
          this.assertCreativeStageDocumentExecutable(brief, "treatment", draft.document, null);
        } catch (error) {
          const message = error instanceof Error ? error.message : String(error);
          const issues = missingRetrievalProviderIssues(draft.document);
          const humanDetail = issues.length
            ? issues.map((issue) => `第 ${issue.index + 1} 项素材安排还没选择画面服务`).join("；")
            : message;
          throw new HumanDecisionConflictError(
            `保存被拒绝：${humanDetail}。当前稿件和讨论已保留，请在素材安排里补齐后保存。技术详情：${message}`,
          );
        }
        this.assertTreatmentProviderSelectionsCompatible(brief, stageReview?.currentDocument, draft.document);
      }
      // 新角色引用同样在受理前校验：输入错误只拒绝本次保存，不能让图把主制作打成失败。
      if (draft.action === "edit_draft" && (draft.stage === "script" || draft.stage === "director")) {
        const scriptReview = isObjectRecord(nodeReview?.stages) && isObjectRecord(nodeReview.stages.script)
          ? nodeReview.stages.script : undefined;
        try {
          this.assertCreativeStageDocumentExecutable(brief, draft.stage, draft.document, scriptReview?.currentDocument ?? null, "draft");
        } catch (error) {
          throw new HumanDecisionConflictError(`保存被拒绝：${error instanceof Error ? error.message : String(error)}。当前有效稿和讨论已保留，请修正后再保存。`);
        }
      }
      if (isObjectRecord(scopedDocument) && brief.rework && (draft.stage === "script" || draft.stage === "director")) {
        const document = scopedDocument;
        const scriptStage = isObjectRecord(nodeReview?.stages) && isObjectRecord(nodeReview.stages.script) ? nodeReview.stages.script : undefined;
        const currentScript = scriptStage?.currentDocument;
        reworkAffectedScenePositions({
          findings: brief.rework.findings,
          ...(brief.rework.previousScript ? { previousScenes: brief.rework.previousScript.scenes, previousCharacters: brief.rework.previousScript.characters } : {}),
          ...(brief.rework.previousDirectorPlan ? { previousShots: brief.rework.previousDirectorPlan.shots } : {}),
          currentScenes: draft.stage === "script" ? document.scenes
            : isObjectRecord(currentScript) ? currentScript.scenes : shotsAsScenePositions(document.shots),
          currentCharacters: draft.stage === "script" ? document.characters
            : isObjectRecord(currentScript) ? currentScript.characters : undefined,
          ...(draft.stage === "script" && brief.rework.previousScript ? {
            previousGlobalIntent: scriptReworkGlobalIntent(brief.rework.previousScript),
            currentGlobalIntent: scriptReworkGlobalIntent(document),
          } : {}),
          ...(draft.stage === "director" ? {
            currentShots: document.shots,
            ...(brief.rework.previousDirectorPlan ? {
              previousGlobalIntent: brief.rework.previousDirectorPlan.visualBible,
              currentGlobalIntent: document.visualBible,
            } : {}),
          } : {}),
          ...(brief.rework.affectedScenePositions !== undefined
            ? { affectedScenePositions: brief.rework.affectedScenePositions }
            : {}),
        });
      }
      // 兼容旧版“页面恢复、图未恢复”：当前命令已过CAS/稿件/结构校验，先对齐真实停点。
      const reopenedReview = await this.reopenPreservedPlanningGeneration(previous);
      const common = {
        stage: draft.stage,
        commandId: normalizedCommandId,
        actor: normalizedActor,
        baseDraftSha256: draft.baseDraftSha256,
        expectedReviewRevision: reopenedReview?.reviewRevision ?? draft.expectedReviewRevision,
      };
      const resume: CreativeReviewResume = draft.action === "confirm"
        ? {
          action: "confirm",
          ...common,
          ...(draft.baseDraftVersionId ? { baseDraftVersionId: draft.baseDraftVersionId } : {}),
          // 人的显式承担必须跟着命令落到 resume 上：少了它，"仍然确认"就退化成再跑一轮复核，
          // 而新裁决照样是 repair 时人永远推不动这条制作。
          ...(draft.acknowledgeRepair === true ? { acknowledgeRepair: true as const } : {}),
          ...(draft.acknowledgeIncomplete === true ? { acknowledgeIncomplete: true as const } : {}),
          ...(draft.acknowledgeUnaudited === true ? { acknowledgeUnaudited: true as const } : {}),
          ...(draft.acceptQualityFallback === true ? { acceptQualityFallback: true as const } : {}),
          // 本节点确认不再触发审计；未审采用不伪造复核身份。
          // OA-03 收口：有审计的确认必须携带用户看到的那一条编号，缺失即冲突拒绝——
          // 图层不再接受任何代填的身份（此前这里会自造摘要，令 OA-03 的校验形同虚设）。
          ...(draft.acknowledgeUnaudited === true ? {} : draft.expectedCheckIdentity
            ? { checkIdentity: draft.expectedCheckIdentity }
            : (() => { throw new HumanDecisionConflictError("缺少你看到的复核编号；请刷新停点后按当前意见确认。"); })()),
          confirmedAt: this.clock(),
        }
        : draft.action === "audit_current"
          ? { action: "audit_current", ...common }
        : draft.action === "discuss" || draft.action === "revise"
          ? {
            action: draft.action,
            ...common,
            // C1：完整 versionId 随命令持久化，迟到结果隔离按“身份任一变更”判定。
            ...(typeof currentDraft?.versionId === "string" ? { baseDraftVersionId: currentDraft.versionId } : {}),
            message: draft.message,
            ...(draft.selection ? { selection: draft.selection } : {}),
          }
          : draft.action === "adopt_proposal"
            ? { action: "adopt_proposal", ...common, proposalId: draft.proposalId }
            : draft.action === "edit_draft"
              ? { action: "edit_draft", ...common, document: draft.document }
              : draft.action === "undo_draft"
              ? { action: "undo_draft", ...common }
              : draft.action === "return_to_stage"
                ? { action: "return_to_stage", ...common, targetStage: draft.targetStage, acknowledgeImpact: true }
                : (() => { throw new Error("Creative review action is invalid."); })();
      const runner = new WorkflowRunner({
        providers: this.createRegistry(brief),
        clock: this.clock,
        idFactory: this.idFactory,
        checkpoint: (run) => checkpoint(run as WorkflowRun<ProductionBrief>),
        shouldPause: () => this.consumePauseRequest(runId),
      });
      const acceptedAt = this.clock();
      const acceptedRun: WorkflowRun<ProductionBrief> = {
        ...previous,
        creativeReviewOperations: [
          ...(previous.creativeReviewOperations ?? []),
          {
            commandId: normalizedCommandId,
            requestDigest,
            action: draft.action,
            stage: draft.stage,
            status: "running",
            acceptedAt,
            request: structuredClone({ ...draft, commandId: normalizedCommandId, actor: normalizedActor }),
            resume: structuredClone(resume),
          },
        ],
      };
      const result = await runner.continueWaitingNode(
        this.createWorkflow(brief, { creativeReviewResume: resume }),
        withExecutableBrief(acceptedRun, brief),
        "creative-planning",
        {
          commandId: normalizedCommandId,
          action: draft.action,
          requestDigest,
          status: "running",
          acceptedAt,
        },
      );
      result.creativeReviewOperations = (result.creativeReviewOperations ?? []).map((operation) => (
        operation.commandId === normalizedCommandId
          ? {
            ...operation,
            status: creativeReviewOperationStatus(result, resume),
            ...creativeReviewOperationDetail(result, resume),
            finishedAt: this.clock(),
            ...((resume.action === "discuss" || resume.action === "revise") && creativeReviewOperationStatus(result, resume) === "completed"
              ? { resultDisposition: creativeConsultationResultDisposition(result, resume) ?? "applied" }
              : {}),
          }
          : operation
      ));
      await checkpoint(result);
      return result;
    }, listener, normalizedCommandId).catch(async (error: unknown) => {
      if (!(error instanceof RunLockedError)) throw error;
      // 完成回执先于执行租约释放落盘；发生争锁后读取最新回执，避免再次使用锁前快照。
      // 只有身份完全相同的已结束命令可只读返回；新命令、unknown 和异内容仍受租约保护。
      const current = await this.store.load<ProductionBrief>(runId);
      const settled = current.creativeReviewOperations?.find(operation => operation.commandId === normalizedCommandId
        && operation.status !== "running" && operation.status !== "unknown");
      if (!settled) throw error;
      if (settled.requestDigest !== requestDigest) {
        throw new Error(`Creative review command '${normalizedCommandId}' was already used with different content.`);
      }
      return { runId, completion: Promise.resolve(current) };
    });
  }

  private async applyCreativeDurationCommand(
    previous: WorkflowRun<ProductionBrief>,
    draft: ProductionCreativeReviewCommandDraft,
    requestDigest: string,
    notifyPersisted: (run: WorkflowRun<ProductionBrief>) => Promise<void>,
    existing?: NonNullable<WorkflowRun["creativeReviewOperations"]>[number],
  ): Promise<WorkflowRun<ProductionBrief>> {
    if (draft.action !== "update_duration" && draft.action !== "confirm") throw new HumanDecisionConflictError("时长事务的原命令身份不一致。");
    const amendment = parseDurationAmendment(draft.durationAmendment);
    const commandId = draft.commandId.trim();
    const actor = draft.actor.trim();
    const localResume = draft.action === "update_duration" ? parseCreativeReviewResume({
      action: "update_duration", commandId, actor, stage: draft.stage,
      expectedReviewRevision: draft.expectedReviewRevision, baseDraftSha256: draft.baseDraftSha256,
      baseDraftVersionId: draft.baseDraftVersionId, durationAmendment: amendment,
    }) : undefined;
    if (existing && localResume && !isDeepStrictEqual(parseCreativeReviewResume(existing.resume), localResume)) {
      throw new HumanDecisionConflictError("时长操作的原恢复信封不一致，不能重新生成。");
    }
    const brief = effectiveProductionBrief(previous);
    if (brief.durationPolicy !== "content-led-v1") throw new HumanDecisionConflictError("旧版制作继续使用原修改流程，不自动迁移时长规则。");
    const nextBrief = parsePersistedBrief({ ...brief, durationRange: amendment.range ?? undefined });
    const node = previous.nodeRuns.find(candidate => candidate.nodeId === "creative-planning")!;
    const inputVersion = node.inputState?.versions.find(version => version.id === node.inputState!.effectiveVersionId);
    if (!inputVersion || !isObjectRecord(inputVersion.value)) throw new HumanDecisionConflictError("当前规划缺少输入版本，不能修改承诺。");
    const checkpoint = async (value: WorkflowRun<ProductionBrief>) => {
      await this.store.checkpoint(value);
      await notifyPersisted(value);
    };
    const store = CreativePlanningStore.open(path.dirname(this.runsRoot));
    try {
      const graph = createInspectionPlanningGraph(store, brief.workflowFeatures?.assetSemanticRank === true);
      if (existing?.durationChange?.phase === "applied") {
        // 有效run已提交：只核已存的双端身份并补回执，不重新解释目录、图源稿或生成后继。
        const tx = existing.durationChange;
        const saved = await graph.getState(store.threadConfig(previous.id, tx.targetInputDigest));
        const state = saved.values as Partial<PlanningGraphState>;
        if (contentSha256(brief) !== tx.newBriefSha256
          || inputVersion.id !== `duration-input:${contentSha256(commandId)}`
          || saved.config.configurable?.checkpoint_id !== tx.targetCheckpointId
          || state.runId !== previous.id || state.inputDigest !== tx.targetInputDigest
          || state.durationChange?.commandId !== commandId
          || state.durationChange?.targetDraftVersionId !== tx.targetDraftVersionId) {
          throw new HumanDecisionConflictError("已保存时长操作的run与规划身份不一致；保留现场，不重发生成。");
        }
        const completed = structuredClone(previous);
        const receipt = completed.creativeReviewOperations!.find(item => item.commandId === commandId)!;
        receipt.status = "completed";
        receipt.finishedAt = this.clock();
        await checkpoint(completed);
        return completed;
      }
      const grammar = brief.workflowFeatures?.referenceGrammar && typeof inputVersion.value.referenceGrammarPath === "string"
        ? await readShotGrammarFile(inputVersion.value.referenceGrammarPath) : undefined;
      const inputDigest = existing?.durationChange?.sourceInputDigest ?? jointPlanningInputDigest(brief, grammar);
      const targetInputDigest = jointPlanningInputDigest(nextBrief, grammar);
      const sourceConfig = { configurable: { ...store.threadConfig(previous.id, inputDigest).configurable,
        ...(existing?.durationChange ? { checkpoint_id: existing.durationChange.sourceCheckpointId } : {}) } };
      const sourceSnapshot = await graph.getState(sourceConfig);
      const source = sourceSnapshot.values as PlanningGraphState;
      const sourceCheckpointId = sourceSnapshot.config.configurable?.checkpoint_id;
      const current = source.creativeReview?.stages[draft.stage];
      if (source.runId !== previous.id || source.inputDigest !== inputDigest || typeof sourceCheckpointId !== "string"
        || source.creativeReview.activeStage !== draft.stage || current?.phase !== "waiting_user"
        || !draft.baseDraftVersionId || current.currentDraft?.versionId !== draft.baseDraftVersionId
        || current.currentDraft.sha256 !== draft.baseDraftSha256
        || source.creativeReview.reviewRevision !== draft.expectedReviewRevision) {
        throw new HumanDecisionConflictError("当前稿件或规划checkpoint已变化，不能把旧时长修改套到新版本。");
      }
      if (!existing && amendment.expectedBriefSha256 !== contentSha256(brief)) {
        throw new HumanDecisionConflictError("时长要求已经变化，请保留输入并重新查看当前要求。");
      }
      if (draft.stage === "director" && draft.reviewPurpose !== (source.creativeReview.directorReviewPurpose ?? "material_plan")) {
        throw new HumanDecisionConflictError("时长修改不属于当前导演决定。");
      }
      const stageOrder: CreativeStage[] = ["treatment", "script", "director"];
      let targetStage = existing?.durationChange?.targetStage ?? draft.stage;
      for (const upstream of stageOrder.slice(0, stageOrder.indexOf(draft.stage))) {
        if (!source.creativeReview.stages[upstream].confirmation) continue;
        try {
          this.assertCreativeStageDocumentExecutable(nextBrief, upstream, source.creativeReview.stages[upstream].currentDocument,
            source.scriptArtifact?.output ?? null);
        } catch (error) {
          if (!(error instanceof PlanContractError) || error.code !== "duration_commitment_conflict" || draft.action === "confirm") throw error;
          // 仅保存承诺时返回最早真实冲突；不重新生成，不丢弃已形成的下游稿件。
          targetStage = upstream;
          break;
        }
      }
      const projected = projectDurationAmendmentState(source, {
        runId: previous.id, inputDigest: targetInputDigest, ...executableDurationFor(nextBrief), creativeReview: CREATIVE_REVIEW_FEATURE,
      }, { commandId, sourceCheckpointId, targetStage });
      const resume: CreativeReviewConfirmResume | undefined = draft.action === "confirm" ? {
        action: "confirm", stage: draft.stage, commandId, actor,
        expectedReviewRevision: projected.creativeReview.reviewRevision,
        baseDraftSha256: projected.creativeReview.stages[draft.stage].currentDraft!.sha256,
        baseDraftVersionId: projected.creativeReview.stages[draft.stage].currentDraft!.versionId,
        acknowledgeUnaudited: true, confirmedAt: existing?.acceptedAt ?? this.clock(),
        ...(draft.acceptQualityFallback ? { acceptQualityFallback: true } : {}),
      } : undefined;
      if (resume) {
        for (const stage of ["treatment", "script", "director"] as const) {
          if (stage === draft.stage || (["treatment", "script", "director"].indexOf(stage) < ["treatment", "script", "director"].indexOf(draft.stage)
            && source.creativeReview.stages[stage].confirmation)) {
            this.assertCreativeStageDocumentExecutable(nextBrief, stage, source.creativeReview.stages[stage].currentDocument,
              source.scriptArtifact?.output ?? null);
          }
        }
        validateDurationAmendmentConfirmation(projected, resume);
      }
      projected.carriedStageInputIdentities = jointPlanningStageInputs(nextBrief, this.options, grammar);
      const historyPath = path.join(this.store.runDirectory(previous.id), "nodes", "creative-planning", "planning-history.json");
      const sourceHistory = (await readJointPlanningHistory(historyPath)).find(entry => entry.inputDigest === inputDigest);
      projected.carriedModelTraces = { ...source.carriedModelTraces, ...sourceHistory?.modelTraces };
      projected.carriedProviderTraces = { ...source.carriedProviderTraces, ...sourceHistory?.providerTraces };
      const targetConfig = store.threadConfig(previous.id, targetInputDigest);
      let targetSnapshot = await graph.getState(targetConfig);
      const targetHeadId = targetSnapshot.config.configurable?.checkpoint_id ?? null;
      let accepted = structuredClone(previous);
      let operation = existing ? structuredClone(existing) : undefined;
      if (!operation) {
        // 复用已有不确定费用校验，并在复用过滤前读取本节点/明确来源的完整账本。
        await this.assertDurationChangeSafe(previous);
        operation = { commandId, requestDigest, action: draft.action, stage: draft.stage,
          status: "running", acceptedAt: resume?.confirmedAt ?? this.clock(), request: structuredClone({ ...draft, commandId, actor }),
          resume: resume ?? localResume,
          durationChange: { phase: "prepared", oldBriefSha256: contentSha256(brief), newBriefSha256: contentSha256(nextBrief),
            sourceInputDigest: inputDigest, sourceCheckpointId, targetInputDigest,
            targetPreviousCheckpointId: typeof targetHeadId === "string" ? targetHeadId : null,
            targetDraftVersionId: projected.creativeReview.stages[targetStage].currentDraft!.versionId,
            targetStage,
            preservedApprovals: (["treatment", "script"] as const).filter(stage => stageOrder.indexOf(stage) < stageOrder.indexOf(targetStage)).flatMap(stage => {
              const approval = source.creativeReview.stages[stage].confirmation;
              return approval ? [{ stage, commandId: approval.commandId, versionId: approval.versionId, draftSha256: approval.draftSha256 }] : [];
            }),
          } };
        accepted.creativeReviewOperations = [...(accepted.creativeReviewOperations ?? []), operation];
        // 只登记受理，不消耗CAS或修改有效brief；此后所有其他写入口由lease内屏障保护。
        await checkpoint(accepted);
        await this.options.durationChangeFailpoints?.afterAccepted?.();
      } else {
        const tx = operation.durationChange!;
        if (tx.newBriefSha256 !== contentSha256(nextBrief) || tx.targetInputDigest !== targetInputDigest
          || tx.targetDraftVersionId !== projected.creativeReview.stages[tx.targetStage].currentDraft!.versionId
          || ![tx.oldBriefSha256, tx.newBriefSha256].includes(contentSha256(brief))) {
          throw new HumanDecisionConflictError("时长事务的恢复身份不一致；保留原记录，不重新生成。");
        }
        accepted.creativeReviewOperations = accepted.creativeReviewOperations!.map(item => item.commandId === commandId ? operation! : item);
      }
      const tx = operation.durationChange!;
      if (tx.phase !== "applied") {
        const target = targetSnapshot.values as Partial<PlanningGraphState>;
        const inputId = `duration-input:${contentSha256(commandId)}`;
        // 首个runner checkpoint已提交新输入后，不能重新注入原阶段确认或清掉原任务身份。
        const continuationStarted = Boolean(existing && inputVersion.id === inputId
          && previous.revision === draft.expectedRunRevision + 1 && contentSha256(brief) === tx.newBriefSha256);
        if (target.durationChange?.commandId === commandId) {
          if (!isDeepStrictEqual(target.durationChange, projected.durationChange)) throw new HumanDecisionConflictError("时长目标checkpoint身份不一致。");
        } else {
          if (targetHeadId !== tx.targetPreviousCheckpointId) throw new HumanDecisionConflictError("目标规划已被其他操作改变，不能覆盖。");
          // 指定源快照的全量投影覆盖旧目标head；A→B→A不会复活A的历史批准或当前稿。
          await graph.updateState(targetConfig, projected, `${tx.targetStage}_review`);
        }
        // 检视图只推进新播种的review游标；组合确认后的后继只能走正式原请求恢复。
        if (!continuationStarted) {
          await runCreativePlanning(graph, { input: projected.base, threadId: store.threadId(previous.id, targetInputDigest) });
        }
        targetSnapshot = await graph.getState(targetConfig);
        tx.targetCheckpointId = String(targetSnapshot.config.configurable!.checkpoint_id);
        await this.options.durationChangeFailpoints?.afterGraph?.();
        const resumeBase = structuredClone(accepted);
        resumeBase.initialInput = nextBrief;
        // 即使进程在runner首个checkpoint中断，恢复也只完成这一个逻辑revision。
        resumeBase.revision = draft.expectedRunRevision;
        const resumeNode = resumeBase.nodeRuns.find(item => item.nodeId === "creative-planning")!;
        if (!continuationStarted) {
          resumeBase.status = "needs_human";
          resumeNode.status = "needs_human";
          resumeNode.intervention = { id: `duration-review:${contentSha256(commandId)}`, nodeId: resumeNode.nodeId,
            kind: "creative_review", requiredAction: "approve", options: ["approve", "request_changes"],
            reason: "时长要求已更新，当前稿尚未采用。", createdAt: operation.acceptedAt,
            continuation: { stage: tx.targetStage, reviewRevision: projected.creativeReview.reviewRevision,
              draftSha256: projected.creativeReview.stages[tx.targetStage].currentDraft!.sha256 } };
          resumeBase.interventions = [...resumeBase.interventions.filter(item => item.nodeId !== resumeNode.nodeId), resumeNode.intervention];
          delete resumeBase.finishedAt;
        }
        if (resumeNode.inputState!.effectiveVersionId !== inputId) {
          const oldInput = resumeNode.inputState!.versions.find(item => item.id === resumeNode.inputState!.effectiveVersionId)!;
          resumeNode.inputState = { ...resumeNode.inputState!, effectiveVersionId: inputId, stale: false,
            versions: [...resumeNode.inputState!.versions, { ...oldInput, id: inputId, source: "human",
              value: { ...inputVersion.value, brief: nextBrief }, parentVersionId: oldInput.id,
              createdAt: operation.acceptedAt, createdBy: actor }] };
        }
        // 普通runner负责登记新稿产物和人工停点；已播种的interrupt不会调用角色或编译。
        let persistedRevision = previous.revision;
        const runner = new WorkflowRunner({ providers: this.createRegistry(nextBrief), clock: this.clock, idFactory: this.idFactory,
          checkpoint: async value => {
            const next = value as WorkflowRun<ProductionBrief>;
            if (next.revision === persistedRevision) await checkpoint(next);
            else { await this.store.save(next, persistedRevision); persistedRevision = next.revision; await notifyPersisted(next); }
          } });
        if (continuationStarted) {
          const state = targetSnapshot.values as PlanningGraphState;
          const confirmationConsumed = state.creativeReview.stages[draft.stage].confirmationHistory.some(approval =>
            approval.commandId === commandId && approval.versionId === tx.targetDraftVersionId);
          if (resumeNode.status === "needs_human") {
            const gate = resumeNode.intervention?.continuation;
            const currentStage = state.creativeReview.activeStage;
            const currentDraft = state.creativeReview.stages[currentStage].currentDraft;
            if (!gate || gate.stage !== currentStage || gate.reviewRevision !== state.creativeReview.reviewRevision
              || gate.draftSha256 !== currentDraft?.sha256 || (resume && !confirmationConsumed)) {
              throw new HumanDecisionConflictError("时长操作后继停点与规划身份不一致，保留现场等待核对。");
            }
            accepted = structuredClone(previous);
          } else if (["pending", "running"].includes(resumeNode.status) || resumeNode.interrupted) {
            // 复用runner的原操作恢复，不走会删除operationRequestId的continueWaitingNode。
            resumeBase.status = "failed";
            resumeNode.status = "failed";
            resumeNode.interrupted = true;
            const originalOperationId = resumeNode.operationRequestId;
            accepted = await runner.retryFailedNode(this.createWorkflow(nextBrief, {
              ...(resume && !confirmationConsumed ? { creativeReviewResume: resume } : {}),
              ...(originalOperationId ? { recoverTextTask: { nodeId: "creative-planning", workflowOperationRequestId: originalOperationId } } : {}),
            }), resumeBase, "creative-planning", resumeNode.outcomeUncertain ? { resumeUncertainOperation: true } : {});
          } else {
            // 后继已成功或已明确失败：保留真实结果，补本地事务回执不等于重试后继。
            accepted = structuredClone(previous);
          }
        } else {
          accepted = await runner.continueWaitingNode(this.createWorkflow(nextBrief, resume ? { creativeReviewResume: resume } : {}), resumeBase, "creative-planning");
        }
        await this.options.durationChangeFailpoints?.afterContinued?.();
        if (!resume && accepted.status !== "needs_human") throw new HumanDecisionConflictError("本地时长修改未回到人工停点，请恢复原命令；不会另发生成。");
        operation = accepted.creativeReviewOperations!.find(item => item.commandId === commandId)!;
        operation.durationChange!.phase = "applied";
        operation.durationChange!.targetCheckpointId = String((await graph.getState(targetConfig)).config.configurable!.checkpoint_id);
        await checkpoint(accepted);
        await this.options.durationChangeFailpoints?.afterRunSaved?.();
      }
      operation.status = "completed";
      operation.finishedAt = this.clock();
      await checkpoint(accepted);
      return accepted;
    } finally { store.close(); }
  }

  private async assertDurationChangeSafe(run: WorkflowRun<ProductionBrief>): Promise<void> {
    const runRoot = this.store.runDirectory(run.id);
    await assertNoUnresolvedPlanningTask(runRoot, run);
    const affected = new Set(productionNodeIds(run.initialInput).filter(id => id !== "brief" && id !== "reference-grammar"));
    assertNoUncertainPaidOutcomeInvalidated(run, affected, await verifiedOptionalReviewInvalidationOperations(run, runRoot));
    const inspect = async (value: WorkflowRun<ProductionBrief>) => {
      const items = paidAssetLedgerLeaves(await inspectPaidAssetLedger(path.join(this.store.runDirectory(value.id), "nodes", "assets")));
      if (items.some(item => ["submitted", "unknown", "provider_succeeded"].includes(item.state))) {
        throw new HumanDecisionConflictError("原素材请求或物化仍待核实，请先恢复原请求；时长要求和现有稿件未修改。");
      }
    };
    await inspect(run);
    const source = run.initialInput.rework;
    if (source) {
      if (source.sourceRunId === run.id) throw new HumanDecisionConflictError("返工来源不能指向当前制作。");
      await this.withRunMaintenanceLease([source.sourceRunId], async () => {
        const original = await this.store.load<ProductionBrief>(source.sourceRunId);
        if (original.revision !== source.sourceRunRevision) throw new HumanDecisionConflictError("返工来源版本已改变，请先核对原制作。");
        assertNoUncertainPaidOutcomeInvalidated(original, new Set(original.nodeRuns.map(item => item.nodeId)),
          await verifiedOptionalReviewInvalidationOperations(original, this.store.runDirectory(original.id)));
        await inspect(original);
      });
    }
  }

  /**
   * F03/D06（2026-10-02 执行包 §2.3）：历史审计异常 failed 记录的显式准备。
   * 只恢复本地人工停点——把保留在节点输出里的创作工作台重新交还用户；不签字、不补审、
   * 不发模型请求。同 commandId 同 body 幂等重放（返回同一停点），异 body 拒绝。
   * 当前稿身份从持久化状态读取（安全可读即可），不采信客户端自报。
   */
  async prepareReviewContinuation(
    runId: string,
    input: ProductionReviewContinuationInput,
    actor = "studio-owner",
  ): Promise<WorkflowRun<ProductionBrief>> {
    const normalizedCommandId = input.commandId.trim();
    if (!normalizedCommandId) throw new Error("Review continuation requires a commandId.");
    const requestDigest = contentSha256({ ...input, commandId: normalizedCommandId, actor });
    const dispatched = await this.dispatchPersistedTransition(runId, async (previous, checkpoint) => {
      const existing = previous.reviewContinuationOperations?.find(
        (operation) => operation.commandId === normalizedCommandId,
      );
      if (existing) {
        if (existing.requestDigest !== requestDigest) {
          throw new Error(`Review continuation command '${normalizedCommandId}' was already used with different content.`);
        }
        // 同 commandId 同 body：幂等重放原停点，不新建确认点、不推进 revision。
        if (existing.status !== "accepted") return { replay: previous };
        if (existing.resultInterventionId && previous.nodeRuns.some(node => node.intervention?.id === existing.resultInterventionId)) {
          existing.status = "applied";
          existing.finishedAt = this.clock();
          await this.store.checkpoint(previous);
          return { replay: previous };
        }
      }
      // 幂等回执优先；只有首次受理才校验页面版本，防止过期页面改写当前停点。
      if (!Number.isSafeInteger(input.expectedRunRevision) || input.expectedRunRevision !== previous.revision) {
        throw new StaleRunRevisionError(runId, input.expectedRunRevision, previous.revision);
      }
      const node = previous.nodeRuns.find((candidate) => candidate.nodeId === input.nodeId);
      if (!node) throw new HumanDecisionConflictError("没有找到对应的审计停点，请重新查看当前制作。");
      if (input.intent === "edit_character_script") {
        return this.prepareCharacterScriptEdit(previous, input, normalizedCommandId, requestDigest, actor, checkpoint);
      }
      if (input.nodeId === "visual-review") {
        return this.prepareRenderedReviewContinuation(previous, input, normalizedCommandId, requestDigest, actor, checkpoint);
      }
      const output = isObjectRecord(node.output) ? node.output : undefined;
      const review = output && isObjectRecord(output.creativeReview) ? output.creativeReview : undefined;
      const stages = review && isObjectRecord(review.stages) ? review.stages : undefined;
      // 准备只要求当前稿安全可读、身份真实；缺保存稿的生成失败不套用本恢复。
      const activeStage = typeof review?.activeStage === "string"
        && ["treatment", "script", "director"].includes(review.activeStage)
        ? review.activeStage as "treatment" | "script" | "director"
        : undefined;
      const stage = input.stage ?? activeStage;
      if (!stage
        || !isObjectRecord(stages?.[stage]) || !isObjectRecord(stages[stage].currentDraft)) {
        throw new HumanDecisionConflictError("这条失败记录没有保留可恢复的创作稿件；请从失败说明选择其它恢复出口。");
      }
      const gate = stages![stage] as { currentDraft: { artifactId: string; versionId: string; sha256: string }; currentDocument: unknown };
      if (input.nodeId !== "creative-planning" || stage !== activeStage
        || gate.currentDraft.artifactId !== input.targetArtifactId
        || gate.currentDraft.versionId !== input.targetVersionId
        || gate.currentDraft.sha256 !== input.targetSha256
        || contentSha256(gate.currentDocument) !== gate.currentDraft.sha256
        || stage === "director" && input.reviewPurpose !== undefined
          && input.reviewPurpose !== (review?.directorReviewPurpose ?? "material_plan")) {
        throw new HumanDecisionConflictError("当前稿件或用途已经变化，请重新查看当前版本后再恢复。");
      }
      const reopenedReview = await this.reopenPreservedPlanningGeneration(previous);
      const reviewRevision = reopenedReview?.reviewRevision ?? (typeof review?.reviewRevision === "number" ? review.reviewRevision : previous.revision);
      if (node.status === "needs_human" && node.intervention?.kind === "creative_review") {
        // 相同停点不新建确认，但仍登记可查询的命令回执，不能让HTTP未知变成无记录。
        const proof = previous.artifacts.find(artifact => artifact.schemaVersion === "video-factory/optional-review-continuation-v1"
          && isObjectRecord(artifact.data) && artifact.data.stage === stage && isObjectRecord(artifact.data.target)
          && artifact.data.target.versionId === input.targetVersionId);
        previous.reviewContinuationOperations = [...(previous.reviewContinuationOperations ?? []).filter(operation => operation.commandId !== normalizedCommandId), {
          commandId: normalizedCommandId, requestDigest, action: "prepare", nodeId: input.nodeId, actor,
          stage, target: { artifactId: input.targetArtifactId, versionId: input.targetVersionId, sha256: input.targetSha256 },
          targetRunRevision: previous.revision, resultRunRevision: previous.revision,
          resultInterventionId: node.intervention.id, ...(proof?.sha256 ? { resultEvidenceId: proof.sha256 } : {}),
          status: "applied", acceptedAt: existing?.acceptedAt ?? this.clock(), finishedAt: this.clock(),
        }];
        await this.store.checkpoint(previous);
        return { replay: previous };
      }
      if (previous.status === "succeeded") {
        throw new HumanDecisionConflictError("已完成作品只读；不能用准备动作重开生产。");
      }
      if (!existing) {
        previous.reviewContinuationOperations = [...(previous.reviewContinuationOperations ?? []), {
          commandId: normalizedCommandId, requestDigest, action: "prepare", nodeId: input.nodeId, actor,
          target: { artifactId: input.targetArtifactId, versionId: input.targetVersionId, sha256: input.targetSha256 },
          ...(input.stage ? { stage: input.stage } : {}), targetRunRevision: previous.revision,
          status: "accepted", acceptedAt: this.clock(),
        }];
        await this.store.checkpoint(previous);
        await this.options.reviewContinuationFailpoints?.afterAccepted?.();
      }
      const interventionId = `creative-review-continuation-${normalizedCommandId}`;
      const intervention: NonNullable<NodeRun["intervention"]> = {
        id: interventionId,
        nodeId: "creative-planning",
        kind: "creative_review" as const,
        reason: "已恢复保留的创作工作台，未发送模型请求。你可以查看、修改或采用；继续生成仍由你决定。",
        requiredAction: "approve" as const,
        options: ["approve", "request_changes"],
        createdAt: this.clock(),
        continuation: {
          stage,
          reviewRevision,
          draftSha256: gate.currentDraft.sha256,
        },
      };
      const next: WorkflowRun<ProductionBrief> = {
        ...previous,
        status: "needs_human",
        revision: previous.revision + 1,
        nodeRuns: previous.nodeRuns.map((candidate) => candidate.nodeId === "creative-planning"
          ? { ...candidate, status: "needs_human", intervention }
          : candidate),
        interventions: [
          ...previous.interventions.filter((candidate) => candidate.nodeId !== "creative-planning"),
          intervention,
        ],
        reviewContinuationOperations: [
          ...(previous.reviewContinuationOperations ?? []).filter(operation => operation.commandId !== normalizedCommandId),
          {
            commandId: normalizedCommandId,
            requestDigest,
            action: "prepare" as const,
            nodeId: input.nodeId,
            actor,
            target: { artifactId: input.targetArtifactId, versionId: input.targetVersionId, sha256: input.targetSha256 },
            resultInterventionId: interventionId,
            resultRunRevision: previous.revision + 1,
            ...(input.stage ? { stage: input.stage } : {}),
            targetRunRevision: previous.revision,
            status: "accepted" as const,
            acceptedAt: existing?.acceptedAt ?? previous.reviewContinuationOperations!.at(-1)!.acceptedAt,
          },
        ],
      };
      const evidence = await this.persistCreativeContinuationEvidence(next, stage, "restore_preserved_draft");
      next.reviewContinuationOperations!.at(-1)!.resultEvidenceId = evidence.sha256!;
      await this.options.reviewContinuationFailpoints?.afterEvidence?.();
      await checkpoint(next);
      await this.options.reviewContinuationFailpoints?.afterDecisionCheckpoint?.();
      next.reviewContinuationOperations!.at(-1)!.status = "applied";
      next.reviewContinuationOperations!.at(-1)!.finishedAt = this.clock();
      await checkpoint(next);
      return next;
    });
    return dispatched.completion;
  }

  private async prepareCharacterScriptEdit(
    previous: WorkflowRun<ProductionBrief>, input: ProductionReviewContinuationInput, commandId: string,
    requestDigest: string, actor: string, checkpoint: (run: WorkflowRun<ProductionBrief>) => Promise<void>,
  ): Promise<WorkflowRun<ProductionBrief>> {
    const brief = effectiveProductionBrief(previous);
    const node = previous.nodeRuns.find(n => n.nodeId === "creative-planning")!;
    const output = effectiveNodeOutput(node);
    const review = isObjectRecord(output) ? (output.creativeReviewHistory ?? output.creativeReview) as CreativeReviewState | undefined : undefined;
    const script = review?.stages.script;
    if (input.nodeId !== "creative-planning" || input.stage !== "script" || input.reviewPurpose || !input.acknowledgeImpact
      || brief.presentationMode !== "character_drama" || previous.status !== "needs_human"
      || !["succeeded", "needs_human"].includes(node.status) || node.intervention?.kind === "creative_review" && node.status === "needs_human"
      || node.inputState?.stale || node.outputState?.stale || !isCharacterScript(script?.currentDocument)
      || script?.currentDraft?.artifactId !== input.targetArtifactId || script.currentDraft.versionId !== input.targetVersionId
      || script.currentDraft.sha256 !== input.targetSha256 || contentSha256(script.currentDocument) !== input.targetSha256) {
      throw new HumanDecisionConflictError("请在当前制作的人工停点确认返回角色与台词；稿件或版本已变化时需重新查看。");
    }
    await assertNoUnresolvedPlanningTask(this.store.runDirectory(previous.id), previous);
    const inputDigest = await this.planningAuditInputDigest(previous);
    if (!inputDigest) throw new HumanDecisionConflictError("当前规划的来源版本缺失，不能重新生成或覆盖。");
    const priorDraft = [...(node.outputState?.versions ?? [])].reverse().map(v => v.output).find(candidate => {
      if (!isObjectRecord(candidate) || candidate.stage !== "script" || !isObjectRecord(candidate.creativeReview)) return false;
      const saved = candidate.creativeReview as unknown as CreativeReviewState;
      return saved.stages.script.currentDraft?.versionId === input.targetVersionId
        && saved.stages.script.currentDraft.sha256 === input.targetSha256 && typeof candidate.draftArtifactId === "string";
    }) as Record<string, unknown> | undefined;
    const draftArtifact = previous.artifacts.find(a => a.id === priorDraft?.draftArtifactId && a.kind === "creative_draft");
    if (!draftArtifact?.uri) throw new HumanDecisionConflictError("当前角色稿的原文件缺失，不能覆盖或伪造稿件。");
    await verifyStoredArtifactWithinRoot(this.store.runDirectory(previous.id), draftArtifact);
    if (contentSha256(JSON.parse(await readFile(draftArtifact.uri, "utf8"))) !== input.targetSha256) {
      throw new HumanDecisionConflictError("角色稿文件与当前版本不一致，请先核对原稿。");
    }
    const runner = new WorkflowRunner({ providers: this.createRegistry(brief), clock: this.clock, idFactory: this.idFactory,
      optionalReviewInvalidationOperations: await verifiedOptionalReviewInvalidationOperations(previous, this.store.runDirectory(previous.id)) });
    // 先经过现有在途/版本/后代失效守卫，再写图；保留文件，不能绕过未知付费请求。
    let next: WorkflowRun<ProductionBrief>;
    try {
      next = runner.applyNodeOverride(this.createWorkflow(brief), withExecutableBrief(previous, brief), {
        nodeId: node.nodeId, actor, expectedVersionId: node.outputState!.effectiveVersionId, output,
      });
    } catch (error) {
      throw new HumanDecisionConflictError(error instanceof Error ? error.message : "当前制作状态不允许返回编辑，请先处理原请求。");
    }
    const existing = previous.reviewContinuationOperations?.find(op => op.commandId === commandId);
    const operation: NonNullable<WorkflowRun["reviewContinuationOperations"]>[number] = existing ?? {
      commandId, requestDigest, action: "prepare", nodeId: "creative-planning", stage: "script", actor,
      target: { artifactId: input.targetArtifactId, versionId: input.targetVersionId, sha256: input.targetSha256 },
      targetRunRevision: previous.revision, status: "accepted", acceptedAt: this.clock(),
    };
    if (!existing) {
      previous.reviewContinuationOperations = [...(previous.reviewContinuationOperations ?? []), operation];
      await this.store.checkpoint(previous);
      await this.options.reviewContinuationFailpoints?.afterAccepted?.();
    }
    const store = CreativePlanningStore.open(path.dirname(this.runsRoot));
    let restored: PlanningGraphState;
    try {
      restored = await reopenCharacterScriptGate(createInspectionPlanningGraph(store, brief.workflowFeatures?.assetSemanticRank === true),
        previous.id, inputDigest, operation.target!, commandId, actor);
    } finally { store.close(); }
    await this.options.reviewContinuationFailpoints?.afterEvidence?.();
    const reopened = next.nodeRuns.find(n => n.nodeId === node.nodeId)!;
    reopened.output = { ...output, stage: "script", draftArtifactId: draftArtifact.id,
      creativeReview: restored.creativeReview, planningStop: restored.planningStop };
    reopened.outputState!.versions.find(v => v.id === reopened.outputState!.effectiveVersionId)!.output = structuredClone(reopened.output);
    reopened.status = "needs_human";
    delete reopened.finishedAt; delete reopened.error; delete reopened.errorCode;
    reopened.intervention = { id: `character-script-edit-${commandId}`, nodeId: node.nodeId, kind: "creative_review", createdAt: this.clock(),
      requiredAction: "approve", options: ["approve", "request_changes"], reason: restored.planningStop!.detail,
      continuation: { stage: "script", reviewRevision: restored.creativeReview.reviewRevision, draftSha256: input.targetSha256 } };
    next.interventions = [...next.interventions.filter(i => i.nodeId !== node.nodeId), reopened.intervention];
    next.status = "needs_human";
    delete next.finishedAt;
    const receipt = { ...operation, resultInterventionId: reopened.intervention.id, resultRunRevision: next.revision };
    next.reviewContinuationOperations = [...(previous.reviewContinuationOperations ?? []).filter(op => op.commandId !== commandId), receipt];
    await checkpoint(next);
    await this.options.reviewContinuationFailpoints?.afterDecisionCheckpoint?.();
    receipt.status = "applied"; receipt.finishedAt = this.clock();
    await checkpoint(next);
    return next;
  }

  private async prepareRenderedReviewContinuation(
    previous: WorkflowRun<ProductionBrief>, input: ProductionReviewContinuationInput, commandId: string,
    requestDigest: string, actor: string, checkpoint: (run: WorkflowRun<ProductionBrief>) => Promise<void>,
  ): Promise<WorkflowRun<ProductionBrief> | { replay: WorkflowRun<ProductionBrief> }> {
    if (input.stage || input.reviewPurpose || previous.status === "succeeded") {
      throw new HumanDecisionConflictError("已完成作品不能重开；成片准备也不接受创作阶段或用途。");
    }
    const node = previous.nodeRuns.find(item => item.nodeId === "visual-review")!;
    if (node.status !== "failed" && !(node.status === "needs_human" && node.intervention?.continuationScope === "rendered_video_optional_review")) {
      throw new HumanDecisionConflictError("当前不在可恢复的成片审片停点，请查看当前步骤。");
    }
    const runRoot = this.store.runDirectory(previous.id);
    const brief = effectiveProductionBrief(previous);
    const outputs = new Map(previous.nodeRuns.map(item => [item.nodeId, effectiveNodeOutput(item)]));
    assertTechnicalReviewReady(outputs.get("technical-review"));
    const selected = await currentArtifactsForPackaging({ artifacts: previous.artifacts, outputs }, brief, false);
    const render = previous.nodeRuns.find(item => item.nodeId === "render");
    const video = selected.find(artifact => artifact.producer?.nodeId === "render" && artifact.contentType === "video/mp4"
      && artifact.uri === outputs.get("render")?.videoPath);
    if (!video || video.id !== input.targetArtifactId || video.sha256 !== input.targetSha256
      || render?.outputState?.stale || render?.outputState?.effectiveVersionId !== input.targetVersionId) {
      throw new HumanDecisionConflictError("当前成片身份或有效版本已变化，请重新查看；不能用风险确认代替缺失成果。");
    }
    await verifyOptionalRequiredMedia(previous, outputs, selected, runRoot);
    const existing = previous.reviewContinuationOperations?.find(operation => operation.commandId === commandId);
    const next = structuredClone(previous);
    const operation: NonNullable<WorkflowRun["reviewContinuationOperations"]>[number] = existing ?? {
      commandId, requestDigest, actor, action: "prepare", nodeId: "visual-review",
      target: { artifactId: video.id, versionId: input.targetVersionId, sha256: video.sha256! },
      targetRunRevision: previous.revision, status: "accepted", acceptedAt: this.clock(),
    };
    next.reviewContinuationOperations = [...(next.reviewContinuationOperations ?? []).filter(item => item.commandId !== commandId), structuredClone(operation)];
    if (!existing) {
      await this.store.checkpoint(next);
      await this.options.reviewContinuationFailpoints?.afterAccepted?.();
    }
    const saved = next.reviewContinuationOperations.at(-1)!;
    if (node.status === "needs_human") {
      saved.resultInterventionId = node.intervention!.id;
      if (node.intervention!.evidenceId) saved.resultEvidenceId = node.intervention!.evidenceId;
      saved.resultRunRevision = previous.revision;
      saved.status = "applied"; saved.finishedAt = this.clock();
      await this.store.checkpoint(next);
      return { replay: next };
    }
    const restored = next.nodeRuns.find(item => item.nodeId === "visual-review")!;
    const priorOutput = effectiveNodeOutput(node);
    restored.output = { ...(isObjectRecord(priorOutput) ? priorOutput : {}),
      continuationScope: "rendered_video_optional_review", reviewStatus: "incomplete", providerOutcomeKnown: false,
      reason: "这次可选审片没有有效结论；当前成片与技术证据已独立核对，原请求/费用仍按原记录待核。",
    };
    // 风险诊断属于宿主本地恢复，不生成媒体，也不改已有机器结论为通过。
    const evidence = await persistRenderedContinuationEvidence(next, restored, runRoot, operation.acceptedAt);
    const output = restored.output as Record<string, unknown>;
    output.visualReviewPath ??= evidence.uri;
    restored.status = "needs_human";
    delete restored.error; delete restored.errorCode; delete restored.finishedAt;
    const intervention: NonNullable<NodeRun["intervention"]> = {
      id: `rendered-review-continuation-${commandId}`, nodeId: "visual-review", createdAt: operation.acceptedAt,
      reason: "已恢复当前成片的人工审看片。准备不会签字或重发审片：请播放并明确采用后，再进入独立人工终审。",
      requiredAction: "approve", options: ["approve", "request_changes", "reject"],
      reviewStatus: "incomplete", continuationScope: "rendered_video_optional_review",
      providerOutcomeKnown: output.providerOutcomeKnown === true, evidenceId: evidence.sha256!, artifactIds: [video.id, evidence.id],
    };
    restored.intervention = intervention;
    restored.artifactIds = [...new Set([...restored.artifactIds, evidence.id])];
    const versionId = `review-continuation-version-${commandId}`;
    const parent = restored.outputState?.effectiveVersionId;
    restored.outputState = { nodeId: restored.nodeId, generatedVersionId: restored.outputState?.generatedVersionId ?? versionId,
      effectiveVersionId: versionId, stale: false, versions: [...(restored.outputState?.versions ?? []), {
        id: versionId, nodeId: restored.nodeId, source: "generated", createdAt: operation.acceptedAt, createdBy: "host-review-continuation",
        schemaVersion: "video-factory/optional-review-continuation-v1", artifactIds: restored.artifactIds,
        inputVersionIds: restored.inputState?.effectiveVersionId ? [restored.inputState.effectiveVersionId] : [],
        ...(parent ? { parentVersionId: parent } : {}), output: structuredClone(output),
      }] };
    next.status = "needs_human"; next.revision++;
    delete next.finishedAt;
    next.interventions = [...next.interventions.filter(item => item.nodeId !== restored.nodeId), intervention];
    saved.resultEvidenceId = evidence.sha256!; saved.resultInterventionId = intervention.id; saved.resultRunRevision = next.revision;
    await this.options.reviewContinuationFailpoints?.afterEvidence?.();
    await checkpoint(next);
    await this.options.reviewContinuationFailpoints?.afterDecisionCheckpoint?.();
    saved.status = "applied"; saved.finishedAt = this.clock();
    await checkpoint(next);
    return next;
  }

  /** 诊断是固定的宿主快照；原请求后续观察另存，不改写用户当时读到的风险。 */
  private async persistCreativeContinuationEvidence(
    run: WorkflowRun<ProductionBrief>, stage: CreativeStage, reasonCode?: string,
  ): Promise<Artifact> {
    const node = run.nodeRuns.find(item => item.nodeId === "creative-planning")!;
    const output = requireOutputRecord(effectiveNodeOutput(node), "creative-planning");
    const review = output.creativeReview as CreativeReviewState;
    const current = review.stages[stage];
    const draft = current.currentDraft;
    if (!draft || contentSha256(current.currentDocument) !== draft.sha256) {
      throw new HumanDecisionConflictError("保留稿的身份无法核对，请先恢复原稿；没有新审计请求。");
    }
    const reason = current.continuation?.reasonCode ?? reasonCode ?? "audit_no_valid_conclusion";
    const operationId = current.continuation?.auditOperationId;
    const existing = run.artifacts.find(artifact => artifact.schemaVersion === "video-factory/optional-review-continuation-v1"
      && isObjectRecord(artifact.data) && artifact.data.scope === "creative_stage"
      && isObjectRecord(artifact.data.target) && artifact.data.target.versionId === draft.versionId
      && artifact.data.stage === stage && Array.isArray(artifact.data.reasonCodes)
      && artifact.data.reasonCodes.includes(reason)
      && (!operationId || (artifact.data.requestFacts as OptionalReviewContinuationEvidence["requestFacts"])
        .some(fact => fact.operationId === operationId)));
    if (existing) { await verifyStoredArtifactWithinRoot(this.store.runDirectory(run.id), existing); return existing; }
    const draftArtifact = run.artifacts.find(artifact => artifact.id === output.draftArtifactId);
    if (!draftArtifact?.uri) throw new HumanDecisionConflictError("保留的稿件文件没有完整登记，不能恢复为当前稿。");
    await verifyStoredArtifactWithinRoot(this.store.runDirectory(run.id), draftArtifact);
    if (contentSha256(JSON.parse(await readFile(draftArtifact.uri, "utf8"))) !== draft.sha256) {
      throw new HumanDecisionConflictError("保留稿件的文件与当前版本不一致，请核对原稿后继续。");
    }
    let validationIssues: OptionalReviewContinuationEvidence["validationIssues"];
    try {
      this.assertCreativeStageDocumentExecutable(parsePersistedBrief(run.initialInput), stage, current.currentDocument,
        review.stages.script.currentDocument);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      validationIssues = [{ path: stage, code: "draft_validation_failed", message }];
      if (current.continuation?.validationIssues?.length) validationIssues = current.continuation.validationIssues;
    }
    const prepared = await boundOptionalTextOperations(this.store.runDirectory(run.id), node, "creative_audit", draft.sha256, operationId);
    const requestFacts: OptionalReviewContinuationEvidence["requestFacts"] = prepared.map(item => ({
      purpose: "creative_audit", operationId: item.workflowOperationId,
      requestId: item.operation.requestId, targetVersionId: draft.versionId,
      inputDigest: item.operation.binding.requestDigest,
      providerId: item.operation.brokerBinding.providerId, modelId: item.operation.brokerBinding.modelId,
      requestState: optionalPreparedRequestState(item), resultState: "absent", reasonCode: reason,
      evidenceArtifactIds: [],
    }));
    if (!requestFacts.length && operationId) requestFacts.push({
      purpose: "creative_audit", operationId, targetVersionId: draft.versionId, inputDigest: draft.stageInputDigest,
      requestState: current.continuation?.status === "unknown" ? "unknown" : "not_submitted",
      resultState: current.continuation?.status === "rejected_operation" ? "conflict" : "absent",
      reasonCode: reason, evidenceArtifactIds: [],
    });
    for (const fact of requestFacts) {
      const source = prepared.find(item => item.operation.requestId === fact.requestId);
      const planningInputDigest = await this.planningAuditInputDigest(run);
      fact.evidenceArtifactIds.push(await persistOptionalOperationIndex(run, node, this.store.runDirectory(run.id), fact, source?.sourceRelativePath,
        planningInputDigest ? { planningInputDigest, auditSource: current.continuation?.source ?? "initial" } : undefined));
    }
    return persistOptionalContinuationEvidence(run, node, this.store.runDirectory(run.id), {
      version: "video-factory/optional-review-continuation-v1", scope: "creative_stage", runId: run.id,
      nodeId: "creative-planning", stage,
      ...(stage === "director" ? { reviewPurpose: review.directorReviewPurpose ?? "material_plan" } : {}),
      target: { artifactId: draft.artifactId, versionId: draft.versionId, sha256: draft.sha256, inputDigest: draft.stageInputDigest },
      adoptionEligibility: validationIssues ? "requires_correction" : "eligible",
      ...(validationIssues ? { validationIssues } : {}),
      artifactBindings: [{ artifactId: draftArtifact.id, nodeId: node.nodeId, versionId: draft.versionId,
        sha256: draftArtifact.sha256!, sizeBytes: draftArtifact.sizeBytes ?? null }],
      requestFacts, reasonCodes: [reason],
    }, this.clock());
  }

  private async bindSettledVisualReviewGate(run: WorkflowRun<ProductionBrief>): Promise<boolean> {
    const visual = run.nodeRuns.find(item => item.nodeId === "visual-review");
    const proof = visual && incompleteVisualDeliveryProof(effectiveNodeOutput(visual));
    if (visual?.status !== "needs_human" || !visual.intervention || visual.outputState?.stale
      || !proof || proof.continuationScope === "rendered_video_optional_review"
      || visual.intervention.evidenceId) return false;
    const evidence = await currentInternalDeliveryEvidence(run, effectiveProductionBrief(run), this.store.runDirectory(run.id));
    Object.assign(visual.intervention, { reviewStatus: "incomplete", providerOutcomeKnown: true,
      evidenceId: contentSha256(evidence) });
    run.interventions = run.interventions.map(item => item.id === visual.intervention!.id ? visual.intervention! : item);
    return true;
  }

  private async captureOptionalReviewDiagnostics(run: WorkflowRun<ProductionBrief>): Promise<void> {
    await this.bindSettledVisualReviewGate(run);
    const node = run.nodeRuns.find(item => item.nodeId === "creative-planning");
    const output = node && effectiveNodeOutput(node);
    const review = isObjectRecord(output?.creativeReview) ? output.creativeReview as unknown as CreativeReviewState : undefined;
    const stage = review?.activeStage;
    if (node?.status !== "running" && stage && review.stages[stage]?.continuation && output?.draftArtifactId) {
      await this.persistCreativeContinuationEvidence(run, stage);
    }
    const visual = run.nodeRuns.find(item => item.nodeId === "visual-review");
    const visualOutput = visual && effectiveNodeOutput(visual);
    if (visual && visual.status !== "running" && visual.status !== "stale" && !visual.outputState?.stale
      && visualOutput?.continuationScope === "rendered_video_optional_review") {
      await persistRenderedContinuationEvidence(run, visual, this.store.runDirectory(run.id), this.clock());
    }
    // 本地采用会换 node.operationRequestId，但不会把原可选审计结清。
    const originalTasks = await originalOptionalReviewTasks(run, this.store.runDirectory(run.id));
    for (const item of run.nodeRuns) {
      if (originalTasks.some(task => task.nodeId === item.nodeId && task.requestState === "unknown")) {
        item.outcomeUncertain = true;
      }
    }
  }

  async originalOptionalReviewTasks(runId: string): Promise<OriginalOptionalReviewTask[]> {
    return originalOptionalReviewTasks(await this.loadPersisted(runId), this.store.runDirectory(runId));
  }

  async assertOptionalReviewContinuationSafe(runId: string): Promise<void> {
    const run = await this.loadPersisted(runId);
    const blocked = await blockingUncertainNode(run, this.store.runDirectory(runId));
    if (blocked) throw new HumanDecisionConflictError(`原请求结果仍在核实（${blocked.nodeId}），请先查询原请求；不能把生成或身份不明的未知当成可选审计。`);
  }

  async recordOptionalReviewObservation(runId: string, observation: OptionalReviewObservation): Promise<WorkflowRun<ProductionBrief>> {
    return this.runPersistedTransition(runId, (previous, checkpoint) =>
      this.applyOptionalReviewObservation(previous, observation, checkpoint), undefined, true);
  }

  /** 已持有原run租约的两种查询入口共用落账，不重新取得租约或运行规划图。 */
  private async applyOptionalReviewObservation(
    previous: WorkflowRun<ProductionBrief>, observation: OptionalReviewObservation,
    checkpoint: (run: WorkflowRun<ProductionBrief>) => Promise<void>,
  ): Promise<WorkflowRun<ProductionBrief>> {
      const runId = previous.id;
      const runRoot = this.store.runDirectory(runId);
      const original = (await originalOptionalReviewTasks(previous, runRoot)).find(task =>
        task.nodeId === observation.nodeId && task.purpose === observation.purpose && task.operationId === observation.operationId
        && task.requestId === observation.requestId && task.targetVersionId === observation.targetVersionId && task.inputDigest === observation.inputDigest);
      if (!original) throw new HumanDecisionConflictError("原审计操作身份不匹配，查询结果不会附到其它版本。");
      if (original.requestState === "settled" && observation.requestState !== "settled") return previous;
      const priorResult = previous.artifacts.find(artifact => artifact.schemaVersion === "video-factory/optional-review-observation-v1"
        && isObjectRecord(artifact.data) && artifact.data.operationId === observation.operationId && artifact.data.requestId === observation.requestId
        && artifact.data.targetVersionId === observation.targetVersionId && artifact.data.inputDigest === observation.inputDigest
        && artifact.data.resultState === "valid");
      if (isObjectRecord(priorResult?.data) && observation.resultState === "valid" && !isDeepStrictEqual(priorResult.data.result, observation.result)) {
        throw new HumanDecisionConflictError("同一审计操作的结论不一致，已拒收新结果；原报告和用户决定保留。");
      }
      const next = structuredClone(previous);
      if (observation.purpose === "creative_audit" && observation.requestState === "settled" && observation.resultState === "valid") {
        const accepted = await this.recordObservedCreativeAudit(next, original, observation.result);
        if (!accepted) observation = { ...observation, resultState: "unusable" };
      }
      const data = { version: "video-factory/optional-review-observation-v1", runId, ...observation };
      const digest = contentSha256(data), id = `optional-observation-${digest}`;
      if (previous.artifacts.some(artifact => artifact.id === id)) {
        await this.syncObservedCreativeAuditHistory(previous);
        return previous;
      }
      const uri = path.join(runRoot, "nodes", observation.nodeId, "optional-review-evidence", `${digest}.json`);
      const content = stableJson(data);
      await mkdir(path.dirname(uri), { recursive: true });
      await writeTextAtomically(uri, content);
      // 无变化通道以对象身份识别重放；新观察必须返回新快照，不能原地改后被当作只读重放。
      next.artifacts.push({ id, kind: "review_diagnostic", data, uri, sha256: digest, sizeBytes: Buffer.byteLength(content),
        contentType: "application/json", schemaVersion: data.version, createdAt: this.clock(),
        producer: { nodeId: observation.nodeId, attempt: 1 }, provenance: { providerId: "host-original-review-observation" } });
      // 新观察只结清原请求事实；当前有效成果、签字风险快照和下游输出都保持原样。
      const tasks = await originalOptionalReviewTasks(next, runRoot);
      for (const node of next.nodeRuns) {
        if (!node.outcomeUncertainOperationIds?.length) continue;
        node.outcomeUncertainOperationIds = node.outcomeUncertainOperationIds.filter(operationId => {
          const matches = tasks.filter(task => task.nodeId === node.nodeId && task.operationId === operationId);
          return !matches.length || matches.some(task => task.requestState === "unknown");
        });
        if (!node.outcomeUncertainOperationIds.length) { delete node.outcomeUncertainOperationIds; delete node.outcomeUncertain; }
      }
      next.revision++;
      // 先把原报告及本版意见耐久写入唯一run事实，再同步图缓存；反序会留下幽灵意见。
      await checkpoint(next);
      await this.options.reviewContinuationFailpoints?.afterObservationCheckpoint?.();
      await this.syncObservedCreativeAuditHistory(next);
      return next;
  }

  /** 旧版本的审计只观察原信封；新承诺/稿件已生效时不得再用旧resume覆盖当前停点。 */
  private async observeDetachedCreativeAudit(
    previous: WorkflowRun<ProductionBrief>, operation: NonNullable<WorkflowRun["creativeReviewOperations"]>[number],
    checkpoint: (run: WorkflowRun<ProductionBrief>) => Promise<void>,
  ): Promise<WorkflowRun<ProductionBrief>> {
    const versionId = operation.request?.baseDraftVersionId;
    const draftSha256 = operation.request?.baseDraftSha256;
    const node = previous.nodeRuns.find(item => item.nodeId === "creative-planning");
    if (!node || typeof versionId !== "string" || typeof draftSha256 !== "string") {
      throw new HumanDecisionConflictError("原审计缺少完整版本身份，请从原请求核对入口查询；当前稿不变，不会重发。");
    }
    const runRoot = this.store.runDirectory(previous.id);
    const auditOperationId = contentSha256({ runId: previous.id, stage: operation.stage, versionId,
      draftSha256, commandId: operation.commandId, source: "manual" });
    const bound = await boundOptionalTextOperations(runRoot, node, "creative_audit", draftSha256, auditOperationId);
    const requestIds = new Set<string>();
    for (const item of bound) {
      const source = JSON.parse(await readFile(path.join(runRoot, item.sourceRelativePath), "utf8"));
      if (source.optionalReviewTarget?.auditOperationId === auditOperationId) requestIds.add(item.operation.requestId);
    }
    const tasks = (await originalOptionalReviewTasks(previous, runRoot)).filter(task => task.purpose === "creative_audit"
      && task.targetVersionId === versionId && task.requestId && requestIds.has(task.requestId));
    if (!tasks.length || tasks.some(task => !task.prepared)) {
      throw new HumanDecisionConflictError("原审计的请求证据不完整，结果和费用仍待核实；当前稿不变，不会重新发送。");
    }
    let current = previous;
    // 一次命令查询只有一个逻辑revision；多候选观察与最终回执都在同一租约内补齐。
    const persist = async (run: WorkflowRun<ProductionBrief>) => {
      run.revision = previous.revision + 1;
      await checkpoint(run);
    };
    let completed = true;
    let valid = true;
    let allNotAccepted = true;
    for (const task of tasks) {
      const { prepared, ...identity } = task;
      const client = new CodexBridgeClient({ socketPath: prepared!.route.socketPath, timeoutMs: 3_000, maxAttempts: 1 });
      const observed = await client.observePreparedOnce(prepared!, { timeoutMs: 3_000 });
      const requestState = observed.state === "not_accepted" ? "not_accepted"
        : observed.state === "completed_success" || observed.state === "completed_failure" ? "settled" : "unknown";
      const resultState = observed.state === "completed_success" ? "valid" : observed.state === "completed_failure" ? "unusable"
        : observed.state === "conflict" ? "conflict" : "absent";
      current = await this.applyOptionalReviewObservation(current, { ...identity, requestState, resultState,
        ...(observed.state === "completed_success" ? { result: observed.execution.output } : {}) }, persist);
      const saved = (await originalOptionalReviewTasks(current, runRoot)).find(item => item.nodeId === task.nodeId
        && item.purpose === task.purpose && item.requestId === task.requestId && item.operationId === task.operationId
        && item.targetVersionId === task.targetVersionId && item.inputDigest === task.inputDigest);
      if (!saved) throw new HumanDecisionConflictError("原审计观察落账后缺少对应请求事实，不会写入终态回执。");
      // 已结清的耐久事实不因本次查询暂不可用而退回待核；三项汇总必须用同一来源。
      completed &&= saved.requestState !== "unknown";
      allNotAccepted &&= saved.requestState === "not_accepted";
      valid &&= saved.resultState === "valid";
    }
    if (!completed) return current;
    const next = structuredClone(current);
    const receipt = next.creativeReviewOperations!.find(item => item.commandId === operation.commandId)!;
    receipt.status = valid ? "completed" : allNotAccepted ? "not_accepted" : "failed";
    receipt.resultDisposition = "recorded_not_applied";
    receipt.finishedAt = this.clock();
    await persist(next);
    return next;
  }

  /** 旧恢复动作只改run而未改图；仅凭当前登记的终态证据修正，不能用历史失败豁免unknown。 */
  private async reopenPreservedPlanningGeneration(run: WorkflowRun<ProductionBrief>): Promise<CreativeReviewState | undefined> {
    const node = run.nodeRuns.find(item => item.nodeId === "creative-planning");
    if (!node?.error || !isObjectRecord(node.output) || !isObjectRecord(node.output.creativeReview)) return undefined;
    const review = node.output.creativeReview as unknown as CreativeReviewState;
    const draft = review.stages[review.activeStage]?.currentDraft;
    const inputDigest = await this.planningAuditInputDigest(run);
    if (!draft || !inputDigest) return undefined;
    const store = CreativePlanningStore.open(path.dirname(this.runsRoot));
    try {
      const graph = createInspectionPlanningGraph(store, effectiveProductionBrief(run).workflowFeatures?.assetSemanticRank === true);
      const snapshot = await graph.getState(store.threadConfig(run.id, inputDigest));
      const state = snapshot.values as Partial<PlanningGraphState>;
      const actual = state.creativeReview;
      if (!actual || actual.stages[review.activeStage]?.currentDraft?.versionId !== draft.versionId
        || actual.stages[review.activeStage]?.currentDraft?.sha256 !== draft.sha256) return undefined;
      if (snapshot.next.length !== 1 || !["script", "director", `${review.activeStage}_review`].includes(snapshot.next[0]!)) return undefined;
      // 真正的人工停点无须迁移；允许从图已恢复、run尚未落盘的窗口继续。
      if (snapshot.next[0] === `${review.activeStage}_review` && actual.reviewRevision === review.reviewRevision) return undefined;
      const version = node.outputState?.versions.find(item => item.id === node.outputState?.effectiveVersionId);
      const trace = run.artifacts.find(item => (version?.artifactIds ?? node.artifactIds).includes(item.id)
        && item.kind === "agent_loop_trace" && item.producer?.nodeId === node.nodeId);
      let settled = false;
      if (trace?.uri) {
        await verifyStoredArtifactWithinRoot(this.store.runDirectory(run.id), trace);
        const failure = JSON.parse(await readFile(trace.uri, "utf8")) as { failure?: { stage?: string } };
        settled = failure.failure?.stage === "completed_failure";
      } else {
        // 旧 joint 包装异常没有登记 loop artifact；必须核本次操作的全部候选 checkpoint，
        // 不能拿外层 command.failed 或历史单个请求替当前所有请求签收。
        settled = await hasSettledPlanningGenerationCheckpoints(this.store.runDirectory(run.id), run, review.activeStage);
      }
      if (!settled) {
        throw new HumanDecisionConflictError("下游生成的原结果尚未核清，请先核对原请求；当前稿已保留，不会重新发送。");
      }
      await assertNoUnresolvedPlanningTask(this.store.runDirectory(run.id), run);
      const restored = await reopenPlanningGenerationGate(graph, run.id, inputDigest,
        { stage: review.activeStage, versionId: draft.versionId, sha256: draft.sha256 });
      if (!restored) throw new HumanDecisionConflictError("保留稿与后台停点不一致，请核对当前版本；没有重新生成。");
      node.output = { ...node.output, creativeReview: restored.creativeReview, planningStop: restored.planningStop };
      // 此处是修复恢复快照，不改稿件版本；命令执行或准备动作随后仍按原事务落盘。
      if (version) version.output = structuredClone(node.output);
      if (node.intervention?.continuation) node.intervention.continuation.reviewRevision = restored.creativeReview.reviewRevision;
      return restored.creativeReview;
    } finally { store.close(); }
  }

  private async planningAuditInputDigest(run: WorkflowRun<ProductionBrief>): Promise<string | undefined> {
    const node = run.nodeRuns.find(item => item.nodeId === "creative-planning");
    const input = node?.inputState?.versions.find(item => item.id === node.inputState!.effectiveVersionId)?.value;
    if (!isObjectRecord(input) || !isObjectRecord(input.brief)) return undefined;
    const brief = effectiveProductionBrief(run);
    const grammar = brief.workflowFeatures?.referenceGrammar && typeof input.referenceGrammarPath === "string"
      ? await readShotGrammarFile(input.referenceGrammarPath) : undefined;
    return jointPlanningInputDigest(mergeCurrentBrief(input.brief, brief), grammar);
  }

  /** 查询不运行角色或图节点；有效晚到报告只登记原版，未采用的当前版才更新意见停点。 */
  private async recordObservedCreativeAudit(run: WorkflowRun<ProductionBrief>, task: OriginalOptionalReviewTask, result: unknown): Promise<boolean> {
    const node = run.nodeRuns.find(item => item.nodeId === task.nodeId)!;
    const ref = node.optionalReviewOperationRefs?.find(item => item.operationId === task.operationId && item.requestId === task.requestId);
    const proof = run.artifacts.find(item => item.id === ref?.continuationEvidenceArtifactId)?.data as OptionalReviewContinuationEvidence | undefined;
    const stage = proof?.stage;
    const payload = task.prepared?.envelope.payload;
    if (!stage || !proof || !isObjectRecord(payload) || contentSha256(payload.candidate) !== proof.target.sha256) return false;
    let audit: RoleAudit;
    try { audit = validateRoleAudit(result, { planningRole: true, role: String(payload.role), candidate: payload.candidate,
      ...(isObjectRecord(payload.hostReadiness) ? { hostReadiness: payload.hostReadiness as unknown as HostPlanningReadiness } : {}) }); }
    catch { return false; }
    const fact = proof.requestFacts.find(item => item.operationId === task.operationId && item.requestId === task.requestId)!;
    const index = fact.evidenceArtifactIds.map(id => run.artifacts.find(item => item.id === id)?.data).find(item =>
      isObjectRecord(item) && typeof item.sourceRelativePath === "string") as {
        sourceRelativePath: string; planningInputDigest?: string; auditSource?: "initial" | "manual";
      } | undefined;
    if (!index) return false;
    const runRoot = await realpath(this.store.runDirectory(run.id));
    const checkpointPath = await realpath(path.resolve(runRoot, index.sourceRelativePath));
    if (!checkpointPath.startsWith(`${runRoot}${path.sep}`)) throw new HumanDecisionConflictError("原审计记录超出制作目录。");
    const checkpoint = JSON.parse(await readFile(checkpointPath, "utf8"));
    const auditOperationId = checkpoint.optionalReviewTarget?.auditOperationId;
    if (typeof auditOperationId !== "string" || checkpoint.optionalReviewTarget.stage !== stage) return false;
    const output = node.output as Record<string, unknown>;
    const reviewKey = isObjectRecord(output.creativeReview) ? "creativeReview" : "creativeReviewHistory";
    const review = output[reviewKey] as CreativeReviewState | undefined;
    const gate = review?.stages[stage];
    if (!review || !gate) return false;
    const target = gate.currentDraft?.versionId === proof.target.versionId ? gate.currentDraft
      : gate.versionHistory.find(item => item.draft.versionId === proof.target.versionId)?.draft;
    if (!target || target.sha256 !== proof.target.sha256) return false;
    const source = index.auditSource ?? (run.creativeReviewOperations?.some(operation => isObjectRecord(operation.resume) && operation.resume.action === "audit_current"
      && contentSha256({ runId: run.id, stage, versionId: target.versionId, draftSha256: target.sha256,
        commandId: operation.commandId, source: "manual" }) === auditOperationId) ? "manual" : "initial");
    const graphDigest = index.planningInputDigest ?? await this.planningAuditInputDigest(run);
    if (!graphDigest) return false;
    const check = { versionId: target.versionId, draftSha256: target.sha256, auditId: `audit-${contentSha256({ auditOperationId })}`,
      checkIdentity: planningAuditCheckIdentity({ runId: run.id, inputDigest: graphDigest, stage, candidateSha256: target.sha256,
        auditModelId: task.prepared!.brokerBinding.modelId,
        contractVersion: stage === "treatment" ? CREATIVE_TREATMENT_AGENT_CONTRACT_VERSION
          : stage === "script" ? SCREENWRITER_AGENT_CONTRACT_VERSION : VISUAL_DIRECTOR_AGENT_CONTRACT_VERSION }),
      verdict: audit.verdict, score: audit.score, summary: audit.summary, issues: structuredClone(audit.issues) };
    const recorded = gate.auditHistory.find(item => item.auditId === check.auditId);
    if (recorded) {
      if (recorded.versionId !== target.versionId || recorded.draftSha256 !== target.sha256 || recorded.source !== source
        || recorded.result.verdict !== check.verdict || recorded.result.score !== check.score
        || recorded.result.summary !== check.summary || !isDeepStrictEqual(recorded.result.issues, check.issues)) {
        throw new HumanDecisionConflictError("同一审计操作的结论与已保存记录不一致，已拒收新结果。");
      }
      return true;
    }
    const active = node.status === "needs_human" && review.activeStage === stage && gate.phase === "waiting_user"
      && gate.currentDraft?.versionId === target.versionId && !gate.confirmation;
    let updated: CreativeReviewState;
    if (active) {
      updated = recordCreativeReviewCheck(review, stage, check, { source, recordedAt: this.clock() });
    } else {
      updated = { ...review, stages: { ...review.stages, [stage]: { ...gate, auditHistory: [...gate.auditHistory,
        { auditId: check.auditId, versionId: target.versionId, draftSha256: target.sha256, checkIdentity: check.checkIdentity,
          result: check, source, recordedAt: this.clock() }] } } };
    }
    node.output = { ...output, [reviewKey]: updated };
    if (active) {
      node.intervention!.continuation!.reviewRevision = updated.reviewRevision;
      const intervention = run.interventions.find(item => item.id === node.intervention!.id);
      if (intervention?.continuation) intervention.continuation.reviewRevision = updated.reviewRevision;
      const version = node.outputState?.versions.find(item => item.id === node.outputState!.effectiveVersionId);
      if (version) version.output = structuredClone(node.output);
    }
    return true;
  }

  /** 原报告观察中断后，以耐久run修复同线程缓存，不invoke、不生成、不改变游标。 */
  private async syncObservedCreativeAuditHistory(run: WorkflowRun<ProductionBrief>): Promise<void> {
    const node = run.nodeRuns.find(item => item.nodeId === "creative-planning");
    const output = node?.output;
    const review = isObjectRecord(output) ? (output.creativeReview ?? output.creativeReviewHistory) as CreativeReviewState | undefined : undefined;
    if (!review || !run.artifacts.some(item => item.schemaVersion === "video-factory/optional-review-observation-v1")) return;
    const digest = await this.planningAuditInputDigest(run);
    if (!digest) return;
    const brief = effectiveProductionBrief(run);
    const store = CreativePlanningStore.open(path.dirname(this.runsRoot));
    try {
      const graph = createInspectionPlanningGraph(store, brief.workflowFeatures?.assetSemanticRank === true);
      const config = store.threadConfig(run.id, digest);
      const graphReview = ((await graph.getState(config)).values as Partial<PlanningGraphState>).creativeReview;
      if (graphReview?.activeStage === review.activeStage
        && graphReview.stages[review.activeStage].currentDraft?.versionId === review.stages[review.activeStage].currentDraft?.versionId
        && !isDeepStrictEqual(graphReview, review)) await graph.updateState(config, { creativeReview: review });
    } finally { store.close(); }
  }

  /** 审计是当前稿的附属记录，不是换稿；不得增加内容版本、撤销下游或代替人工确认。 */
  async recordNodeDocumentAudit(runId: string, draft: ProductionNodeDocumentAuditDraft): Promise<WorkflowRun<ProductionBrief>> {
    return this.runPersistedTransition(runId, async (previous) => {
      if (draft.nodeId !== "publish-package" && draft.nodeId !== "reference-grammar") {
        throw new Error("Only creator-facing document nodes support a document audit.");
      }
      if (!draft.actor.trim() || !draft.auditId.trim()) throw new Error("Document audit identity is required.");
      const historicalAudit = previous.nodeRuns.find((item) => item.nodeId === draft.nodeId)?.outputState?.versions.flatMap((version) => {
        const review = isObjectRecord(version.output) && isObjectRecord(version.output.contentReview) ? version.output.contentReview : undefined;
        return [...(review ? [review] : []), ...(Array.isArray(review?.history) ? review.history.filter(isObjectRecord) : [])];
      }).find((record) => record.auditId === draft.auditId);
      if (draft.documentCommandId && historicalAudit) {
        if (historicalAudit.versionId !== draft.expectedVersionId || JSON.stringify(historicalAudit.audit) !== JSON.stringify(draft.audit)) {
          throw new DocumentCommandConflictError("同一审计操作的结果不一致，不能改写已保存记录。");
        }
        return previous;
      }
      if (previous.revision !== draft.expectedRunRevision) {
        throw new StaleRunRevisionError(runId, draft.expectedRunRevision, previous.revision);
      }
      if (previous.status === "running") {
        throw new Error("Resolve the running or uncertain task before recording a document audit.");
      }
      await verifiedOptionalReviewInvalidationOperations(previous, this.store.runDirectory(runId));
      const next = structuredClone(previous);
      const node = next.nodeRuns.find((item) => item.nodeId === draft.nodeId);
      const version = node?.outputState?.versions.find((item) => item.id === node.outputState?.effectiveVersionId);
      if (!node || !version || version.id !== draft.expectedVersionId || node.outputState?.stale || node.inputState?.stale) {
        throw new NodeVersionConflictError(draft.nodeId, draft.expectedVersionId, node?.outputState?.effectiveVersionId ?? "");
      }
      const output = version.output ?? node.output;
      if (!isObjectRecord(output)) throw new Error("Document output is not available for auditing.");
      const previousReview = isObjectRecord(output.contentReview) ? output.contentReview : undefined;
      const history = Array.isArray(previousReview?.history) ? structuredClone(previousReview.history)
        : previousReview && previousReview.status !== "not_audited"
          ? [{ ...structuredClone(previousReview), versionId: version.id }]
          : [];
      const record = {
        versionId: version.id, auditId: draft.auditId, auditedAt: this.clock(), actor: draft.actor,
        status: draft.audit.verdict === "pass" ? "passed" : "has_suggestions",
        score: draft.audit.score, summary: draft.audit.summary,
        suggestions: draft.audit.issues.map((issue) => issue.creatorAction ?? issue.repairInstruction).filter(Boolean),
        audit: structuredClone(draft.audit),
      };
      const updatedOutput = { ...output, contentReview: { ...record, history: [...history, record] } };
      version.output = updatedOutput;
      node.output = updatedOutput;
      next.revision += 1;
      return next;
    }, draft.documentCommandId);
  }

  async applyNodeOverride(runId: string, override: NodeOverrideDraft): Promise<WorkflowRun<ProductionBrief>> {
    return this.runPersistedTransition(runId, async (previous) => {
      if (override.documentCommandId) {
        if (!override.documentResultSha256 || !/^[a-f0-9]{64}$/.test(override.documentResultSha256)) {
          throw new DocumentCommandConflictError("文字操作缺少可核对的结果身份。");
        }
        const committed = previous.nodeRuns.find((node) => node.nodeId === override.nodeId)?.outputState?.versions.find(
          (version) => version.documentCommand?.commandId === override.documentCommandId,
        );
        if (committed) {
          if (committed.documentCommand?.resultSha256 !== override.documentResultSha256) {
            throw new DocumentCommandConflictError("同一文字操作的结果不一致，不能覆盖已保存稿件。");
          }
          return previous;
        }
      }
      if (override.expectedRunRevision !== undefined && override.expectedRunRevision !== previous.revision) {
        throw new StaleRunRevisionError(runId, override.expectedRunRevision, previous.revision);
      }
      await verifyNodeOverrideBoundary(this.store.runDirectory(runId), override);
      const brief = parsePersistedBrief(previous.initialInput);
      let effectiveOverride = override.nodeId === "visual-direction"
        ? await this.prepareVisualDirectionOverride(previous, override)
        : override;
      if (override.nodeId === "brief" && override.output !== undefined) {
        const node = previous.nodeRuns.find((candidate) => candidate.nodeId === "brief");
        const base = node ? effectiveNodeOutput(node) : null;
        // 内容编辑只能沿用当前交付的配置快照；保存时再绑定已单独确认的新配置，
        // 避免换源后无法改文，或让旧快照回滚供应商、模型和费用限制。
        const content = validateBriefInputOverride(override.output, base ? parsePersistedBrief(base) : brief);
        effectiveOverride = { ...override, output: mergeCurrentBrief(content, brief) };
      }
      const runner = new WorkflowRunner({
        optionalReviewInvalidationOperations: await verifiedOptionalReviewInvalidationOperations(previous, this.store.runDirectory(runId)),
        providers: this.createRegistry(brief),
        clock: this.clock,
        idFactory: this.idFactory,
      });
      const next = runner.applyNodeOverride(this.createWorkflow(brief), withExecutableBrief(previous, brief), effectiveOverride);
      if (override.documentCommandId && override.documentResultSha256) {
        const revised = next.nodeRuns.find((node) => node.nodeId === override.nodeId)!;
        const state = revised.outputState!;
        state.versions.find((version) => version.id === state.effectiveVersionId)!.documentCommand = {
          commandId: override.documentCommandId, resultSha256: override.documentResultSha256,
        };
        if (override.nodeId === "publish-package" && boundaryGatesEnabled(brief)
          && previous.nodeRuns.find(node => node.nodeId === override.nodeId)?.status === "succeeded") {
          // 用户授权生成新文案，不等于已经读过并采用新稿；原成片和独立终审保持有效。
          revised.status = "needs_human";
          delete revised.finishedAt;
          revised.intervention = { id: `document-review-${contentSha256(override.documentCommandId)}`,
            nodeId: revised.nodeId, createdAt: this.clock(), boundary: "node-complete",
            reason: "文案修订版已保存，请阅读后决定是否采用。原成片与终审记录保持不变。",
            requiredAction: "approve", options: ["approve", "reject"] };
          next.interventions = [...next.interventions.filter(item => item.nodeId !== revised.nodeId), revised.intervention];
          next.status = "needs_human";
          delete next.finishedAt;
        }
      }
      return next;
    }, override.documentCommandId);
  }

  async previewNarrationPlan(runId: string): Promise<NarrationPlanPreview> {
    const run = await this.store.load<ProductionBrief>(runId);
    const context = await this.narrationPlanContext(run, { readOnly: true });
    if (context.editorMode !== "pre_generation" && !context.characterScript) {
      const legacy = await this.legacyNarrationSource(run, context).catch(error => ({
        unavailable: error instanceof Error ? error.message : "旧声音来源暂不能核验。",
      }));
      if (legacy) return { expectedRunRevision: run.revision, confirmed: false,
        sourceContextId: this.narrationSourceContextIdV2(run, context, this.voiceProviderConfigDigest(run, context)),
        plan: "unavailable" in legacy ? context.plan : legacy.plan,
        ...("unavailable" in legacy ? { legacySourceUnavailableReason: legacy.unavailable } : { legacySource: legacy.source }),
        editorContext: { mode: context.editorMode, defaultPlan: context.plan, baseGroups: [], savedPlanStatus: "none" } };
    }
    const voiceConfig = providerConfigs(parsePersistedBrief(run.initialInput), this.options).find((config) => config.nodeId === "voice")!;
    const quoteFor = async (plan: SupportedNarrationPlan) => {
      try {
        return await this.options.worker.forecastPaidVoiceSpend?.({ runId, nodeDirectory: path.join(this.runsRoot, runId, "nodes", "voice"),
          input: { ...context.voiceInput, narrationPlan: plan },
          parameters: { ...voiceConfig.parameters, providerId: voiceConfig.id, modelId: voiceConfig.metadata?.modelId } });
      } catch {
        // 只把本地forecast边界的不可用降级为未知价；来源、文件与身份错误仍在此前/下方明确抛出。
        return undefined;
      }
    };
    const node = run.nodeRuns.find((candidate) => candidate.nodeId === "voice");
    const inputVersion = node?.inputState?.versions.find((version) => version.id === node.inputState?.effectiveVersionId);
    const input = inputVersion?.value;
    const providerConfigDigest = this.voiceProviderConfigDigest(run, context);
    const sourceContextId = this.narrationSourceContextIdV2(run, context, providerConfigDigest);
    const baseGroups = (context.characterScript ? [] : deriveV2SourceFacts(context.scenes).baseGroups).map((group) => ({
      baseGroupId: group.baseGroupId,
      text: group.canonicalText,
      endCodePoint: group.endCodePoint,
      frameRange: { ...group.frameRange },
      allowedBoundaries: sentenceBoundaryCandidatesV2(group.canonicalText)
        .filter((boundary) => boundary > 0 && boundary < group.endCodePoint),
    }));
    let savedPlanStatus: "none" | "current" | "stale" = "none";
    let savedPlan: SupportedNarrationPlan | undefined;
    if (isObjectRecord(input) && typeof input.narrationPlanPath === "string") {
      const artifact = run.artifacts.find((candidate) => candidate.kind === "narration_plan" && candidate.uri === input.narrationPlanPath);
      if (!artifact) throw new HumanDecisionConflictError("已确认旁白方案的留档缺失，请先核查原记录。");
      const savedSourceContextId = typeof input.sourceContextId === "string" ? input.sourceContextId : "";
      const identityCurrent = !node?.inputState?.stale
        && isDeepStrictEqual(inputVersion?.upstreamVersionIds ?? [], context.upstreamVersionIds)
        && (!["video-factory/narration-plan-v2", CHARACTER_NARRATION_PLAN_VERSION].includes(inputVersion?.schemaVersion ?? "")
          || savedSourceContextId === sourceContextId);
      savedPlanStatus = identityCurrent ? "current" : "stale";
      try {
        await verifyStoredArtifactWithinRoot(this.store.runDirectory(runId), artifact);
        const persistedPlan: unknown = JSON.parse(await readFile(input.narrationPlanPath, "utf8"));
        let savedCharacterScript = context.characterScript;
        let savedSources = {
          scenes: context.scenes, scriptSha256: context.scriptArtifact.sha256,
          visualSha256: context.visualArtifact.sha256,
        };
        if (!identityCurrent) {
          // 旧计划只能按其输入版本绑定的历史来源核验；用新来源比较会把正常失效误判成损坏，
          // 堵住重新确认出口。历史文件仍须通过同一 run 内的路径、字节与摘要核验。
          const oldScript = run.artifacts.find((item) => item.kind === "script" && item.uri === input.scriptPath);
          const oldVisual = run.artifacts.find((item) => item.kind === "executable_plan" && item.uri === input.executablePlanPath);
          if (!oldScript?.sha256 || !oldVisual?.sha256) {
            throw new HumanDecisionConflictError("旧旁白方案的历史稿件或画面留档缺失，请先核查原记录。");
          }
          await Promise.all([oldScript, oldVisual].map((item) => verifyStoredArtifactWithinRoot(this.store.runDirectory(runId), item)));
          const script = requireOutputRecord(JSON.parse(await readFile(oldScript.uri!, "utf8")), "saved narration script");
          const visual = parseExecutableProductionPlan(JSON.parse(await readFile(oldVisual.uri!, "utf8")));
          if (!Array.isArray(script.scenes) || script.scenes.length !== visual.cuts.length) {
            throw new HumanDecisionConflictError("旧旁白方案的历史稿件与画面镜头数量不一致。");
          }
          savedCharacterScript = isCharacterScript(script) ? validateCharacterScriptStructure({
            ...script, scenes: script.scenes.map((scene, index) => {
              if (scene.position !== visual.cuts[index]!.scenePosition) throw new HumanDecisionConflictError("旧角色稿与画面顺序不一致。");
              return { ...scene, duration: visual.cuts[index]!.frameCount / 30 };
            }),
          }) : undefined;
          const scenes = savedCharacterScript ? [] : script.scenes.map((value, index) => {
            const scene = requireOutputRecord(value, "saved narration scene");
            const cut = visual.cuts[index]!;
            if (scene.position !== cut.scenePosition || typeof scene.narration !== "string") {
              throw new HumanDecisionConflictError("旧旁白方案的历史稿件与画面顺序不一致。");
            }
            return { position: cut.scenePosition, narration: scene.narration, duration: cut.frameCount / 30 };
          });
          savedSources = { scenes, scriptSha256: oldScript.sha256, visualSha256: oldVisual.sha256 };
        }
        if (narrationPlanVersion(persistedPlan) === CHARACTER_NARRATION_PLAN_VERSION) {
          if (!savedCharacterScript) throw new HumanDecisionConflictError("角色声音计划缺少对应的角色稿。");
          savedPlan = validateCharacterNarrationPlan(persistedPlan, { ...savedSources,
            script: savedCharacterScript, sourceContextId: savedSourceContextId });
        } else if (narrationPlanVersion(persistedPlan) === "video-factory/narration-plan-v2") {
          if (savedCharacterScript) throw new HumanDecisionConflictError("角色稿不能采用单旁白声音计划。");
          if (!savedSourceContextId.trim()) {
            throw new HumanDecisionConflictError("已保存旁白方案的来源身份缺失，请重新确认方案。");
          }
          savedPlan = validateNarrationPlanV2(persistedPlan, narrationPlanV2StandaloneInput(persistedPlan, {
            ...savedSources, sourceContextId: savedSourceContextId,
          }));
        } else {
          if (savedCharacterScript || context.plan.version !== "video-factory/narration-plan-v1") throw new HumanDecisionConflictError("角色稿不能采用单旁白声音计划。");
          savedPlan = validateNarrationPlan(persistedPlan, identityCurrent ? context.plan
            : buildNarrationPlan(savedSources.scenes, savedSources.scriptSha256, savedSources.visualSha256));
        }
      } catch (error) {
        if (error instanceof HumanDecisionConflictError || error instanceof NarrationTextV2Error) throw error;
        throw new HumanDecisionConflictError("已确认旁白方案的留档无法核验（可能已损坏或来源已变化），请先核查原记录后重新确认。");
      }
    }
    const plan = savedPlanStatus === "current" && savedPlan ? savedPlan : context.plan;
    const quote = await quoteFor(plan);
    return {
      expectedRunRevision: run.revision,
      confirmed: savedPlanStatus === "current",
      sourceContextId,
      plan,
      ...(quote ? { quote } : {}),
      editorContext: {
        mode: context.editorMode,
        defaultPlan: context.plan,
        ...(context.characterScript ? { characters: context.characterScript.characters.map((c) => ({
          id: c.id, name: c.name, voiceProfileId: c.voice_profile_id,
          ...(this.options.characterVoiceProfiles?.find((voice) => voice.id === c.voice_profile_id)?.label
            ? { voiceLabel: this.options.characterVoiceProfiles.find((voice) => voice.id === c.voice_profile_id)!.label } : {}),
        })) } : {}),
        baseGroups,
        savedPlanStatus,
        ...(savedPlanStatus === "stale" && savedPlan ? { stalePlan: savedPlan } : {}),
      },
    };
  }

  async confirmNarrationPlan(runId: string, draft: {
    expectedRunRevision: number; plan: unknown; actor: string;
  }): Promise<WorkflowRun<ProductionBrief>> {
    return this.runPersistedTransition(runId, async (previous) => {
      if (previous.revision !== draft.expectedRunRevision) {
        throw new StaleRunRevisionError(runId, draft.expectedRunRevision, previous.revision);
      }
      if (!draft.actor.trim()) throw new HumanDecisionConflictError("采用旁白方案需要创作者身份。");
      const context = await this.narrationPlanContext(previous);
      if (context.plan.version !== "video-factory/narration-plan-v1") {
        throw new HumanDecisionConflictError("角色声音计划须先预览，再凭同一票据保存。");
      }
      const plan = validateNarrationPlan(draft.plan, context.plan);
      const content = `${JSON.stringify(plan, null, 2)}\n`;
      const sha256 = createHash("sha256").update(content).digest("hex");
      const directory = path.join(this.store.runDirectory(runId), "nodes", "voice", "plans");
      await mkdir(directory, { recursive: true });
      const planPath = path.join(directory, `${sha256}.json`);
      await writeTextAtomically(planPath, content);
      const next = structuredClone(previous);
      const node = next.nodeRuns.find((candidate) => candidate.nodeId === "voice") ?? {
        nodeId: "voice", role: "声音导演", status: "pending" as const, startedAt: this.clock(), artifactIds: [], qualityGateResults: [],
      };
      if (!next.nodeRuns.includes(node)) next.nodeRuns.push(node);
      const artifactId = this.idFactory("artifact");
      next.artifacts.push({ id: artifactId, kind: "narration_plan", uri: planPath, sha256,
        sizeBytes: Buffer.byteLength(content), contentType: "application/json", schemaVersion: plan.version,
        parentArtifactIds: context.parentArtifactIds, createdAt: this.clock(), producer: { nodeId: "voice", attempt: 0 },
        provenance: { providerId: "creator-narration-plan-v1", providerVersion: "1" } });
      const versionId = this.idFactory("input-version");
      node.inputState = { nodeId: "voice", effectiveVersionId: versionId, stale: false, versions: [
        ...(node.inputState?.versions ?? []), { id: versionId, nodeId: "voice", source: "derived", createdAt: this.clock(),
          createdBy: draft.actor, schemaVersion: plan.version, upstreamVersionIds: context.upstreamVersionIds,
          ...(node.inputState ? { parentVersionId: node.inputState.effectiveVersionId } : {}),
          value: { ...context.voiceInput, narrationPlanPath: planPath, voiceInputVersionId: versionId } },
      ] };
      // 只保存下一步的声音输入，不批准当前素材停点，也不触发配音或任何付费请求。
      next.revision += 1;
      return next;
    });
  }

  private async legacyNarrationSource(run: WorkflowRun<ProductionBrief>,
    context: Awaited<ReturnType<ProductionPipeline["narrationPlanContext"]>>) {
    const voice = run.nodeRuns.find(node => node.nodeId === "voice");
    const version = voice?.outputState?.versions.find(v => v.id === voice.outputState?.effectiveVersionId);
    if (!voice || !version || voice.outputState?.stale || voice.inputState?.stale || context.characterScript) return undefined;
    const artifact = run.artifacts.find(a => a.kind === "voiceover_plan" && version.artifactIds.includes(a.id));
    if (!artifact?.uri || !artifact.sha256) return undefined;
    await verifyStoredArtifactWithinRoot(this.store.runDirectory(run.id), artifact);
    const doc = requireOutputRecord(JSON.parse(await readFile(artifact.uri, "utf8")), "voice plan");
    if (doc.version !== "video-factory/voiceover-plan-v2") return undefined;
    const track = run.artifacts.find(a => a.kind === "voiceover" && version.artifactIds.includes(a.id) && a.uri === doc.track_path);
    if (!track?.sha256) throw new HumanDecisionConflictError("旧声音缺少对应音轨，原声音保持不变。");
    await verifyStoredArtifactWithinRoot(this.store.runDirectory(run.id), track);
    const retained = isObjectRecord(doc.legacyVoiceSource) ? doc.legacyVoiceSource : undefined;
    const origin = retained ? requireOutputRecord(retained.origin, "legacy origin") : undefined;
    const originalVersion = origin ? voice.outputState!.versions.find(v => v.id === origin.voiceVersionId) : version;
    if (!originalVersion) throw new HumanDecisionConflictError("旧声音原输入版本无法核验。");
    const originalInputs = voice.inputState?.versions.filter(v => originalVersion.inputVersionIds.includes(v.id)) ?? [];
    if (originalInputs.length !== 1) throw new HumanDecisionConflictError("旧声音原输入版本无法核验。");
    const inputVersion = originalInputs[0];
    const input = requireOutputRecord(inputVersion?.value, "legacy voice input");
    if (!inputVersion || input.narrationPlanPath !== undefined
      || input.scriptPath !== context.voiceInput.scriptPath || input.executablePlanPath !== context.voiceInput.executablePlanPath
      || !isDeepStrictEqual(inputVersion.upstreamVersionIds, context.upstreamVersionIds)
      || origin && origin.voiceInputVersionId !== inputVersion.id) {
      throw new HumanDecisionConflictError("旧声音已不对应当前稿件和画面，请先核对来源；原声音保留。");
    }
    const originalArtifact = retained ? run.artifacts.find(a => a.kind === "voiceover_plan"
      && originalVersion.artifactIds.includes(a.id) && a.uri === retained.voicePlanPath && a.sha256 === retained.voicePlanSha256) : artifact;
    if (!originalArtifact?.uri || !originalArtifact.sha256) throw new HumanDecisionConflictError("旧声音原计划留档缺失。");
    await verifyStoredArtifactWithinRoot(this.store.runDirectory(run.id), originalArtifact);
    const originalDoc = requireOutputRecord(JSON.parse(await readFile(originalArtifact.uri, "utf8")), "legacy original voice plan");
    const originalTrack = run.artifacts.find(a => a.kind === "voiceover" && originalVersion.artifactIds.includes(a.id) && a.uri === originalDoc.track_path);
    if (!originalTrack?.sha256 || retained && retained.trackSha256 !== originalTrack.sha256) throw new HumanDecisionConflictError("旧声音原音轨身份不符。");
    const operationId = origin ? requiredOutputString(origin, "sourceVoiceOperationId") : voice.operationRequestId;
    if (!operationId) throw new HumanDecisionConflictError("旧声音缺少原请求编号，不重新生成声音。");
    const verified = await inspectLegacyVoiceSource({ nodeRoot: path.join(this.store.runDirectory(run.id), "nodes", "voice"),
      source: { voicePlanPath: originalArtifact.uri, voicePlanSha256: originalArtifact.sha256, trackSha256: originalTrack.sha256,
        origin: { voiceVersionId: originalVersion.id, voiceInputVersionId: inputVersion.id, sourceVoiceOperationId: operationId } },
      scenes: context.scenes, scriptSha256: context.scriptArtifact.sha256, visualSha256: context.visualArtifact.sha256,
      ...(retained ? { currentPlan: doc.narrationPlan } : {}) });
    if (retained && retained.ledgerSha256 !== verified.files.ledgerSha256) throw new HumanDecisionConflictError("原账本已变化，请先核查原请求。");
    const source: LegacyNarrationSource = { kind: "legacy_voice_version", voiceVersionId: version.id,
      voicePlanArtifactId: artifact.id, voicePlanSha256: artifact.sha256, expectedAudioSha256: track.sha256,
      expectedNarrationPlanSha256: createHash("sha256").update(canonicalJsonV2(verified.plan)).digest("hex"), expectedLedgerSha256: verified.files.ledgerSha256,
      sourceVoiceOperationId: operationId };
    return { ...verified, source, sourceIdentity: { voiceInputVersionId: inputVersion.id,
      scriptArtifactId: context.scriptArtifact.id, scriptOutputVersionId: context.scriptArtifact.outputVersionId,
      visualArtifactId: context.visualArtifact.id, visualOutputVersionId: context.visualArtifact.outputVersionId,
      parentArtifactIds: context.parentArtifactIds, upstreamVersionIds: context.upstreamVersionIds } };
  }

  private async narrationPlanContext(run: WorkflowRun<ProductionBrief>, options?: { readOnly?: boolean }): Promise<{
    plan: NarrationPlan | CharacterNarrationPlan; characterScript?: CharacterScript;
    scenes: Array<{ position: number; narration: string; duration: number }>;
    scriptArtifact: { id: string; sha256: string; outputVersionId: string };
    visualArtifact: { id: string; sha256: string; outputVersionId: string };
    voiceInput: Record<string, unknown>; parentArtifactIds: string[]; upstreamVersionIds: string[];
    editorMode: "pre_generation" | "voice_stop" | "final_review";
  }> {
    const voice = run.nodeRuns.find((node) => node.nodeId === "voice");
    const finalReview = run.nodeRuns.find((node) => node.nodeId === "final-review");
    let editorMode: "pre_generation" | "voice_stop" | "final_review" = "pre_generation";
    const upstreamRevisionCanReconfirm = ["needs_human", "paused", "stale"].includes(run.status)
      && voice?.status === "stale"
      && !voice.operationRequestId && (!voice.outputState || voice.outputState.stale);
    if (!["needs_human", "paused", "stale"].includes(run.status) || run.nodeRuns.some((node) => node.status === "running" || node.outcomeUncertain)
      || voice && !upstreamRevisionCanReconfirm
        && (voice.status !== "pending" || voice.operationRequestId || voice.outputState && !voice.outputState.stale)) {
      // §6 首次 fit 冲突恢复：voice 停在可恢复冲突时，时间调整编辑器仍需只读读取已保存计划
      // （不签发新票据、不保存、不发 TTS——那些路径各有更严的守卫）。这里按只读放行 GET。
      if (options?.readOnly && voice?.status === "needs_human" && voice.intervention) {
        editorMode = "voice_stop";
      } else if (options?.readOnly && finalReview?.status === "needs_human" && finalReview.intervention
        && voice?.status === "succeeded" && voice.outputState && !voice.outputState.stale) {
        editorMode = "final_review";
      } else {
        throw new HumanDecisionConflictError("请在素材确认后、尚未开始配音时查看和采用旁白方案；原有配音不会被静默替换。");
      }
    }
    const brief = parsePersistedBrief(run.initialInput);
    if (brief.providers.voice !== "minimax-tts-v1") throw new HumanDecisionConflictError("连贯旁白当前支持 MiniMax 系统音色，请先选择对应的配音服务。");
    const voiceDirection = requireTtsVoiceDirection(brief);
    const outputs = new Map(run.nodeRuns.map((node) => [node.nodeId, effectiveNodeOutput(node)]));
    const planning = currentPlanningOutputPaths({ outputs }, brief);
    if (!planning.executablePlanPath) throw new HumanDecisionConflictError("正式画面方案尚未准备好，请先完成创作规划。");
    const definition = this.createWorkflow(brief).nodes.find((node) => node.id === "voice")!;
    const dependencies = (definition.dependsOn ?? []).map((id) => run.nodeRuns.find((node) => node.nodeId === id));
    if (dependencies.some((node) => !node?.outputState || node.outputState.stale
      || !["succeeded", "needs_human"].includes(node.status))) {
      throw new HumanDecisionConflictError("请先完成画面素材及其审查，再确认连贯旁白方案。");
    }
    await verifyExecutablePlanInput({ ...planning }, { runId: run.id, artifacts: run.artifacts, outputs, initialInput: run.initialInput }, this.runsRoot);
    const scriptArtifact = run.artifacts.find((artifact) => artifact.kind === "script" && artifact.uri === planning.scriptPath);
    const visualArtifact = run.artifacts.find((artifact) => artifact.kind === "executable_plan" && artifact.uri === planning.executablePlanPath);
    if (!scriptArtifact?.sha256 || !visualArtifact?.sha256) throw new HumanDecisionConflictError("正式稿件缺少可核对的产物身份。");
    const effectiveProducerVersionId = (artifact: Artifact, label: string): string => {
      const producerNode = run.nodeRuns.find((node) => node.nodeId === artifact.producer?.nodeId);
      const version = producerNode?.outputState?.versions.find((candidate) =>
        candidate.id === producerNode.outputState?.effectiveVersionId);
      if (!version || !version.artifactIds.includes(artifact.id)) {
        throw new HumanDecisionConflictError(`${label}产物已不属于其当前有效输出版本，请刷新后重新确认旁白方案。`);
      }
      return version.id;
    };
    const scriptOutputVersionId = effectiveProducerVersionId(scriptArtifact, "正式稿件");
    const visualOutputVersionId = effectiveProducerVersionId(visualArtifact, "正式画面方案");
    await verifyStoredArtifactWithinRoot(this.store.runDirectory(run.id), scriptArtifact);
    const script = requireOutputRecord(JSON.parse(await readFile(planning.scriptPath, "utf8")), "narration script");
    const visual = parseExecutableProductionPlan(JSON.parse(await readFile(planning.executablePlanPath, "utf8")));
    if (!Array.isArray(script.scenes) || script.scenes.length !== visual.cuts.length) throw new HumanDecisionConflictError("脚本和画面镜头数量不一致。");
    const characterScript = isCharacterScript(script) ? validateCharacterScriptStructure({
      ...script, scenes: script.scenes.map((scene, index) => {
        const cut = visual.cuts[index]!;
        if (scene.position !== cut.scenePosition) throw new HumanDecisionConflictError("角色稿与画面顺序不一致。");
        return { ...scene, duration: cut.frameCount / 30 };
      }),
    }) : undefined;
    if ((brief.presentationMode === "character_drama") !== Boolean(characterScript)) {
      throw new HumanDecisionConflictError("视频形式与声音所用稿件不一致，请返回剧本核对。");
    }
    const scenes = characterScript ? [] : script.scenes.map((value, index) => {
      const scene = requireOutputRecord(value, "narration scene");
      const cut = visual.cuts[index]!;
      if (scene.position !== cut.scenePosition) throw new HumanDecisionConflictError("脚本与画面顺序不一致。");
      if (typeof scene.narration !== "string") throw new HumanDecisionConflictError("旁白场景缺少文本。");
      return { position: scene.position as number, narration: scene.narration, duration: cut.frameCount / 30 };
    });
    const parentArtifactIds = [scriptArtifact.id, visualArtifact.id];
    const upstreamVersionIds = dependencies.map((node) => node!.outputState!.effectiveVersionId);
    const effectiveVoiceInput = voice?.inputState?.versions.find((v) => v.id === voice.inputState?.effectiveVersionId)?.value;
    const context = {
      ...(characterScript ? { characterScript } : {}),
      scenes, scriptArtifact: { id: scriptArtifact.id, sha256: scriptArtifact.sha256, outputVersionId: scriptOutputVersionId },
      visualArtifact: { id: visualArtifact.id, sha256: visualArtifact.sha256, outputVersionId: visualOutputVersionId },
      parentArtifactIds,
      upstreamVersionIds,
      voiceInput: { ...planning, voice: voiceDirection.profileId.split(":").slice(1).join(":"),
        ...(characterScript ? { baseVoiceInputVersionId: isObjectRecord(effectiveVoiceInput)
          && "baseVoiceInputVersionId" in effectiveVoiceInput ? effectiveVoiceInput.baseVoiceInputVersionId
          : voice?.inputState?.effectiveVersionId ?? null } : {}),
        rate: voiceDirection.rate, pause_scale: voiceDirection.pauseScale, mastering_preset: voiceDirection.masteringPreset,
        scriptArtifactId: scriptArtifact.id, scriptOutputVersionId,
        visualArtifactId: visualArtifact.id, visualOutputVersionId,
        parentArtifactIds, upstreamVersionIds },
      editorMode };
    const sourceContextId = this.narrationSourceContextIdV2(run, context, this.voiceProviderConfigDigest(run, context));
    return { ...context, plan: characterScript
      ? buildCharacterNarrationPlan({ script: characterScript, scriptSha256: scriptArtifact.sha256,
        visualSha256: visualArtifact.sha256, sourceContextId })
      : buildNarrationPlan(scenes, scriptArtifact.sha256, visualArtifact.sha256) };
  }

  // ══ §2.2 候选预览与采用 v2（S2）：本地核价、受控票据、只凭同身份票据保存 ══

  private voiceProviderConfigDigest(run: WorkflowRun<ProductionBrief>, context: { voiceInput: Record<string, unknown> }): string {
    const voiceConfig = providerConfigs(parsePersistedBrief(run.initialInput), this.options).find((config) => config.nodeId === "voice")!;
    const parts = ["providerId", voiceConfig.id, "modelId", String(voiceConfig.metadata?.modelId ?? ""),
      "voice", String(context.voiceInput.voice ?? ""), "rate", String(context.voiceInput.rate ?? ""),
      "pause_scale", String(context.voiceInput.pause_scale ?? ""), "mastering_preset", String(context.voiceInput.mastering_preset ?? "")];
    return createHash("sha256").update(JSON.stringify(parts), "utf8").digest("hex");
  }

  /** sourceContextId 由宿主按有效输出版本/产物身份/上游依赖与配音配置派生；同内容新版本也不同。 */
  private narrationSourceContextIdV2(run: WorkflowRun<ProductionBrief>, context: Omit<Awaited<ReturnType<ProductionPipeline["narrationPlanContext"]>>, "plan">, providerConfigDigest: string): string {
    return "sc-" + createHash("sha256").update(JSON.stringify([
      run.id, context.scriptArtifact.id, context.scriptArtifact.sha256,
      context.visualArtifact.id, context.visualArtifact.sha256,
      context.upstreamVersionIds, providerConfigDigest,
      ...(context.characterScript ? [context.scriptArtifact.outputVersionId, context.visualArtifact.outputVersionId,
        context.voiceInput.baseVoiceInputVersionId ?? null] : []),
    ]), "utf8").digest("hex");
  }

  private async latestNarrationTicketSequence(ticketsDirectory: string, actor: string, editorSessionId: string): Promise<number> {
    let names: string[] = [];
    try {
      names = await readdir(ticketsDirectory);
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
    }
    let latest = -1;
    for (const name of names) {
      if (!name.endsWith(".json") || name === "reservations.json") continue;
      try {
        const ticket = JSON.parse(await readFile(path.join(ticketsDirectory, name), "utf8")) as Record<string, unknown>;
        if (isObjectRecord(ticket) && ticket.actor === actor && ticket.editorSessionId === editorSessionId
          && typeof ticket.editSequence === "number" && Number.isSafeInteger(ticket.editSequence)) {
          latest = Math.max(latest, ticket.editSequence);
        }
      } catch {
        // 损坏票据不参与代次比较；签发与保存核对都以可读票据为准。
      }
    }
    return latest;
  }

  /**
   * §4.2.3 在途代次预留：复用 proper-lockfile 文件锁（与执行租约同一原语家族）对
   * `plan-preview-tickets/reservations.json` 做短临界区读改写。不加 DB、后台任务或新锁架构。
   */
  private async updateNarrationEditReservations(
    runId: string,
    mutate: (records: NarrationEditReservationRecord[], ticketsDirectory: string) => Promise<void>,
  ): Promise<void> {
    const ticketsDirectory = path.join(this.store.runDirectory(runId), "nodes", "voice", "plan-preview-tickets");
    await mkdir(ticketsDirectory, { recursive: true });
    const target = path.join(ticketsDirectory, "reservations.json");
    let release: (() => Promise<void>) | undefined;
    for (let attempts = 0; !release; attempts += 1) {
      try {
        release = await lockFile(target, { realpath: false, stale: 30_000, update: 1_000, retries: 0 });
      } catch (error) {
        // 短临界区：并发预览排队等待而不是失败；锁陈旧 30s 后可重新获取。
        if (hasCode(error, "ELOCKED") && attempts < 600) {
          await new Promise((resolve) => { setTimeout(resolve, 20); });
          continue;
        }
        throw error;
      }
    }
    try {
      let records: NarrationEditReservationRecord[] = [];
      try {
        const parsed = JSON.parse(await readFile(target, "utf8")) as unknown;
        if (!Array.isArray(parsed)) throw new Error("reservations must be a list");
        records = parsed.filter((entry): entry is NarrationEditReservationRecord => isObjectRecord(entry)
          && typeof entry.actor === "string" && typeof entry.editorSessionId === "string"
          && typeof entry.editSequence === "number" && Number.isSafeInteger(entry.editSequence)
          && typeof entry.candidateId === "string" && (entry.state === "reserved" || entry.state === "ticketed"));
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code !== "ENOENT") {
          throw new HumanDecisionConflictError("旁白预览的代次预留记录不可读，请核查该运行的编辑历史后再试。");
        }
      }
      await mutate(records, ticketsDirectory);
      await writeTextAtomically(target, `${JSON.stringify(records, null, 2)}\n`);
    } finally {
      await release();
    }
  }

  /** 签发/保存前的代次防护：预留（在途）与已签票据共同决定该会话的最高编辑代次。 */
  private async assertNarrationEditGenerationFresh(
    records: NarrationEditReservationRecord[],
    ticketsDirectory: string,
    actor: string,
    editorSessionId: string,
    editSequence: number,
    candidateId: string,
  ): Promise<void> {
    const reserved = records.filter((entry) => entry.actor === actor && entry.editorSessionId === editorSessionId);
    const latest = Math.max(editSequence - 1, await this.latestNarrationTicketSequence(ticketsDirectory, actor, editorSessionId),
      ...reserved.map((entry) => entry.editSequence));
    if (editSequence < latest) {
      throw new HumanDecisionConflictError("这份编辑已经过期（同一会话已有更新的编辑），请基于最新方案继续。");
    }
    const sameSequence = reserved.find((entry) => entry.editSequence === editSequence);
    if (sameSequence && sameSequence.candidateId !== candidateId) {
      throw new HumanDecisionConflictError("同一编辑代次已用于不同的候选，请基于最新方案继续或刷新重试。");
    }
  }

  async previewNarrationPlanV2(runId: string, draft: {
    version?: "video-factory/narration-plan-v2" | "video-factory/narration-plan-v3";
    expectedRunRevision: number; sourceContextId: string; editorSessionId: string; editSequence: number;
    candidateId?: string; candidate: unknown; actor: string;
  }): Promise<NarrationPreviewTicketResponseV2> {
    const run = await this.store.load<ProductionBrief>(runId);
    assertNoPendingDurationChange(run);
    if (run.revision !== draft.expectedRunRevision) {
      throw new StaleRunRevisionError(runId, draft.expectedRunRevision, run.revision);
    }
    if (!draft.actor.trim()) throw new HumanDecisionConflictError("预览旁白候选需要创作者身份。");
    const context = await this.narrationPlanContext(run);
    const editorSessionId = narrationEditorSessionId(draft.editorSessionId);
    const editSequence = narrationEditSequence(draft.editSequence);
    const requestedVersion = draft.version ?? "video-factory/narration-plan-v2";
    if (!["video-factory/narration-plan-v2", CHARACTER_NARRATION_PLAN_VERSION].includes(requestedVersion)) {
      throw new NarrationTextV2Error("声音候选版本未知。");
    }
    const candidate = requestedVersion === CHARACTER_NARRATION_PLAN_VERSION
      ? parseCharacterNarrationCandidate(draft.candidate) : parseNarrationCandidate(draft.candidate);
    if ((candidate.version === CHARACTER_NARRATION_PLAN_VERSION) !== Boolean(context.characterScript)) {
      throw new NarrationTextV2Error("声音候选与当前视频形式不一致。");
    }
    const candidateId = candidate.version === CHARACTER_NARRATION_PLAN_VERSION
      ? characterCandidateId(candidate, draft.sourceContextId) : candidateIdV2(candidate);
    if (draft.candidateId !== undefined && draft.candidateId !== candidateId) {
      throw new HumanDecisionConflictError("候选身份与候选内容不一致，请刷新后重新编辑。");
    }
    const providerConfigDigest = this.voiceProviderConfigDigest(run, context);
    const sourceContextId = this.narrationSourceContextIdV2(run, context, providerConfigDigest);
    if (draft.sourceContextId !== sourceContextId) {
      throw new HumanDecisionConflictError("旁白来源或配音配置已变化，请刷新方案后重新编辑。");
    }
    const reloadCurrentSource = async () => {
      const currentRun = await this.store.load<ProductionBrief>(runId);
      assertNoPendingDurationChange(currentRun);
      if (currentRun.revision !== draft.expectedRunRevision) {
        throw new StaleRunRevisionError(runId, draft.expectedRunRevision, currentRun.revision);
      }
      const currentContext = await this.narrationPlanContext(currentRun);
      const currentProviderConfigDigest = this.voiceProviderConfigDigest(currentRun, currentContext);
      const currentSourceContextId = this.narrationSourceContextIdV2(
        currentRun,
        currentContext,
        currentProviderConfigDigest,
      );
      if (currentProviderConfigDigest !== providerConfigDigest
        || currentSourceContextId !== sourceContextId
        || !isDeepStrictEqual(currentContext.upstreamVersionIds, context.upstreamVersionIds)) {
        throw new HumanDecisionConflictError("旁白来源或配音配置在核价期间发生变化，请刷新后重新编辑。");
      }
      return { currentRun, currentContext };
    };
    // §4.2.3 阶段1：forecast 前用现有文件锁原语耐久预留 (actor, session, sequence, candidate)；
    // 旧序拒绝、同序异候选拒绝、同序同候选复用。短临界区后释放，再进行可能缓慢的核价。
    await this.options.narrationPlanFailpoints?.beforePreviewGenerationLock?.();
    await this.updateNarrationEditReservations(runId, async (records, ticketsDirectory) => {
      // 等待短锁期间，正式采用可能已经提交。必须在锁内重读 run，避免给旧 revision
      // 留下代次预留；preview 不持 run lease，因此不会形成反向锁等待。
      await reloadCurrentSource();
      await this.assertNarrationEditGenerationFresh(records, ticketsDirectory, draft.actor, editorSessionId, editSequence, candidateId);
      const record = records.find((entry) => entry.actor === draft.actor
        && entry.editorSessionId === editorSessionId && entry.editSequence === editSequence);
      if (record) {
        record.candidateId = candidateId;
        record.state = "reserved";
        record.ticketId = undefined;
        record.updatedAt = this.clock();
      } else {
        records.push({ actor: draft.actor, editorSessionId, editSequence, candidateId,
          state: "reserved", updatedAt: this.clock() });
      }
    });
    const plan = candidate.version === CHARACTER_NARRATION_PLAN_VERSION
      ? buildCharacterNarrationPlan({ script: context.characterScript!, scriptSha256: context.scriptArtifact.sha256,
        visualSha256: context.visualArtifact.sha256, sourceContextId }, candidate)
      : buildNarrationPlanV2FromCandidate(
      { scenes: context.scenes, scriptSha256: context.scriptArtifact.sha256, visualSha256: context.visualArtifact.sha256, sourceContextId },
      candidate);
    const voiceConfig = providerConfigs(parsePersistedBrief(run.initialInput), this.options).find((config) => config.nodeId === "voice")!;
    // §4.2.3 阶段2：仅核价阶段的可恢复失败转为 quote 不可得（不带金额）；
    // 来源/CAS/输入校验错误已经在此前抛出，不会被吞成价格未知。
    let rawQuote: NarrationSpendQuote | undefined;
    try {
      rawQuote = await this.options.worker.forecastPaidVoiceSpend?.({ runId, nodeDirectory: path.join(this.runsRoot, runId, "nodes", "voice"),
        input: { ...context.voiceInput, narrationPlan: plan },
        parameters: { ...voiceConfig.parameters, providerId: voiceConfig.id, modelId: voiceConfig.metadata?.modelId } });
    } catch {
      rawQuote = undefined;
    }
    const quote: NarrationPreviewQuoteV2 = rawQuote
      ? { status: "estimated", source: "configured_rate", estimatedCostCny: rawQuote.estimatedCostCny,
        maxCostCny: rawQuote.maxCostCny, unitPriceCny: rawQuote.unitPriceCny, items: rawQuote.items }
      : { status: "unavailable", source: "configured_rate" };
    const planSha256 = plan.version === CHARACTER_NARRATION_PLAN_VERSION ? characterPlanSha256(plan) : planCanonicalSha256V2(plan);
    // §4.2.3 阶段3：签票前重新核最高代次与 run/source/config；迟到旧代次不得签发票据。
    const ticketId = `npt-${randomUUID().replaceAll("-", "")}`;
    const relativePlanPath = `nodes/voice/plans/${planSha256}.json`;
    await this.updateNarrationEditReservations(runId, async (records, ticketsDirectory) => {
      const { currentRun, currentContext } = await reloadCurrentSource();
      await this.assertNarrationEditGenerationFresh(records, ticketsDirectory, draft.actor, editorSessionId, editSequence, candidateId);
      await mkdir(path.join(this.store.runDirectory(runId), "nodes", "voice", "plans"), { recursive: true });
      // §4.2.2 字节口径：v2 计划落盘即待保存规范 JSON 字节（无 pretty、无换行），
      // planSha256 / artifact.sha256 / 文件字节 SHA 三者一致；旧 v1 pretty 格式不改。
      await writeTextAtomically(path.join(this.store.runDirectory(runId), relativePlanPath), canonicalJsonV2(plan));
      const ticket = {
        version: NARRATION_PREVIEW_TICKET_VERSION, ticketId, runId, actor: draft.actor, createdAt: this.clock(),
        ...(plan.version === CHARACTER_NARRATION_PLAN_VERSION ? { narrationPlanVersion: plan.version } : {}),
        editorSessionId, editSequence, candidateId, sourceContextId, expectedRunRevision: currentRun.revision,
        providerConfigDigest, planSha256, planPath: relativePlanPath, quoteStatus: quote.status,
        upstreamVersionIds: currentContext.upstreamVersionIds, parentArtifactIds: currentContext.parentArtifactIds, candidate,
      };
      await mkdir(ticketsDirectory, { recursive: true });
      await writeTextAtomically(path.join(ticketsDirectory, `${ticketId}.json`), `${JSON.stringify(ticket, null, 2)}\n`);
      const record = records.find((entry) => entry.actor === draft.actor
        && entry.editorSessionId === editorSessionId && entry.editSequence === editSequence)!;
      record.state = "ticketed";
      record.ticketId = ticketId;
      record.updatedAt = this.clock();
    });
    return { expectedRunRevision: run.revision, sourceContextId, editorSessionId, editSequence,
      candidateId, ticketId, plan, planSha256, providerConfigDigest, quote };
  }

  async confirmNarrationPlanV2(runId: string, draft: {
    version?: "video-factory/narration-plan-v2" | "video-factory/narration-plan-v3";
    requestId: string; expectedRunRevision: number; sourceContextId: string;
    editorSessionId: string; editSequence: number; candidateId: string;
    ticketId: string; planSha256: string; acknowledgeQuoteUnavailable?: boolean; actor: string;
  }): Promise<{ receipt: NarrationConfirmReceiptV2; run: WorkflowRun<ProductionBrief> }> {
    let receiptOut: NarrationConfirmReceiptV2 | undefined;
    const run = await this.runPersistedTransition(runId, async (previous, checkpoint) => {
      if (!draft.actor.trim()) throw new HumanDecisionConflictError("采用旁白方案需要创作者身份。");
      const requestedVersion = draft.version ?? "video-factory/narration-plan-v2";
      if (!["video-factory/narration-plan-v2", CHARACTER_NARRATION_PLAN_VERSION].includes(requestedVersion)) {
        throw new NarrationTextV2Error("声音保存版本未知。");
      }
      const requestId = narrationRequestId(draft.requestId);
      const editorSessionId = narrationEditorSessionId(draft.editorSessionId);
      const editSequence = narrationEditSequence(draft.editSequence);
      const ticketId = narrationTicketId(draft.ticketId);
      if (typeof draft.candidateId !== "string" || !draft.candidateId.trim()
        || typeof draft.planSha256 !== "string" || !/^[a-f0-9]{64}$/.test(draft.planSha256)
        || typeof draft.sourceContextId !== "string" || !draft.sourceContextId.trim()) {
        throw new HumanDecisionConflictError("保存旁白计划的编辑身份不完整。");
      }
      const runDirectory = this.store.runDirectory(runId);
      const receiptsDirectory = path.join(runDirectory, "nodes", "voice", "plan-confirm-receipts");
      const operationPath = path.join(receiptsDirectory, `${requestId}.json`);
      // 请求摘要绑定 action/run/actor 与原编辑身份；跨actor或任一字段变化均不可复用原ID。
      const requestDigest = createHash("sha256").update(JSON.stringify([
        requestedVersion === CHARACTER_NARRATION_PLAN_VERSION ? "video-factory/narration-confirm-v3" : "video-factory/narration-confirm-v2",
        runId, draft.actor, requestId, draft.expectedRunRevision,
        draft.sourceContextId, editorSessionId, editSequence, draft.candidateId, ticketId,
        draft.planSha256, draft.acknowledgeQuoteUnavailable === true,
      ]), "utf8").digest("hex");
      let nextOut: WorkflowRun<ProductionBrief> | undefined;
      let replay = false;
      await this.updateNarrationEditReservations(runId, async (records, ticketsDirectory) => {
        let operation: NarrationConfirmOperationRecord | undefined;
        try {
          const stored = JSON.parse(await readFile(operationPath, "utf8")) as Record<string, unknown>;
          if (stored.requestDigest !== requestDigest) {
            throw new HumanDecisionConflictError("同一保存请求身份已被不同内容使用，请换新的请求后重试。");
          }
          if (stored.version === NARRATION_CONFIRM_OPERATION_VERSION
            && (stored.state === "reserved" || stored.state === "projected")
            && stored.runId === runId && stored.requestId === requestId
            && typeof stored.artifactId === "string" && typeof stored.inputVersionId === "string") {
            operation = stored as unknown as NarrationConfirmOperationRecord;
          } else if (stored.version === NARRATION_CONFIRM_RECEIPT_VERSION
            && typeof stored.artifactId === "string" && typeof stored.inputVersionId === "string") {
            // 读取当前功能早期写出的v1收据；run仍是权威，后续投影为新operation格式。
            operation = {
              version: NARRATION_CONFIRM_OPERATION_VERSION, state: "projected", runId, requestId, requestDigest,
              actor: draft.actor, expectedRunRevision: draft.expectedRunRevision,
              sourceContextId: draft.sourceContextId, editorSessionId, editSequence,
              candidateId: draft.candidateId, ticketId, planSha256: draft.planSha256,
              acknowledgeQuoteUnavailable: draft.acknowledgeQuoteUnavailable === true,
              artifactId: stored.artifactId, inputVersionId: stored.inputVersionId,
              createdAt: typeof stored.createdAt === "string" ? stored.createdAt : this.clock(),
              updatedAt: this.clock(),
              ...(typeof stored.resultingRunRevision === "number" ? { resultingRunRevision: stored.resultingRunRevision } : {}),
            };
          } else {
            throw new HumanDecisionConflictError("旁白保存操作记录不可核对，请保留当前制作并检查原请求。");
          }
        } catch (error) {
          if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
        }

        const voiceForReplay = previous.nodeRuns.find((node) => node.nodeId === "voice");
        const adoptions = (voiceForReplay?.inputState?.versions ?? []).flatMap((version) => {
          const value = isObjectRecord(version.value) ? version.value : undefined;
          const adoption = value && isObjectRecord(value.narrationPlanAdoption) ? value.narrationPlanAdoption : undefined;
          return adoption?.requestId === requestId ? [{ version, adoption }] : [];
        });
        if (adoptions.length > 1) throw new HumanDecisionConflictError("同一旁白保存请求出现了多个正式采用版本，请先核查运行记录。");
        const adopted = adoptions[0];
        const legacyAdoptedVersion = !adopted && operation
          ? voiceForReplay?.inputState?.versions.find((version) => version.id === operation!.inputVersionId)
          : undefined;
        const adoptedVersion = adopted?.version ?? legacyAdoptedVersion;
        const adoptedArtifactId = adopted?.adoption.artifactId ?? operation?.artifactId;
        const adoptedArtifact = typeof adoptedArtifactId === "string"
          ? previous.artifacts.find((artifact) => artifact.id === adoptedArtifactId) : undefined;
        if (adoptedVersion && adoptedArtifact) {
          if (adopted && adopted.adoption.requestDigest !== requestDigest) {
            throw new HumanDecisionConflictError("同一保存请求身份已被不同内容使用，请换新的请求后重试。");
          }
          if (operation && (operation.inputVersionId !== adoptedVersion.id || operation.artifactId !== adoptedArtifact.id)) {
            throw new HumanDecisionConflictError("旁白保存投影与正式采用版本不一致，请先核查运行记录。");
          }
          const resultingRunRevision = typeof adopted?.adoption.resultingRunRevision === "number"
            ? adopted.adoption.resultingRunRevision : operation?.resultingRunRevision;
          if (!Number.isSafeInteger(resultingRunRevision)) {
            throw new HumanDecisionConflictError("旁白保存缺少正式结果版本，请先核查运行记录。");
          }
          receiptOut = {
            accepted: true, requestId, planSha256: draft.planSha256,
            artifactId: adoptedArtifact.id, inputVersionId: adoptedVersion.id,
            expectedRunRevision: draft.expectedRunRevision,
            resultingRunRevision: resultingRunRevision as number,
            replay: true, current: voiceForReplay?.inputState?.effectiveVersionId === adoptedVersion.id,
          };
          const repaired: NarrationConfirmOperationRecord = {
            version: NARRATION_CONFIRM_OPERATION_VERSION, state: "projected", runId, requestId, requestDigest,
            actor: draft.actor, expectedRunRevision: draft.expectedRunRevision,
            sourceContextId: draft.sourceContextId, editorSessionId, editSequence,
            candidateId: draft.candidateId, ticketId, planSha256: draft.planSha256,
            acknowledgeQuoteUnavailable: draft.acknowledgeQuoteUnavailable === true,
            artifactId: adoptedArtifact.id, inputVersionId: adoptedVersion.id,
            createdAt: operation?.createdAt ?? this.clock(), updatedAt: this.clock(),
            resultingRunRevision: resultingRunRevision as number,
          };
          await mkdir(receiptsDirectory, { recursive: true });
          await writeTextAtomically(operationPath, `${JSON.stringify(repaired, null, 2)}\n`);
          replay = true;
          return;
        }

        await this.options.narrationPlanFailpoints?.afterConfirmationGenerationLock?.();
        if (previous.revision !== draft.expectedRunRevision) {
          throw new StaleRunRevisionError(runId, draft.expectedRunRevision, previous.revision);
        }
        let ticket: Record<string, unknown>;
        try {
          ticket = JSON.parse(await readFile(path.join(ticketsDirectory, `${ticketId}.json`), "utf8")) as Record<string, unknown>;
        } catch (error) {
          if ((error as NodeJS.ErrnoException).code === "ENOENT") {
            throw new HumanDecisionConflictError("预览票据不存在或已过期，请重新预览后再保存。");
          }
          throw error;
        }
        if (!isObjectRecord(ticket) || ticket.version !== NARRATION_PREVIEW_TICKET_VERSION
          || (ticket.narrationPlanVersion ?? "video-factory/narration-plan-v2") !== requestedVersion
          || ticket.runId !== runId || ticket.actor !== draft.actor
          || ticket.editorSessionId !== editorSessionId || ticket.editSequence !== editSequence
          || ticket.candidateId !== draft.candidateId || ticket.planSha256 !== draft.planSha256
          || ticket.sourceContextId !== draft.sourceContextId || typeof ticket.planPath !== "string") {
          throw new HumanDecisionConflictError("预览票据与本次保存不匹配，请重新预览后再保存。");
        }
        await this.assertNarrationEditGenerationFresh(records, ticketsDirectory,
          draft.actor, editorSessionId, editSequence, draft.candidateId);
        const context = await this.narrationPlanContext(previous);
        if (ticket.providerConfigDigest !== this.voiceProviderConfigDigest(previous, context)) {
          throw new HumanDecisionConflictError("配音配置在预览后发生了变化，请重新预览核价。");
        }
        if (draft.sourceContextId !== this.narrationSourceContextIdV2(previous, context, ticket.providerConfigDigest as string)
          || !isDeepStrictEqual(ticket.upstreamVersionIds, context.upstreamVersionIds)) {
          throw new HumanDecisionConflictError("旁白来源在预览后发生了变化，请重新预览后再保存。");
        }
        const requestedPlanPath = path.resolve(runDirectory, ticket.planPath);
        const [resolvedPlanPath, resolvedRunDirectory] = await Promise.all([
          realpath(requestedPlanPath), realpath(runDirectory),
        ]);
        if (!resolvedPlanPath.startsWith(resolvedRunDirectory + path.sep)) {
          throw new HumanDecisionConflictError("预览票据引用了运行目录之外的路径。");
        }
        const planBytes = await readFile(resolvedPlanPath);
        const actualPlanSha256 = createHash("sha256").update(planBytes).digest("hex");
        if (actualPlanSha256 !== draft.planSha256 || actualPlanSha256 !== ticket.planSha256) {
          throw new HumanDecisionConflictError("待保存计划的实际文件字节摘要与预览票据不一致，请重新预览。");
        }
        let planContent: string;
        try {
          planContent = new TextDecoder("utf-8", { fatal: true }).decode(planBytes);
        } catch {
          throw new HumanDecisionConflictError("待保存计划不是有效的 UTF-8 文件，请重新预览。");
        }
        if ((requestedVersion === CHARACTER_NARRATION_PLAN_VERSION) !== Boolean(context.characterScript)) {
          throw new HumanDecisionConflictError("预览票据与当前视频形式不一致。");
        }
        const ticketCandidate = requestedVersion === CHARACTER_NARRATION_PLAN_VERSION
          ? parseCharacterNarrationCandidate(ticket.candidate) : parseNarrationCandidate(ticket.candidate);
        if (ticketCandidate.version === CHARACTER_NARRATION_PLAN_VERSION
          && characterCandidateId(ticketCandidate, draft.sourceContextId) !== draft.candidateId) {
          throw new HumanDecisionConflictError("角色声音候选与来源身份不一致。");
        }
        const plan = ticketCandidate.version === CHARACTER_NARRATION_PLAN_VERSION
          ? validateCharacterNarrationPlan(JSON.parse(planContent), { script: context.characterScript!,
            scriptSha256: context.scriptArtifact.sha256, visualSha256: context.visualArtifact.sha256,
            sourceContextId: draft.sourceContextId })
          : validateNarrationPlanV2(JSON.parse(planContent), candidateToBuildInput(
          { scenes: context.scenes, scriptSha256: context.scriptArtifact.sha256,
            visualSha256: context.visualArtifact.sha256, sourceContextId: draft.sourceContextId },
          ticketCandidate));
        if ((plan.version === CHARACTER_NARRATION_PLAN_VERSION ? characterPlanSha256(plan) : planCanonicalSha256V2(plan)) !== draft.planSha256
          || canonicalJsonV2(plan) !== planContent
          || (ticketCandidate.version === CHARACTER_NARRATION_PLAN_VERSION
            && !isDeepStrictEqual(plan, buildCharacterNarrationPlan({ script: context.characterScript!,
              scriptSha256: context.scriptArtifact.sha256, visualSha256: context.visualArtifact.sha256,
              sourceContextId: draft.sourceContextId }, ticketCandidate)))) {
          throw new HumanDecisionConflictError("待保存计划的规范字节与票据不一致，请重新预览。");
        }
        if (ticket.quoteStatus === "unavailable" && draft.acknowledgeQuoteUnavailable !== true) {
          throw new HumanDecisionConflictError("当前核价不可用：请知情确认后保存，或稍后重新核价。");
        }

        if (!operation) {
          operation = {
            version: NARRATION_CONFIRM_OPERATION_VERSION, state: "reserved", runId, requestId, requestDigest,
            actor: draft.actor, expectedRunRevision: draft.expectedRunRevision,
            sourceContextId: draft.sourceContextId, editorSessionId, editSequence,
            candidateId: draft.candidateId, ticketId, planSha256: draft.planSha256,
            acknowledgeQuoteUnavailable: draft.acknowledgeQuoteUnavailable === true,
            artifactId: this.idFactory("artifact"), inputVersionId: this.idFactory("input-version"),
            createdAt: this.clock(), updatedAt: this.clock(),
          };
          await mkdir(receiptsDirectory, { recursive: true });
          await writeTextAtomically(operationPath, `${JSON.stringify(operation, null, 2)}\n`);
        }
        await this.options.narrationPlanFailpoints?.afterAdoptionReservation?.();

        const next = structuredClone(previous);
        const node = next.nodeRuns.find((candidate) => candidate.nodeId === "voice") ?? {
          nodeId: "voice", role: "声音导演", status: "pending" as const, startedAt: this.clock(), artifactIds: [], qualityGateResults: [],
        };
        if (!next.nodeRuns.includes(node)) next.nodeRuns.push(node);
        if (next.artifacts.some((artifact) => artifact.id === operation!.artifactId)
          || node.inputState?.versions.some((version) => version.id === operation!.inputVersionId)) {
          throw new HumanDecisionConflictError("旁白保存预留身份已被其他版本占用，请先核查运行记录。");
        }
        const resultingRunRevision = previous.revision + 1;
        next.artifacts.push({ id: operation.artifactId, kind: "narration_plan", uri: resolvedPlanPath, sha256: draft.planSha256,
          sizeBytes: planBytes.byteLength, contentType: "application/json", schemaVersion: plan.version,
          parentArtifactIds: context.parentArtifactIds, createdAt: this.clock(), producer: { nodeId: "voice", attempt: 0 },
          provenance: { providerId: "creator-narration-plan-v1", providerVersion: "1" } });
        node.inputState = { nodeId: "voice", effectiveVersionId: operation.inputVersionId, stale: false, versions: [
          ...(node.inputState?.versions ?? []), { id: operation.inputVersionId, nodeId: "voice", source: "derived", createdAt: this.clock(),
            createdBy: draft.actor, schemaVersion: plan.version, upstreamVersionIds: context.upstreamVersionIds,
            ...(node.inputState ? { parentVersionId: node.inputState.effectiveVersionId } : {}),
            value: { ...context.voiceInput, narrationPlanPath: resolvedPlanPath, sourceContextId: draft.sourceContextId,
              voiceInputVersionId: operation.inputVersionId, scriptArtifactId: context.scriptArtifact.id,
              visualArtifactId: context.visualArtifact.id, parentArtifactIds: context.parentArtifactIds,
              narrationPlanAdoption: {
                requestId, requestDigest, artifactId: operation.artifactId, inputVersionId: operation.inputVersionId,
                expectedRunRevision: draft.expectedRunRevision, resultingRunRevision, actor: draft.actor,
              } } },
        ] };
        next.revision = resultingRunRevision;
        await checkpoint(next);
        await this.options.narrationPlanFailpoints?.afterAdoptionCheckpoint?.();
        operation = { ...operation, state: "projected", resultingRunRevision, updatedAt: this.clock() };
        await writeTextAtomically(operationPath, `${JSON.stringify(operation, null, 2)}\n`);
        receiptOut = {
          accepted: true, requestId, planSha256: draft.planSha256,
          artifactId: operation.artifactId, inputVersionId: operation.inputVersionId,
          expectedRunRevision: draft.expectedRunRevision, resultingRunRevision,
          replay: false, current: true,
        };
        nextOut = next;
      });
      return replay ? previous : nextOut!;
    }, undefined, true);
    return { receipt: receiptOut!, run };
  }

  async requestVoiceTimingRevision(
    runId: string,
    draft: ProductionVoiceTimingRevisionDraft,
  ): Promise<WorkflowRun<ProductionBrief>> {
    const accepted = await this.runPersistedTransition(runId, async (previous) => {
      if (previous.revision !== draft.expectedRunRevision) {
        throw new StaleRunRevisionError(runId, draft.expectedRunRevision, previous.revision);
      }
      if (previous.status !== "needs_human" || !draft.actor.trim()) {
        throw new Error(`Run '${runId}' is not waiting for a voice timing change.`);
      }
      const voiceNode = previous.nodeRuns.find((node) => node.nodeId === "voice" && node.status === "needs_human");
      if (!voiceNode) throw new Error("Voice timing revision requires the active voice node.");
      const intervention = voiceNode?.intervention;
      if (intervention?.id !== draft.interventionId || !intervention.options?.includes("request_changes")) {
        throw new Error("Voice timing revision requires the active planning intervention.");
      }
      const brief = effectiveProductionBrief(previous);
      let nextBrief = brief;
      if (draft.durationAmendment !== undefined) {
        if (brief.durationPolicy !== "content-led-v1") {
          throw new HumanDecisionConflictError("旧版制作不能通过声音修订更换时长合同。");
        }
        const amendment = parseDurationAmendment(draft.durationAmendment);
        if (amendment.expectedBriefSha256 !== contentSha256(brief)) {
          throw new HumanDecisionConflictError("当前时长要求已变化，请核对最新版本后再调整。");
        }
        const { durationRange: _previousRange, ...unchanged } = brief;
        nextBrief = parseBrief({ ...unchanged, ...(amendment.range ? { durationRange: amendment.range } : {}) });
      }
      const voiceOutput = requireOutputRecord(voiceNode.output, "voice output");
      const groupConflict = isObjectRecord(voiceOutput.conflict) && voiceOutput.conflict.code === "NARRATION_GROUP_DOES_NOT_FIT"
        ? parseNarrationGroupConflict(voiceOutput.conflict) : undefined;
      // §4.2.7 v2 首次 fit 冲突的改画面适配：v2 冲突不携带 cuts（不伪装完整时间线），
      // 场景时长从当前正式 executable plan 取；旧 parser 不吞 v2 事实。
      const v2ConflictRecord = isObjectRecord(voiceOutput.conflict)
        && voiceOutput.conflict.code === "NARRATION_GROUP_DOES_NOT_FIT_V2" ? voiceOutput.conflict : undefined;
      const conflict = groupConflict || v2ConflictRecord ? undefined : parseVoiceDoesNotFitConflict(voiceOutput.conflict);
      if (groupConflict ? draft.groupId !== groupConflict.groupId || !groupConflict.sourceScenePositions.includes(draft.scenePosition)
        : v2ConflictRecord
          ? draft.groupId !== v2ConflictRecord.groupId
            || !Array.isArray(v2ConflictRecord.sourceScenePositions)
            || !v2ConflictRecord.sourceScenePositions.includes(draft.scenePosition)
          : draft.groupId !== undefined || draft.scenePosition !== conflict!.scenePosition) {
        throw new Error("Voice timing revision scene is no longer current.");
      }
      // v2 的必需时长 = 当前镜头 cut + 缺口帧（availableFrames 不足以容纳 requiredFrames 的部分）。
      let requiredSeconds: number;
      if (groupConflict) {
        requiredSeconds = (groupConflict.cuts.find((cut) => cut.scenePosition === draft.scenePosition)!.frameCount
          + groupConflict.requiredFrames - (groupConflict.window.endFrame - groupConflict.window.startFrame)) / 30;
      } else if (v2ConflictRecord) {
        const briefForPlan = parsePersistedBrief(previous.initialInput);
        const planOwner = usesJointCreativePlanning(briefForPlan) ? "creative-planning" : "production-preflight";
        const ownerNode = previous.nodeRuns.find((node) => node.nodeId === planOwner);
        const ownerVersion = ownerNode?.outputState?.versions.find(
          (version) => version.id === ownerNode.outputState?.effectiveVersionId);
        const ownerOutput = ownerVersion ? requireOutputRecord(ownerVersion.output ?? ownerNode?.output, `${planOwner} output`) : undefined;
        const v2PlanPath = ownerOutput ? requiredOutputString(ownerOutput, "executablePlanPath") : undefined;
        const v2PlanArtifact = v2PlanPath
          ? previous.artifacts.find((artifact) => ownerVersion?.artifactIds.includes(artifact.id)
            && artifact.kind === "executable_plan" && artifact.uri === v2PlanPath)
          : undefined;
        if (!v2PlanArtifact?.uri) throw new Error("Current executable production plan artifact is unavailable.");
        const v2CurrentPlan = parseExecutableProductionPlan(JSON.parse(await readFile(v2PlanArtifact.uri, "utf8")));
        const sceneCut = v2CurrentPlan.cuts.find((cut) => cut.scenePosition === draft.scenePosition);
        if (!sceneCut) throw new Error("Voice timing revision scene is missing from the executable production plan.");
        requiredSeconds = (sceneCut.frameCount
          + Number(v2ConflictRecord.shortfallFrames ?? v2ConflictRecord.requiredFrames)) / 30;
      } else {
        requiredSeconds = conflict!.requiredSeconds;
      }
      if (!Number.isFinite(draft.durationSeconds) || draft.durationSeconds < requiredSeconds - 1e-8
        || (brief.durationPolicy !== "content-led-v1" && draft.durationSeconds > 180)) {
        throw new Error("Voice timing revision must cover the complete natural speech and satisfy the duration contract.");
      }

      if (!usesExecutablePlan(brief) || !brief.director) {
        throw new Error("Voice timing revision requires an executable production plan.");
      }
      const planOwnerNodeId = usesJointCreativePlanning(brief) ? "creative-planning" : "production-preflight";
      const preflightNode = previous.nodeRuns.find((node) => node.nodeId === planOwnerNodeId);
      const preflightVersion = preflightNode?.outputState?.versions.find(
        (version) => version.id === preflightNode.outputState?.effectiveVersionId,
      );
      if (!preflightVersion) throw new Error("Current executable production plan version is unavailable.");
      const preflightOutput = requireOutputRecord(preflightVersion.output ?? preflightNode?.output, `${planOwnerNodeId} output`);
      const currentPlanPath = requiredOutputString(preflightOutput, "executablePlanPath");
      const currentPlanArtifact = previous.artifacts.find((artifact) => (
        preflightVersion.artifactIds.includes(artifact.id)
        && artifact.kind === "executable_plan"
        && artifact.uri === currentPlanPath
        && artifact.producer?.nodeId === planOwnerNodeId
      ));
      if (!currentPlanArtifact?.uri) throw new Error("Current executable production plan artifact is unavailable.");
      await verifyStoredArtifactWithinRoot(this.store.runDirectory(runId), currentPlanArtifact);
      const currentPlan = parseExecutableProductionPlan(JSON.parse(await readFile(currentPlanArtifact.uri, "utf8")));
      const expectedPlanVersion = brief.durationPolicy === "content-led-v1"
        ? "video-factory/executable-plan-v2" : "video-factory/executable-plan-v1";
      if (currentPlan.version !== expectedPlanVersion || currentPlanArtifact.schemaVersion !== expectedPlanVersion
        || !isDeepStrictEqual(currentPlan.durationRange, brief.durationRange)) {
        throw new HumanDecisionConflictError("当前声音方案与制作时长合同不一致，请先核对有效方案。");
      }
      if (groupConflict && groupConflict.cuts.some((cut) => !currentPlan.cuts.some((actual) => actual.scenePosition === cut.scenePosition
        && actual.startFrame === cut.startFrame && actual.frameCount === cut.frameCount))) {
        throw new HumanDecisionConflictError("这组旁白的画面方案已变化，请先核对当前版本。");
      }
      const requestedFrameCount = Math.ceil(draft.durationSeconds * currentPlan.fps - 1e-6);
      const requiredFrameCount = Math.ceil(requiredSeconds * currentPlan.fps - 1e-6);
      if (!Number.isSafeInteger(requestedFrameCount) || requestedFrameCount < 1 || requestedFrameCount < requiredFrameCount) {
        throw new Error("Voice timing revision loses part of the natural speech after frame quantization.");
      }
      let nextStartFrame = 0;
      const cuts = currentPlan.cuts.map((cut) => {
        const frameCount = cut.scenePosition === draft.scenePosition ? requestedFrameCount : cut.frameCount;
        const revisedCut = { ...cut, startFrame: nextStartFrame, frameCount };
        nextStartFrame += frameCount;
        return revisedCut;
      });
      if (!cuts.some((cut) => cut.scenePosition === draft.scenePosition)) {
        throw new Error("Voice timing revision scene is missing from the executable production plan.");
      }
      const revisedPlan = parseExecutableProductionPlan({
        ...currentPlan,
        ...(brief.durationPolicy === "content-led-v1" ? { durationRange: nextBrief.durationRange } : {}),
        totalFrames: nextStartFrame,
        cuts,
      });
      // 先核原付费事实，再写任何新方案；新范围不能洗掉原请求或关联源的未知费用。
      await this.assertDurationChangeSafe(previous);
      const revisionBase = structuredClone(withExecutableBrief(previous, nextBrief));
      if (draft.durationAmendment && usesJointCreativePlanning(nextBrief)) {
        const owner = revisionBase.nodeRuns.find(node => node.nodeId === planOwnerNodeId)!;
        const inputState = owner.inputState;
        const currentInput = inputState?.versions.find(version => version.id === inputState.effectiveVersionId);
        if (!inputState || !currentInput || !isObjectRecord(currentInput.value) || !isObjectRecord(currentInput.value.brief)) {
          throw new HumanDecisionConflictError("当前规划输入身份缺失，时长调整未保存。");
        }
        const inputId = this.idFactory("input");
        // 旧graph仍是旧合同的历史；后续返回规划只能基于新有效输入重新核验。
        owner.inputState = { ...inputState, effectiveVersionId: inputId, stale: false,
          versions: [...inputState.versions, { ...currentInput, id: inputId, source: "human",
            value: { ...currentInput.value, brief: nextBrief }, parentVersionId: currentInput.id,
            createdAt: this.clock(), createdBy: draft.actor.trim() }] };
      }
      const revisionDirectory = path.join(
        this.runsRoot,
        runId,
        "nodes",
        planOwnerNodeId,
        "revisions",
        `revision-${previous.revision + 1}`,
      );
      await mkdir(revisionDirectory, { recursive: true });
      const revisedPlanPath = path.join(revisionDirectory, "executable_plan.json");
      const revisedPlanContent = `${JSON.stringify(revisedPlan, null, 2)}\n`;
      await writeTextAtomically(revisedPlanPath, revisedPlanContent);
      const definition = this.createWorkflow(nextBrief);
      const runner = new WorkflowRunner({
        optionalReviewInvalidationOperations: await verifiedOptionalReviewInvalidationOperations(previous, this.store.runDirectory(runId)),
        providers: this.createRegistry(nextBrief),
        clock: this.clock,
        idFactory: this.idFactory,
      });
      const revised = runner.applyNodeRevision(definition, revisionBase, {
        nodeId: planOwnerNodeId,
        actor: draft.actor.trim(),
        output: { ...preflightOutput, executablePlanPath: revisedPlanPath },
        artifacts: [fileArtifact(
          "executable_plan",
          revisedPlanPath,
          revisedPlanContent,
          "application/json",
          currentPlanArtifact.schemaVersion ?? "video-factory/executable-plan-v1",
          planOwnerNodeId,
          [currentPlanArtifact.id, ...voiceNode.artifactIds],
          "human-voice-timing-revision-v1",
          "Creator accepted a longer cut for the complete natural-speed narration.",
        )],
        // F6 残留收口：新版本保留当前方案的规划支撑引用集（joint 为整组 planning 证据，
        // legacy 为同版本其余产物），使修订后的 current version 仍满足引用闭包——
        // 声音修订进入同一正式发布合同，而不是留下只装一个新 plan 文件的断链版本。
        retainedArtifactIds: preflightVersion.artifactIds.filter((artifactId) => artifactId !== currentPlanArtifact.id),
        invalidateDescendantNodeIds: [
          "asset-source-review",
          "assets",
          "voice",
          "render",
          "technical-review",
          "visual-review",
          "final-review",
          "publish-package",
        ].filter((nodeId) => productionNodeIds(brief).includes(nodeId)),
        expectedVersionId: preflightVersion.id,
        schemaVersion: preflightVersion.schemaVersion,
        decision: {
          interventionId: intervention.id,
          action: "request_changes",
          actor: draft.actor.trim(),
          note: `镜头 ${draft.scenePosition} 时长调整为 ${requestedFrameCount / currentPlan.fps} 秒。`,
        },
      });
      if (groupConflict) await this.carryConfirmedNarrationPlan(previous, revised, draft.actor);
      return revised;
    });
    try { return await this.resumeStale(runId); }
    catch (cause) { throw new VoiceTimingContinuationError(accepted.revision, cause); }
  }

  /** 明确的局部改字/改时长沿新父产物重建声音输入，保留已选模式和仍适用的落点。 */
  private async carryConfirmedNarrationPlan(previous: WorkflowRun<ProductionBrief>, revised: WorkflowRun<ProductionBrief>, actor: string): Promise<void> {
    const voice = previous.nodeRuns.find((node) => node.nodeId === "voice");
    const input = voice?.inputState?.versions.find((version) => version.id === voice.inputState?.effectiveVersionId)?.value;
    if (!isObjectRecord(input) || typeof input.narrationPlanPath !== "string") return;
    const root = this.store.runDirectory(previous.id);
    const oldArtifact = previous.artifacts.find((artifact) => artifact.kind === "narration_plan" && artifact.uri === input.narrationPlanPath);
    if (!oldArtifact) throw new HumanDecisionConflictError("原连续旁白方案缺少留档，不能静默退回逐镜配音。");
    await verifyStoredArtifactWithinRoot(root, oldArtifact);
    const oldPlan = JSON.parse(await readFile(oldArtifact.uri!, "utf8")) as NarrationPlan;
    if (["video-factory/narration-plan-v2", CHARACTER_NARRATION_PLAN_VERSION].includes((oldPlan as { version?: string }).version ?? "")) {
      // §3：上游变化不自动重建/降级 v2——分段与显式静默是否仍适配由用户重新确认，
      // 旧计划保留为过期参考；voice 输入已由本次修订的后代失效标记 stale。
      return;
    }
    const context = (run: WorkflowRun<ProductionBrief>) => ({ outputs: new Map(run.nodeRuns.map((node) => [node.nodeId, effectiveNodeOutput(node)])) });
    const buildFor = async (run: WorkflowRun<ProductionBrief>) => {
      const paths = currentPlanningOutputPaths(context(run), parsePersistedBrief(run.initialInput));
      const script = run.artifacts.find((artifact) => artifact.kind === "script" && artifact.uri === paths.scriptPath);
      const visual = run.artifacts.find((artifact) => artifact.kind === "executable_plan" && artifact.uri === paths.executablePlanPath);
      if (!script?.sha256 || !visual?.sha256) throw new HumanDecisionConflictError("连续旁白的新稿件或画面身份缺失。");
      await Promise.all([script, visual].map((artifact) => verifyStoredArtifactWithinRoot(root, artifact)));
      const source = requireOutputRecord(JSON.parse(await readFile(paths.scriptPath, "utf8")), "narration script");
      const cuts = parseExecutableProductionPlan(JSON.parse(await readFile(visual.uri!, "utf8"))).cuts;
      if (!Array.isArray(source.scenes) || source.scenes.length !== cuts.length) throw new HumanDecisionConflictError("旁白与画面镜头不一致。");
      const scenes = source.scenes.map((scene, index) => ({ ...requireOutputRecord(scene, "narration scene"), duration: cuts[index]!.frameCount / 30 }));
      return { paths, script, visual, plan: buildNarrationPlan(scenes, script.sha256, visual.sha256) };
    };
    validateNarrationPlan(oldPlan, (await buildFor(previous)).plan);
    const next = await buildFor(revised);
    const expected = structuredClone(next.plan);
    for (const group of next.plan.groups) {
      const old = oldPlan.groups.find((candidate) => candidate.sourceScenePositions.join(",") === group.sourceScenePositions.join(","));
      if (old) group.placement = { ...old.placement };
    }
    // 不把不再容纳原落点的新画面自动修成另一个落点。
    validateNarrationPlan(next.plan, expected);
    const content = `${JSON.stringify(next.plan, null, 2)}\n`;
    const sha256 = createHash("sha256").update(content).digest("hex");
    const planPath = path.join(root, "nodes", "voice", "plans", `${sha256}.json`);
    await mkdir(path.dirname(planPath), { recursive: true });
    await writeTextAtomically(planPath, content);
    revised.artifacts.push({ ...fileArtifact("narration_plan", planPath, content, "application/json", next.plan.version,
      "voice", [next.script.id, next.visual.id, oldArtifact.id], "creator-narration-plan-v1", "Confirmed local revision; unchanged groups retain audio synthesis identity."),
      id: this.idFactory("artifact"), createdAt: this.clock(), provenance: { providerId: "creator-narration-plan-v1", providerVersion: "1" } });
    const target = revised.nodeRuns.find((node) => node.nodeId === "voice")!;
    const id = this.idFactory("input-version");
    // 保留历史人工版本；新路径是由本次明确修订派生的输入，待上游实际完成再绑定其版本。
    target.inputState = { nodeId: "voice", stale: true, effectiveVersionId: id, versions: [
      ...(target.inputState?.versions ?? []), { id, nodeId: "voice", source: "derived", schemaVersion: next.plan.version,
        createdAt: this.clock(), createdBy: actor, parentVersionId: voice!.inputState!.effectiveVersionId, upstreamVersionIds: [],
        value: { ...input, ...next.paths, narrationPlanPath: planPath } },
    ] };
  }

  private async prepareVisualDirectionOverride(
    previous: WorkflowRun<ProductionBrief>,
    override: NodeOverrideDraft,
  ): Promise<NodeOverrideDraft> {
    const currentBrief = effectiveProductionBrief(previous);
    const direction = currentBrief.director;
    if (!direction) throw new Error("Visual direction is not enabled for this run.");

    const submittedOutput = validatePathOutput(override.output, "directorPlanPath", "visual-direction");
    const submittedPath = requiredOutputString(submittedOutput, "directorPlanPath");
    const scriptPath = requiredOutputString(
      previous.nodeRuns.find((node) => node.nodeId === "script")?.output,
      "scriptPath",
    );
    const script = JSON.parse(await readFile(scriptPath, "utf8")) as { viewerPromise?: unknown; narrativeArc?: unknown; scenes?: unknown };
    const scenes = parseDirectorScenes(script);
    const plan = validateVisualDirectorPlan(
      JSON.parse(await readFile(submittedPath, "utf8")) as unknown,
      visualDirectorPlanValidation(
        currentBrief,
        scenes,
        this.options.assetProviders ?? [],
        this.options.providerRuntimeMetadata ?? [],
        optionalOutputString(script.viewerPromise),
      ),
    );

    const attempt = await reserveAttemptDirectory(path.join(
      this.store.runDirectory(previous.id),
      "nodes",
      "visual-direction",
      "manual-overrides",
    ));
    const planPath = path.join(attempt.directory, "director_plan.json");
    const content = `${JSON.stringify(plan, null, 2)}\n`;
    await writeTextAtomically(planPath, content);
    const parentArtifactIds = previous.artifacts
      .filter((artifact) => artifact.producer?.nodeId === "script" && artifact.uri !== undefined
        && path.resolve(artifact.uri) === path.resolve(scriptPath))
      .map((artifact) => artifact.id);
    const validatedArtifact = fileArtifact(
      "storyboard",
      planPath,
      content,
      "application/json",
      plan.version,
      "visual-direction",
      parentArtifactIds,
      "human-validated-director-plan-v1",
      "Human-edited director plan validated and repriced by the server.",
      attempt.attempt,
    );
    const effectiveOverride = {
      ...override,
      output: { ...submittedOutput, directorPlanPath: planPath },
      artifacts: [...(override.artifacts ?? []), validatedArtifact],
    };
    await verifyNodeOverrideBoundary(this.store.runDirectory(previous.id), effectiveOverride);
    return effectiveOverride;
  }

  async applyNodeInputOverride(runId: string, override: NodeInputOverrideDraft): Promise<WorkflowRun<ProductionBrief>> {
    return this.runPersistedTransition(runId, async (previous) => {
      const brief = parsePersistedBrief(previous.initialInput);
      // B4 对外编辑合同（joint-v1）：caller tokens 必填，省略即拒绝，不提供无 token 豁免
      // 路径；legacy 拓扑保持既有行为（token 提供时仍然参与复核）。
      if (usesJointCreativePlanning(brief)) {
        if (!Number.isSafeInteger(override.expectedRunRevision) || Number(override.expectedRunRevision) < 0) {
          throw new Error(`Joint planning input override for '${runId}' requires a non-negative expectedRunRevision.`);
        }
        if (typeof override.expectedVersionId !== "string" || !override.expectedVersionId.trim()) {
          throw new Error(`Joint planning input override for '${runId}' requires the expected input version id.`);
        }
      }
      // 持锁复核 caller revision：服务预检查读取的 revision 与此刻真实 head 之间可能已有
      // 后台写入（异步 dispatch 的 checkpoint 会推进 revision），stale token 在这里失败，
      // 而不是靠节点输入版本未变放过一次基于过期观察的覆盖。
      if (override.expectedRunRevision !== undefined && previous.revision !== override.expectedRunRevision) {
        throw new StaleRunRevisionError(runId, override.expectedRunRevision, previous.revision);
      }
      await verifyNodeInputOverrideBoundary(this.store.runDirectory(runId), override);
      await assertNoUnresolvedPlanningTask(this.store.runDirectory(runId), previous);
      // joint-v1 的 planning input 中包含当前有效 brief。人工调整声音节奏、用户要求或
      // 系列事实时，不能只把新值留在节点 override、而让 initialInput 继续成为另一份旧配置。
      // 这里先用同一个正式 merge/parse 边界得到唯一有效 brief，再同时交给工作流定义和
      // 持久化 run；阶段 identity 会据此只复用真正未受影响的上游。
      const effectiveBrief = override.nodeId === "creative-planning"
        && isObjectRecord(override.input)
        && isObjectRecord(override.input.brief)
        ? mergeCurrentBrief(override.input.brief, brief)
        : brief;
      const effectivePrevious = effectiveBrief === brief
        ? previous
        : { ...previous, initialInput: effectiveBrief };
      const runner = new WorkflowRunner({
        optionalReviewInvalidationOperations: await verifiedOptionalReviewInvalidationOperations(previous, this.store.runDirectory(runId)),
        providers: this.createRegistry(effectiveBrief),
        clock: this.clock,
        idFactory: this.idFactory,
      });
      return runner.applyNodeInputOverride(
        this.createWorkflow(effectiveBrief),
        withExecutableBrief(effectivePrevious, effectiveBrief),
        override,
      );
    });
  }

  async requestSceneRevision(
    runId: string,
    draft: ProductionSceneRevisionDraft,
  ): Promise<WorkflowRun<ProductionBrief>> {
    const dispatched = await this.dispatchSceneRevision(runId, draft);
    return dispatched.completion;
  }

  async dispatchSceneRevision(
    runId: string,
    draft: ProductionSceneRevisionDraft,
    listener?: ProductionRunListener,
  ): Promise<DispatchedProductionRun> {
    await this.runPersistedTransition(runId, async (previous) => {
      if (previous.revision !== draft.expectedRunRevision) {
        throw new StaleRunRevisionError(runId, draft.expectedRunRevision, previous.revision);
      }
      if (previous.status !== "needs_human") {
        throw new Error(`Run '${runId}' is not waiting for human review.`);
      }
      if (!draft.actor.trim() || !draft.note.trim()) {
        throw new Error("Scene revision actor and note are required.");
      }
      if (!Number.isInteger(draft.findingIndex) || draft.findingIndex < 0) {
        throw new Error("Scene revision finding index is invalid.");
      }
      if (!Number.isInteger(draft.reuseFromScenePosition) || draft.reuseFromScenePosition < 1) {
        throw new Error("Scene revision reuse source is invalid.");
      }

      const brief = parsePersistedBrief(previous.initialInput);
      const definition = this.createWorkflow(brief);
      const finalIntervention = previous.nodeRuns.find((node) => node.nodeId === "final-review")?.intervention;
      if (!finalIntervention) throw new Error("Scene revision requires an active final-review intervention.");
      const visualReviewNodeRun = previous.nodeRuns.find((node) => node.nodeId === "visual-review");
      const visualReviewVersion = visualReviewNodeRun?.outputState?.versions.find(
        (version) => version.id === visualReviewNodeRun.outputState?.effectiveVersionId,
      );
      const reviewArtifact = previous.artifacts.find((artifact) => artifact.id === draft.reviewArtifactId);
      if (
        !visualReviewVersion?.artifactIds.includes(draft.reviewArtifactId)
        || reviewArtifact?.kind !== "review_report"
        || reviewArtifact.producer?.nodeId !== "visual-review"
      ) {
        throw new Error("Scene revision requires a current visual-review report artifact.");
      }
      await verifyStoredArtifactWithinRoot(this.store.runDirectory(runId), reviewArtifact);
      const reviewOutput = requireOutputRecord(
        visualReviewVersion.output ?? visualReviewNodeRun?.output,
        "visual review output",
      );
      const reviewDurationMs = Number(reviewOutput.durationMs);
      if (!Number.isInteger(reviewDurationMs) || reviewDurationMs <= 0) {
        throw new Error("Current visual-review duration is invalid.");
      }
      const storedReportValue = JSON.parse(await readFile(reviewArtifact.uri!, "utf8"));
      assertCurrentVisualReviewContract(storedReportValue);
      const storedReport = validateAggregatedVisualReviewReport(
        storedReportValue,
        reviewDurationMs,
      );
      if (draft.findingIndex >= storedReport.findings.length) {
        throw new Error("Scene revision finding is no longer current.");
      }

      const renderNodeRun = previous.nodeRuns.find((node) => node.nodeId === "render");
      const renderVersion = renderNodeRun?.outputState?.versions.find(
        (version) => version.id === renderNodeRun.outputState?.effectiveVersionId,
      );
      const renderOutput = requireOutputRecord(renderVersion?.output ?? renderNodeRun?.output, "render output");
      const renderManifestPath = requiredOutputString(renderOutput, "renderManifestPath");
      const renderManifestArtifact = previous.artifacts.find((artifact) => (
        renderVersion?.artifactIds.includes(artifact.id)
        && artifact.kind === "render_manifest"
        && artifact.uri === renderManifestPath
        && artifact.producer?.nodeId === "render"
      ));
      if (!renderManifestArtifact) {
        throw new Error("Scene revision requires the current render manifest artifact.");
      }
      await verifyStoredArtifactWithinRoot(this.store.runDirectory(runId), renderManifestArtifact);
      const localizedReport = await localizeVisualReviewReport(
        storedReport,
        renderManifestPath,
        reviewDurationMs,
      );
      const scenePosition = localizedReport.findings[draft.findingIndex]!.scenePosition!;
      if (scenePosition === draft.reuseFromScenePosition) {
        throw new Error("A scene cannot reuse itself as a revision source.");
      }
      if (draft.reuseFromScenePosition > scenePosition) {
        throw new Error(`Reuse source scene ${draft.reuseFromScenePosition} must be earlier than reviewed scene ${scenePosition}.`);
      }

      const assetsNodeRun = previous.nodeRuns.find((node) => node.nodeId === "assets");
      const assetVersion = assetsNodeRun?.outputState?.versions.find(
        (version) => version.id === assetsNodeRun.outputState?.effectiveVersionId,
      );
      if (!assetVersion || assetVersion.id !== draft.expectedAssetVersionId) {
        throw new NodeVersionConflictError("assets", draft.expectedAssetVersionId, assetVersion?.id ?? "missing");
      }
      const assetPlanArtifact = previous.artifacts.find((artifact) => (
        artifact.kind === "asset_plan"
        && Boolean(artifact.uri)
        && assetVersion.artifactIds.includes(artifact.id)
        && artifact.producer?.nodeId === "assets"
      ));
      if (!assetPlanArtifact?.uri) throw new Error("Current asset plan artifact is unavailable.");
      await verifyStoredArtifactWithinRoot(this.store.runDirectory(runId), assetPlanArtifact);
      const currentAssetOutput = requireOutputRecord(assetVersion.output ?? assetsNodeRun?.output, "assets output");
      const currentPlan = requireOutputRecord(
        JSON.parse(await readFile(assetPlanArtifact.uri, "utf8")),
        "asset plan",
      );
      const revisedPlan = reviseAssetPlanByReuse(currentPlan, scenePosition, draft.reuseFromScenePosition);
      const retainedArtifactIds = await mediaArtifactIdsReferencedByPlan(
        this.store.runDirectory(runId),
        previous.artifacts,
        assetVersion.artifactIds,
        revisedPlan,
      );
      const revisionDirectory = path.join(
        this.runsRoot,
        runId,
        "nodes",
        "assets",
        "revisions",
        `revision-${previous.revision + 1}`,
      );
      await mkdir(revisionDirectory, { recursive: true });
      const revisedPlanPath = path.join(revisionDirectory, "asset_plan.json");
      const revisedPlanContent = `${JSON.stringify(revisedPlan, null, 2)}\n`;
      await writeTextAtomically(revisedPlanPath, revisedPlanContent);
      const revisionRequest = {
        version: "video-factory/scene-revision-v1",
        reviewArtifactId: draft.reviewArtifactId,
        findingIndex: draft.findingIndex,
        scenePosition,
        reuseFromScenePosition: draft.reuseFromScenePosition,
        actor: draft.actor.trim(),
        note: draft.note.trim(),
      };
      const runner = new WorkflowRunner({
        optionalReviewInvalidationOperations: await verifiedOptionalReviewInvalidationOperations(previous, this.store.runDirectory(runId)),
        providers: this.createRegistry(brief),
        clock: this.clock,
        idFactory: this.idFactory,
      });
      const revised = runner.applyNodeRevision(definition, withExecutableBrief(previous, brief), {
        nodeId: "assets",
        actor: draft.actor.trim(),
        output: {
          ...currentAssetOutput,
          assetPlanPath: revisedPlanPath,
          currentMediaArtifactIds: retainedArtifactIds,
        },
        artifacts: [
          fileArtifact(
            "asset_plan",
            revisedPlanPath,
            revisedPlanContent,
            "application/json",
            assetPlanArtifact.schemaVersion ?? "video-factory/asset-plan-v1",
            "assets",
            [assetPlanArtifact.id, draft.reviewArtifactId],
            "human-scene-revision-v1",
            "Creator-requested reuse of an existing run asset; no new Provider call was made.",
          ),
          jsonArtifact(
            "scene_revision_request",
            revisionRequest,
            "video-factory/scene-revision-v1",
            "assets",
            [assetPlanArtifact.id, draft.reviewArtifactId],
          ),
        ],
        retainedArtifactIds,
        invalidateDescendantNodeIds: [
          "asset-source-review",
          // BG-07：assets 失效后 voice 是其后代——旁白时间线基于旧 asset plan 计算，
          // 不得沿用；后续 render/review 已在列表中。
          "voice",
          "render",
          "technical-review",
          "visual-review",
          "final-review",
          "publish-package",
        ],
        expectedVersionId: draft.expectedAssetVersionId,
        schemaVersion: assetVersion.schemaVersion,
        decision: {
          interventionId: finalIntervention.id,
          action: "request_changes",
          actor: draft.actor.trim(),
          note: draft.note.trim(),
        },
      });
      await this.carryConfirmedNarrationPlan(previous, revised, draft.actor);
      return revised;
    });
    return this.dispatchResumeStale(runId, listener);
  }

  async requestSceneResourceRevision(
    runId: string,
    draft: ProductionSceneResourceRevisionDraft,
  ): Promise<WorkflowRun<ProductionBrief>> {
    const dispatched = await this.dispatchSceneResourceRevision(runId, draft);
    return dispatched.completion;
  }

  async dispatchSceneResourceRevision(
    runId: string,
    draft: ProductionSceneResourceRevisionDraft,
    listener?: ProductionRunListener,
  ): Promise<DispatchedProductionRun> {
    await this.runPersistedTransition(runId, async (previous) => {
      if (previous.revision !== draft.expectedRunRevision) {
        throw new StaleRunRevisionError(runId, draft.expectedRunRevision, previous.revision);
      }
      if (previous.status !== "needs_human") {
        throw new Error(`Run '${runId}' is not waiting for human review.`);
      }
      if (!draft.actor.trim() || !draft.note.trim()) {
        throw new Error("Scene resource revision actor and note are required.");
      }
      if (!Number.isInteger(draft.findingIndex) || draft.findingIndex < 0) {
        throw new Error("Scene resource revision finding index is invalid.");
      }

      const brief = parsePersistedBrief(previous.initialInput);
      const definition = this.createWorkflow(brief);
      const finalIntervention = previous.nodeRuns.find((node) => node.nodeId === "final-review")?.intervention;
      if (!finalIntervention) throw new Error("Scene resource revision requires an active final-review intervention.");
      const visualReviewNodeRun = previous.nodeRuns.find((node) => node.nodeId === "visual-review");
      const visualReviewVersion = visualReviewNodeRun?.outputState?.versions.find(
        (version) => version.id === visualReviewNodeRun.outputState?.effectiveVersionId,
      );
      const reviewArtifact = previous.artifacts.find((artifact) => artifact.id === draft.reviewArtifactId);
      if (
        !visualReviewVersion?.artifactIds.includes(draft.reviewArtifactId)
        || reviewArtifact?.kind !== "review_report"
        || reviewArtifact.producer?.nodeId !== "visual-review"
      ) {
        throw new Error("Scene resource revision requires a current visual-review report artifact.");
      }
      await verifyStoredArtifactWithinRoot(this.store.runDirectory(runId), reviewArtifact);
      const reviewOutput = requireOutputRecord(
        visualReviewVersion.output ?? visualReviewNodeRun?.output,
        "visual review output",
      );
      const reviewDurationMs = Number(reviewOutput.durationMs);
      if (!Number.isInteger(reviewDurationMs) || reviewDurationMs <= 0) {
        throw new Error("Current visual-review duration is invalid.");
      }
      const storedReportValue = JSON.parse(await readFile(reviewArtifact.uri!, "utf8"));
      assertCurrentVisualReviewContract(storedReportValue);
      const storedReport = validateAggregatedVisualReviewReport(storedReportValue, reviewDurationMs);
      if (draft.findingIndex >= storedReport.findings.length) {
        throw new Error("Scene resource revision finding is no longer current.");
      }

      const renderNodeRun = previous.nodeRuns.find((node) => node.nodeId === "render");
      const renderVersion = renderNodeRun?.outputState?.versions.find(
        (version) => version.id === renderNodeRun.outputState?.effectiveVersionId,
      );
      const renderOutput = requireOutputRecord(renderVersion?.output ?? renderNodeRun?.output, "render output");
      const renderManifestPath = requiredOutputString(renderOutput, "renderManifestPath");
      const renderManifestArtifact = previous.artifacts.find((artifact) => (
        renderVersion?.artifactIds.includes(artifact.id)
        && artifact.kind === "render_manifest"
        && artifact.uri === renderManifestPath
        && artifact.producer?.nodeId === "render"
      ));
      if (!renderManifestArtifact) {
        throw new Error("Scene resource revision requires the current render manifest artifact.");
      }
      await verifyStoredArtifactWithinRoot(this.store.runDirectory(runId), renderManifestArtifact);
      const localizedReport = await localizeVisualReviewReport(storedReport, renderManifestPath, reviewDurationMs);
      const finding = localizedReport.findings[draft.findingIndex]!;
      // 这条路径只处理"画面本身不合格"。审片把不合格指向别的节点（配音、时长）时，
      // 换素材既不是它要的动作，也解释不了它的结论。
      if (finding.targetNodeId !== "assets" || finding.nextAction !== "rework_asset") {
        throw new Error("Scene resource revision requires a finding that asks for the scene asset itself to be reworked.");
      }
      const scenePosition = finding.scenePosition;
      if (typeof scenePosition !== "number" || !Number.isInteger(scenePosition) || scenePosition < 1) {
        throw new Error("Scene resource revision finding is not localized to a scene.");
      }

      const joint = usesJointCreativePlanning(brief);
      const planningNodeId = joint ? "creative-planning" : "visual-direction";
      const planningNodeRun = previous.nodeRuns.find((node) => node.nodeId === planningNodeId);
      const planningVersion = planningNodeRun?.outputState?.versions.find(
        (version) => version.id === planningNodeRun.outputState?.effectiveVersionId,
      );
      if (!planningVersion) {
        throw new Error(`Scene resource revision requires the current '${planningNodeId}' output version.`);
      }
      const planningOutput = requireOutputRecord(
        planningVersion.output ?? planningNodeRun?.output,
        `${planningNodeId} output`,
      );
      const rankingPath = requiredOutputString(planningOutput, "candidateRankingPath");
      const rankingArtifact = previous.artifacts.find((artifact) => (
        planningVersion.artifactIds.includes(artifact.id)
        && artifact.uri === rankingPath
        && artifact.producer?.nodeId === planningNodeId
      ));
      if (!rankingArtifact) {
        throw new Error("Scene resource revision requires the current candidate ranking artifact.");
      }
      await verifyStoredArtifactWithinRoot(this.store.runDirectory(runId), rankingArtifact);
      const ranking = requireOutputRecord(
        JSON.parse(await readFile(rankingArtifact.uri!, "utf8")),
        "candidate ranking",
      );
      const assetsNode = previous.nodeRuns.find(node => node.nodeId === "assets");
      const assetsVersion = assetsNode?.outputState?.versions.find(version => version.id === assetsNode.outputState?.effectiveVersionId);
      const assetsArtifact = previous.artifacts.find(artifact => artifact.kind === "asset_plan"
        && assetsVersion?.artifactIds.includes(artifact.id) && artifact.producer?.nodeId === "assets");
      if (!assetsArtifact?.uri) throw new Error("Current asset plan artifact is unavailable.");
      await verifyStoredArtifactWithinRoot(this.store.runDirectory(runId), assetsArtifact);
      const assetsPlan = requireOutputRecord(JSON.parse(await readFile(assetsArtifact.uri, "utf8")), "current asset plan");
      const actual = Array.isArray(assetsPlan.scene_assets) ? assetsPlan.scene_assets.filter(isObjectRecord)
        .find(scene => scene.scene_position === scenePosition) : undefined;
      if (typeof actual?.provider !== "string" || typeof actual.asset_id !== "string") {
        throw new Error("Current scene asset identity is unavailable; refusing to guess rank one.");
      }
      const advance = advanceSceneCandidateRanking(ranking, scenePosition, { provider: actual.provider, assetId: actual.asset_id });
      const revisionDirectory = path.join(
        this.runsRoot,
        runId,
        "nodes",
        planningNodeId,
        "revisions",
        `revision-${previous.revision + 1}`,
      );
      await mkdir(revisionDirectory, { recursive: true });
      const revisedRankingPath = path.join(revisionDirectory, "candidate_ranking.json");
      const revisedRankingContent = `${JSON.stringify(advance.ranking, null, 2)}\n`;
      await writeTextAtomically(revisedRankingPath, revisedRankingContent);
      const revisionRequest = {
        version: "video-factory/scene-resource-revision-v1",
        reviewArtifactId: draft.reviewArtifactId,
        findingIndex: draft.findingIndex,
        scenePosition,
        replacedProvider: advance.replaced.provider,
        replacedAssetId: advance.replaced.assetId,
        replacementProvider: advance.replacement.provider,
        replacementAssetId: advance.replacement.assetId,
        actor: draft.actor.trim(),
        note: draft.note.trim(),
      };
      const runner = new WorkflowRunner({
        optionalReviewInvalidationOperations: await verifiedOptionalReviewInvalidationOperations(previous, this.store.runDirectory(runId)),
        providers: this.createRegistry(brief),
        clock: this.clock,
        idFactory: this.idFactory,
      });
      // 失效从素材节点起：画面要换，素材必须重取，其下游全部作废。
      // 但改动只落在排序上——其它镜头的检索意图与候选一个字段都没动，
      // 已付费分镜的输入指纹因此不变，重跑时按原样带过，不产生新的 Provider 调用。
      const invasiveNodeIds = [
        "assets",
        "asset-source-review",
        "voice",
        "render",
        "technical-review",
        "visual-review",
        "final-review",
        "publish-package",
      ].filter((nodeId) => productionNodeIds(brief).includes(nodeId));
      const revised = runner.applyNodeRevision(definition, withExecutableBrief(previous, brief), {
        nodeId: planningNodeId,
        actor: draft.actor.trim(),
        output: {
          ...planningOutput,
          candidateRankingPath: revisedRankingPath,
        },
        artifacts: [
          fileArtifact(
            // 沿用被改那一份的 kind：素材节点按本拓扑的既有约定认排序，这里不该另发明一种。
            rankingArtifact.kind,
            revisedRankingPath,
            revisedRankingContent,
            "application/json",
            rankingArtifact.schemaVersion ?? "video-factory/asset-ranking-v1",
            planningNodeId,
            [rankingArtifact.id, draft.reviewArtifactId],
            "human-scene-resource-revision-v1",
            "Creator-requested reselection among this scene's already-reviewed candidates; no new Provider call was made.",
            rankingArtifact.producer?.attempt ?? 1,
          ),
          jsonArtifact(
            "scene_resource_revision_request",
            revisionRequest,
            "video-factory/scene-resource-revision-v1",
            planningNodeId,
            [rankingArtifact.id, draft.reviewArtifactId],
          ),
        ],
        // 原排序留在版本里：候选搜索与排序是那次规划的证据快照，人工改选是另立一件，
        // 与被改的那一版并列可查，而不是把原稿覆盖掉。
        retainedArtifactIds: planningVersion.artifactIds,
        invalidateDescendantNodeIds: invasiveNodeIds,
        expectedVersionId: planningVersion.id,
        schemaVersion: planningVersion.schemaVersion,
        decision: {
          interventionId: finalIntervention.id,
          action: "request_changes",
          actor: draft.actor.trim(),
          note: draft.note.trim(),
        },
      });
      return revised;
    });
    return this.dispatchResumeStale(runId, listener);
  }

  async requestNarrationRevision(
    runId: string,
    draft: ProductionNarrationRevisionDraft,
  ): Promise<WorkflowRun<ProductionBrief>> {
    const dispatched = await this.dispatchNarrationRevision(runId, draft);
    return dispatched.completion;
  }

  async dispatchNarrationRevision(
    runId: string,
    draft: ProductionNarrationRevisionDraft,
    listener?: ProductionRunListener,
  ): Promise<DispatchedProductionRun> {
    if (parsePersistedBrief((await this.store.load<ProductionBrief>(runId)).initialInput).audioMode === "native_av") {
      throw new HumanDecisionConflictError("视频原声不支持独立TTS改词、排轨或字幕恢复，请返回规划或关联返工。");
    }
    if (draft.action === "relayout_narration") {
      const parsed = parseNarrationRelayoutRequest(draft);
      return this.dispatchNarrationRelayout(runId, { ...parsed, actor: draft.actor.trim() }, listener);
    }
    if (draft.action === "recover_subtitles") return this.dispatchSubtitleRecovery(runId, draft, listener);
    await this.runPersistedTransition(runId, async (previous) => {
      if (previous.revision !== draft.expectedRunRevision) {
        throw new StaleRunRevisionError(runId, draft.expectedRunRevision, previous.revision);
      }
      if (previous.status !== "needs_human") {
        throw new Error(`Run '${runId}' is not waiting for human review.`);
      }
      if (!draft.actor.trim() || !draft.note.trim()) {
        throw new Error("Narration revision actor and note are required.");
      }
      if (!Number.isInteger(draft.scenePosition) || draft.scenePosition < 1) {
        throw new Error("Narration revision scene position is invalid.");
      }
      const narration = draft.narration.trim();
      if (!narration) {
        throw new Error("Narration revision text must not be empty.");
      }
      if (narration.length > 600 || /[\u0000-\u001f\u007f]/.test(narration)) {
        throw new Error("Narration revision text is not a valid single line of narration.");
      }

      const brief = parsePersistedBrief(previous.initialInput);
      if (brief.presentationMode === "character_drama") {
        throw new HumanDecisionConflictError("角色剧情不能保存为单旁白。请回到脚本工作区修改对应角色和台词，已有声音保留。");
      }
      const definition = this.createWorkflow(brief);
      const finalIntervention = previous.nodeRuns.find((node) => node.nodeId === "final-review")?.intervention;
      if (!finalIntervention) throw new Error("Narration revision requires an active final-review intervention.");

      // 脚本是配音与字幕共同的来源。改字要落在脚本上，否则下游仍会读到旧文字；
      // 但画面（assets）与画面预检不受这一行字影响，因此从失效清单里排除。
      const joint = usesJointCreativePlanning(brief);
      const planningNodeId = joint ? "creative-planning" : "script";
      const planningNodeRun = previous.nodeRuns.find((node) => node.nodeId === planningNodeId);
      const planningVersion = planningNodeRun?.outputState?.versions.find(
        (version) => version.id === planningNodeRun.outputState?.effectiveVersionId,
      );
      if (!planningVersion) throw new Error(`Narration revision requires the current '${planningNodeId}' output version.`);
      const planningOutput = requireOutputRecord(
        planningVersion.output ?? planningNodeRun?.output,
        `${planningNodeId} output`,
      );
      const scriptPath = requiredOutputString(planningOutput, "scriptPath");
      // 认产物看的是"它是不是这个节点写在 scriptPath 上的那一份"，而不是它的 kind：
      // AI 编剧产出的 kind 是 script，模板与 Python worker 拓扑下是 script_draft，两种都要能改。
      const scriptArtifact = previous.artifacts.find((artifact) => (
        planningVersion.artifactIds.includes(artifact.id)
        && artifact.uri === scriptPath
        && artifact.producer?.nodeId === planningNodeId
      ));
      if (!scriptArtifact) throw new Error("Narration revision requires the current script artifact.");
      await verifyStoredArtifactWithinRoot(this.store.runDirectory(runId), scriptArtifact);
      const script = requireOutputRecord(
        JSON.parse(await readFile(scriptPath, "utf8")),
        "script",
      );
      if (!Array.isArray(script.scenes)) throw new Error("Narration revision requires a script with scenes.");
      const sceneIndex = script.scenes.findIndex((scene) => (
        typeof scene === "object" && scene !== null && !Array.isArray(scene)
        && Number((scene as Record<string, unknown>).position) === draft.scenePosition
      ));
      if (sceneIndex < 0) {
        throw new Error(`Narration revision scene ${draft.scenePosition} is no longer in the current script.`);
      }
      const revisedScript = {
        ...script,
        // 第 1 镜的旁白同时是脚本的 hook 字段；只改旁白不改它，脚本会自相矛盾。
        ...(sceneIndex === 0 ? { hook: narration } : {}),
        scenes: script.scenes.map((scene, index) => (
          index === sceneIndex ? { ...requireOutputRecord(scene, `script scene ${index + 1}`), narration } : scene
        )),
      };
      const revisionDirectory = path.join(
        this.runsRoot,
        runId,
        "nodes",
        planningNodeId,
        "revisions",
        `revision-${previous.revision + 1}`,
      );
      await mkdir(revisionDirectory, { recursive: true });
      const revisedScriptPath = path.join(revisionDirectory, "script.json");
      const revisedScriptContent = `${JSON.stringify(revisedScript, null, 2)}\n`;
      await writeTextAtomically(revisedScriptPath, revisedScriptContent);
      const revisionRequest = {
        version: "video-factory/narration-revision-v1",
        scenePosition: draft.scenePosition,
        actor: draft.actor.trim(),
        note: draft.note.trim(),
      };
      const runner = new WorkflowRunner({
        optionalReviewInvalidationOperations: await verifiedOptionalReviewInvalidationOperations(previous, this.store.runDirectory(runId)),
        providers: this.createRegistry(brief),
        clock: this.clock,
        idFactory: this.idFactory,
      });
      // 失效范围是"读这一行字的下游"，收窄到配音以后：画面没变，重新买画面是纯浪费。
      // 计划里允许改文字的前提是别的一切照旧，所以镜位之外的字段一个都没动。
      const invasiveNodeIds = [
        "voice",
        "render",
        "technical-review",
        "visual-review",
        "final-review",
        "publish-package",
      // 按图里有没有这个节点来过滤，而不是按"跑没跑过"：还没轮到的下游（如 publish-package）
      // 同样是这一行字的下游，漏掉它会让失效集不闭合。
      ].filter((nodeId) => productionNodeIds(brief).includes(nodeId));
      const revised = runner.applyNodeRevision(definition, withExecutableBrief(previous, brief), {
        nodeId: planningNodeId,
        actor: draft.actor.trim(),
        output: {
          ...planningOutput,
          scriptPath: revisedScriptPath,
        },
        artifacts: [
          fileArtifact(
            // 沿用被改那一份的 kind：下游按本拓扑的既有约定认脚本，这里不该另发明一种。
            scriptArtifact.kind,
            revisedScriptPath,
            revisedScriptContent,
            "application/json",
            scriptArtifact.schemaVersion ?? "video-factory/script-draft-v1",
            planningNodeId,
            // 父级是被改的那一版原稿：如实记录"这行字从哪一版改来"，不冒充任何 Provider 产物。
            [scriptArtifact.id],
            "human-narration-revision-v1",
            "Creator-edited narration and caption text; no Provider call was made for the visuals.",
            scriptArtifact.producer?.attempt ?? 1,
          ),
          jsonArtifact(
            "narration_revision_request",
            revisionRequest,
            "video-factory/narration-revision-v1",
            planningNodeId,
            [scriptArtifact.id],
          ),
        ],
        // 被替换掉的原稿是否留在版本里，两种拓扑的答案不同：
        // legacy 的脚本节点只有脚本本身，直接换掉即可；
        // joint 的可执行方案按 artifact id 引用脚本，而方案的引用集受"必须同属规划节点当前
        // 接受版本"的约束（verifyExecutablePlanReferenceClosure）。方案是那次规划 commit 的
        // 证据快照——commit 文件里记的引用 id 与磁盘字节都要求方案继续指向原稿，方案本身也
        // 不该被人工改字动到。所以 joint 下原稿必须留在版本里：丢掉它，方案就引用了一份不在
        // 版本内的脚本，assets/voice 一消费方案就 fail closed（这正是生产里复现的失败）。
        // 人工改出来的新稿件另立一件，下游按 output.scriptPath 读新文字；方案的时长与镜位
        // 一个字段都没动，所以既不重编译、也不产生任何 Provider 调用与费用。
        retainedArtifactIds: planningVersion.artifactIds.filter((artifactId) => (
          joint || artifactId !== scriptArtifact.id
        )),
        invalidateDescendantNodeIds: invasiveNodeIds,
        expectedVersionId: planningVersion.id,
        schemaVersion: planningVersion.schemaVersion,
        decision: {
          interventionId: finalIntervention.id,
          action: "request_changes",
          actor: draft.actor.trim(),
          note: draft.note.trim(),
        },
      });
      await this.carryConfirmedNarrationPlan(previous, revised, draft.actor);
      return revised;
    });
    return this.dispatchResumeStale(runId, listener);
  }

  /** §2.4/§2.5 纯本地排轨：核清单→原raw→本地assemble→字幕重映射；零 TTS、零素材购买。 */
  private async dispatchNarrationRelayout(
    runId: string, draft: NarrationRelayoutRequest & { actor: string }, listener?: ProductionRunListener,
  ): Promise<DispatchedProductionRun> {
    return this.dispatchPersistedTransition(runId, async (previous, checkpoint) => {
      if (!draft.actor.trim()) throw new HumanDecisionConflictError("时间调整需要创作者身份。");
      const brief = parsePersistedBrief(previous.initialInput);
      const voice = previous.nodeRuns.find((node) => node.nodeId === "voice");
      if (!voice?.outputState) throw new HumanDecisionConflictError("这条制作还没有可调整的声音版本。");
      const runDirectory = this.store.runDirectory(runId);
      const operationsDirectory = path.join(runDirectory, "nodes", "voice", "relayout-operations");
      const requestDigest = contentSha256(draft.intent === "apply" ? {
        runId, action: draft.action, intent: draft.intent, requestId: draft.requestId,
        actor: draft.actor, expectedRunRevision: draft.expectedRunRevision,
        interventionId: draft.interventionId, sourceContextId: draft.sourceContextId,
        source: draft.source, layout: draft.layout, note: draft.note,
      } : {
        runId, action: draft.action, intent: draft.intent, requestId: draft.requestId,
        actor: draft.actor, expectedRunRevision: draft.expectedRunRevision,
        interventionId: draft.interventionId, targetRequestId: draft.targetRequestId,
        note: draft.note,
      });
      // §2.5/§4.2.6：同ID同内容重放返回原结果；同ID异内容拒绝；操作文件是去重锚的一部分。
      // 采用权威是 run 本身（appliedRequestId + voice 版本），旁边操作 JSON 不能单独宣布成功。
      let reservedOperation: Record<string, unknown> | undefined;
      try {
        const saved = JSON.parse(await readFile(path.join(operationsDirectory, `${draft.requestId}.json`), "utf8")) as Record<string, unknown>;
        if (isObjectRecord(saved) && saved.version === RELAYOUT_OPERATION_VERSION) {
          if (saved.requestDigest !== requestDigest) {
            throw new HumanDecisionConflictError("同一时间调整请求身份已被不同内容使用，请换新的请求。");
          }
          if (saved.state === "discarded") {
            // discard 请求自身的重放，或已被撤销 apply 的原 ID 重放，都只返回
            // 当前权威 run；discarded 是终态，不得重启 worker 把旧意图复活。
            return { replay: previous };
          }
          if (saved.state === "applied") {
            const adopted = voice.outputState?.versions.find((candidate) =>
              isObjectRecord(candidate.output)
              && candidate.output.appliedRequestId === draft.requestId
              && candidate.output.requestDigest === requestDigest);
            if (adopted) {
              const adoption = isObjectRecord(adopted.output) && isObjectRecord(adopted.output.relayoutAdoption)
                ? adopted.output.relayoutAdoption : undefined;
              await writeTextAtomically(path.join(operationsDirectory, `${draft.requestId}.json`),
                `${JSON.stringify({ ...saved, state: "applied", resultVoiceVersionId: adopted.id,
                  ...(typeof adoption?.resultingRunRevision === "number"
                    ? { resultingRunRevision: adoption.resultingRunRevision } : {}) }, null, 2)}\n`);
              return { replay: previous };
            }
            if (draft.intent === "apply" && isObjectRecord(saved.output)
              && Array.isArray(saved.artifacts)
              && typeof saved.output.completionReceiptPath === "string") {
              // 旧进程可能在 run 保存前错误地先投影 applied；按完成收据重新核验后才允许采用。
              reservedOperation = { ...saved, state: "completed" };
            } else {
              throw new HumanDecisionConflictError("操作记录声称已采用，但制作中没有对应的声音版本（记录超前），请核查原记录。");
            }
          }
          if (saved.state === "completed") {
            const adopted = voice.outputState?.versions.find((candidate) => isObjectRecord(candidate.output)
              && candidate.output.appliedRequestId === draft.requestId
              && candidate.output.requestDigest === requestDigest);
            if (adopted) {
            // §4.2.6 侧文件落后（操作记录停在 completed，run 已采用）：先对照真实采用，
              // 显式原 ID 重放修复侧投影，但不重复采用、不制造重复版本。
              const adoption = isObjectRecord(adopted.output) && isObjectRecord(adopted.output.relayoutAdoption)
                ? adopted.output.relayoutAdoption : undefined;
              await writeTextAtomically(path.join(operationsDirectory, `${draft.requestId}.json`),
                `${JSON.stringify({ ...saved, state: "applied", appliedAt: saved.appliedAt ?? this.clock(),
                  resultVoiceVersionId: adopted.id,
                  ...(typeof adoption?.resultingRunRevision === "number"
                    ? { resultingRunRevision: adoption.resultingRunRevision } : {}) }, null, 2)}\n`);
              return { replay: previous };
            }
          }
          if (draft.intent === "apply" && (saved.state === "reserved" || saved.state === "completed")) {
            // 同一 requestId 的恢复沿用原预留（attempt 目录/输入版本身份），不再预留新目录。
            reservedOperation = saved;
          }
          if (draft.intent === "apply" && saved.state === "failed") {
            // 确定性 fit/非法布局失败不得用原 ID 自动重跑。当前 worker 尚未生产
            // 有限的“已结束且可恢复本地 IO”错误码，所以 failed 保守地终止；用户
            // 可先显式撤销，再以新 requestId 提交新布局。
            throw new HumanDecisionConflictError("这次时间调整已明确失败，原请求不会自动重跑；请先撤销后再提交新布局。");
          }
        }
      } catch (error) {
        // 仅"尚无操作记录"继续首次执行；同 ID 异内容等一切其他错误都向上抛。
        if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
      }
      // §2.5：重放识别完成后才判断旧 revision；首次执行在这里做 CAS。
      if (previous.revision !== draft.expectedRunRevision) {
        throw new StaleRunRevisionError(runId, draft.expectedRunRevision, previous.revision);
      }
      const planning = currentPlanningOutputPaths(
        { outputs: new Map(previous.nodeRuns.map((node) => [node.nodeId, effectiveNodeOutput(node)])) }, brief);
      if (!planning.executablePlanPath) throw new HumanDecisionConflictError("正式画面方案不可读，无法调整声音时间。");
      const definition = this.createWorkflow(brief);

      // 首次 apply/discard 都必须来自当前真实停点；历史终态重放已在 CAS 之前返回。
      const stopOwner = previous.nodeRuns.find((node) => node.status === "needs_human"
        && node.intervention?.id === draft.interventionId
        && (node.nodeId === "voice" || node.nodeId === "final-review"));
      if (!stopOwner) {
        throw new HumanDecisionConflictError("时间调整必须从当前有效的声音试听或成片返工停点发起；请刷新后重试。");
      }

      const discardUnapplied = async (discard: Extract<NarrationRelayoutRequest,
        { intent: "discard_unapplied" }>): Promise<WorkflowRun<ProductionBrief>> => {
        // 只撤销尚未采用的本地调整意图：保留原有效声音与可用停点，不触碰任何产物版本。
        // §4.2.6 discard 有自己的耐久请求；先把 target 写成终态，再写 discard
        // 结果。若两次原子写之间中断，同 discard ID 可根据 target 上的摘要补齐。
        const targetPath = path.join(operationsDirectory, `${discard.targetRequestId}.json`);
        const discardPath = path.join(operationsDirectory, `${discard.requestId}.json`);
        let target: Record<string, unknown>;
        try {
          target = JSON.parse(await readFile(targetPath, "utf8")) as Record<string, unknown>;
        } catch {
          throw new HumanDecisionConflictError("要撤销的时间调整不存在或已结束；原声音与停点保持不变。");
        }
        if (!isObjectRecord(target) || target.version !== RELAYOUT_OPERATION_VERSION
          || target.intent !== "apply" || target.actor !== draft.actor) {
          throw new HumanDecisionConflictError("该时间调整身份不符，不能撤销；原声音保留。");
        }
        if (target.state === "reserved"
          && typeof target.attemptDirectory === "string"
          && typeof target.commandId === "string"
          && typeof target.attempt === "number"
          && typeof target.workerExecutionToken === "string") {
          await assertNarrationRelayoutWorkerInactive(target.attemptDirectory, {
            commandId: target.commandId,
            attempt: target.attempt,
            workerExecutionToken: target.workerExecutionToken,
          });
        }
        const adopted = voice.outputState?.versions.some((candidate) => isObjectRecord(candidate.output)
          && (candidate.output as Record<string, unknown>).appliedRequestId === discard.targetRequestId);
        if (adopted) {
          throw new HumanDecisionConflictError("该时间调整已被制作记录采用，不能撤销；原声音保留。");
        }
        if (target.state === "discarded"
          && (target.discardRequestId !== discard.requestId || target.discardRequestDigest !== requestDigest)) {
          throw new HumanDecisionConflictError("该时间调整已由另一条撤销请求结束；不会改写原记录。");
        }
        const discardedAt = typeof target.discardedAt === "string" ? target.discardedAt : this.clock();
        const previousTargetState = target.state === "discarded"
          ? (typeof target.previousState === "string" ? target.previousState : "unknown") : target.state;
        if (target.state !== "discarded") {
          await writeTextAtomically(targetPath, `${JSON.stringify({
            ...target, state: "discarded", previousState: previousTargetState,
            discardedBy: draft.actor, discardedAt, discardRequestId: discard.requestId,
            discardRequestDigest: requestDigest,
          }, null, 2)}\n`);
        }
        const discardRecord = {
          version: RELAYOUT_OPERATION_VERSION, requestId: discard.requestId, requestDigest,
          actor: draft.actor, state: "discarded" as const, intent: discard.intent,
          expectedRunRevision: discard.expectedRunRevision, interventionId: discard.interventionId,
          targetRequestId: discard.targetRequestId, note: discard.note,
          createdAt: discardedAt, discardedAt,
          result: { targetRequestId: discard.targetRequestId, targetState: "discarded", previousTargetState },
        };
        await writeTextAtomically(discardPath, `${JSON.stringify(discardRecord, null, 2)}\n`);
        return previous;
      };

      if (draft.intent === "discard_unapplied") {
        // 丢弃未采用的意图后 run 不变：走重放通道，不产生新版本或重复保存。
        return { replay: await discardUnapplied(draft) };
      }
      const apply = draft;
      await assertNoOtherPendingNarrationRelayout(operationsDirectory, apply.requestId);

      // ── apply：先解析来源（两类身份不可混淆），再调用本地 worker ──
      type OriginVoiceSourceIdentity = {
        voiceInputVersionId: string;
        sourceContextId?: string;
        narrationPlanPath: string;
        scriptArtifactId: string;
        scriptOutputVersionId: string;
        visualArtifactId: string;
        visualOutputVersionId: string;
        parentArtifactIds: string[];
        upstreamVersionIds: string[];
      };
      const resolveOriginVoiceSourceIdentity = async (
        manifest: Record<string, unknown>, sourceOperationId: string,
      ): Promise<OriginVoiceSourceIdentity> => {
        if (manifest.sourceOperationId !== sourceOperationId) {
          throw new HumanDecisionConflictError("来源清单与原声音操作身份不一致，请核查原记录。");
        }
        const voiceInputVersionId = requiredOutputString(manifest, "voiceInputVersionId");
        const inputVersion = voice.inputState?.versions.find((candidate) => candidate.id === voiceInputVersionId);
        const input = requireOutputRecord(inputVersion?.value, "original voice input");
        if (input.voiceInputVersionId !== voiceInputVersionId) {
          throw new HumanDecisionConflictError("原声音输入版本缺少可核对的正式采用身份。");
        }
        const narrationPlanPath = requiredOutputString(input, "narrationPlanPath");
        const narrationPlan = requireOutputRecord(manifest.narrationPlan, "manifest narration plan");
        const voiceNodeRoot = path.join(runDirectory, "nodes", "voice");
        const voiceNodeRootReal = await realpath(voiceNodeRoot);
        const planReal = await realpath(narrationPlanPath);
        const manifestPlanReal = await realpath(path.join(voiceNodeRoot,
          requiredOutputString(narrationPlan, "relativePath")));
        if (planReal !== manifestPlanReal || path.relative(voiceNodeRootReal, planReal).startsWith("..")) {
          throw new HumanDecisionConflictError("原声音计划不在当前 run 的声音目录内，不能据此调整时间。");
        }
        const planBytes = await readFile(planReal);
        if (createHash("sha256").update(planBytes).digest("hex") !== narrationPlan.sha256) {
          throw new HumanDecisionConflictError("原声音计划的实际文件字节已变化，不能据此调整时间。");
        }
        const planArtifact = previous.artifacts.find((artifact) => artifact.kind === "narration_plan"
          && path.resolve(artifact.uri ?? "") === path.resolve(narrationPlanPath));
        if (!planArtifact || planArtifact.sha256 !== narrationPlan.sha256) {
          throw new HumanDecisionConflictError("原声音计划缺少与实际字节一致的正式产物记录。");
        }
        await verifyStoredArtifactWithinRoot(runDirectory, planArtifact);

        const parentArtifactIds = Array.isArray(input.parentArtifactIds)
          && input.parentArtifactIds.every((value): value is string => typeof value === "string")
          ? [...input.parentArtifactIds] : [];
        const upstreamVersionIds = Array.isArray(inputVersion?.upstreamVersionIds)
          && inputVersion.upstreamVersionIds.every((value): value is string => typeof value === "string")
          ? [...inputVersion.upstreamVersionIds] : [];
        if (!isDeepStrictEqual(parentArtifactIds, manifest.parentArtifactIds)
          || !isDeepStrictEqual(upstreamVersionIds, manifest.upstreamVersionIds)) {
          throw new HumanDecisionConflictError("原声音输入与来源清单的上游版本或父产物绑定不一致。");
        }
        const sourceContextId = typeof input.sourceContextId === "string" ? input.sourceContextId : undefined;
        if ((typeof manifest.sourceContextId === "string" ? manifest.sourceContextId : undefined) !== sourceContextId) {
          throw new HumanDecisionConflictError("原声音输入与来源清单的来源上下文不一致。");
        }

        const verifyUpstreamArtifact = async (options: {
          manifestField: "script" | "visualPlan";
          inputArtifactField: "scriptArtifactId" | "visualArtifactId";
          inputVersionField: "scriptOutputVersionId" | "visualOutputVersionId";
          label: string;
        }): Promise<{ artifactId: string; outputVersionId: string }> => {
          const recorded = requireOutputRecord(manifest[options.manifestField], options.label);
          const artifactId = requiredOutputString(input, options.inputArtifactField);
          const outputVersionId = requiredOutputString(input, options.inputVersionField);
          if (recorded.artifactId !== artifactId || recorded.outputVersionId !== outputVersionId) {
            throw new HumanDecisionConflictError(`${options.label}的来源身份与原声音输入不一致。`);
          }
          const artifact = previous.artifacts.find((candidate) => candidate.id === artifactId);
          if (!artifact?.sha256 || artifact.sha256 !== recorded.sha256) {
            throw new HumanDecisionConflictError(`${options.label}的正式产物摘要与来源清单不一致。`);
          }
          await verifyStoredArtifactWithinRoot(runDirectory, artifact);
          const producer = previous.nodeRuns.find((node) => node.nodeId === artifact.producer?.nodeId);
          const effective = producer?.outputState?.versions.find((version) =>
            version.id === producer.outputState?.effectiveVersionId);
          if (!effective || effective.id !== outputVersionId || !effective.artifactIds.includes(artifactId)) {
            throw new HumanDecisionConflictError(`${options.label}已不是当前有效输出版本，请先重新确认声音来源。`);
          }
          return { artifactId, outputVersionId };
        };
        const script = await verifyUpstreamArtifact({ manifestField: "script", inputArtifactField: "scriptArtifactId",
          inputVersionField: "scriptOutputVersionId", label: "正式稿件" });
        const visual = await verifyUpstreamArtifact({ manifestField: "visualPlan", inputArtifactField: "visualArtifactId",
          inputVersionField: "visualOutputVersionId", label: "正式画面方案" });

        const ledger = requireOutputRecord(manifest.ledger, "manifest ledger");
        const snapshot = requireOutputRecord(ledger.snapshot, "manifest ledger snapshot");
        const snapshotReal = await realpath(path.join(voiceNodeRoot, requiredOutputString(snapshot, "relativePath")));
        if (path.relative(voiceNodeRootReal, snapshotReal).startsWith("..")) {
          throw new HumanDecisionConflictError("来源账本快照越出了当前 run 的声音目录。");
        }
        const snapshotBytes = await readFile(snapshotReal);
        if (createHash("sha256").update(snapshotBytes).digest("hex") !== snapshot.sha256
          || snapshotBytes.byteLength !== snapshot.byteSize || snapshot.contentType !== "application/json") {
          throw new HumanDecisionConflictError("来源账本快照的实际字节、大小或类型与登记不一致。");
        }
        const snapshotDoc = requireOutputRecord(JSON.parse(snapshotBytes.toString("utf8")), "voice ledger snapshot");
        if (snapshotDoc.operationId !== sourceOperationId || snapshotDoc.completed !== true) {
          throw new HumanDecisionConflictError("原声音账本尚未证明全部组已完成，不能进入本地排轨。");
        }
        return {
          voiceInputVersionId, ...(sourceContextId ? { sourceContextId } : {}), narrationPlanPath,
          scriptArtifactId: script.artifactId, scriptOutputVersionId: script.outputVersionId,
          visualArtifactId: visual.artifactId, visualOutputVersionId: visual.outputVersionId,
          parentArtifactIds, upstreamVersionIds,
        };
      };

      const resolveMaterializedSource = async (
        source: Extract<NarrationRelayoutRequest, { intent: "apply" }>["source"] & { kind: "materialized_operation" },
      ): Promise<{ manifestPath: string; sourceOperationId: string; relayoutSource: string;
        sourceIdentity: OriginVoiceSourceIdentity;
        sourceManifestIdentity: { artifactId: string; sha256: string } }> => {
        if (voice.inputState?.effectiveVersionId !== source.voiceInputVersionId) {
          throw new HumanDecisionConflictError("声音输入版本已变化，请重新查看首次配音的来源。");
        }
        const manifestArtifact = previous.artifacts.find((artifact) => artifact.id === source.sourceManifestArtifactId
          && artifact.kind === "voice_source_manifest");
        if (!manifestArtifact?.uri) throw new HumanDecisionConflictError("首次配音的来源清单留档缺失，请核查原记录。");
        await verifyStoredArtifactWithinRoot(runDirectory, manifestArtifact);
        const manifest = requireOutputRecord(JSON.parse(await readFile(manifestArtifact.uri, "utf8")), "voice source manifest");
        if (manifest.manifestSha256 !== source.sourceManifestSha256) {
          throw new HumanDecisionConflictError("来源清单与收据摘要不一致，不能据此调整时间。");
        }
        // §4.2.6.1 sourceContextId 消费校验：v2 来源必须与清单内登记的来源上下文一致。
        if (typeof manifest.sourceContextId === "string" && manifest.sourceContextId !== apply.sourceContextId) {
          throw new HumanDecisionConflictError("时间调整的来源上下文与清单不一致，请刷新后重试。");
        }
        const receiptArtifact = previous.artifacts.find((artifact) => artifact.id === source.sourceReceiptArtifactId);
        if (!receiptArtifact || receiptArtifact.kind !== "voice_source_receipt" || !receiptArtifact.uri) {
          throw new HumanDecisionConflictError("首次排轨失败的来源收据缺失或类型不符，请核查原记录。");
        }
        // §4.2.4 恢复侧收据核验：文件字节 SHA + 正文与 manifest/operation/input/sourceContext 的绑定。
        await verifyStoredArtifactWithinRoot(runDirectory, receiptArtifact);
        const receiptDoc = requireOutputRecord(JSON.parse(await readFile(receiptArtifact.uri, "utf8")), "voice source receipt");
        if (receiptDoc.version !== "video-factory/voice-source-receipt-v1"
          || !["first_fit_conflict", "layout_incomplete"].includes(String(receiptDoc.reason))
          || receiptDoc.manifestArtifactId !== manifestArtifact.id
          || receiptDoc.manifestSha256 !== source.sourceManifestSha256
          || receiptDoc.sourceOperationId !== source.sourceVoiceOperationId
          || receiptDoc.voiceInputVersionId !== source.voiceInputVersionId
          || (typeof manifest.sourceContextId === "string" && receiptDoc.sourceContextId !== manifest.sourceContextId)) {
          throw new HumanDecisionConflictError("来源收据与本次恢复请求的绑定不一致，不能据此调整时间。");
        }
        const sourceIdentity = await resolveOriginVoiceSourceIdentity(manifest, source.sourceVoiceOperationId);
        return { manifestPath: manifestArtifact.uri, sourceOperationId: source.sourceVoiceOperationId,
          relayoutSource: "materialized_operation", sourceIdentity,
          sourceManifestIdentity: { artifactId: manifestArtifact.id, sha256: source.sourceManifestSha256 } };
      };
      const resolveVoiceVersionSource = async (
        source: Extract<NarrationRelayoutRequest, { intent: "apply" }>["source"] & { kind: "voice_version" },
      ): Promise<{ manifestPath: string; sourceOperationId: string; relayoutSource: string;
        sourceIdentity: OriginVoiceSourceIdentity;
        sourceManifestIdentity: { artifactId: string; sha256: string } }> => {
        const voiceState = voice.outputState;
        if (!voiceState) throw new HumanDecisionConflictError("这条制作还没有可调整的声音版本。");
        if (voiceState.stale) throw new HumanDecisionConflictError("有效声音已过期，请先复核声音输入。");
        const version = voiceState.versions.find((candidate) => candidate.id === source.voiceVersionId);
        if (!version || version.id !== voiceState.effectiveVersionId) {
          throw new HumanDecisionConflictError("指定的声音版本已不是当前有效版本，请刷新后重试。");
        }
        const planArtifact = previous.artifacts.find((artifact) => artifact.id === source.voicePlanArtifactId
          && version.artifactIds.includes(artifact.id));
        if (!planArtifact?.uri || planArtifact.sha256 !== source.voicePlanSha256) {
          throw new HumanDecisionConflictError("有效声音的计划留档缺失或摘要不符。");
        }
        const planDoc = requireOutputRecord(JSON.parse(await readFile(planArtifact.uri, "utf8")), "voiceover plan");
        if (planDoc.voiceOperationId !== source.sourceVoiceOperationId
          || planDoc.layoutKey !== source.expectedLayoutKey
          || planCanonicalSha256V2(requireOutputRecord(planDoc.narrationPlan, "layout plan") as unknown as Parameters<typeof planCanonicalSha256V2>[0]) !== source.expectedNarrationPlanSha256) {
          throw new HumanDecisionConflictError("有效声音的计划或布局已变化，请重新查看后调整。");
        }
        const trackBound = previous.artifacts.some((artifact) => version.artifactIds.includes(artifact.id)
          && artifact.kind === "voiceover" && artifact.sha256 === source.expectedAudioSha256);
        if (!trackBound) throw new HumanDecisionConflictError("有效声音的音轨身份不匹配，不能据此调整时间。");
        // §4.2.6.1 sourceContextId 消费校验：有效输入固化了来源上下文时必须一致（v2）。
        const inputSourceContext = requireOutputRecord(
          voice.inputState?.versions.find((candidate) => candidate.id === voice.inputState?.effectiveVersionId)?.value,
          "voice input").sourceContextId;
        if (typeof inputSourceContext === "string" && inputSourceContext !== apply.sourceContextId) {
          throw new HumanDecisionConflictError("时间调整的来源上下文与当前声音输入不一致，请刷新后重试。");
        }
        // §4.2.5 origin manifest 显式引用：新 relayout 输出携带 originManifest（节点根相对路径 +
        // 文件字节 SHA + 正文摘要），不再从当前 attempt 同目录猜路径；旧成功版本无该引用时
        // 保留同目录探测作为 legacy 回退（不封已有路径）。
        const originReference = isObjectRecord(planDoc.originManifest)
          && typeof planDoc.originManifest.relativePath === "string" ? planDoc.originManifest : undefined;
        if (originReference) {
          const voiceNodeRoot = path.resolve(path.dirname(planArtifact.uri!), "..");
          const originPath = path.resolve(voiceNodeRoot, String(originReference.relativePath));
          // 词法包含检查：relativePath 由 Python 端 relative_to 保证为节点根内的相对路径；
          // 不用绝对前缀比较（macOS 临时目录 /var 与 /private/var 的符号链接会误判越根）。
          const relativeToNode = path.relative(voiceNodeRoot, originPath);
          if (!relativeToNode || relativeToNode.startsWith("..") || path.isAbsolute(relativeToNode)) {
            throw new HumanDecisionConflictError("origin manifest 引用越出了运行目录，不能据此调整时间。");
          }
          const originBytes = await readFile(originPath);
          if (createHash("sha256").update(originBytes).digest("hex") !== originReference.fileSha256) {
            throw new HumanDecisionConflictError("origin manifest 与其登记的字节摘要不一致，请核查原记录。");
          }
          const originManifest = requireOutputRecord(JSON.parse(originBytes.toString("utf8")), "origin voice manifest");
          const originArtifact = previous.artifacts.find((artifact) => artifact.kind === "voice_source_manifest"
            && artifact.uri && path.resolve(artifact.uri) === originPath
            && artifact.sha256 === originReference.fileSha256);
          if (!originArtifact || typeof originReference.manifestSha256 !== "string") {
            throw new HumanDecisionConflictError("origin manifest 缺少正式产物身份，不能据此调整时间。");
          }
          const sourceIdentity = await resolveOriginVoiceSourceIdentity(originManifest, source.sourceVoiceOperationId);
          return { manifestPath: originPath, sourceOperationId: source.sourceVoiceOperationId,
            relayoutSource: "voice_version", sourceIdentity,
            sourceManifestIdentity: { artifactId: originArtifact.id, sha256: originReference.manifestSha256 } };
        }
        const candidateManifestPath = path.join(path.dirname(planArtifact.uri), "materialized_voice_source.json");
        try {
          await readFile(candidateManifestPath);
        } catch {
          throw new HumanDecisionConflictError("这一版声音缺少来源清单；请按既有恢复出口核对原请求，本动作不改写历史。");
        }
        const originManifest = requireOutputRecord(JSON.parse(await readFile(candidateManifestPath, "utf8")),
          "legacy origin voice manifest");
        const manifestBytes = await readFile(candidateManifestPath);
        const manifestFileSha256 = createHash("sha256").update(manifestBytes).digest("hex");
        const originArtifact = previous.artifacts.find((artifact) => artifact.kind === "voice_source_manifest"
          && artifact.uri && path.resolve(artifact.uri) === path.resolve(candidateManifestPath)
          && artifact.sha256 === manifestFileSha256);
        if (!originArtifact || typeof originManifest.manifestSha256 !== "string") {
          throw new HumanDecisionConflictError("这一版声音的来源清单没有正式产物身份；请按既有恢复出口核对原请求。");
        }
        const sourceIdentity = await resolveOriginVoiceSourceIdentity(originManifest, source.sourceVoiceOperationId);
        return { manifestPath: candidateManifestPath, sourceOperationId: source.sourceVoiceOperationId,
          relayoutSource: "voice_version", sourceIdentity,
          sourceManifestIdentity: { artifactId: originArtifact.id, sha256: originManifest.manifestSha256 } };
      };
      const resolveLegacySource = async (source: LegacyNarrationSource) => {
        if (voice.outputState?.effectiveVersionId !== source.voiceVersionId) {
          throw new HumanDecisionConflictError("指定的声音版本已不是当前有效版本，请刷新后重试。");
        }
        const context = await this.narrationPlanContext(previous, { readOnly: true });
        const verified = await this.legacyNarrationSource(previous, context);
        if (!verified || !isDeepStrictEqual(verified.source, source)) {
          throw new HumanDecisionConflictError("旧声音来源或原账本已变化，请重新查看后调整。");
        }
        return { sourceOperationId: source.sourceVoiceOperationId, relayoutSource: "legacy_voice_version",
          sourceIdentity: verified.sourceIdentity, legacyVoiceSource: verified.files,
          sourceLegacyIdentity: { sha256: verified.files.voicePlanSha256, ledgerSha256: verified.files.ledgerSha256 } };
      };
      const resolvedSource: { sourceOperationId: string; relayoutSource: string; sourceIdentity: Record<string, unknown>;
        manifestPath?: string; sourceManifestIdentity?: { artifactId: string; sha256: string };
        legacyVoiceSource?: LegacyVoiceSourceFiles; sourceLegacyIdentity?: { sha256: string; ledgerSha256: string } } =
        apply.source.kind === "legacy_voice_version" ? await resolveLegacySource(apply.source)
          : apply.source.kind === "materialized_operation" ? await resolveMaterializedSource(apply.source)
            : await resolveVoiceVersionSource(apply.source);
      const { sourceOperationId, relayoutSource, sourceIdentity, sourceManifestIdentity, sourceLegacyIdentity } = resolvedSource;

      // §4.2.6 执行前耐久预留完整请求：actor、原 CAS/停点/source 快照、目标布局与说明、
      // 固定 command/layout operation、attempt 目录与输入/输出版本身份；同一 requestId 的恢复
      // 沿用原预留，不再新预留目录或版本。
      await mkdir(operationsDirectory, { recursive: true });
      const freshAttempt = reservedOperation ? undefined
        : await reserveAttemptDirectory(path.join(this.runsRoot, runId, "nodes", "voice"));
      const attemptDirectory = typeof reservedOperation?.attemptDirectory === "string"
        ? reservedOperation.attemptDirectory : freshAttempt!.directory;
      const attempt = typeof reservedOperation?.attempt === "number"
        && Number.isSafeInteger(reservedOperation.attempt) && reservedOperation.attempt >= 1
        ? reservedOperation.attempt : freshAttempt?.attempt;
      if (!attempt || path.basename(attemptDirectory) !== `attempt-${attempt}`) {
        throw new HumanDecisionConflictError("时间调整的预留 attempt 身份不完整，不能更换目录继续。");
      }
      const voiceNodeRoot = await realpath(path.join(runDirectory, "nodes", "voice"));
      const attemptRoot = await realpath(attemptDirectory);
      const attemptRelative = path.relative(voiceNodeRoot, attemptRoot);
      if (!attemptRelative || attemptRelative.startsWith(`..${path.sep}`) || path.isAbsolute(attemptRelative)) {
        throw new HumanDecisionConflictError("时间调整的预留 attempt 越出了当前声音目录。");
      }
      const reservedInputVersionId = typeof reservedOperation?.reservedInputVersionId === "string"
        ? reservedOperation.reservedInputVersionId : this.idFactory("input-version");
      const reservedOutputVersionId = typeof reservedOperation?.reservedOutputVersionId === "string"
        ? reservedOperation.reservedOutputVersionId : this.idFactory("version");
      const workerExecutionToken = typeof reservedOperation?.workerExecutionToken === "string"
        ? reservedOperation.workerExecutionToken : randomUUID();
      const commandId = typeof reservedOperation?.commandId === "string"
        ? reservedOperation.commandId : `relayout-${draft.requestId}`;
      const layoutOperationId = typeof reservedOperation?.layoutOperationId === "string"
        ? reservedOperation.layoutOperationId : `relayout-${commandId}`;
      if (commandId !== `relayout-${draft.requestId}` || layoutOperationId !== `relayout-${commandId}`) {
        throw new HumanDecisionConflictError("时间调整的预留命令身份不一致，不能沿原请求继续。");
      }
      const reservation: Record<string, unknown> = {
        version: RELAYOUT_OPERATION_VERSION, requestId: draft.requestId, requestDigest,
        actor: draft.actor, runId, state: reservedOperation?.state === "completed" ? "completed" : "reserved",
        intent: draft.intent, interventionId: draft.interventionId,
        expectedRunRevision: draft.expectedRunRevision, sourceContextId: draft.sourceContextId,
        source: apply.source, layout: apply.layout,
        note: draft.note, sourceOperationId, relayoutSource, sourceKind: apply.source.kind,
        commandId, layoutOperationId, attempt, attemptDirectory,
        reservedInputVersionId, reservedOutputVersionId, workerExecutionToken,
        ...(typeof reservedOperation?.createdAt === "string" ? { createdAt: reservedOperation.createdAt }
          : { createdAt: this.clock() }),
        ...(Array.isArray(reservedOperation?.artifacts) ? { artifacts: reservedOperation.artifacts } : {}),
        ...(isObjectRecord(reservedOperation?.output) ? { output: reservedOperation.output } : {}),
      };
      await writeTextAtomically(path.join(operationsDirectory, `${draft.requestId}.json`),
        `${JSON.stringify(reservation, null, 2)}\n`);
      // 测试故障点 W1：预留已经耐久，但正式 worker 尚未接收请求。
      // 生产装配不提供该回调；独立进程测试会在这里真实结束父进程。
      await this.options.narrationRelayoutFailpoints?.afterReservation?.();
      let response: WorkerResponse;
      if (reservedOperation?.state === "completed") {
        // §4.2.6 窗口2：worker 产物与完成回执已落盘、run 未采用——恢复只按回执核验产物后
        // 进入采用，不再调用 worker（总 worker 次数不增加）。
        const recordedArtifacts = (Array.isArray(reservedOperation.artifacts)
          ? reservedOperation.artifacts : []) as Array<Record<string, unknown>>;
        for (const artifact of recordedArtifacts) {
          if (typeof artifact.uri !== "string" || typeof artifact.sha256 !== "string") {
            throw new HumanDecisionConflictError("完成回执的产物事实不完整，请核查原记录后重试。");
          }
          const bytes = await readFile(artifact.uri);
          if (createHash("sha256").update(bytes).digest("hex") !== artifact.sha256) {
            throw new HumanDecisionConflictError("完成回执的产物与登记摘要不一致，不能直接采用。");
          }
        }
        response = { protocolVersion: WORKER_PROTOCOL_VERSION, commandId,
          status: "succeeded", output: requireOutputRecord(reservedOperation.output, "completed relayout output"),
          artifacts: recordedArtifacts as unknown as WorkerResponse["artifacts"] };
      } else {
        // 父进程可能在 detached worker 写完后、收到 stdout 前退出。此时 worker 自身的
        // 完成收据是权威事实：先尝试从同一 attempt 恢复正式响应，不能再次启动 worker。
        const completedByWorker = await narrationRelayoutResponseFromCompletion(attemptDirectory);
        if (completedByWorker) {
          response = completedByWorker;
        } else {
          await assertNarrationRelayoutWorkerInactive(attemptDirectory, {
            commandId, attempt, workerExecutionToken,
          });
          response = await this.options.worker.run({
            protocolVersion: WORKER_PROTOCOL_VERSION, commandId,
            runId, nodeRunId: "voice", attempt, capability: "voice.synthesize",
            input: { relayout: true, ...resolvedSource, layout: apply.layout,
              relayoutReservation: { requestDigest, commandId, layoutOperationId,
                reservedInputVersionId, reservedOutputVersionId, workerExecutionToken, attempt },
              scriptPath: planning.scriptPath, executablePlanPath: planning.executablePlanPath },
            parameters: { providerId: "local-relayout-v1", maxCostCny: 0, maxAttempts: 0 },
            outputDir: attemptDirectory,
          });
        }
      }
      if (response.status !== "succeeded") {
        // §4.2.7 最小失败设计：保留原 run 与原活动停点，失败事实写操作记录；
        // 不强行新增 request_changes/reject 声音停点盖住旧入口，来源与旧版都不动。
        const conflict = isObjectRecord(response.output) && isObjectRecord(response.output.conflict)
          ? response.output.conflict : undefined;
        const v2Conflict = response.error?.code === "NARRATION_TURN_DOES_NOT_FIT" ? parseNarrationFitConflictV3(conflict)
          : response.error?.code === "NARRATION_GROUP_DOES_NOT_FIT_V2" ? parseNarrationFitConflictV2(conflict) : undefined;
        const requiredFrames = v2Conflict?.requiredFrames
          ?? (conflict && typeof conflict.requiredFrames === "number" ? conflict.requiredFrames : undefined);
        const availableFrames = v2Conflict?.availableFrames
          ?? (conflict && typeof conflict.availableFrames === "number" ? conflict.availableFrames : undefined);
        await writeTextAtomically(path.join(operationsDirectory, `${draft.requestId}.json`),
          `${JSON.stringify({ ...reservation, state: "failed",
            errorCode: response.error?.code ?? "UNKNOWN", failedAt: this.clock(),
            failureClass: response.error?.code === "NARRATION_GROUP_DOES_NOT_FIT_V2"
              || response.error?.code === "NARRATION_TURN_DOES_NOT_FIT"
              || response.error?.code === "NARRATION_GROUP_DOES_NOT_FIT" ? "deterministic_fit" : "deterministic_local",
            ...(v2Conflict ? { conflict: v2Conflict } : {}),
            failureReason: requiredFrames !== undefined
              ? `分段仍需要 ${requiredFrames} 帧，当前窗口只有 ${availableFrames} 帧。`
              : "本地处理失败。" }, null, 2)}\n`);
        throw new HumanDecisionConflictError(`时间调整没有完成：${requiredFrames !== undefined
          ? `分段仍需要 ${requiredFrames} 帧，当前窗口只有 ${availableFrames} 帧。`
          : "本地处理失败。"}原有效声音、草稿与当前停点保持不变，可继续调整或撤销这次修改。`);
      }
      await verifyWorkerArtifacts(response, attemptDirectory);
      await verifyNarrationRelayoutCompletion({ response, attemptDirectory, requestDigest, commandId,
        layoutOperationId, runId, attempt, reservedInputVersionId, reservedOutputVersionId,
        sourceOperationId, relayoutSource, sourceIdentity,
        ...(sourceManifestIdentity ? { sourceManifestIdentity } : {}), ...(sourceLegacyIdentity ? { sourceLegacyIdentity } : {}) });
      // §4.2.6.3 worker 完整输出先写耐久完成回执（产物根/类型/SHA/大小 + 预留身份），再进入采用；
      // applied 在 completed 记录上追加（保留 output/artifacts 供侧文件落后时的真实采用对照）。
      const completionRecord = { ...reservation, state: "completed" as const, completedAt: this.clock(),
        output: requireOutputRecord(response.output, "relayout output"),
        artifacts: response.artifacts.map((artifact) => ({
          kind: artifact.kind, uri: artifact.uri, sha256: artifact.sha256,
          sizeBytes: artifact.sizeBytes, contentType: artifact.contentType,
          ...(artifact.schemaVersion ? { schemaVersion: artifact.schemaVersion } : {}),
          provenance: artifact.provenance })) };
      await writeTextAtomically(path.join(operationsDirectory, `${draft.requestId}.json`),
        `${JSON.stringify(completionRecord, null, 2)}\n`);
      // 测试故障点 W2：worker 的完成收据、全部产物和 completed 投影均已耐久，
      // 但正式 run 还没有采用这次调整。
      await this.options.narrationRelayoutFailpoints?.afterWorkerCompletion?.();
      const output = requireOutputRecord(response.output, "relayout output");
      // 目标计划和完成收据必须来自 worker 已耐久的本次 attempt；父进程只核验和登记，
      // 不在收到 response 后补造唯一计划或完成事实。
      const currentVersion = voice.outputState.versions.find(
        (candidate) => candidate.id === voice.outputState!.effectiveVersionId)!;
      const currentParentArtifactIds = currentVersion.artifactIds.filter((artifactId) =>
        previous.artifacts.some((artifact) => artifact.id === artifactId));
      const planDoc = requireOutputRecord(JSON.parse(
        await readFile(requiredOutputString(output, "voiceoverPlanPath"), "utf8")), "relayout voiceover plan");
      const targetPlanPath = requiredOutputString(output, "narrationPlanPath");
      const targetNarrationPlan = requireOutputRecord(JSON.parse(
        await readFile(targetPlanPath, "utf8")), "target narration plan");
      if (!isDeepStrictEqual(planDoc.narrationPlan, targetNarrationPlan)) {
        throw new HumanDecisionConflictError("本地排轨的目标旁白计划与声音时间线不一致。");
      }
      const targetPlanVersion = targetNarrationPlan.version;
      if (targetPlanVersion !== "video-factory/narration-plan-v1"
        && targetPlanVersion !== "video-factory/narration-plan-v2" && targetPlanVersion !== CHARACTER_NARRATION_PLAN_VERSION) {
        throw new HumanDecisionConflictError("本地排轨返回了未知的目标旁白计划版本。");
      }
      const targetInputVersionId = reservedInputVersionId;
      const previousInputValue = requireOutputRecord(
        voice.inputState?.versions.find((candidate) => candidate.id === voice.inputState?.effectiveVersionId)?.value,
        "voice input");
      // §4.2.7 首次 fit 冲突恢复的换版：applyNodeOverride 的通用文件引用守卫要求新输出不删除
      // 旧输出里的文件引用（conflict.audioArtifact.uri 指向保留的原始音频，产物与引用继续有效）。
      // 成功换版输出原样保留该引用并加 conflictResolved 标记；消费者以停点与标记判断冲突已恢复。
      const adoptionBase = structuredClone(previous);
      const adoptionVoice = adoptionBase.nodeRuns.find((node) => node.nodeId === "voice")!;
      const staleConflict = adoptionVoice.output && isObjectRecord(adoptionVoice.output)
        && isObjectRecord((adoptionVoice.output as Record<string, unknown>).conflict)
        ? (adoptionVoice.output as Record<string, unknown>).conflict : undefined;
      const previousInputVersion = adoptionVoice.inputState?.versions.find(
        (candidate) => candidate.id === adoptionVoice.inputState?.effectiveVersionId);
      const targetSourceContextId = isObjectRecord(targetNarrationPlan.source)
        && typeof targetNarrationPlan.source.sourceContextId === "string"
        ? targetNarrationPlan.source.sourceContextId : previousInputValue.sourceContextId;
      adoptionVoice.inputState = { nodeId: "voice", effectiveVersionId: targetInputVersionId, stale: false,
        versions: [...(adoptionVoice.inputState?.versions ?? []), {
          id: targetInputVersionId, nodeId: "voice", source: "derived", createdAt: this.clock(),
          createdBy: draft.actor, schemaVersion: targetPlanVersion,
          upstreamVersionIds: previousInputVersion?.upstreamVersionIds ?? [],
          ...(previousInputVersion ? { parentVersionId: previousInputVersion.id } : {}),
          value: { ...previousInputValue, narrationPlanPath: targetPlanPath,
            ...(typeof targetSourceContextId === "string" ? { sourceContextId: targetSourceContextId } : {}),
            voiceInputVersionId: targetInputVersionId } }] };
      let reservedOutputIssued = false;
      const runner = new WorkflowRunner({
        optionalReviewInvalidationOperations: await verifiedOptionalReviewInvalidationOperations(previous, this.store.runDirectory(runId)),
        providers: this.createRegistry(brief), clock: this.clock,
        idFactory: (prefix) => {
          if (prefix === "version" && !reservedOutputIssued) {
            reservedOutputIssued = true;
            return reservedOutputVersionId;
          }
          return this.idFactory(prefix);
        },
      });
      const resultingRunRevision = adoptionBase.revision + 1;
      const next = runner.applyNodeOverride(definition, withExecutableBrief(adoptionBase, brief), {
        nodeId: "voice", actor: draft.actor,
        expectedVersionId: voice.outputState.effectiveVersionId,
        output: { voiceoverPlanPath: requiredOutputString(output, "voiceoverPlanPath"),
          trackPath: requiredOutputString(output, "trackPath"),
          narrationMode: targetNarrationPlan.mode, subtitleStatus: output.subtitleStatus,
          ...(typeof output.layoutKey === "string" ? { layoutKey: output.layoutKey } : {}),
          ...(typeof output.voiceOperationId === "string" ? { voiceOperationId: output.voiceOperationId } : {}),
          layoutOperationId: requiredOutputString(output, "layoutOperationId"),
          externalSendCount: 0, appliedRequestId: draft.requestId,
          requestDigest,
          voiceInputVersionId: targetInputVersionId,
          relayoutAdoption: { actor: draft.actor, requestId: draft.requestId, requestDigest,
            layoutOperationId, inputVersionId: targetInputVersionId,
            voiceVersionId: reservedOutputVersionId, resultingRunRevision },
          ...(staleConflict ? { conflict: staleConflict, conflictResolved: "relayout" as const } : {}) },
        artifacts: response.artifacts.map((artifact) => ({
          kind: artifact.kind, uri: artifact.uri, sha256: artifact.sha256, sizeBytes: artifact.sizeBytes,
          contentType: artifact.contentType,
          ...(artifact.schemaVersion ? { schemaVersion: artifact.schemaVersion } : {}),
          ...(artifact.kind === "narration_plan" ? { schemaVersion: targetPlanVersion } : {}),
          parentArtifactIds: currentParentArtifactIds,
          producer: { nodeId: "voice", attempt },
          provenance: { ...artifact.provenance, providerId: "local-relayout-v1",
            licenseNote: artifact.provenance.licenseNote || "Relocated original narration audio; no new synthesis." },
        })) as ArtifactDraft[],
        ...(currentVersion.schemaVersion ? { schemaVersion: currentVersion.schemaVersion } : {}),
      });
      const adoptedVoice = next.nodeRuns.find((node) => node.nodeId === "voice")!;
      const adoptedVersion = adoptedVoice.outputState?.versions.find(
        (candidate) => candidate.id === adoptedVoice.outputState?.effectiveVersionId);
      if (!reservedOutputIssued || adoptedVersion?.id !== reservedOutputVersionId
        || !adoptedVersion.inputVersionIds.includes(targetInputVersionId)) {
        throw new HumanDecisionConflictError("本地排轨的预留版本未被正式声音版本事务采用。");
      }
      // 有界声音 helper：applyNodeOverride 之后明确建立新的声音试听停点（approve/reject），
      // 不沿用任何 fit 冲突的 request_changes 停点，也不自动恢复渲染。
      const voiceRun = next.nodeRuns.find((node) => node.nodeId === "voice")!;
      voiceRun.status = "needs_human";
      voiceRun.intervention = {
        id: this.idFactory("intervention"), nodeId: "voice", createdAt: this.clock(),
        boundary: "node-complete" as const,
        reason: "已用原配音完成本地时间调整（未重新购买）。请试听新的声音时间线；确认后才继续渲染，旧版本保留可回退。",
        requiredAction: "approve",
        options: ["approve", "reject"],
      };
      next.interventions = next.interventions.filter((intervention) => intervention.nodeId !== "voice");
      next.interventions.push(voiceRun.intervention);
      next.status = "needs_human";
      if (next.revision !== resultingRunRevision) {
        throw new HumanDecisionConflictError("本地排轨采用产生了未预期的制作版本变化。");
      }
      // 正式 run 是采用权威；只有 run.json 已成功持久保存后，侧索引才可投影 applied。
      await checkpoint(next);
      // 测试故障点 W3：run 已正式采用，sidecar/HTTP 尚未完成。
      await this.options.narrationRelayoutFailpoints?.afterAdoptionCheckpoint?.();
      await writeTextAtomically(path.join(operationsDirectory, `${draft.requestId}.json`),
        `${JSON.stringify({ ...completionRecord, state: "applied", appliedAt: this.clock(),
          layoutOperationId: requiredOutputString(output, "layoutOperationId"),
          resultVoiceVersionId: reservedOutputVersionId,
          resultingRunRevision: next.revision }, null, 2)}\n`);
      return next;
    }, listener);
  }

  /** §2.5/§4.2.6 只读查询：本地时间调整的操作状态与是否当前；绝不启动 worker，不暴露磁盘路径。 */
  async readNarrationRelayoutOperation(runId: string, requestId: string): Promise<{
    requestId: string; state: "reserved" | "completed" | "applied" | "failed" | "discarded";
    requestDigest?: string;
    sourceOperationId?: string; relayoutSource?: string; layoutOperationId?: string;
    resultVoiceVersionId?: string; isCurrent: boolean; failureReason?: string; createdAt?: string;
  }> {
    if (!/^[a-zA-Z0-9_-]{1,128}$/.test(requestId)) {
      throw new HumanDecisionConflictError("时间调整编号无效。");
    }
    const run = await this.store.load<ProductionBrief>(runId);
    const operationPath = path.join(this.store.runDirectory(runId), "nodes", "voice",
      "relayout-operations", `${requestId}.json`);
    let operation: Record<string, unknown>;
    try {
      operation = requireOutputRecord(JSON.parse(await readFile(operationPath, "utf8")), "narration relayout operation");
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") {
        throw new HumanDecisionConflictError("没有这条时间调整的记录；请从声音入口重新发起。");
      }
      throw error;
    }
    if (operation.version !== RELAYOUT_OPERATION_VERSION
      || typeof operation.state !== "string"
      || !["reserved", "completed", "applied", "failed", "discarded"].includes(operation.state)) {
      throw new HumanDecisionConflictError("时间调整记录不可读，请核查原记录。");
    }
    const voice = run.nodeRuns.find((node) => node.nodeId === "voice");
    const adoptedVersion = voice?.outputState?.versions.find((candidate) =>
      isObjectRecord(candidate.output)
      && candidate.output.appliedRequestId === requestId
      && candidate.output.requestDigest === operation.requestDigest);
    // GET 只投影正式 run，不写侧索引：run 已采用即 applied；侧索引超前却没有
    // 对应版本时最多是 completed，不能向界面谎报已经生效。
    const projectedState = adoptedVersion ? "applied"
      : operation.state === "applied" ? "completed"
        : operation.state as "reserved" | "completed" | "failed" | "discarded";
    const resultVoiceVersionId = adoptedVersion?.id
      ?? (typeof operation.resultVoiceVersionId === "string" ? operation.resultVoiceVersionId : undefined);
    return {
      requestId,
      state: projectedState,
      ...(typeof operation.requestDigest === "string" && /^[a-f0-9]{64}$/u.test(operation.requestDigest)
        ? { requestDigest: operation.requestDigest } : {}),
      ...(typeof operation.sourceOperationId === "string" ? { sourceOperationId: operation.sourceOperationId } : {}),
      ...(typeof operation.relayoutSource === "string" ? { relayoutSource: operation.relayoutSource } : {}),
      ...(typeof operation.layoutOperationId === "string" ? { layoutOperationId: operation.layoutOperationId } : {}),
      ...(resultVoiceVersionId ? { resultVoiceVersionId } : {}),
      isCurrent: adoptedVersion?.id === voice?.outputState?.effectiveVersionId,
      ...(typeof operation.failureReason === "string" ? { failureReason: operation.failureReason } : {}),
      ...(typeof operation.createdAt === "string" ? { createdAt: operation.createdAt } : {}),
    };
  }

  private async dispatchSubtitleRecovery(
    runId: string, draft: ProductionSubtitleRecoveryDraft, listener?: ProductionRunListener,
  ): Promise<DispatchedProductionRun> {
    if (!/^[a-zA-Z0-9_-]{1,128}$/.test(draft.requestId) || !draft.actor.trim() || !draft.note.trim()) {
      throw new HumanDecisionConflictError("字幕恢复需要有效的操作编号与说明。");
    }
    const requestDigest = contentSha256(draft);
    const revised = await this.runPersistedTransition(runId, async (previous) => {
      const voice = previous.nodeRuns.find(node => node.nodeId === "voice");
      const applied = voice?.outputState?.versions.find(version => isObjectRecord(version.output)
        && isObjectRecord(version.output.subtitleRecoveryRequest) && version.output.subtitleRecoveryRequest.requestId === draft.requestId);
      if (applied) {
        const saved = requireOutputRecord(requireOutputRecord(applied.output, "voice output").subtitleRecoveryRequest, "subtitle recovery");
        if (saved.digest !== requestDigest) throw new HumanDecisionConflictError("这个字幕恢复编号已用于另一份请求，请勿重复提交。");
        return previous;
      }
      if (previous.revision !== draft.expectedRunRevision) throw new StaleRunRevisionError(runId, draft.expectedRunRevision, previous.revision);
      const intervention = previous.nodeRuns.find(node => node.nodeId === "final-review" && node.status === "needs_human")?.intervention;
      if (previous.status !== "needs_human" || !intervention || previous.nodeRuns.some(node => node.outcomeUncertain || node.status === "running")) {
        throw new HumanDecisionConflictError("请在原请求已结清的成片确认阶段恢复字幕；现有声音与成片会保留。");
      }
      const version = voice?.outputState?.versions.find(candidate => candidate.id === voice.outputState?.effectiveVersionId);
      if (!voice || !version || version.id !== draft.expectedVoiceVersionId || voice.outputState?.stale) {
        throw new HumanDecisionConflictError("声音版本已经变化，请查看当前版本后再恢复字幕。");
      }
      const output = requireOutputRecord(version.output ?? voice.output, "voice output");
      const currentArtifacts = previous.artifacts.filter(artifact => version.artifactIds.includes(artifact.id));
      const planArtifact = currentArtifacts.find(artifact => artifact.uri === output.voiceoverPlanPath);
      const audioArtifact = currentArtifacts.find(artifact => artifact.uri === output.trackPath);
      if (!planArtifact?.uri || !audioArtifact?.sha256 || audioArtifact.sha256 !== draft.expectedAudioSha256) {
        throw new HumanDecisionConflictError("当前配音的留档无法核对，请先检查原声音；不会重新购买。");
      }
      const root = this.store.runDirectory(runId);
      await Promise.all([verifyStoredArtifactWithinRoot(root, planArtifact), verifyStoredArtifactWithinRoot(root, audioArtifact)]);
      const plan = requireOutputRecord(JSON.parse(await readFile(planArtifact.uri, "utf8")), "voice plan");
      const subtitles = requireOutputRecord(plan.subtitles, "retained subtitles");
      if (!["video-factory/voiceover-plan-v3", "video-factory/voiceover-plan-v4"].includes(String(plan.version)) || plan.layoutKey !== draft.expectedLayoutKey
        || subtitles.acceptedNarrationPlanSha256 !== draft.expectedNarrationPlanSha256) {
        throw new HumanDecisionConflictError("旁白或字幕布局已经变化，请刷新后再试。");
      }
      const input = requireOutputRecord(voice.inputState?.versions.find(candidate => candidate.id === voice.inputState?.effectiveVersionId)?.value, "voice input");
      const narration = previous.artifacts.find(artifact => artifact.kind === "narration_plan" && artifact.uri === input.narrationPlanPath);
      if (!narration || narration.sha256 !== draft.expectedNarrationPlanSha256 || voice.inputState?.stale) {
        throw new HumanDecisionConflictError("已采用的旁白方案已经变化，请先确认当前方案。");
      }
      await verifyStoredArtifactWithinRoot(root, narration);
      const sourceOperationId = optionalOutputString(plan.voiceOperationId) ?? voice.executionReceipt?.requestId;
      if (!sourceOperationId) throw new HumanDecisionConflictError("缺少原配音请求身份，暂不能单独恢复字幕；原成片仍可查看与确认。");
      const brief = parsePersistedBrief(previous.initialInput);
      const planning = currentPlanningOutputPaths({ outputs: new Map(previous.nodeRuns.map(node => [node.nodeId, effectiveNodeOutput(node)])) }, brief);
      const attempt = await reserveAttemptDirectory(path.join(root, "nodes", "voice"));
      const response = await this.options.worker.run({ protocolVersion: WORKER_PROTOCOL_VERSION,
        commandId: draft.requestId, runId, nodeRunId: "voice", attempt: attempt.attempt, capability: "voice.synthesize",
        input: { ...planning, narrationPlanPath: narration.uri, recover_subtitles: true,
          voiceoverPlanPath: planArtifact.uri, voiceoverPlanSha256: planArtifact.sha256, trackSha256: audioArtifact.sha256,
          layoutKey: draft.expectedLayoutKey, sourceOperationId,
          ...(draft.refetchReason ? { subtitle_refetch: true, subtitle_refetch_reason: draft.refetchReason } : {}) },
        parameters: { providerId: "local-subtitle-recovery-v1", maxCostCny: 0, maxAttempts: 0 }, outputDir: attempt.directory });
      await verifyWorkerArtifacts(response, attempt.directory);
      if (response.commandId !== draft.requestId || response.status !== "succeeded"
        || response.diagnostics?.meteredAttemptCount !== 0 || response.diagnostics.actualCostCny !== 0
        || !response.artifacts.some(artifact => artifact.kind === "voiceover" && artifact.sha256 === audioArtifact.sha256)) {
        throw new HumanDecisionConflictError("字幕恢复没有完成，原声音和成片均保留；请查看原因后再处理，不要重新合成。");
      }
      const result = await workerResponseToNodeResult(response, { artifacts: currentArtifacts }, ["voice"]);
      const runner = new WorkflowRunner({
        optionalReviewInvalidationOperations: await verifiedOptionalReviewInvalidationOperations(previous, this.store.runDirectory(runId)), providers: this.createRegistry(brief), clock: this.clock, idFactory: this.idFactory });
      return runner.applyNodeRevision(this.createWorkflow(brief), withExecutableBrief(previous, brief), {
        nodeId: "voice", actor: draft.actor, expectedVersionId: version.id, schemaVersion: version.schemaVersion,
        output: { ...result.output, subtitleRecoveryRequest: { requestId: draft.requestId, digest: requestDigest } },
        artifacts: result.artifacts ?? [], retainedArtifactIds: [],
        invalidateDescendantNodeIds: ["render", "technical-review", "visual-review", "final-review", "publish-package"]
          .filter(id => productionNodeIds(brief).includes(id)),
        decision: { interventionId: intervention.id, action: "request_changes", actor: draft.actor, note: draft.note },
      });
    }, undefined, true);
    // 重放已经采用的操作不重排下游；仅崩溃在采用后、重渲染前时继续未完成的本地工作。
    if (revised.status !== "stale") return { runId, completion: Promise.resolve(revised) };
    return this.dispatchResumeStale(runId, listener);
  }

  async applyNodeExecutionConfiguration(
    runId: string,
    nodeId: string,
    nextBriefInput: ProductionBrief,
    actor: string,
    expectedRunRevision?: number,
  ): Promise<WorkflowRun<ProductionBrief>> {
    return this.runPersistedTransition(runId, async (previous) => {
      const jointEdit = usesJointCreativePlanning(parsePersistedBrief(previous.initialInput));
      // B4 对外编辑合同（joint-v1）：caller revision 必填；legacy 保持既有可选行为。
      if (jointEdit && (!Number.isSafeInteger(expectedRunRevision) || Number(expectedRunRevision) < 0)) {
        throw new Error(`Joint planning execution configuration override for '${runId}' requires a non-negative expectedRunRevision.`);
      }
      // 与输入覆盖同一持锁复核合同：配置编辑不得用预检查后新加载的服务端 revision 代替
      // caller revision；两者不一致说明预检查后有并发写入，必须在写入前失败。
      if (expectedRunRevision !== undefined && previous.revision !== expectedRunRevision) {
        throw new StaleRunRevisionError(runId, expectedRunRevision, previous.revision);
      }
      const nextBrief = parseBrief(nextBriefInput);
      await assertNoUnresolvedPlanningTask(this.store.runDirectory(runId), previous);
      const runner = new WorkflowRunner({
        optionalReviewInvalidationOperations: await verifiedOptionalReviewInvalidationOperations(previous, this.store.runDirectory(runId)),
        providers: this.createRegistry(nextBrief),
        clock: this.clock,
        idFactory: this.idFactory,
      });
      return runner.applyExecutionConfigurationOverride(
        this.createWorkflow(nextBrief),
        previous,
        { nodeId, actor, initialInput: nextBrief },
      );
    });
  }

  async authorizeSpend(runId: string, authorization: SpendAuthorizationDraft): Promise<WorkflowRun<ProductionBrief>> {
    const dispatched = await this.dispatchSpendAuthorization(runId, authorization);
    return dispatched.completion;
  }

  async dispatchSpendAuthorization(
    runId: string,
    authorization: SpendAuthorizationDraft,
    listener?: ProductionRunListener,
    // C1：持锁 CAS 边界内的额外校验（如 scope head 未被 supersede 的复核）。
    // 在 runner 接受子凭证之前执行；抛错即整个派发事务失败、零副作用。
    guard?: (previous: WorkflowRun<ProductionBrief>) => Promise<void>,
  ): Promise<DispatchedProductionRun> {
    return this.dispatchPersistedTransition(runId, async (previous, checkpoint) => {
      if (guard) await guard(previous);
      const brief = parsePersistedBrief(previous.initialInput);
      const runner = new WorkflowRunner({
        providers: this.createRegistry(brief),
        clock: this.clock,
        idFactory: this.idFactory,
        checkpoint: (run) => checkpoint(run as WorkflowRun<ProductionBrief>),
        shouldPause: () => this.consumePauseRequest(runId),
      });
      return runner.authorizeSpend(this.createWorkflow(brief), withExecutableBrief(previous, brief), authorization);
    }, listener);
  }

  async rejectSpend(runId: string, rejection: ProductionSpendRejectionDraft): Promise<WorkflowRun<ProductionBrief>> {
    const dispatched = await this.dispatchSpendRejection(runId, rejection);
    return dispatched.completion;
  }

  async dispatchSpendRejection(
    runId: string,
    rejection: ProductionSpendRejectionDraft,
    listener?: ProductionRunListener,
  ): Promise<DispatchedProductionRun> {
    return this.dispatchPersistedTransition(runId, async (previous, checkpoint) => {
      const brief = parsePersistedBrief(previous.initialInput);
      if (previous.status !== "awaiting_spend_approval" && previous.status !== "approval_invalidated") {
        throw new Error(`Run '${runId}' is not waiting for spend approval.`);
      }
      if (rejection.nodeId !== "assets" || !brief.director) {
        throw new Error("Only an AI-directed asset quote can be returned to the director for replanning.");
      }
      if (!rejection.rejectedBy.trim()) throw new Error("Spend rejection actor is required.");
      if (!["too_expensive", "provider_mix", "plan_not_approved", "other"].includes(rejection.reason)) {
        throw new Error("Spend rejection reason is invalid.");
      }
      if (rejection.note !== undefined && (!rejection.note.trim() || rejection.note.trim().length > 1_000)) {
        throw new Error("Spend rejection note must contain between 1 and 1000 characters.");
      }
      if (rejection.targetEstimatedCostCny !== undefined
        && (!Number.isFinite(rejection.targetEstimatedCostCny) || rejection.targetEstimatedCostCny < 0 || rejection.targetEstimatedCostCny > 100_000)) {
        throw new Error("Spend rejection target estimate must be a finite non-negative amount.");
      }
      const waitingNode = previous.nodeRuns.find((node) => node.nodeId === rejection.nodeId);
      const plan = waitingNode?.spendPlan;
      if (!plan || plan.id !== rejection.spendPlanId
        || (waitingNode.status !== "awaiting_spend_approval" && waitingNode.status !== "approval_invalidated")) {
        throw new Error("Spend rejection does not match the active quote.");
      }
      if (rejection.reason === "too_expensive"
        && rejection.targetEstimatedCostCny !== undefined
        && rejection.targetEstimatedCostCny >= plan.estimatedCostCny) {
        throw new Error("Spend rejection target estimate must be lower than the active quote.");
      }
      const nextBrief = parseBrief({
        ...brief,
        spendFeedback: [
          ...(brief.spendFeedback ?? []),
          {
            spendPlanId: plan.id,
            nodeId: rejection.nodeId,
            reason: rejection.reason,
            previousEstimatedCostCny: plan.estimatedCostCny,
            ...(rejection.targetEstimatedCostCny !== undefined
              ? { targetEstimatedCostCny: rejection.targetEstimatedCostCny }
              : {}),
            ...(rejection.note ? { note: rejection.note.trim() } : {}),
            rejectedBy: rejection.rejectedBy.trim(),
            rejectedAt: this.clock(),
          },
        ].slice(-20),
      });
      const runner = new WorkflowRunner({
        providers: this.createRegistry(nextBrief),
        clock: this.clock,
        idFactory: this.idFactory,
        checkpoint: (run) => checkpoint(run as WorkflowRun<ProductionBrief>),
        shouldPause: () => this.consumePauseRequest(runId),
      });
      const stale = runner.applyExecutionConfigurationOverride(
        this.createWorkflow(nextBrief),
        withExecutableBrief(previous, brief),
        {
          // joint-v1 拓扑没有独立 visual-direction 节点：报价退回的失效目标是 creative-planning。
          nodeId: usesJointCreativePlanning(nextBrief) ? "creative-planning" : "visual-direction",
          actor: rejection.rejectedBy.trim(),
          initialInput: nextBrief,
        },
      );
      return stale;
    }, listener);
  }

  async resumeStale(runId: string): Promise<WorkflowRun<ProductionBrief>> {
    const dispatched = await this.dispatchResumeStale(runId);
    return dispatched.completion;
  }

  async dispatchResumeStale(
    runId: string,
    listener?: ProductionRunListener,
  ): Promise<DispatchedProductionRun> {
    const dispatched = await this.dispatchPersistedTransition(runId, async (previous, checkpoint) => {
      const brief = parsePersistedBrief(previous.initialInput);
      const runner = new WorkflowRunner({
        optionalReviewInvalidationOperations: await verifiedOptionalReviewInvalidationOperations(previous, this.store.runDirectory(runId)),
        providers: this.createRegistry(brief),
        clock: this.clock,
        idFactory: this.idFactory,
        checkpoint: (run) => checkpoint(run as WorkflowRun<ProductionBrief>),
        shouldPause: () => this.consumePauseRequest(runId),
      });
      return runner.resumeStale(this.createWorkflow(brief), withExecutableBrief(previous, brief));
    }, listener);
    return this.continueCoveredSpendApproval(runId, dispatched, listener);
  }

  async retryFailedNode(
    runId: string,
    nodeId: string,
    options?: ProductionNodeRetryOptions,
  ): Promise<WorkflowRun<ProductionBrief>> {
    const dispatched = await this.dispatchRetryFailedNode(runId, nodeId, undefined, options);
    return dispatched.completion;
  }

  async reconcilePaidNode(
    runId: string,
    draft: ProductionPaidNodeReconciliationDraft,
    options?: { settleOnly?: boolean },
  ): Promise<WorkflowRun<ProductionBrief>> {
    if (!draft.nodeId.trim()) throw new Error("Paid reconciliation node id is required.");
    if (!draft.reconciliationId.trim() || draft.reconciliationId.trim().length > 128) {
      throw new Error("Paid reconciliation id must contain between 1 and 128 characters.");
    }
    if (!["resume_original", "requote", "confirmed_not_charged", "confirmed_charged"].includes(draft.outcome)) {
      throw new Error("Paid reconciliation outcome is invalid.");
    }
    const taskId = draft.taskId?.trim();
    if (draft.taskId !== undefined && (!taskId || taskId.length > 256)) {
      throw new Error("Paid reconciliation task id must contain between 1 and 256 characters.");
    }
    if (taskId && draft.outcome !== "resume_original") {
      throw new Error("A provider task id can only resume the original paid operation.");
    }
    const manualResolution = draft.outcome === "confirmed_not_charged" || draft.outcome === "confirmed_charged";
    if (options?.settleOnly === true && !manualResolution) {
      throw new Error("Settle-only paid reconciliation requires a confirmed manual outcome.");
    }
    const itemRequestId = draft.itemRequestId?.trim();
    if (draft.itemRequestId !== undefined && (!itemRequestId || itemRequestId.length > 256)) {
      throw new Error("Paid reconciliation item request id must contain between 1 and 256 characters.");
    }
    if (itemRequestId && (draft.nodeId !== "assets" || !manualResolution)) {
      throw new Error("A paid item can only be selected when manually reconciling an asset operation.");
    }
    const actor = draft.actor?.trim();
    const note = draft.note?.trim();
    if (manualResolution && (!actor || actor.length > 160)) {
      throw new Error("Paid manual reconciliation actor must contain between 1 and 160 characters.");
    }
    if (manualResolution && (!note || note.length > 2_000)) {
      throw new Error("Paid manual reconciliation note must contain between 1 and 2000 characters.");
    }
    if (!manualResolution && (draft.actor !== undefined || draft.note !== undefined || draft.actualCostCny !== undefined)) {
      throw new Error("Manual reconciliation evidence is only valid for a confirmed manual outcome.");
    }
    if (draft.actualCostCny !== undefined && (
      draft.outcome !== "confirmed_charged"
      || !Number.isFinite(draft.actualCostCny)
      || draft.actualCostCny < 0
    )) {
      throw new Error("Paid reconciliation actual cost must be a finite non-negative amount for a confirmed charge.");
    }
    if (!Number.isInteger(draft.expectedRunRevision) || draft.expectedRunRevision < 0) {
      throw new Error("Paid reconciliation expected run revision must be a non-negative integer.");
    }
    const lease = await this.acquireExecutionLease(runId);
    try {
      await this.assertExecutionLease(lease);
      const previous = await this.store.load<ProductionBrief>(runId);
      const recordPath = this.paidReconciliationPath(runId, draft.reconciliationId.trim());
      const existingRecord = await readPaidNodeReconciliationRecord(recordPath);
      if (existingRecord && (
        existingRecord.reconciliationId !== draft.reconciliationId.trim()
        || existingRecord.nodeId !== draft.nodeId
        || existingRecord.outcome !== draft.outcome
        || existingRecord.itemRequestId !== itemRequestId
        || existingRecord.taskId !== taskId
        || existingRecord.expectedRunRevision !== draft.expectedRunRevision
        || existingRecord.actor !== actor
        || existingRecord.note !== note
        || existingRecord.reportedActualCostCny !== draft.actualCostCny
      )) {
        throw new Error(`Paid reconciliation '${draft.reconciliationId}' conflicts with its persisted request.`);
      }
      if (existingRecord?.status === "completed") return previous;
      if (existingRecord?.status === "in_progress" && previous.revision !== existingRecord.expectedRunRevision) {
        const currentNode = previous.nodeRuns.find((node) => node.nodeId === draft.nodeId);
        if (!currentNode?.outcomeUncertain) {
          await this.assertExecutionLease(lease);
          await writePaidNodeReconciliationRecord(recordPath, {
            ...existingRecord,
            status: "completed",
            resultingRunRevision: previous.revision,
          });
          return previous;
        }
      }
      if (!existingRecord && previous.revision !== draft.expectedRunRevision) {
        throw new StaleRunRevisionError(runId, draft.expectedRunRevision, previous.revision);
      }
      const previousNode = previous.nodeRuns.find((node) => node.nodeId === draft.nodeId);
      if (!previousNode || previousNode.status !== "failed" || !previousNode.outcomeUncertain) {
        throw new Error(`Node '${draft.nodeId}' has no uncertain paid-provider outcome to reconcile.`);
      }
      if (draft.nodeId !== "assets" && draft.nodeId !== "voice" && !manualResolution) {
        throw new PaidOperationManualReconciliationError(draft.nodeId, []);
      }
      const operationId = previousNode.operationRequestId;
      const nodeDirectory = path.join(this.runsRoot, runId, "nodes", draft.nodeId);
      let items = operationId
        && draft.nodeId === "assets"
        ? (await inspectPaidAssetLedger(nodeDirectory)).filter((item) => item.operationId === operationId)
        : [];
      if (
        draft.outcome === "requote"
        && operationId
        && draft.nodeId === "assets"
        && isTrustedPreSubmissionAssetRejection(previousNode, items)
        && items.length > 0
      ) {
        await this.assertExecutionLease(lease);
        await markPaidAssetPreSubmissionRejections(nodeDirectory, operationId);
        items = (await inspectPaidAssetLedger(nodeDirectory)).filter((item) => item.operationId === operationId);
      }
      let voiceOperation = operationId && draft.nodeId === "voice"
        ? await readPaidVoiceOperation(nodeDirectory, operationId)
        : undefined;
      // 角色逐句任务不能以估价结算绕过仍未核清的组，再创建整批新请求。
      // 仅只读查原响应；所有组已有明确结果后才按既有恢复合同继续。
      if (draft.nodeId === "voice" && parsePersistedBrief(previous.initialInput).presentationMode === "character_drama"
        && manualResolution && (!voiceOperation || voiceOperation.items.some(item =>
          item.state === "unknown" || item.state === "submitted" || item.state === "provider_succeeded"))) {
        throw new Error("角色配音的原请求仍待核清；请核对原请求结果，不能登记估价后重新发送。");
      }
      const discoveredVoiceManifest = draft.outcome === "resume_original"
        && operationId
        && voiceOperation
        && canRebuildPaidVoiceManifest(voiceOperation)
        ? await discoverPaidVoiceManifest(nodeDirectory, operationId)
        : undefined;
      const voiceManifestRecovery = draft.outcome === "resume_original"
        && operationId
        && voiceOperation
        && canRebuildPaidVoiceManifest(voiceOperation)
        ? {
            sourceOperationId: operationId,
            ...(discoveredVoiceManifest ? { manifestPath: discoveredVoiceManifest } : {}),
          }
        : undefined;
      let manualAssetItem: PaidAssetLedgerItemSummary | undefined;
      let manualAssetItemAlreadyResolved = false;
      if (manualResolution && draft.nodeId === "assets" && items.length > 0) {
        if (!itemRequestId) {
          throw new Error("人工核对素材账单时必须选择一个具体镜头，不能整批标记。");
        }
        const matchingItems = items.filter((item) => item.itemRequestId === itemRequestId);
        if (matchingItems.length !== 1) {
          throw new Error(`Paid reconciliation item '${itemRequestId}' does not uniquely identify an item in the active operation.`);
        }
        const matchingItem = matchingItems[0]!;
        manualAssetItem = matchingItem;
        const expectedResolutionError = draft.outcome === "confirmed_charged"
          ? confirmedChargedAssetItemError(draft.reconciliationId.trim())
          : confirmedNotChargedAssetItemError(draft.reconciliationId.trim());
        manualAssetItemAlreadyResolved = Boolean(existingRecord
          && matchingItem.state === "terminal_failed"
          && (existingRecord.actualCostCny === undefined
            ? matchingItem.actualCostCny === undefined
            : matchingItem.actualCostCny === roundCurrency(existingRecord.actualCostCny))
          && matchingItem.error === expectedResolutionError);
        if (!manualAssetItemAlreadyResolved && !paidAssetItemNeedsManualReconciliation(matchingItem)) {
          throw new Error(
            `Paid item '${itemRequestId}' has a recoverable result or is not awaiting manual charge reconciliation.`,
          );
        }
      } else if (itemRequestId) {
        throw new Error(`Paid reconciliation item '${itemRequestId}' is not present in the active operation.`);
      }
      let resumeOriginalOperation = false;
      if (draft.outcome === "resume_original" || draft.outcome === "requote") {
        if (!operationId) {
          throw new PaidOperationManualReconciliationError(draft.nodeId, items);
        }
        if (draft.nodeId === "assets") {
          const trustedPreSubmissionRejection = isTrustedPreSubmissionAssetRejection(previousNode, items);
          if (items.length === 0 && !trustedPreSubmissionRejection) {
            throw new PaidOperationManualReconciliationError(draft.nodeId, items);
          }
          const missingTaskItems = items.filter((item) => (
            (item.state === "submitted" || item.state === "unknown") && !item.taskId
          ));
          const matchingTaskItems = taskId ? items.filter((item) => item.taskId === taskId) : [];
          if (taskId && !(
            (missingTaskItems.length === 1 && matchingTaskItems.length === 0)
            || (missingTaskItems.length === 0 && matchingTaskItems.length === 1)
          )) {
            throw new Error("A provider task id can only be attached when exactly one unresolved paid item is missing it.");
          }
          const missingQueryableTask = items.some((item) => (
            (item.state === "submitted" || item.state === "unknown")
            && !item.taskId
            && (!taskId || item.itemRequestId !== missingTaskItems[0]?.itemRequestId)
          ) || (
            item.state === "provider_succeeded" && !item.taskId
          ));
          if (missingQueryableTask) {
            throw new PaidOperationManualReconciliationError(draft.nodeId, items);
          }
          resumeOriginalOperation = !paidAssetRemainderNeedsNewOperation(items) && (items.some((item) => (
            item.state === "submitted"
            || item.state === "provider_succeeded"
            || item.state === "unknown"
          )) || items.every((item) => item.state === "materialized"));
          if (trustedPreSubmissionRejection && items.length === 0) resumeOriginalOperation = false;
        } else if (draft.nodeId === "voice") {
          if (!voiceOperation || !canResumePaidVoiceOperation(voiceOperation)) {
            throw new PaidOperationManualReconciliationError(draft.nodeId, []);
          }
          if (taskId) throw new Error("Voice reconciliation does not accept a Provider task id.");
          resumeOriginalOperation = true;
        } else {
          throw new PaidOperationManualReconciliationError(draft.nodeId, []);
        }
        const resolvedOutcome = resumeOriginalOperation ? "resume_original" : "requote";
        if (draft.outcome !== resolvedOutcome) {
          throw new Error(
            `Paid reconciliation '${draft.reconciliationId}' requested '${draft.outcome}' but the ledger requires '${resolvedOutcome}'.`,
          );
        }
      }
      const confirmedActualCostCny = draft.outcome === "confirmed_charged"
        ? draft.actualCostCny
          ?? manualAssetItem?.estimatedCostCny
          ?? originalPaidEstimate(previous, previousNode)
        : undefined;
      if (draft.outcome === "confirmed_charged" && confirmedActualCostCny === undefined) {
        throw new Error("Paid reconciliation actual cost is required because the original estimate is unavailable.");
      }
      const settlementActualCostSource = draft.outcome === "confirmed_charged" && draft.actualCostCny !== undefined
        ? "manual_reconciled"
        : previousNode.executionReceipt?.actualCostSource === "provider_reported"
          || previousNode.executionReceipt?.actualCostSource === "manual_reconciled"
          ? previousNode.executionReceipt.actualCostSource
          : "configured_rate";
      const reconciliationRecord: PaidNodeReconciliationRecord = existingRecord ?? {
        version: "video-factory/paid-reconciliation-v1",
        reconciliationId: draft.reconciliationId.trim(),
        nodeId: draft.nodeId,
        outcome: draft.outcome,
        ...(itemRequestId ? { itemRequestId } : {}),
        ...(taskId ? { taskId } : {}),
        ...(actor ? { actor } : {}),
        ...(note ? { note } : {}),
        ...(confirmedActualCostCny !== undefined ? { actualCostCny: confirmedActualCostCny } : {}),
        ...(draft.actualCostCny !== undefined ? { reportedActualCostCny: draft.actualCostCny } : {}),
        expectedRunRevision: previous.revision,
        status: "in_progress",
        createdAt: this.clock(),
      };
      if (!existingRecord) {
        await this.assertExecutionLease(lease);
        await writePaidNodeReconciliationRecord(recordPath, reconciliationRecord);
      }
      if (draft.outcome === "confirmed_charged" && manualAssetItem && operationId) {
        if (!manualAssetItemAlreadyResolved) {
          await this.assertExecutionLease(lease);
          await markPaidAssetItemCharged(
            nodeDirectory,
            operationId,
            manualAssetItem.itemRequestId,
            reconciliationRecord.reconciliationId,
            confirmedActualCostCny!,
            draft.actualCostCny !== undefined ? "manual_reconciled" : "configured_rate",
          );
        }
        items = (await inspectPaidAssetLedger(nodeDirectory)).filter((item) => item.operationId === operationId);
      } else if (draft.outcome === "confirmed_charged") {
        const result = applyConfirmedChargedResolution(
          previous,
          draft.nodeId,
          operationId,
          confirmedActualCostCny!,
          settlementActualCostSource,
          this.clock(),
        );
        if (options?.settleOnly === true) {
          const settledNode = result.nodeRuns.find((node) => node.nodeId === draft.nodeId)!;
          delete settledNode.spendPlan;
          settledNode.error = "这笔历史付费任务已完成账单结算；旧版制作不会恢复执行，请创建新版本继续制作。";
        }
        await this.assertExecutionLease(lease);
        await this.store.save(result, previous.revision);
        await this.assertExecutionLease(lease);
        await writePaidNodeReconciliationRecord(recordPath, {
          ...reconciliationRecord,
          status: "completed",
          resultingRunRevision: result.revision,
        });
        return result;
      }
      if (taskId && operationId) {
        if (draft.nodeId !== "assets") throw new Error("A provider task id can only reconcile a paid asset operation.");
        await this.assertExecutionLease(lease);
        items = await attachPaidAssetTaskId(nodeDirectory, operationId, taskId, items);
      }
      if (draft.outcome === "confirmed_not_charged" && operationId && manualAssetItem) {
        if (!manualAssetItemAlreadyResolved) {
          await this.assertExecutionLease(lease);
          await markPaidAssetItemNotCharged(
            nodeDirectory,
            operationId,
            manualAssetItem.itemRequestId,
            reconciliationRecord.reconciliationId,
          );
        }
        items = (await inspectPaidAssetLedger(nodeDirectory)).filter((item) => item.operationId === operationId);
      }
      if (draft.outcome === "confirmed_not_charged" && voiceOperation) {
        await this.assertExecutionLease(lease);
        voiceOperation = await markPaidVoiceItemsNotCharged(nodeDirectory, voiceOperation);
      }
      if (manualAssetItem && items.some((item) => (
        item.itemRequestId !== manualAssetItem.itemRequestId
        && (
          (item.state === "submitted" || item.state === "unknown") && Boolean(item.taskId)
          || item.state === "provider_succeeded" && Boolean(item.taskId) && !item.resultUrl
        )
      ))) {
        resumeOriginalOperation = true;
      }
      const retrySource = structuredClone(previous);
      const settlement = draft.nodeId === "assets"
        ? paidAssetSettlement(items)
        : draft.nodeId === "voice" && voiceOperation
          ? paidVoiceSettlement(voiceOperation)
          : { actualCostCny: 0, meteredAttemptCount: 0, meteredFailedAttemptCount: 0 };
      settlePaidOperationReceipt(
        retrySource,
        draft.nodeId,
        operationId,
        settlement.actualCostCny,
        settlement.meteredAttemptCount,
        settlement.meteredFailedAttemptCount,
        this.clock(),
        settlementActualCostSource,
      );
      const retryNode = retrySource.nodeRuns.find((node) => node.nodeId === draft.nodeId)!;
      if (draft.nodeId === "voice" && draft.outcome === "confirmed_not_charged") {
        const authorizationId = retryNode.spendAuthorizationId;
        if (authorizationId) {
          const consumed = (retrySource.consumedSpendAuthorizationIds ??= []);
          if (!consumed.includes(authorizationId)) consumed.push(authorizationId);
        }
        retryNode.status = "failed";
        retryNode.error = options?.settleOnly === true
          ? "这笔历史付费任务已完成账单结算；旧版制作不会恢复执行，请创建新版本继续制作。"
          : "配音请求已按服务商明确拒绝结清；请先调整配音设置，再点击“重试失败步骤”创建新任务。";
        retryNode.finishedAt = this.clock();
        delete retryNode.spendAuthorizationId;
        if (options?.settleOnly === true) delete retryNode.spendPlan;
        delete retryNode.outcomeUncertain;
        delete retryNode.interrupted;
        delete retryNode.operationRequestId;
        retrySource.revision += 1;
        retrySource.status = "failed";
        retrySource.finishedAt = this.clock();
        await this.assertExecutionLease(lease);
        await this.store.save(retrySource, previous.revision);
        await this.assertExecutionLease(lease);
        await writePaidNodeReconciliationRecord(recordPath, {
          ...reconciliationRecord,
          status: "completed",
          resultingRunRevision: retrySource.revision,
        });
        return retrySource;
      }
      const remainingManualAssetItems = manualAssetItem
        ? items.filter((item) => paidAssetItemNeedsManualReconciliation(item))
        : [];
      if (remainingManualAssetItems.length > 0) {
        const authorizationId = retryNode.spendAuthorizationId;
        if (authorizationId) {
          const consumed = (retrySource.consumedSpendAuthorizationIds ??= []);
          if (!consumed.includes(authorizationId)) consumed.push(authorizationId);
        }
        delete retryNode.spendAuthorizationId;
        retryNode.status = "failed";
        retryNode.operationRequestId = operationId!;
        retryNode.outcomeUncertain = true;
        retryNode.interrupted = true;
        retrySource.revision += 1;
        retrySource.status = "failed";
        retrySource.finishedAt = this.clock();
        await this.assertExecutionLease(lease);
        await this.store.save(retrySource, previous.revision);
        await this.assertExecutionLease(lease);
        await writePaidNodeReconciliationRecord(recordPath, {
          ...reconciliationRecord,
          status: "completed",
          resultingRunRevision: retrySource.revision,
        });
        return retrySource;
      }
      if (options?.settleOnly === true) {
        const authorizationId = retryNode.spendAuthorizationId;
        if (authorizationId) {
          const consumed = (retrySource.consumedSpendAuthorizationIds ??= []);
          if (!consumed.includes(authorizationId)) consumed.push(authorizationId);
        }
        delete retryNode.spendAuthorizationId;
        delete retryNode.spendPlan;
        delete retryNode.outcomeUncertain;
        delete retryNode.interrupted;
        delete retryNode.operationRequestId;
        retryNode.status = "failed";
        retryNode.error = "这笔历史付费任务已完成账单结算；旧版制作不会恢复执行，请创建新版本继续制作。";
        retryNode.finishedAt = this.clock();
        retrySource.revision += 1;
        retrySource.status = "failed";
        retrySource.finishedAt = this.clock();
        await this.assertExecutionLease(lease);
        await this.store.save(retrySource, previous.revision);
        await this.assertExecutionLease(lease);
        await writePaidNodeReconciliationRecord(recordPath, {
          ...reconciliationRecord,
          status: "completed",
          resultingRunRevision: retrySource.revision,
        });
        return retrySource;
      }
      if (resumeOriginalOperation) {
        retryNode.interrupted = true;
      } else {
        delete retryNode.outcomeUncertain;
        delete retryNode.interrupted;
        delete retryNode.operationRequestId;
      }

      const brief = parsePersistedBrief(retrySource.initialInput);
      let persisted = false;
      let persistedRevision = previous.revision;
      const checkpoint = async (run: WorkflowRun<ProductionBrief>) => {
        await this.assertExecutionLease(lease);
        if (run.revision === persistedRevision + 1) {
          await this.store.save(run, persistedRevision);
          persisted = true;
          persistedRevision = run.revision;
          return;
        }
        if (run.revision !== persistedRevision) {
          throw new StaleRunRevisionError(run.id, run.revision, persistedRevision);
        }
        await this.store.checkpoint(run);
      };
      const runner = new WorkflowRunner({
        providers: this.createRegistry(brief, voiceManifestRecovery,
          draft.nodeId === "assets" && resumeOriginalOperation ? operationId : undefined),
        clock: this.clock,
        idFactory: this.idFactory,
        checkpoint: (run) => checkpoint(run as WorkflowRun<ProductionBrief>),
        shouldPause: () => this.consumePauseRequest(runId),
      });
      let result = await runner.retryFailedNode(
        this.createWorkflow(brief),
        withExecutableBrief(retrySource, brief),
        draft.nodeId,
        resumeOriginalOperation ? { resumeUncertainOperation: true } : undefined,
      );
      if (draft.nodeId === "assets" && operationId && resumeOriginalOperation) {
        items = (await inspectPaidAssetLedger(nodeDirectory)).filter((item) => item.operationId === operationId);
        const unresolvedItems = items.filter((item) => (
          item.state === "submitted"
          || item.state === "unknown"
          || item.state === "provider_succeeded"
        ));
        const recoveryNode = result.nodeRuns.find((node) => node.nodeId === draft.nodeId);
        if (unresolvedItems.length > 0 && recoveryNode?.status === "failed") {
          const lockedNode = recoveryNode;
          const updatedSettlement = paidAssetSettlement(items);
          settlePaidOperationReceipt(
            result,
            draft.nodeId,
            operationId,
            updatedSettlement.actualCostCny,
            updatedSettlement.meteredAttemptCount,
            updatedSettlement.meteredFailedAttemptCount,
            this.clock(),
            settlementActualCostSource,
          );
          lockedNode.status = "failed";
          lockedNode.operationRequestId = operationId;
          lockedNode.outcomeUncertain = true;
          lockedNode.interrupted = true;
          result.status = "failed";
          result.finishedAt ??= this.clock();
          await this.assertExecutionLease(lease);
          await this.store.checkpoint(result);
        } else if (paidAssetRemainderNeedsNewOperation(items) && recoveryNode?.status === "failed") {
          const completedRecoveryNode = recoveryNode;
          const readyForRequote = items.length > 0 && items.every((item) => (
            item.state === "materialized"
            || item.state === "terminal_failed"
            || item.state === "prepared"
          ));
          if (!completedRecoveryNode || completedRecoveryNode.status !== "failed" || !readyForRequote) {
            throw new Error("Paid asset recovery did not reach a safe state for a new quote.");
          }
          const requoteSource = structuredClone(result);
          const updatedSettlement = paidAssetSettlement(items);
          settlePaidOperationReceipt(
            requoteSource,
            draft.nodeId,
            operationId,
            updatedSettlement.actualCostCny,
            updatedSettlement.meteredAttemptCount,
            updatedSettlement.meteredFailedAttemptCount,
            this.clock(),
            settlementActualCostSource,
          );
          const requoteNode = requoteSource.nodeRuns.find((node) => node.nodeId === draft.nodeId)!;
          delete requoteNode.outcomeUncertain;
          delete requoteNode.interrupted;
          delete requoteNode.operationRequestId;
          // 原任务已物化，剩余采购必须回到普通报价，不能继承恢复专用的零新增许可。
          const requoteRunner = new WorkflowRunner({
            providers: this.createRegistry(brief), clock: this.clock, idFactory: this.idFactory,
            checkpoint: (run) => checkpoint(run as WorkflowRun<ProductionBrief>),
            shouldPause: () => this.consumePauseRequest(runId),
          });
          result = await requoteRunner.retryFailedNode(
            this.createWorkflow(brief),
            withExecutableBrief(requoteSource, brief),
            draft.nodeId,
          );
        }
      }
      if (!persisted) {
        await this.assertExecutionLease(lease);
        await this.store.save(result, previous.revision);
      }
      await this.assertExecutionLease(lease);
      await writePaidNodeReconciliationRecord(recordPath, {
        ...reconciliationRecord,
        status: "completed",
        resultingRunRevision: result.revision,
      });
      return result;
    } finally {
      await this.releaseExecutionLease(lease);
    }
  }

  // C1：接受制作范围授权（用户确认方案/追加额度的业务许可）。校验全部在宿主内完成——
  // approvalRevision 必须等于当前 run revision（lease 内单写者核验），supersedes 必须指向
  // 本 run 已接受的授权，不接受重复 id。记录原子落盘，不注册为节点产物（宿主级许可）。
  async acceptProductionAuthorization(runId: string, scopeInput: unknown): Promise<WorkflowRun<ProductionBrief>> {
    const updated = await this.runPersistedTransition(runId, async (previous) => {
      const scope = parseProductionAuthorizationScope(scopeInput);
      if (!/^[A-Za-z0-9_-]{1,128}$/.test(scope.id)) {
        throw new Error("Production authorization id must be a filename-safe identifier (letters, digits, underscore, hyphen; max 128).");
      }
      if (scope.supersedesAuthorizationId !== undefined && !/^[A-Za-z0-9_-]{1,128}$/.test(scope.supersedesAuthorizationId)) {
        throw new Error("Production authorization supersedes id must be a filename-safe identifier.");
      }
      if (scope.runId !== previous.id) {
        throw new Error(`Production authorization '${scope.id}' belongs to run '${scope.runId}', not '${previous.id}'.`);
      }
      if (scope.approvalRevision !== previous.revision) {
        throw new StaleRunRevisionError(runId, scope.approvalRevision, previous.revision);
      }
      const directory = path.join(this.runsRoot, runId, "production-authorization");
      const destination = path.join(directory, `${scope.id}.json`);
      const scopeContent = `${JSON.stringify(scope, null, 2)}\n`;
      const committedRecords = productionAuthorizationRecords(previous.artifacts);
      const committedScopeIds = new Set(committedRecords.map((record) => record.id));
      try {
        const existing = await readFile(destination, "utf8");
        if (existing !== scopeContent || committedScopeIds.has(scope.id)) {
          throw new Error(`Production authorization '${scope.id}' has already been accepted with different state.`);
        }
      } catch (error) {
        if (!hasCode(error, "ENOENT")) throw error;
      }
      // 链完整性无条件校验（与读取共用同一严格校验器，含内容摘要/身份/前驱/环检查）：
      // 目录里已有授权时，新授权必须 supersede 当前 head（唯一幸存者）；未提供前驱只允许
      // 在尚无任何授权时（首份）。损坏链返回 integrity_error 并 fail closed。
      const chain = await inspectProductionAuthorizationChain(directory, previous.id, committedRecords);
      if (chain.state === "integrity_error") {
        throw new Error(
          `Production authorization chain of run '${previous.id}' failed integrity validation (${chain.reason}); refusing to accept '${scope.id}'.`,
        );
      }
      const currentHeadId = chain.state === "committed" ? chain.head.id : undefined;
      if (scope.supersedesAuthorizationId) {
        if (currentHeadId !== scope.supersedesAuthorizationId) {
          throw new Error(
            `Production authorization '${scope.id}' must supersede the current active authorization '${currentHeadId ?? "none"}', not '${scope.supersedesAuthorizationId}'.`,
          );
        }
      } else if (currentHeadId !== undefined) {
        throw new Error(
          `Production authorization '${scope.id}' must supersede the current active authorization '${currentHeadId}'; the run already holds an active authorization.`,
        );
      }
      await writeTextAtomically(destination, scopeContent);
      // 接受授权是 run 状态变化：revision + 1，使后续追加/编辑的 approvalRevision 重新对齐。
      return {
        ...previous,
        revision: previous.revision + 1,
        artifacts: [
          ...previous.artifacts,
          {
            id: `production-authorization:${scope.id}`,
            kind: "production_authorization",
            uri: destination,
            createdAt: this.clock(),
            provenance: {
              providerId: "video-factory-production-authorization",
              producerRequestDigest: createHash("sha256").update(scopeContent).digest("hex"),
            },
            sha256: createHash("sha256").update(scopeContent).digest("hex"),
            sizeBytes: Buffer.byteLength(scopeContent),
            contentType: "application/json",
            schemaVersion: PRODUCTION_AUTHORIZATION_VERSION,
          },
        ],
      };
    });
    // transition 之外续链（lease 已释放）：若 run 正停在报价等待且该授权完全覆盖当前报价，
    // 立即派生子凭证继续制作；未覆盖则保持人工等待。继续链失败按原语义冒泡（授权已落盘，不回滚）。
    if (updated.status === "awaiting_spend_approval" || updated.status === "approval_invalidated") {
      return this.continueCoveredSpendApproval(runId, { runId, completion: Promise.resolve(updated) }).completion;
    }
    return updated;
  }

  // 当前有效的制作范围授权：已被追加替代的授权不再生效，取最新接受的一份。
  // 与接受路径共用同一严格链校验器（内容摘要/身份/前驱/环全覆盖）；损坏链抛完整性
  // 错误，绝不按"尚无授权"处理。
  async readProductionAuthorization(runId: string): Promise<ProductionAuthorizationScope | undefined> {
    const directory = path.join(this.runsRoot, runId, "production-authorization");
    const run = await this.store.load<ProductionBrief>(runId);
    const chain = await inspectProductionAuthorizationChain(
      directory,
      runId,
      productionAuthorizationRecords(run.artifacts),
    );
    if (chain.state === "integrity_error") {
      throw new Error(`Production authorization state of run '${runId}' failed integrity validation (${chain.reason}).`);
    }
    if (chain.state === "absent") return undefined;
    return chain.head;
  }

  // C1：报价等待的制作范围自动继续（可信宿主派生子凭证，复用既有 authorizeSpend，不新建
  // 第二套授权路径）。覆盖评估锚定当前 executable plan 内容 digest（方案变了必须重新确认）
  // 与质量合同投影；逐项核验 assetKey/模型/金额/次数，余额按 paid ledger 保守汇总。
  // 派生的子凭证与当前报价计划在 matcher 逐字段一致（maxCostCny/maxAttempts 不再收窄——
  // 收窄过的凭证必然被原 exact matcher 拒绝）；scope 逐素材次数预算经 itemCreateBudgets
  // 随子凭证下发，由 worker 在每个 create 边界强制执行。任何一项不覆盖都保持人工等待，
  // 并把结构化 assessment 落到等待节点供 C2 展示。
  private continueCoveredSpendApproval(
    runId: string,
    dispatched: DispatchedProductionRun,
    listener?: ProductionRunListener,
  ): DispatchedProductionRun {
    // 惰性链：不阻塞 dispatch 返回（调用方依赖“首检查点后立即返回”的合同）；
    // completion 落定后才检查是否可凭 scope 自动继续。
    const chained: Promise<WorkflowRun<ProductionBrief>> = (async () => {
      let current = dispatched;
      for (let hop = 0; hop < 8; hop += 1) {
        const run = await current.completion;
        if (run.status !== "awaiting_spend_approval" && run.status !== "approval_invalidated") return run;
        // 损坏授权链在此抛完整性错误（fail closed），绝不当作"尚无授权"继续。
        const scope = await this.readProductionAuthorization(runId);
        if (!scope) return run;
        const waiting = run.nodeRuns.find((node) => (
          (node.status === "awaiting_spend_approval" || node.status === "approval_invalidated") && node.spendPlan
        ));
        const plan = waiting?.spendPlan;
        if (!plan) return run;
        // 唯一 ledger 快照：覆盖判定与派生预算共用同一次读取——第二次读取失败被
        // 当作零占用会让"次数/余额已消耗"凭空消失（审计 N6 残留）。
        const ledgerSnapshot = await inspectPaidAssetLedger(
          path.join(this.runsRoot, runId, "nodes", plan.nodeId),
        ).catch(() => null);
        const result = await assessProductionScopePendingQuote({
          scope,
          run,
          runsRoot: this.runsRoot,
          spendPlan: plan,
          paidItems: ledgerSnapshot,
        });
        if (!result.covered) {
          if (result.assessment) {
            // 评估已持久化：返回更新后的 run（内存里的 run 快照不含新写入的 assessment）。
            const updated = await this.recordNodeSpendAssessment(runId, plan.nodeId, run.revision, result.assessment);
            if (updated) return updated;
          }
          return run;
        }
        const foldedLedger = foldProductionSpendLedger(ledgerSnapshot ?? [], {
          terminalOperationIds: finishedPaidOperationIds(run, plan.nodeId),
        });
        // 逐素材剩余 create 预算（scope 用户批准的每素材上限 - ledger 已用次数）。
        // 全覆盖评估保证每个新 create 项至少剩 1 次；预算随子凭证下发，由 worker 在
        // create 边界执行——收窄发生在预留层，不改动必须与报价计划逐字段一致的凭证。
        const itemCreateBudgets: Record<string, number> = {};
        for (const quoteItem of plan.items ?? []) {
          const permitted = scope.permittedAssets.find((asset) => asset.assetKey === quoteItem.id);
          if (!permitted) continue;
          const remaining = permitted.maxCreateAttempts - (foldedLedger.attemptsByAsset[quoteItem.id] ?? 0);
          if (remaining >= 1) itemCreateBudgets[quoteItem.id] = remaining;
        }
        // 金额上界已并入整份计划评估（planMaximumCents）：assessment 覆盖"条目合计与
        // 计划最高占用取大"的完整口径，这里不再重复检查。
        const expectedScopeId = scope.id;
        current = await this.dispatchSpendAuthorization(runId, {
          spendPlanId: plan.id,
          nodeId: plan.nodeId,
          inputVersionIds: plan.inputVersionIds,
          providerId: plan.providerId,
          modelId: plan.modelId,
          // 与当前报价计划逐字段一致（原 exact matcher 原样通过）；
          // 范围约束在 itemCreateBudgets（预留层）与 scope 余额核对（此处）执行。
          maxCostCny: plan.maxCostCny,
          maxAttempts: plan.maxAttempts,
          // 子凭证的批准者记录其派生来源；人类批准者仍是接受 scope 时的 approvedBy。
          approvedBy: `${scope.approvedBy}（制作范围授权 ${scope.id}）`,
          derivedFromScopeId: scope.id,
          itemCreateBudgets,
        }, listener, async () => {
          // supersession 防护（C1-R1）：派发事务持锁边界内重读授权链，确认 head 仍是覆盖
          // 判定所用的 scope；已被替代的 scope 不得为尚未开始的新请求签发子授权。
          const latest = await this.readProductionAuthorization(runId);
          if (latest?.id !== expectedScopeId) {
            throw new Error(
              `Production authorization '${expectedScopeId}' is no longer the active authorization of run '${runId}'; refusing to derive a child spend credential.`,
            );
          }
        });
      }
      return current.completion;
    })();
    return { runId, completion: chained };
  }

  // C1-R5：把"范围未覆盖"的结构化评估落到等待节点（CAS 持久化），供 C2 投影展示；
  // 节点已离开等待状态或 revision 已前进而并发变化时不覆盖任何新状态。
  // 返回写入后的最新 run；无法写入（并发变化）时返回 undefined。
  private async recordNodeSpendAssessment(
    runId: string,
    nodeId: string,
    expectedRevision: number,
    assessment: ProductionSpendPlanAssessment,
  ): Promise<WorkflowRun<ProductionBrief> | undefined> {
    // 预检查：不可写状态直接放弃，不进入 CAS（save 合同要求 revision + 1，不接受无变更返回）。
    const current = await this.store.load<ProductionBrief>(runId);
    const currentTarget = current.nodeRuns.find((node) => node.nodeId === nodeId);
    if (current.revision !== expectedRevision || !currentTarget
      || (currentTarget.status !== "awaiting_spend_approval" && currentTarget.status !== "approval_invalidated")) {
      return undefined;
    }
    try {
      return await this.runPersistedTransition(runId, async (previous) => {
        // 持锁边界内二次核对：预检查后发生并发变化时放弃（save 以异常失败，由外层捕获）。
        const target = previous.nodeRuns.find((node) => node.nodeId === nodeId);
        if (previous.revision !== expectedRevision || !target
          || (target.status !== "awaiting_spend_approval" && target.status !== "approval_invalidated")) {
          throw new StaleRunRevisionError(runId, expectedRevision, previous.revision);
        }
        return {
          ...previous,
          revision: previous.revision + 1,
          nodeRuns: previous.nodeRuns.map((node) => (
            node.nodeId === nodeId
              ? { ...node, spendAssessment: assessment as unknown as Record<string, unknown> }
              : node
          )),
        };
      });
    } catch {
      // 评估落盘是尽力而为的投影：并发状态变化时放弃写入，不阻断等待语义本身。
      return undefined;
    }
  }

  // C2/CG-01：授权命令的续链恢复——授权已提交但 governed continuation 未完成（进程在
  // run CAS 之后、续链完成之前中断）时，重新触发同一条 continuation。幂等：run 不在
  // 报价等待状态时原样返回；仍在等待且未覆盖时记录评估并保持等待，不签发任何新凭证。
  async resumeCoveredSpendApproval(runId: string): Promise<WorkflowRun<ProductionBrief>> {
    const run = await this.store.load<ProductionBrief>(runId);
    return this.continueCoveredSpendApproval(runId, { runId, completion: Promise.resolve(run) }).completion;
  }

  async inspectPaidNode(runId: string, nodeId: string): Promise<ProductionPaidNodeSummary> {    const run = await this.store.load<ProductionBrief>(runId);
    const node = run.nodeRuns.find((candidate) => candidate.nodeId === nodeId);
    if (!node) throw new Error(`Unknown workflow node '${nodeId}'.`);
    const operationId = node.operationRequestId;
    if (!operationId) {
      return { nodeId, failureKind: "missing_evidence", requiresManualReconciliation: true, items: [] };
    }
    const nodeDirectory = path.join(this.runsRoot, runId, "nodes", nodeId);
    if (nodeId === "voice") {
      const voiceOperation = await readPaidVoiceOperation(nodeDirectory, operationId);
      const resumable = voiceOperation ? canResumePaidVoiceOperation(voiceOperation) : false;
      const terminalFailure = Boolean(voiceOperation?.items.some((item) => item.state === "terminal_failed"))
        && voiceOperation!.items.every((item) => (
          item.state === "prepared" || item.state === "materialized" || item.state === "terminal_failed"
        ));
      return {
        nodeId,
        operationId,
        ...(resumable
          ? { recommendedOutcome: "resume_original" as const }
          : terminalFailure
            ? { recommendedOutcome: "confirmed_not_charged" as const, failureKind: "terminal_failure" as const }
            : { failureKind: voiceOperation ? "unknown_outcome" as const : "missing_evidence" as const }),
        requiresManualReconciliation: !resumable,
        items: [],
      };
    }
    if (nodeId !== "assets") return { nodeId, operationId, failureKind: "missing_evidence", requiresManualReconciliation: true, items: [] };
    const ledgerItems = (await inspectPaidAssetLedger(
      nodeDirectory,
    )).filter((item) => item.operationId === operationId);
    const effectiveItems = isTrustedPreSubmissionAssetRejection(node, ledgerItems)
      ? ledgerItems.map((item) => {
          if (item.state !== "unknown" || item.taskId) return item;
          const { actualCostCny: _actualCostCny, actualCostSource: _actualCostSource, ...rest } = item;
          return { ...rest, state: "terminal_failed" as const };
        })
      : ledgerItems;
    const trustedPreSubmissionRejection = isTrustedPreSubmissionAssetRejection(node, ledgerItems);
    const requiresManualReconciliation = trustedPreSubmissionRejection
      ? false
      : paidAssetOperationNeedsManualReconciliation(effectiveItems);
    const resumeOriginalOperation = effectiveItems.length > 0 && canResumePaidAssetOperation(effectiveItems);
    return {
      nodeId,
      operationId,
      ...(!requiresManualReconciliation
        ? { recommendedOutcome: resumeOriginalOperation ? "resume_original" as const : "requote" as const }
        : {}),
      requiresManualReconciliation,
      items: effectiveItems.map((item) => ({
        operationId: item.operationId,
        itemRequestId: item.itemRequestId,
        quoteItemId: item.quoteItemId,
        scenePosition: item.scenePosition,
        executorProviderId: item.executorProviderId,
        providerId: item.providerId,
        modelId: item.modelId,
        state: item.state,
        estimatedCostCny: item.estimatedCostCny,
        ...(item.taskId ? { taskId: item.taskId } : {}),
        ...(item.actualCostCny !== undefined ? { actualCostCny: item.actualCostCny } : {}),
        ...(item.actualCostSource ? { actualCostSource: item.actualCostSource } : {}),
        ...(item.error ? { error: item.error } : {}),
        ...(item.manualReconciliationRequired ? { manualReconciliationRequired: true } : {}),
      })),
    };
  }

  // joint-v1 规划阶段的只读检视（Studio 详情消费）：阶段列表来自当前路线的真实拓扑，
  // 状态只由 checkpoint 快照、role-agent checkpoint 与经严格校验的 planning commit 推导。
  // 读取绝不 invoke 图、绝不触发角色/Provider；checkpoint 缺失如实全 pending，
  // 身份错配或存储损坏返回 undefined（fail closed，不回退旧 NodeRun 也不伪造状态）。
  async inspectCreativePlanningStages(runId: string): Promise<CreativePlanningStageInspection[] | undefined> {
    const run = await this.store.load<ProductionBrief>(runId);
    const brief = effectiveProductionBrief(run);
    if (brief.workflowFeatures?.creativePlanning !== "joint-v1") return undefined;
    const libraryRoute = brief.workflowFeatures?.assetSemanticRank === true;
    const stageIds = libraryRoute ? PLANNING_STAGE_ORDER_LIBRARY : PLANNING_STAGE_ORDER_FIXED;
    const bindingModelOf = (stage: PlanningStageId) => this.planningBindingModelId(stage, brief);
    const planningNode = run.nodeRuns.find((node) => node.nodeId === "creative-planning");
    const inputState = planningNode?.inputState;
    if (!planningNode || !inputState || inputState.stale) {
      // 规划尚未启动（上游失败或未轮到），或当前有效输入已被上游改动标记过时：
      // 新 thread 尚未确定，不得拿旧输入身份的 checkpoint 冒充当前进度；模型阶段仍显示当前绑定。
      return planningStagesAllPending(stageIds, bindingModelOf, (stage) => this.planningBindingProviderId(stage, brief));
    }
    const effectiveInput = inputState.versions.find(
      (version) => version.id === inputState.effectiveVersionId,
    )?.value;
    if (!isObjectRecord(effectiveInput) || !isObjectRecord(effectiveInput.brief)) return undefined;
    const referenceGrammarEnabled = brief.workflowFeatures?.referenceGrammar === true;
    let inputDigest: string;
    try {
      const referenceGrammar = referenceGrammarEnabled && typeof effectiveInput.referenceGrammarPath === "string"
        ? await readShotGrammarFile(effectiveInput.referenceGrammarPath)
        : undefined;
      // 正式校验当前输入 brief：坏输入（字段级非法）不得进入身份计算，fail closed。
      inputDigest = jointPlanningInputDigest(mergeCurrentBrief(effectiveInput.brief, brief), referenceGrammar);
    } catch {
      // 参考语法文件缺失/损坏，或当前输入 brief 不满足正式合同：无法确定输入身份，fail closed。
      return undefined;
    }
    // checkpoint 存储尚不存在说明该工作区从未启动过 joint 规划：如实全 pending，
    // 且读取路径不得创建存储文件。
    let sqliteExists = true;
    try {
      await stat(planningCheckpointSqlitePath(path.dirname(this.runsRoot)));
    } catch {
      sqliteExists = false;
    }
    if (!sqliteExists) return planningStagesAllPending(stageIds, bindingModelOf, (stage) => this.planningBindingProviderId(stage, brief));
    let values: Partial<PlanningGraphState>;
    let cursor: readonly string[] = [];
    try {
      const store = CreativePlanningStore.open(path.dirname(this.runsRoot));
      try {
        const snapshot = await createInspectionPlanningGraph(store, libraryRoute)
          .getState(store.threadConfig(runId, inputDigest));
        values = (snapshot?.values ?? {}) as Partial<PlanningGraphState>;
        cursor = snapshot?.next ?? [];
      } finally {
        store.close();
      }
    } catch {
      // 存储损坏或不可读（含身份校验失败）：不伪造任何阶段状态。
      return undefined;
    }
    if (values.inputDigest == null) {
      // thread 无 checkpoint（规划未开始，或输入已进入新 thread）：如实全 pending。
      return planningStagesAllPending(stageIds, bindingModelOf, (stage) => this.planningBindingProviderId(stage, brief));
    }
    // 快照身份必须与当前请求完全对齐：错 thread/错 run/错 digest 一律 fail closed，
    // 与 runCreativePlanning 的恢复防线同一纪律。
    if (values.runId !== runId || values.inputDigest !== inputDigest) return undefined;

    const completedStages = new Set(stageIds.filter((stage) => planningStageArtifactPresent(stage, values)));
    const cursorStage = cursor.map((node) => node.endsWith("_review") ? node.slice(0, -7) : node)
      .find((node) => (stageIds as readonly string[]).includes(node)) as PlanningStageId | undefined;
    const runningStage = planningNode.status === "running" ? cursorStage : undefined;
    const structuredIssueByStage = new Map<PlanningStageId, string>();
    for (const issue of Array.isArray(values.issues) ? values.issues : []) {
      if (!isObjectRecord(issue)) continue;
      const stage = typeof issue.target === "string" ? planningIssueTargetStage(issue.target) : undefined;
      if (!stage) continue;
      const reason = typeof issue.reason === "string" ? issue.reason : "";
      const requiredChange = typeof issue.requiredChange === "string" ? issue.requiredChange : "";
      const text = `${reason}${requiredChange ? `（${requiredChange}）` : ""}`.trim();
      if (text && !structuredIssueByStage.has(stage)) structuredIssueByStage.set(stage, text);
    }
    // 失败阶段归属：结构化 issue 的目标阶段优先（duplicate_issue/回退耗尽停止时，承担
    // 未决问题的导演已有产物，不能因产物存在就标 completed、把 integrate 标 failed）；
    // 无结构化 issue 时回退到“第一个无产物阶段”；图已完成而正式发布失败（所有阶段都有
    // 产物却没有 commit 接受）时，失败归属于正式方案阶段——不能把发布失败显示成全部完成。
    // role trace 严格绑定当前 inputDigest：只读执行历史里本 digest 的记录，不读其他
    // thread（旧执行）的 v7 checkpoint 或旧 trace——编辑换 digest 后旧 trace 不再冒充。
    const roleModelTraces = await readJointPlanningModelTraces(
      path.join(this.runsRoot, runId, "nodes", "creative-planning", "planning-history.json"),
      inputDigest,
    );
    const publicationVerified = completedStages.size === stageIds.length && planningNode.status === "succeeded";
    const planningCommitted = publicationVerified
      ? await this.planningCommitArtifactIds(runId, inputDigest, values, libraryRoute, run)
      : {};
    // F9 残留：节点已 succeeded、图产物齐全，但正式 commit/registry 核验失败（映射为空）
    // ——发布没有成立，必须在正式方案阶段暴露可行动失败，而不是全绿。
    const commitVerificationFailed = publicationVerified
      && Object.values(planningCommitted).every((ids) => !(ids && ids.length > 0));
    const reviewStage = values.creativeReview?.activeStage;
    const stoppedReviewStage = reviewStage && values.creativeReview?.stages[reviewStage].currentDraft
      && values.creativeReview.stages[reviewStage].phase !== "confirmed" ? reviewStage : undefined;
    const failedStage: PlanningStageId | undefined = planningNode.status === "failed"
      ? stoppedReviewStage ?? cursorStage ?? stageIds.find((stage) => structuredIssueByStage.has(stage))
        ?? stageIds.find((stage) => !completedStages.has(stage))
        ?? (completedStages.size === stageIds.length ? "compile" : undefined)
      : commitVerificationFailed
        ? "compile"
        : undefined;
    return stageIds.map((stage) => {
      // 状态优先级：当前失败 > checkpoint cursor 正在执行 > 已有产物（旧完成）> 待开始。
      // 阶段重跑时旧产物不得把当前活动覆盖成 completed；发布失败不得显示全部 completed。
      const status: CreativePlanningStageInspection["status"] = stage === failedStage
        ? "failed"
        : stage === runningStage
          ? "running"
          : completedStages.has(stage)
            ? "completed"
            : "pending";
      const artifactIds = planningCommitted[stage] ?? [];
      // 来源诚实合同：pending/running 显示当前绑定（用户据此判断这次会用什么）；已完成
      // 模型阶段必须来自真实执行 trace——来源未知时显式 unknown，不用首选绑定冒充
      // （如 fallback 后的实际模型、跨崩溃窗口丢失的 provenance）；确定性阶段无模型字段。
      const modelStage = stage === "treatment" || stage === "script" || stage === "director" || stage === "rank";
      const effectiveModelId = status === "completed"
        ? roleModelTraces[stage] ?? (modelStage ? "unknown" : undefined)
        : roleModelTraces[stage] ?? this.planningBindingModelId(stage, brief);
      const providerId = this.planningBindingProviderId(stage, brief);
      const reviewState = stage === "treatment" || stage === "script" || stage === "director"
        ? values.creativeReview?.stages[stage] : undefined;
      const decisionStatus = reviewState?.currentDraft
        ? reviewState.phase === "waiting_user" ? "waiting_user" as const
          : reviewState.phase === "checking" ? "checking" as const
            : reviewState.phase === "confirmed" && reviewState.confirmation?.draftSha256 === reviewState.currentDraft.sha256
              ? "confirmed" as const : undefined
        : undefined;
      const issue = status === "failed"
        ? structuredIssueByStage.get(stage)
          // CR3（2026-10-05 复审）：失败的前期构思若还能核对当前稿，优先只读结构化诊断
          //（第 N 项＋claim）；当前稿不可核时不断言行号，走 planningFailureForCreators
          // 的窄范围翻译兜底。
          ?? (stage === "treatment" && isObjectRecord(reviewState?.currentDocument)
            ? treatmentMissingProviderIssueText(reviewState.currentDocument) : undefined)
          ?? (commitVerificationFailed && stage === "compile"
            ? "正式交付记录暂未核对成功；已产出的内容会保留，请先检查交付记录。"
            : planningFailureForCreators(planningNode.error ?? ""))
        : decisionStatus === "waiting_user" ? structuredIssueByStage.get(stage) : undefined;
      const allowedActions: CreativePlanningStageAction[] = [
        ...(stage === "treatment" || stage === "script" || stage === "director"
          ? (["edit_input", "change_model"] as const)
          : []),
        ...(artifactIds.length > 0 ? (["view_artifacts"] as const) : []),
      ];
      return {
        id: stage,
        status,
        ...(effectiveModelId !== undefined ? { effectiveModelId } : {}),
        ...(providerId !== undefined ? { providerId } : {}),
        artifactIds: [...artifactIds],
        ...(decisionStatus ? { decisionStatus } : {}),
        ...(stage === "director" && values.creativeReview?.directorReviewPurpose
          ? { reviewPurpose: values.creativeReview.directorReviewPurpose } : {}),
        ...(issue !== undefined && issue !== "" ? { issue } : {}),
        allowedActions,
      };
    });
  }

  // 尚未执行的角色阶段回退到当前有效绑定的首选模型；已执行的以执行历史的真实 trace
  // 为准（含 fallback 后的实际模型）。确定性阶段（candidates/integrate/compile）没有模型。
  private planningBindingModelId(stage: PlanningStageId, brief: ProductionBrief): string | undefined {
    switch (stage) {
      case "treatment": return effectiveTreatmentModelId(brief, this.options.treatmentAgents ?? []);
      case "script": return brief.models?.[brief.providers.script] ?? this.options.screenwriterAgent?.modelId;
      case "director": return brief.providers.director !== undefined
        ? brief.models?.[brief.providers.director] ?? this.options.directorAgent?.modelId
        : this.options.directorAgent?.modelId;
      case "rank": return this.options.assetSemanticRanker
        ? brief.models?.[this.options.assetSemanticRanker.id] ?? this.options.assetSemanticRanker.modelId
        : undefined;
      default: return undefined;
    }
  }

  // 模型阶段当前绑定的能力提供者：UI 的模型选择据此解析，不按能力目录顺序猜测。
  private planningBindingProviderId(stage: PlanningStageId, brief: ProductionBrief): string | undefined {
    switch (stage) {
      case "treatment": return this.options.treatmentAgents?.length ? CREATIVE_TREATMENT_PROVIDER_ID : undefined;
      case "script": return brief.providers.script;
      case "director": return brief.providers.director;
      case "rank": return this.options.assetSemanticRanker?.id;
      default: return undefined;
    }
  }

  // 整份规划正式落定后，把阶段映射到 planning commit 严格绑定过的 run 正式产物 id。
  // 任何一步验证不通过都返回空映射：进行中的规划只能呈现 checkpoint 真实持有的阶段身份，
  // 不得给出不存在的 StudioArtifact id。
  private async planningCommitArtifactIds(
    runId: string,
    inputDigest: string,
    values: Partial<PlanningGraphState>,
    libraryRoute: boolean,
    run: WorkflowRun<ProductionBrief>,
  ): Promise<Partial<Record<PlanningStageId, string[]>>> {
    const script = values.scriptArtifact;
    const treatment = values.treatmentArtifact;
    const finalPlan = values.integratedPlan ?? values.directorPlan;
    const candidates = values.candidatesArtifact;
    const ranking = values.ranking;
    const executablePlan = values.executablePlan;
    if (!treatment || !script || !finalPlan || !executablePlan) return {};
    if (libraryRoute && (!candidates || !ranking)) return {};
    let commit: JointPlanningCommit;
    try {
      const planningCommitKey = jointPlanningCommitKey({
        runId,
        inputDigest,
        treatment: treatment.artifactId,
        script: script.artifactId,
        directorPlan: finalPlan.artifactId,
        ...(libraryRoute && candidates ? { candidates: candidates.artifactId } : {}),
        ...(libraryRoute && ranking ? { ranking: ranking.artifactId } : {}),
        stockAcceptance: confirmedStockDeliveryAcceptance(values as PlanningGraphState),
        executablePlan: executablePlan.artifactId,
        ...characterPlanningCommitIdentity(script.output, values.creativeReview),
      });
      const existing = await readJointPlanningCommit(
        path.join(this.runsRoot, runId, "planning", "commits", `${planningCommitKey}.json`),
      );
      if (existing === undefined) return {};
      commit = await verifyJointPlanningCommit({
        commit: existing,
        planningCommitKey,
        inputDigest,
        runId,
        runRoot: path.join(this.runsRoot, runId),
        artifacts: run.artifacts,
        expectedKinds: jointPlanningExpectedKinds(libraryRoute),
      });
    } catch {
      return {};
    }
    const idsOfKind = (kind: string) => commit.artifacts
      .filter((entry) => entry.kind === kind)
      .map((entry) => entry.artifactId);
    // BG-01 尾巴：声音时长修订等人工修订会替换 planning 节点当前 effective version 的
    // 成员（如新 executable_plan）。stage 投影必须反映"当前接受版本"，不能永远指向
    // 原始 graph commit 的产物。
    const planningNode = run.nodeRuns.find((node) => node.nodeId === "creative-planning");
    const currentVersionIds = new Set(
      planningNode?.outputState?.versions.find(
        (version) => version.id === planningNode.outputState?.effectiveVersionId,
      )?.artifactIds ?? [],
    );
    const currentVersionExecutablePlan = currentVersionIds.size > 0
      ? run.artifacts
        .filter((artifact) => (
          currentVersionIds.has(artifact.id)
          && artifact.kind === "executable_plan"
          && artifact.producer?.nodeId === "creative-planning"
        ))
        .map((artifact) => artifact.id)
      : [];
    return {
      treatment: idsOfKind("creative_treatment"),
      script: idsOfKind("script"),
      director: idsOfKind("storyboard"),
      ...(libraryRoute ? {
        candidates: idsOfKind("asset_candidates"),
        rank: idsOfKind("asset_ranking"),
        integrate: idsOfKind("storyboard"),
      } : {}),
      compile: currentVersionExecutablePlan.length > 0 ? currentVersionExecutablePlan : idsOfKind("executable_plan"),
    };
  }

  private paidReconciliationPath(runId: string, reconciliationId: string): string {
    const name = createHash("sha256").update(reconciliationId).digest("hex");
    return path.join(this.store.runDirectory(runId), ".paid-reconciliations", `${name}.json`);
  }

  async dispatchRetryFailedNode(
    runId: string,
    nodeId: string,
    listener?: ProductionRunListener,
    options?: ProductionNodeRetryOptions,
  ): Promise<DispatchedProductionRun> {
    const observed = await this.store.load<ProductionBrief>(runId);
    const failedReview = observed.nodeRuns.find(node => node.nodeId === nodeId);
    if (nodeId === "asset-source-review" && observed.status === "failed" && failedReview?.status === "failed"
      && failedReview.errorCode === "SOURCE_RANGE_TOO_SHORT" && !failedReview.outcomeUncertain) {
      await this.runPersistedTransition(runId, async previous => {
        if (previous.revision !== observed.revision) throw new StaleRunRevisionError(runId, observed.revision, previous.revision);
        const brief = parsePersistedBrief(previous.initialInput);
        const assets = previous.nodeRuns.find(node => node.nodeId === "assets");
        const inputVersion = assets?.inputState?.versions.find(version => version.id === assets.inputState?.effectiveVersionId);
        const assetInput = requireOutputRecord(inputVersion?.value, "saved asset input");
        if (!await supportsFreeStockRematch(brief, assetInput.directorPlanPath)) {
          throw new Error("当前路线不能自动重新匹配免费素材；请调整素材方案，涉及新购买仍须重新确认费用。");
        }
        const version = assets?.outputState?.versions.find(item => item.id === assets.outputState?.effectiveVersionId);
        const planPath = requiredOutputString(version?.output ?? assets?.output, "assetPlanPath");
        const plan = previous.artifacts.find(item => version?.artifactIds.includes(item.id)
          && item.kind === "asset_plan" && item.uri === planPath && item.producer?.nodeId === "assets");
        if (!plan) throw new Error("当前素材方案缺少可核对的产物记录，不能重新匹配。");
        await verifyStoredArtifactWithinRoot(this.store.runDirectory(runId), plan);
        const runner = new WorkflowRunner({ providers: this.createRegistry(brief), clock: this.clock, idFactory: this.idFactory });
        // 使用同一正式编辑/失效合同，只重开素材及其后代；规划版本和已有文件保持不动。
        return runner.applyNodeInputOverride(this.createWorkflow(brief), withExecutableBrief(previous, brief), {
          nodeId: "assets", actor: "creator", expectedVersionId: inputVersion!.id, allowTerminalEdit: true,
          input: { ...assetInput, reuseAssetPlanArtifactId: plan.id },
        });
      });
      return this.dispatchResumeStale(runId, listener);
    }
    const dispatched = await this.dispatchPersistedTransition(runId, async (previous, checkpoint) => {
      const retryRejectedReview = canRetryRejectedReviewNode(previous, nodeId);
      const retryNativeAudio = canRetryNativeAudioNode(previous, nodeId);
      if (options?.nativeAudioRecovery || retryNativeAudio) {
        const target = options?.nativeAudioRecovery;
        if (!retryNativeAudio || !target || target.expectedRunRevision !== previous.revision
          || target.interventionId !== previous.nodeRuns.find(node => node.nodeId === nodeId)?.intervention?.id) {
          throw new HumanDecisionConflictError("原声准备停点已变化，请刷新后再试。");
        }
      }
      const brief = parsePersistedBrief(previous.initialInput);
      const recoveryWorkflowOperationRequestId = options?.recoverOriginalTextTask
        ? previous.nodeRuns.find((node) => node.nodeId === nodeId)?.operationRequestId
        : undefined;
      const creativeCommand = recoverableCreativeReviewCommand(previous, nodeId);
      const failedNode = previous.nodeRuns.find((node) => node.nodeId === nodeId);
      const voiceOperation = nodeId === "voice" && failedNode?.status === "failed"
        && !failedNode.outcomeUncertain && failedNode.executionReceipt?.providerId === "minimax-tts-v1"
        && failedNode.operationRequestId
        ? await readPaidVoiceOperation(path.join(this.runsRoot, runId, "nodes", nodeId), failedNode.operationRequestId)
        : undefined;
      const voiceManifestPath = voiceOperation && failedNode?.operationRequestId
        && canRebuildPaidVoiceManifest(voiceOperation)
        ? await discoverPaidVoiceManifest(
            path.join(this.runsRoot, runId, "nodes", nodeId),
            failedNode.operationRequestId,
          )
        : undefined;
      const voiceManifestRecovery = voiceOperation && failedNode?.operationRequestId
        && canRebuildPaidVoiceManifest(voiceOperation)
        ? {
            sourceOperationId: failedNode.operationRequestId,
            ...(voiceManifestPath ? { manifestPath: voiceManifestPath } : {}),
          }
        : undefined;
      const resumeKnownVoice = voiceOperation && canResumePaidVoiceOperation(voiceOperation)
        && voiceOperation.items.some((item) => item.state === "materialized");
      const recoverKnownVoice = Boolean(voiceManifestRecovery) || Boolean(resumeKnownVoice);
      const recoveryBase = creativeCommand || recoverKnownVoice ? structuredClone(previous) : previous;
      if (recoverKnownVoice) {
        // 本地归一化失败不撤销已合成音频；普通重试沿原身份，只补尚未提交的段落。
        recoveryBase.nodeRuns.find((node) => node.nodeId === nodeId)!.interrupted = true;
      }
      if (creativeCommand) {
        const operation = recoveryBase.creativeReviewOperations!.find((item) => item.commandId === creativeCommand.commandId)!;
        operation.status = "running";
        delete operation.finishedAt;
      }
      const runner = new WorkflowRunner({
        providers: this.createRegistry(brief, voiceManifestRecovery),
        clock: this.clock,
        idFactory: this.idFactory,
        checkpoint: (run) => checkpoint(run as WorkflowRun<ProductionBrief>),
        shouldPause: () => this.consumePauseRequest(runId),
      });
      const result = await runner.retryFailedNode(
        this.createWorkflow(brief, {
          ...(creativeCommand ? { creativeReviewResume: creativeCommand.resume } : {}),
          ...(options?.resumeCompletedTextTask ? { resumeCompletedTextTaskNodeId: nodeId } : {}),
          ...(options?.resumeCompletedTextTaskRequestId
            ? { resumeCompletedTextTaskRequestId: options.resumeCompletedTextTaskRequestId }
            : {}),
          ...(recoveryWorkflowOperationRequestId
            ? { recoverTextTask: { nodeId, workflowOperationRequestId: recoveryWorkflowOperationRequestId } }
            : {}),
        }),
        withExecutableBrief(recoveryBase, brief),
        nodeId,
        retryNativeAudio
          ? { allowLocalPreparationRetry: true }
          : retryRejectedReview
          ? { allowRejectedNode: true }
          : previous.nodeRuns.find((node) => node.nodeId === nodeId)?.intervention?.kind === "source_review_retry"
            ? { allowSourceReviewRetry: true }
            : undefined,
      );
      // 取回原请求与重放原命令必须收口同一条回执，不能只恢复稿件却永久显示命令失败。
      // 仅消费本次失败节点携带的命令身份，不扫改其他历史失败记录。
      if (creativeCommand) {
        const node = result.nodeRuns.find((candidate) => candidate.nodeId === nodeId);
        const completed = isObjectRecord(node?.output) ? node.output.creativeReviewOperation : undefined;
        const finished = node?.status !== "failed" && isObjectRecord(completed)
          && completed.commandId === creativeCommand.commandId
          && completed.action === creativeCommand.resume.action && completed.status === "completed";
        if (finished || node?.status === "failed") {
          result.creativeReviewOperations = (result.creativeReviewOperations ?? []).map((operation) => (
            operation.commandId === creativeCommand.commandId
              ? { ...operation, status: finished ? "completed" as const : "failed" as const, finishedAt: this.clock() }
              : operation
          ));
          await checkpoint(result);
        }
      }
      return result;
    }, listener);
    return this.continueCoveredSpendApproval(runId, dispatched, listener);
  }

  async dispatchVisualReinspection(
    runId: string,
    draft: ProductionVisualReinspectionDraft,
    listener?: ProductionRunListener,
  ): Promise<DispatchedProductionRun> {
    return this.dispatchPersistedTransition(runId, async (previous, checkpoint) => {
      if (previous.revision !== draft.expectedRunRevision) {
        throw new StaleRunRevisionError(runId, draft.expectedRunRevision, previous.revision);
      }
      if (previous.status !== "needs_human" && previous.status !== "rejected") {
        throw new Error(`Run '${runId}' is not waiting for visual reinspection.`);
      }
      const brief = parsePersistedBrief(previous.initialInput);
      if (!brief.providers.visualReview) throw new Error("Visual reinspection is not enabled for this run.");
      const stop = previous.nodeRuns.find(node => node.status === "needs_human" || node.status === "rejected");
      if (!stop || !["visual-review", "final-review"].includes(stop.nodeId)) {
        throw new HumanDecisionConflictError("请先到当前成片的审片或内部定版停点，再决定是否重新审查。");
      }
      if (previous.nodeRuns.some(node => node.outcomeUncertain === true)) {
        throw new HumanDecisionConflictError("原请求结果仍待核实，请先查询原请求；不会重新提交审片或重买素材。");
      }
      const delivery = requireOutputRecord(currentVisualReviewDelivery(previous), "visual-review delivery");
      assertAudioReviewNotUnknown(delivery);
      const runRoot = this.store.runDirectory(runId);
      const sourceNodes = new Set(["creative-planning", "script", "reference-grammar", "visual-direction",
        "production-preflight", "assets", "voice", "render", "technical-review", "visual-review"]);
      const currentArtifactIds = new Set<string>();
      const filmArtifactIds: string[] = [];
      for (const node of previous.nodeRuns.filter(node => sourceNodes.has(node.nodeId))) {
        if (node.outputState?.stale) throw new HumanDecisionConflictError("当前成片依赖的稿件或素材已变化，请先完成对应更新再审查，旧成片保留。");
        const version = node.outputState?.versions.find(item => item.id === node.outputState?.effectiveVersionId);
        for (const id of version?.artifactIds ?? node.artifactIds) currentArtifactIds.add(id);
        if (node.nodeId === "render" || node.nodeId === "technical-review") {
          filmArtifactIds.push(...(version?.artifactIds ?? node.artifactIds));
        }
      }
      // joint 规划最终版本只登记定稿，但成片的真实来源还包含其创作草稿。
      // 只沿当前成片/技术检查的来源链补齐；不能让旧审片报告自己给任意历史文件背书。
      const ancestry = new Set<string>();
      const visiting = new Set<string>();
      const includeSource = (id: string): void => {
        if (visiting.has(id)) throw new HumanDecisionConflictError("当前成片的来源记录存在循环，请先恢复原产物记录。");
        if (ancestry.has(id)) return;
        const matches = previous.artifacts.filter(artifact => artifact.id === id);
        if (matches.length !== 1) throw new HumanDecisionConflictError("当前成片的来源文件没有完整登记，请先恢复原产物。");
        visiting.add(id);
        for (const parent of matches[0]!.parentArtifactIds ?? []) includeSource(parent);
        visiting.delete(id);
        ancestry.add(id);
        currentArtifactIds.add(id);
      };
      filmArtifactIds.forEach(includeSource);
      // 在新一轮付费审查之前核对当前产物，不能仅凭旧报告的证据编号沿用已被替换的文件。
      for (const id of currentArtifactIds) {
        const artifact = previous.artifacts.find(item => item.id === id);
        if (!artifact) throw new HumanDecisionConflictError("当前审查证据文件没有完整登记，请先恢复原产物。");
        if (artifact.uri) await verifyStoredArtifactWithinRoot(runRoot, artifact);
      }
      if (visualReviewScopeEvidenceId(delivery)) {
        const scope = finalVisualReviewScope(delivery);
        if (scope.evidenceId !== draft.reviewEvidenceId || !Array.isArray(scope.sourceArtifactIds)
          || scope.sourceArtifactIds.some(id => !currentArtifactIds.has(id))) {
          throw new HumanDecisionConflictError("重新审查没有绑定当前成片证据，请刷新后重新确认。");
        }
      } else {
        const final = previous.nodeRuns.find(node => node.nodeId === "final-review");
        const finalOutput = final && effectiveNodeOutput(final);
        if (!incompleteVisualDeliveryProof(delivery) || !finalOutput
          || finalOutput.deliveryEvidenceId !== draft.reviewEvidenceId) {
          throw new HumanDecisionConflictError("请先进入未复核交付停点，核对当前成片证据后再审查。");
        }
        assertInternalDeliveryEvidenceSnapshot(finalOutput, await currentInternalDeliveryEvidence(previous, brief, runRoot));
      }
      // 显式补查必须开启新的审片缓存轮次；同一轮因进程中断而重试时仍沿用该轮，
      // 这样既不会把旧审片结论冒充补查结果，也不会重复已完成的模型分支。
      await writeTextAtomically(
        visualReinspectionCyclePath(this.runsRoot, runId),
        `${randomUUID()}\n`,
      );
      const runner = new WorkflowRunner({
        providers: this.createRegistry(brief),
        clock: this.clock,
        idFactory: this.idFactory,
        checkpoint: (run) => checkpoint(run as WorkflowRun<ProductionBrief>),
        shouldPause: () => this.consumePauseRequest(runId),
      });
      return runner.rerunFromNode(
        this.createWorkflow(brief),
        withExecutableBrief(previous, brief),
        "visual-review",
      );
    }, listener);
  }

  async resumePaused(runId: string): Promise<WorkflowRun<ProductionBrief>> {
    const dispatched = await this.dispatchResumePaused(runId);
    return dispatched.completion;
  }

  async dispatchResumePaused(
    runId: string,
    listener?: ProductionRunListener,
  ): Promise<DispatchedProductionRun> {
    await rm(this.pauseRequestPath(runId), { force: true });
    return this.dispatchPersistedTransition(runId, async (previous, checkpoint) => {
      const brief = parsePersistedBrief(previous.initialInput);
      const runner = new WorkflowRunner({
        providers: this.createRegistry(brief),
        clock: this.clock,
        idFactory: this.idFactory,
        checkpoint: (run) => checkpoint(run as WorkflowRun<ProductionBrief>),
        shouldPause: () => this.consumePauseRequest(runId),
      });
      return runner.resumePaused(this.createWorkflow(brief), withExecutableBrief(previous, brief));
    }, listener);
  }

  private async runPersistedTransition(
    runId: string,
    transition: (
      previous: WorkflowRun<ProductionBrief>,
      checkpoint: (run: WorkflowRun<ProductionBrief>) => Promise<void>,
    ) => Promise<WorkflowRun<ProductionBrief>>,
    allowedDocumentCommandId?: string,
    allowUnchanged = false,
  ): Promise<WorkflowRun<ProductionBrief>> {
    const lease = await this.acquireExecutionLease(runId);
    try {
      await this.assertExecutionLease(lease);
      const previous = await this.store.load<ProductionBrief>(runId);
      await assertNoPendingDocumentCommands(this.store.runDirectory(runId), allowedDocumentCommandId);
      let persisted = false;
      const checkpoint = async (run: WorkflowRun<ProductionBrief>) => {
        await this.assertExecutionLease(lease);
        if (!persisted) {
          await this.store.save(run, previous.revision);
          persisted = true;
          return;
        }
        await this.store.checkpoint(run);
      };
      const result = await transition(previous, checkpoint);
      if (!persisted && (allowedDocumentCommandId || allowUnchanged) && result === previous) return previous;
      if (!persisted) {
        await this.assertExecutionLease(lease);
        await this.store.save(result, previous.revision);
      }
      return result;
    } finally {
      await this.releaseExecutionLease(lease);
    }
  }

  private async dispatchPersistedTransition(
    runId: string,
    transition: (
      previous: WorkflowRun<ProductionBrief>,
      checkpoint: (run: WorkflowRun<ProductionBrief>) => Promise<void>,
      notifyPersisted: (run: WorkflowRun<ProductionBrief>) => Promise<void>,
    ) => Promise<WorkflowRun<ProductionBrief> | PersistedTransitionReplay>,
    listener?: ProductionRunListener,
    allowedDurationCommandId?: string,
  ): Promise<DispatchedProductionRun> {
    const lease = await this.acquireExecutionLease(runId, allowedDurationCommandId);
    let previous: WorkflowRun<ProductionBrief>;
    try {
      await this.assertExecutionLease(lease);
      previous = await this.store.load<ProductionBrief>(runId);
      await assertNoPendingDocumentCommands(this.store.runDirectory(runId));
    } catch (error) {
      await this.releaseExecutionLease(lease);
      throw error;
    }

    let persisted = false;
    let resolveCheckpoint!: () => void;
    let rejectCheckpoint!: (error: unknown) => void;
    const firstCheckpoint = new Promise<void>((resolve, reject) => {
      resolveCheckpoint = resolve;
      rejectCheckpoint = reject;
    });
    const checkpoint = async (run: WorkflowRun<ProductionBrief>) => {
      await this.assertExecutionLease(lease);
      await this.captureOptionalReviewDiagnostics(run);
      if (!persisted) {
        await this.store.save(run, previous.revision);
        persisted = true;
      } else {
        await this.store.checkpoint(run);
      }
      await notifyListener(listener, run);
      resolveCheckpoint();
    };
    // 本域事务可能自己完成CAS/图协调；只通知已耐久事实，不为通知再保存或增加revision。
    const notifyPersisted = async (run: WorkflowRun<ProductionBrief>) => {
      await this.assertExecutionLease(lease);
      await notifyListener(listener, run);
      resolveCheckpoint();
    };
    const completion = transition(previous, checkpoint, notifyPersisted).then(
      async (result) => {
        if (isPersistedTransitionReplay(result)) {
          resolveCheckpoint();
          await this.releaseExecutionLease(lease);
          return result.replay;
        }
        const run = result;
        if (!persisted) {
          await this.assertExecutionLease(lease);
          await this.captureOptionalReviewDiagnostics(run);
          await this.store.save(run, previous.revision);
          persisted = true;
          await notifyListener(listener, run);
          resolveCheckpoint();
        }
        await this.releaseExecutionLease(lease);
        return run;
      },
      async (error: unknown) => {
        await this.releaseExecutionLease(lease);
        rejectCheckpoint(error);
        throw error;
      },
    );
    void completion.catch(() => undefined);
    await firstCheckpoint;
    return { runId, completion };
  }

  private pauseRequestPath(runId: string): string {
    return path.join(this.runsRoot, runId, ".pause-request.json");
  }

  private async consumePauseRequest(runId: string): Promise<boolean> {
    const requestPath = this.pauseRequestPath(runId);
    try {
      await stat(requestPath);
      await rm(requestPath, { force: true });
      return true;
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return false;
      throw error;
    }
  }

  private createRegistry(
    brief: ProductionBrief,
    voiceManifestRecovery?: VoiceManifestRecovery,
    assetOperationRecoveryId?: string,
  ): ProviderRegistry {
    const registry = new ProviderRegistry();
    if (brief.providers.script === "codex-screenwriter-v1") {
      const screenwriterAgent = this.options.screenwriterAgent;
      if (!screenwriterAgent || screenwriterAgent.id !== brief.providers.script) {
        throw new Error(`Script provider '${brief.providers.script}' is not configured.`);
      }
      registry.register(new ScreenwriterProvider(
        screenwriterAgent,
        brief.models?.[brief.providers.script],
        modelSourceFor(brief, brief.providers.script),
      ));
    }
    if (brief.director) {
      const directorAgent = this.options.directorAgent;
      if (!directorAgent || directorAgent.id !== brief.providers.director) {
        throw new Error(`Director provider '${brief.providers.director}' is not configured.`);
      }
      registry.register(new VisualDirectorProvider(
        directorAgent,
        brief.models?.[brief.providers.director],
        modelSourceFor(brief, brief.providers.director),
      ));
    }
    if (brief.providers.visualReview) {
      const visualReviewAgent = [
        ...(this.options.visualReviewAgents ?? []),
        ...(this.options.visualReviewAgent ? [this.options.visualReviewAgent] : []),
      ].find((agent) => agent.id === brief.providers.visualReview);
      const metadata = this.options.providerRuntimeMetadata?.find((item) => item.id === brief.providers.visualReview);
      validateVisualReviewRuntimeMetadata(brief.providers.visualReview, metadata);
      registry.register(visualReviewAgent?.id === brief.providers.visualReview
        ? new VisualReviewProvider(visualReviewAgent, metadata)
        : new UnavailableVisualReviewProvider(brief.providers.visualReview, metadata));
    }
    for (const config of providerConfigs(brief, this.options)) {
      registry.register(new WorkerProvider(
        config,
        this.options.worker,
        this.runsRoot,
        config.nodeId === "voice" ? voiceManifestRecovery : undefined,
        (sourceRunId, action) => this.withRunMaintenanceLease([sourceRunId], action),
        config.nodeId === "assets" ? assetOperationRecoveryId : undefined,
      ));
    }
    return registry;
  }

  private createWorkflow(
    brief: ProductionBrief,
    options: {
      allowUnavailableProviders?: boolean;
      resumeCompletedTextTaskNodeId?: string;
      resumeCompletedTextTaskRequestId?: string;
      recoverTextTask?: { nodeId: string; workflowOperationRequestId: string };
      creativeReviewResume?: CreativeReviewResume;
    } = {},
  ): WorkflowDefinition {
    const resumeCompletedTextTaskNodeId = options.resumeCompletedTextTaskNodeId;
    const resumeCompletedTextTaskRequestId = options.resumeCompletedTextTaskRequestId;
    const withSourceRunSnapshot: SourceRunSnapshot = (sourceRunId, snapshot) => (
      this.withRunMaintenanceLease([sourceRunId], snapshot)
    );
    const assetReworkScenePositions = brief.rework
      ? reworkAffectedScenePositions({
        findings: brief.rework.findings,
        ...(brief.rework.previousScript ? { previousScenes: brief.rework.previousScript.scenes, previousCharacters: brief.rework.previousScript.characters } : {}),
        ...(brief.rework.previousDirectorPlan ? { previousShots: brief.rework.previousDirectorPlan.shots } : {}),
        // 工作流定义阶段脚本尚未生成：有 previousScript 时用它作 current 的保守下界（script 差异为 0），
        // 否则退回 previousDirectorPlan 的镜头位置作为有效镜头集合。
        ...(brief.rework.previousScript
          ? { currentScenes: brief.rework.previousScript.scenes, currentCharacters: brief.rework.previousScript.characters }
          : brief.rework.previousDirectorPlan
            ? { currentScenes: shotsAsScenePositions(brief.rework.previousDirectorPlan.shots) }
            : { currentScenes: [] }),
        ...(brief.rework.previousDirectorPlan ? { currentShots: brief.rework.previousDirectorPlan.shots } : {}),
        ...(brief.rework.affectedScenePositions !== undefined
          ? { affectedScenePositions: brief.rework.affectedScenePositions }
          : {}),
      })
      : [];
    const workerNode = (
      id: string,
      label: string,
      capability: Capability,
      providerId: string,
      dependsOn: string[],
      parentNodeIds: string[],
      getInput: (context: WorkflowContext) => Record<string, unknown>,
      role?: string,
      validateInputOverride?: (input: unknown) => Record<string, unknown>,
    ): NodeDefinition => ({
      id,
      label,
      ...(role ? { role } : {}),
      capability,
      providerId,
      mode: "automatic",
      dependsOn,
      getInput,
      execute: async (input, context) => {
        const provider = context.resolveProvider<Record<string, unknown>, WorkerResponse>({
          capability,
          providerId,
        });
        let workerResponse: WorkerResponse;
        try {
          workerResponse = await provider.run(input as Record<string, unknown>, context);
        } catch (error) {
          if (!isSourceReviewIncompleteError(error)) throw error;
          // 试片审查没跑出结论（复核服务故障）：没有任何裁决，不能判死制作，也不能给
          // 「放行」出口（跳过审查=未审查继续花钱）。转入暂停干预，人只能重试审查或终止。
          return {
            status: "needs_human" as const,
            error: error instanceof Error ? error.message : String(error),
            intervention: {
              kind: "source_review_retry" as const,
              reason: error instanceof Error ? error.message : String(error),
              requiredAction: "reject" as const,
              options: ["reject" as const],
            },
          };
        }
        const response = capability === "script.draft" && brief.seriesContext
          ? await validateSeriesWorkerScriptResponse(workerResponse)
          : workerResponse;
        const receipt = providerExecutionReceipt(provider, response);
        if (capability === "voice.synthesize") {
          receipt.parameters = effectiveVoiceReceiptParameters(input as Record<string, unknown>, receipt.parameters);
        }
        const sourceReview = response.sourceReview === undefined
          ? undefined
          : parseSourceReviewOutcome(response.sourceReview);
        if (sourceReview) {
          assertSourceReviewWorkerBinding({ capability, response, sourceReview, context });
          const result = await workerResponseToNodeResult(response, context, parentNodeIds);
          const reason = response.error?.message ?? "素材试片审查暂停。";
          const providerOutcomeKnown = result.providerOutcomeKnown === true;
          const canAcceptIncomplete = sourceReview.kind === "incomplete" && providerOutcomeKnown;
          return {
            status: "needs_human" as const,
            error: reason,
            output: { ...(response.output ?? {}), sourceReview },
            ...(result.artifacts ? { artifacts: result.artifacts } : {}),
            ...(result.providerOutcomeKnown !== undefined ? { providerOutcomeKnown: result.providerOutcomeKnown } : {}),
            intervention: sourceReview.kind === "complete_negative" ? {
              kind: "source_review_decision" as const,
              reason,
              requiredAction: "approve" as const,
              options: ["approve" as const, "request_changes" as const, "reject" as const],
            } : {
              kind: "source_review_retry" as const,
              reason,
              requiredAction: canAcceptIncomplete ? "approve" as const : "reject" as const,
              options: canAcceptIncomplete
                ? ["approve" as const, "reject" as const]
                : ["reject" as const],
              reviewStatus: canAcceptIncomplete ? "incomplete" as const : "unknown_or_unsafe" as const,
              providerOutcomeKnown,
              evidenceId: sourceReview.evidenceId,
            },
            receipt,
          };
        }
        const nodeResult = await workerResponseToNodeResult(response, context, parentNodeIds);
        if (capability === "voice.synthesize") {
          // §4.2.4：首次 fit 冲突的可恢复来源收据由宿主在正式登记 manifest 产物、
          // 取得真实 artifactId 后写不可变 receipt 并登记；恢复输出同时引用两件真实产物。
          await registerVoiceSourceReceiptArtifacts(nodeResult, context, parentNodeIds);
        }
        return {
          ...nodeResult,
          receipt,
        };
      },
      validateInputOverride: validateInputOverride ?? ((input) => requireOutputRecord(input, `${id} input`)),
      validateOverride: (output) => {
        if (id === "voice" && brief.audioMode === "native_av") throw new HumanDecisionConflictError("视频原声必须来自当前采用的视频，不能手工替换为TTS计划。请重新准备原声或关联返工。");
        return validateWorkerNodeOverride(id, output);
      },
    });

    const nodes: NodeDefinition[] = [
      {
        id: "brief",
        label: "Validate brief",
        role: "制片人",
        capability: "brief.validate",
        mode: "automatic",
        getInput: (context) => context.initialInput as ProductionBrief,
        execute: async (input, context) => {
          const validatedBrief = validateBriefInputOverride(input, brief);
          // 独立复核是建议性证据，不是状态：它挂在节点 checkpoint 上（界面据 node.agentLoopProgress
          // 显示建议），无论裁决是 pass 还是 repair，本节点照常 succeeded，暂停由边界闸门负责。
          if (boundaryGatesEnabled(brief)) await recordBriefAudit(this.options.briefAuditAgents, validatedBrief, context, this.runsRoot);
          return ({
          status: "succeeded",
          output: validatedBrief,
          artifacts: [jsonArtifact("production_brief", validatedBrief, "video-factory/brief-v1", "brief", [])],
          });
        },
        validateInputOverride: (input) => validateBriefInputOverride(input, brief),
        validateOverride: (output) => validateBriefInputOverride(output, brief),
      },
      ...(usesJointCreativePlanning(brief)
        // joint-v1 不创建外层 script/visual-direction/asset-candidates/asset-semantic-rank/
        // production-preflight：四段规划收敛为一个 creative-planning 节点。
        ? []
        : brief.providers.script === "codex-screenwriter-v1"
          ? [screenwriterNode(
              brief,
              this.options.screenwriterAgent,
              this.options,
              this.runsRoot,
              withSourceRunSnapshot,
              options.allowUnavailableProviders === true,
            )]
          : [workerNode(
              "script",
              "Draft script",
              "script.draft",
              brief.providers.script,
              ["brief"],
              ["brief"],
              (context) => ({ brief: currentEffectiveBriefFromContext(context, brief) }),
              "编剧",
            )]),
      ...(brief.workflowFeatures?.referenceGrammar ? [referenceGrammarNode(brief, this.options, this.runsRoot)] : []),
      ...(usesJointCreativePlanning(brief)
        ? [creativePlanningNode(
          brief,
          this.options,
          this.runsRoot,
          options.allowUnavailableProviders === true,
          resumeCompletedTextTaskNodeId,
          resumeCompletedTextTaskRequestId,
          options.recoverTextTask,
          options.creativeReviewResume,
        )]
        : [
            ...(brief.director ? [directorNode(brief, this.options, this.runsRoot, withSourceRunSnapshot)] : []),
            ...(brief.workflowFeatures?.assetSemanticRank ? [
              workerNode(
                "asset-candidates",
                "Discover asset candidates",
                "asset.search",
                "asset-candidate-search-v1",
                ["visual-direction"],
                ["script", "visual-direction"],
                (context) => ({
                  scriptPath: outputPath(context, "script", "scriptPath"),
                  directorPlanPath: outputPath(context, "visual-direction", "directorPlanPath"),
                }),
                "素材研究员",
              ),
              assetSemanticRankNode(brief, this.options, this.runsRoot),
            ] : []),
            ...(usesExecutablePlan(brief)
              ? [productionPreflightNode(brief, this.runsRoot)]
              : []),
          ]),
      workerNode(
        "assets",
        "Prepare assets",
        "asset.prepare",
        brief.providers.assets,
        [usesJointCreativePlanning(brief)
          ? "creative-planning"
          : usesExecutablePlan(brief)
            ? "production-preflight"
            : brief.workflowFeatures?.assetSemanticRank
              ? "asset-semantic-rank"
              : brief.director
                ? "visual-direction"
                : "script"],
        usesJointCreativePlanning(brief)
          ? ["creative-planning"]
          : usesExecutablePlan(brief)
            ? ["production-preflight"]
            : brief.workflowFeatures?.assetSemanticRank
              ? ["script", "visual-direction", "asset-candidates", "asset-semantic-rank"]
              : brief.director
                ? ["script", "visual-direction"]
                : ["script"],
        (context) => {
          // 唯一规划产物投影：joint/legacy 的路径选择收敛到 currentPlanningOutputPaths；
          // joint 的候选路径经 planningCandidatePaths 严格校验，legacy 保持可选字段兼容。
          const joint = usesJointCreativePlanning(brief);
          const planning = currentPlanningOutputPaths(context, brief);
          const candidates = !brief.workflowFeatures?.assetSemanticRank
            ? undefined
            : joint
              ? planningCandidatePaths(planning)
              : {
                ...(planning.candidateRankingPath ? { candidateRankingPath: planning.candidateRankingPath } : {}),
                ...(planning.candidateInventoryPath ? { candidateInventoryPath: planning.candidateInventoryPath } : {}),
              };
          return {
            scriptPath: planning.scriptPath,
            ...(planning.directorPlanPath !== undefined ? { directorPlanPath: planning.directorPlanPath } : {}),
            ...(planning.executablePlanPath !== undefined ? { executablePlanPath: planning.executablePlanPath } : {}),
            ...(candidates ?? {}),
            ...(brief.rework ? {
              rework: {
                sourceRunId: brief.rework.sourceRunId,
                sourceRunRevision: brief.rework.sourceRunRevision,
                nodeInstructions: brief.rework.nodeInstructions,
                // 素材节点只接收 visual-direction/assets 的 findings（与 reworkAffectedScenePositions
                // 内部对 visual findings 的同一过滤语义）；script-only finding 不透传给素材，
                // 其场景实际变化仍经 current/previous script 逐镜差异进入统一 affected 闭包。
                findings: brief.rework.findings.filter((finding) => finding.action !== "inspect_existing_media"
                  && finding.targetNodeIds.some((target) => target === "visual-direction" || target === "assets")),
                ...(assetReworkScenePositions.length || brief.rework.affectedScenePositions !== undefined
                  ? { affectedScenePositions: assetReworkScenePositions }
                  : {}),
                ...(brief.rework.previousScript ? { previousScript: brief.rework.previousScript } : {}),
                ...(brief.rework.previousDirectorPlan ? { previousDirectorPlan: brief.rework.previousDirectorPlan } : {}),
              },
            } : {}),
          };
        },
        "素材导演",
      ),
      ...(brief.providers.visualReview ? [sourceAssetVisualReviewNode(brief, this.runsRoot)] : []),
      workerNode(
        "voice",
        brief.audioMode === "native_av" ? "Prepare native audio" : "Synthesize voice",
        brief.audioMode === "native_av" ? "audio.prepare_native" : "voice.synthesize",
        brief.providers.voice,
        [usesJointCreativePlanning(brief) ? "creative-planning" : "script", brief.providers.visualReview ? "asset-source-review" : "assets"],
        usesJointCreativePlanning(brief)
          ? ["creative-planning", "assets"]
          : usesExecutablePlan(brief) ? ["production-preflight", "assets"] : ["script", "assets"],
        (context) => {
          const planning = currentPlanningOutputPaths(context, brief);
          if (brief.audioMode === "native_av") return { ...planning, audioMode: "native_av",
            assetPlanPath: outputPath(context, "assets", "assetPlanPath") };
          const voiceDirection = requireTtsVoiceDirection(brief);
          // 声音模式由用户确认的产物决定。上游显式改时长后沿新的父产物取重绑定方案，
          // 不因 inputState 失效而静默退回逐镜合成，也不借用其他历史脚本的方案。
          const parents = context.artifacts.filter((artifact) => artifact.kind === "script" && artifact.uri === planning.scriptPath
            || artifact.kind === "executable_plan" && artifact.uri === planning.executablePlanPath).map((artifact) => artifact.id);
          const confirmedPlans = context.artifacts.filter((artifact) => artifact.kind === "narration_plan"
            && artifact.provenance?.providerId === "creator-narration-plan-v1");
          const narration = (planning.executablePlanPath ? confirmedPlans.filter((artifact) =>
            parents.length === 2 && parents.every((id) => artifact.parentArtifactIds?.includes(id))).at(-1) : undefined)
            // 非界面恢复入口也不能丢掉已选声音模式；陈旧方案由执行前绑定校验拒绝，不会付费。
            ?? confirmedPlans.at(-1);
          return {
            scriptPath: planning.scriptPath,
            ...(planning.executablePlanPath !== undefined ? { executablePlanPath: planning.executablePlanPath } : {}),
            ...(narration?.uri ? { narrationPlanPath: narration.uri } : {}),
            voice: voiceDirection.profileId.slice(voiceDirection.profileId.indexOf(":") + 1),
            rate: voiceDirection.rate,
            pause_scale: voiceDirection.pauseScale,
            mastering_preset: voiceDirection.masteringPreset,
          };
        },
        "声音导演",
        brief.audioMode === "native_av" ? validateNativeVoiceNodeInput : validateVoiceNodeInput,
      ),
      workerNode(
        "render",
        "Render video",
        "video.render",
        brief.providers.render,
        ["assets", "voice"],
        usesJointCreativePlanning(brief)
          ? ["creative-planning", "assets", "voice"]
          : usesExecutablePlan(brief) ? ["production-preflight", "assets", "voice"] : ["script", "assets", "voice"],
        (context) => {
          const planning = currentPlanningOutputPaths(context, brief);
          return {
            scriptPath: planning.scriptPath,
            ...(planning.executablePlanPath !== undefined ? { executablePlanPath: planning.executablePlanPath } : {}),
            assetPlanPath: outputPath(context, "assets", "assetPlanPath"),
            ...(brief.audioMode === "native_av" ? { audioMode: "native_av", nativeAudioPlanPath: outputPath(context, "voice", "nativeAudioPlanPath") }
              : { voiceoverPlanPath: outputPath(context, "voice", "voiceoverPlanPath") }),
          };
        },
        "剪辑师",
      ),
      workerNode(
        "technical-review",
        "Technical review",
        "quality.review",
        brief.providers.technicalReview,
        ["render"],
        usesJointCreativePlanning(brief)
          ? ["creative-planning", "assets", "render"]
          : usesExecutablePlan(brief) ? ["production-preflight", "assets", "render"] : ["script", "assets", "render"],
        (context) => {
          const planning = currentPlanningOutputPaths(context, brief);
          return {
            videoPath: outputPath(context, "render", "videoPath"),
            assetPlanPath: outputPath(context, "assets", "assetPlanPath"),
            scriptPath: planning.scriptPath,
            ...(planning.executablePlanPath !== undefined ? { executablePlanPath: planning.executablePlanPath } : {}),
          };
        },
        "技术质检",
      ),
      ...(brief.providers.visualReview ? [visualReviewNode(brief, this.runsRoot)] : []),
      {
        id: "final-review",
        label: "Human final review",
        role: "总导演",
        capability: "quality.review.human",
        mode: brief.reviewMode === "manual" ? "manual" : "automatic",
        dependsOn: [brief.providers.visualReview ? "visual-review" : "technical-review"],
        getInput: (context) => ({
          review: context.outputs.get(brief.providers.visualReview ? "visual-review" : "technical-review"),
          canonFacts: outputStringArray(
            context.outputs.get(usesJointCreativePlanning(brief) ? "creative-planning" : "script"),
            "canonFacts",
          ),
        }),
        execute: async (input, context) => {
          const reviewedInput = validateFinalReviewInput(input, Boolean(brief.seriesContext));
          const optionalContinuation = isObjectRecord(reviewedInput.review)
            && reviewedInput.review.continuationScope === "rendered_video_optional_review";
          if (isUnconfiguredVisualFirstCut(brief) || optionalContinuation
            || brief.providers.visualReview && visualReviewScopeEvidenceId(reviewedInput.review) === null) {
            // T03 内部交付：机器审片未取得有效结论。终审必须停在用户面前——自动模式
            // 也不例外，没有可核对的审片结论时，放行只能由用户显式决定（不能静默跳过）。
            const proof = incompleteVisualDeliveryProof(reviewedInput.review);
            if (!proof && !isUnconfiguredVisualFirstCut(brief)) {
              throw new Error("Visual review delivery has neither a rendered-video evidence scope nor the host's no-valid-conclusion proof.");
            }
            const reviewArtifactIds = currentFinalReviewArtifactIds(context, brief, reviewedInput.review);
            const deliveryEvidence = await currentInternalDeliveryEvidence(
              await this.store.load(context.runId), brief, this.store.runDirectory(context.runId),
            );
            const deliveryEvidenceId = contentSha256(deliveryEvidence);
            return {
              status: "needs_human",
              output: { ...reviewedInput, reviewArtifactIds, deliveryEvidence, deliveryEvidenceId },
              intervention: {
                reason: isUnconfiguredVisualFirstCut(brief)
                  ? "本次没有配置或请求机器审片。成片可以播放；你可以明确接受未经机器复核的风险，完成内部定版。这不代表审片通过，也不会自动调用审片模型。"
                  : "机器审片未取得完整有效结论，已有视觉或声音意见仍保留。成片可以播放；你可以接受未复核风险并完成内部定版，或先补查原请求。这不代表审片通过。",
                requiredAction: "approve",
                options: ["approve", "request_changes", "reject"],
                artifactIds: reviewArtifactIds,
                reviewStatus: "incomplete",
                providerOutcomeKnown: optionalContinuation ? proof?.providerOutcomeKnown === true : true,
                evidenceId: deliveryEvidenceId,
                ...(optionalContinuation ? { continuationScope: "rendered_video_optional_review" as const } : {}),
              },
            };
          }
          const reviewArtifactIds = currentFinalReviewArtifactIds(context, brief, reviewedInput.review);
          const boundInput = {
            ...reviewedInput,
            reviewArtifactIds,
            ...(brief.providers.visualReview ? {
              reviewEvidenceId: finalVisualReviewScope(reviewedInput.review).evidenceId,
            } : {}),
          };
          if (brief.reviewMode === "automatic") {
            const recommendation = visualReviewRecommendation(reviewedInput.review);
            if (recommendation === "reject" || recommendation === "revise") {
              return {
                status: "needs_human",
                output: boundInput,
                intervention: {
                  reason: recommendation === "reject"
                    ? "视觉审片判定存在阻断问题，请人工确认后再继续。"
                    : "视觉审片建议修改，请人工确认是否继续。",
                  requiredAction: "approve",
                  options: ["approve", "request_changes", "reject"],
                  artifactIds: reviewArtifactIds,
                },
              };
            }
            return { status: "succeeded", output: boundInput };
          }
          return {
            status: "needs_human",
            output: boundInput,
            intervention: {
              reason: "请完整观看成片，检查画面、字幕、旁白、事实和素材授权。",
              requiredAction: "approve",
              options: ["approve", "request_changes", "reject"],
              artifactIds: reviewArtifactIds,
            },
          };
        },
        validateInputOverride: (input) => validateFinalReviewInput(input, Boolean(brief.seriesContext)),
        validateOverride: (output) => validateFinalReviewInput(output, Boolean(brief.seriesContext)),
      },
      {
        id: "publish-package",
        label: "发布文案与发布包",
        role: "发行编辑",
        capability: "publish.package",
        mode: "automatic",
        dependsOn: ["final-review"],
        getInput: (context) => {
          const currentBrief = currentEffectiveBriefFromContext(context, brief);
          return {
            scriptPath: outputPath(
              context,
              usesJointCreativePlanning(brief) ? "creative-planning" : "script",
              "scriptPath",
            ),
            brief: {
              title: currentBrief.title,
              angle: currentBrief.angle,
              audience: currentBrief.audience,
              nicheSlug: currentBrief.nicheSlug,
              platform: currentBrief.platform,
            },
          };
        },
        validateInputOverride: (input) => validatePublishPackageInput(input),
        execute: async (input, context) => {
          const packageInput = validatePublishPackageInput(input);
          const currentBrief = currentEffectiveBriefFromContext(context, brief);
          const publishBrief: ProductionBrief = { ...currentBrief, ...packageInput.brief };
          assertPublishEvidenceReady(context, publishBrief, this.options);
          const currentArtifacts = await currentArtifactsForPackaging(context, currentBrief);
          await verifyStoredArtifacts(currentArtifacts);
          const finalReviewOutput = requireOutputRecord(context.outputs.get("final-review"), "final-review output");
          if (isObjectRecord(finalReviewOutput.deliveryEvidence)) {
            const currentEvidence = await currentInternalDeliveryEvidence(
              await this.store.load(context.runId), currentBrief, this.store.runDirectory(context.runId),
            );
            assertInternalDeliveryEvidenceSnapshot(finalReviewOutput, currentEvidence);
          }
          const artifactIds = currentArtifacts.map((artifact) => artifact.id);
          const scriptParentIds = currentArtifacts
            .filter((artifact) => artifact.producer?.nodeId === (usesJointCreativePlanning(brief) ? "creative-planning" : "script"))
            .map((artifact) => artifact.id);
          const publishAttempt = await reserveAttemptDirectory(path.join(this.runsRoot, context.runId, "publish"));
          let copyOutcome: PublishCopyOutcome;
          try {
            copyOutcome = await generatePublishCopy({
              writer: this.options.publishCopyWriter,
              brief: publishBrief,
              scriptPath: packageInput.scriptPath,
              checkpoint: nodeAgentLoopCheckpoint(
                this.runsRoot,
                context.runId,
                "publish-package",
                { brief: publishBrief, scriptPath: packageInput.scriptPath },
                PUBLISH_COPY_AGENT_CONTRACT_VERSION,
                undefined,
                context.operationRequestId,
              ),
            });
          } catch (error) {
            if (!(error instanceof RoleAgentLoopError) || !this.options.publishCopyWriter) throw error;
            return failedAgentLoopNodeResult({
              error,
              attemptDirectory: publishAttempt.directory,
              nodeId: "publish-package",
              attempt: publishAttempt.attempt,
              parentArtifactIds: scriptParentIds,
              provider: {
                id: this.options.publishCopyWriter.id,
                modelId: this.options.publishCopyWriter.id,
                transport: "unix_socket",
                billing: "subscription",
                configurationSource: "system_default",
                parameters: { promptPack: "video-factory/publish-editor-v4" },
              },
              providerLabel: "Codex 发行编辑",
            });
          }
          const copyArtifacts: ArtifactDraft[] = [];
          if (copyOutcome.writerId !== undefined) {
            const copyPath = path.join(publishAttempt.directory, "publish_copy.json");
            const copyContent = `${JSON.stringify(copyOutcome.copy, null, 2)}\n`;
            await writeTextAtomically(copyPath, copyContent);
            copyArtifacts.push(fileArtifact(
              "publish_copy",
              copyPath,
              copyContent,
              "application/json",
              "video-factory/publish-copy-v1",
              "publish-package",
              scriptParentIds,
              copyOutcome.writerId,
              "AI-generated platform copy; review before upload.",
              publishAttempt.attempt,
            ));
          }
          const copyTraceArtifact = await persistModelTrace({
            trace: copyOutcome.trace,
            attemptDirectory: publishAttempt.directory,
            nodeId: "publish-package",
            attempt: publishAttempt.attempt,
            parentArtifactIds: scriptParentIds,
          });
          if (copyTraceArtifact) copyArtifacts.push(copyTraceArtifact);
          const copyLoopArtifact = await persistAgentLoopTrace({
            loop: copyOutcome.agentLoop,
            attemptDirectory: publishAttempt.directory,
            nodeId: "publish-package",
            attempt: publishAttempt.attempt,
            parentArtifactIds: scriptParentIds,
          });
          if (copyLoopArtifact) copyArtifacts.push(copyLoopArtifact);
          const resourceManifestPath = path.join(publishAttempt.directory, "resource_manifest.json");
          const privateReferenceArtifacts = context.artifacts.filter((artifact) => artifact.kind === "reference_video");
          const manifestArtifacts = [...currentArtifacts, ...privateReferenceArtifacts];
          const resourceManifest = await buildResourceManifest(context.runId, manifestArtifacts);
          const resourceManifestContent = `${JSON.stringify(resourceManifest, null, 2)}\n`;
          await writeTextAtomically(resourceManifestPath, resourceManifestContent);
          const resourceManifestArtifact = fileArtifact(
            "resource_manifest",
            resourceManifestPath,
            resourceManifestContent,
            "application/json",
            "video-factory/resource-manifest-v1",
            "publish-package",
            manifestArtifacts.map((artifact) => artifact.id),
            "video-factory-ts-v1",
            "Traceable resource inventory; unknown rights remain explicitly marked for review.",
            publishAttempt.attempt,
          );
          const packagePath = path.join(publishAttempt.directory, "publish_package.json");
          const persistedApproval = currentPublishApproval(context);
          // 内部交付事实：机器复核无结论时，包内必须如实记录，不得写成机器通过。
          const internalDeliveryFacts = isObjectRecord(finalReviewOutput.deliveryEvidence)
            || visualReviewScopeEvidenceId(context.outputs.get("visual-review")) === null
            ? (() => {
              const finalReviewOutput = requireOutputRecord(context.outputs.get("final-review"), "final-review output");
              return {
                machineVisualReview: isUnconfiguredVisualFirstCut(publishBrief) ? "not_requested" as const
                  : visualReviewScopeEvidenceId(context.outputs.get("visual-review")) !== null ? "completed" as const : "incomplete" as const,
                acceptedUnreviewedRisks: isObjectRecord(finalReviewOutput.deliveryEvidence)
                  ? finalReviewOutput.deliveryEvidence.risks : ["visual_review_without_valid_conclusion"],
                ...(typeof finalReviewOutput.deliveryEvidenceId === "string" ? { deliveryEvidenceId: finalReviewOutput.deliveryEvidenceId } : {}),
                ...(isObjectRecord(finalReviewOutput.deliveryEvidence) ? { evidence: finalReviewOutput.deliveryEvidence } : {}),
              };
            })()
            : undefined;
          const payload = {
            version: "video-factory/publish-package-v1",
            runId: context.runId,
            platform: publishBrief.platform,
            title: copyOutcome.copy.title,
            copy: {
              source: copyOutcome.source,
              title: copyOutcome.copy.title,
              description: copyOutcome.copy.description,
              hashtags: copyOutcome.copy.hashtags,
              ...(copyOutcome.fallbackReason !== undefined ? { fallbackReason: copyOutcome.fallbackReason } : {}),
            },
            approval: persistedApproval
              ? {
                  status: "approved",
                  actor: persistedApproval.actor,
                  note: persistedApproval.note ?? "",
                  action: persistedApproval.action,
                  interventionId: persistedApproval.interventionId,
                  ...("id" in persistedApproval && typeof persistedApproval.id === "string"
                    ? { decisionId: persistedApproval.id }
                    : {}),
                  ...(persistedApproval.reviewEvidenceId ? { reviewEvidenceId: persistedApproval.reviewEvidenceId } : {}),
                  reviewArtifactIds: finalReviewArtifactIdsFromOutput(context.outputs.get("final-review")),
                }
              : {
                  status: "approved",
                  actor: "automatic-review",
                  note: "",
                  action: "approve",
                  reviewArtifactIds: finalReviewArtifactIdsFromOutput(context.outputs.get("final-review")),
                },
            aigc: {
              disclosureRequired: true,
              explicitLabelChecked: true,
              explicitLabelText: "AI 辅助创作",
              implicitMetadataWritten: true,
              platformDeclarationRequired: true,
              humanReviewRequiredBeforeUpload: true,
            },
            resourceManifest: {
              version: resourceManifest.version,
              itemCount: resourceManifest.items.length,
              needsReviewCount: resourceManifest.items.filter((item) => (
                requiresRightsReviewCategory(item.category) && item.reviewStatus === "needs_review"
              )).length,
            },
            ...(internalDeliveryFacts ? { internalDelivery: internalDeliveryFacts } : {}),
            artifacts: currentArtifacts.map(publishArtifactDescriptor),
          };
          const packageContent = `${JSON.stringify(payload, null, 2)}\n`;
          await writeTextAtomically(packagePath, packageContent);
          return {
            status: "succeeded",
            output: { publishPackagePath: packagePath, resourceManifestPath, contentReview: contentReviewForCreator(copyOutcome.agentLoop) },
            receipt: copyOutcome.trace
              ? {
                  ...modelTraceReceipt(copyOutcome.trace, "Codex 发行编辑", "subscription", copyOutcome.agentLoop),
                  ...(copyOutcome.fallbackReason ? { fallbackReason: copyOutcome.fallbackReason } : {}),
                }
              : {
                  providerId: "video-factory-publish-package-v1",
                  providerLabel: "本地发布包",
                  modelId: "deterministic-copy-fallback-v1",
                  transport: "local_process",
                  billing: "free",
                  configurationSource: "system_default",
                  parameters: { copySource: copyOutcome.source },
                },
            artifacts: [
              fileArtifact(
                "publish_package",
                packagePath,
                packageContent,
                "application/json",
                "video-factory/publish-package-v1",
                "publish-package",
                artifactIds,
                "video-factory-ts-v1",
                "Generated publish package; platform upload remains a manual action.",
                publishAttempt.attempt,
              ),
              resourceManifestArtifact,
              ...copyArtifacts,
            ],
          };
        },
        validateOverride: (output) => {
          const value = validatePathOutput(output, "publishPackagePath", "publish-package");
          return value.resourceManifestPath === undefined
            ? value
            : { ...value, resourceManifestPath: requiredOutputString(value, "resourceManifestPath") };
        },
      },
    ];

    return {
      id: "daily-production",
      name: "Daily short-video production",
      version: productionWorkflowVersion(brief),
      nodes: boundaryGatesEnabled(brief) ? nodes.map(withBoundaryGate) : nodes,
    };
  }
}

// 边界闸门：节点照常执行，执行成功后不直接放行，而是把控制权交回用户，等他按下"进入下一步"。
// 停点只由一个不带 kind 的 needs_human 表达——带 kind 会落到 creative_review 那类专门路径，
// 而这里要的是通用路径：批准即把本节点标 succeeded、产物与回执原样保留、不重跑本节点。
// 自己就返回 needs_human 的节点（final-review 等）原样放过，不二次包裹。
export function withBoundaryGate(node: NodeDefinition): NodeDefinition {
  const execute = node.execute;
  if (!execute) return node;
  return {
    ...node,
    execute: async (input, context) => {
      // qualityGates 只在"执行成功"之后评估（workflow-runner 的 evaluateQualityGates），而边界包装
      // 会把成功整个换成人工停点——两者叠加会让一个不可绕过的约束在没人看见的地方消失，而停点上
      // 还摆着一个"批准"按钮。今天没有任何节点声明 qualityGates，所以这条路走不到；真到了那一天，
      // 需要先决定这些约束与人工停点的先后，而不是在这里静默降级。
      if (node.qualityGates?.length) {
        throw new Error(`节点 '${node.id}' 声明了 qualityGates，边界闸门无法在保留这些约束的前提下停下：请先决定约束与人工停点的先后，再启用边界闸门。`);
      }
      const result = await execute(input, context);
      // 成功臂的 status 是可选的，undefined 与 "succeeded" 同义，两者都要拦下来。
      if (result.status !== undefined && result.status !== "succeeded") return result;
      return {
        ...result,
        status: "needs_human",
        intervention: {
          boundary: "node-complete",
          // 终审的自动通过分支返回 succeeded + boundInput，里面带着 reviewArtifactIds；
          // 边界包装必须原样透传，否则终审批准时的 artifact 绑定校验会把正确批准也拦下（EB-04）。
          ...(node.id === "final-review"
            && isObjectRecord(result.output)
            && Array.isArray((result.output as Record<string, unknown>).reviewArtifactIds)
            ? { artifactIds: finalReviewArtifactIdsFromOutput(result.output) }
            : {}),
          // 刻意不拼 node.label：它是内部的英文标识（"Validate brief"），拼进来就成了
          // 「Validate brief已完成」这种半截中英混排。步骤名由界面按 nodeId 用它自己的中文表渲染。
          reason: "这一步已完成，等你确认后进入下一步。",
          requiredAction: "approve",
          options: ["approve", "reject"],
        },
      };
    },
  };
}

function boundaryGatesEnabled(brief: Pick<ProductionBrief, "workflowFeatures">): boolean {
  return brief.workflowFeatures?.boundaryGates === "user-confirmed-v1";
}

function currentPublishApproval(context: WorkflowContext): WorkflowContext["decisions"][number] | undefined {
  const finalReview = isObjectRecord(context.outputs.get("final-review"))
    ? context.outputs.get("final-review") as Record<string, unknown>
    : undefined;
  const intervention = [...context.interventions].reverse().find(item => item.nodeId === "final-review");
  if (!finalReview || !intervention) return undefined;
  // 只有当前保留的终审停点能签成片，不能用同证据的审片/文案批准顶替。
  const evidenceId = finalReview.reviewEvidenceId;
  const deliveryEvidenceId = finalReview.deliveryEvidenceId;
  if (("reviewEvidenceId" in finalReview && (typeof evidenceId !== "string" || !/^[a-f0-9]{64}$/.test(evidenceId)))
    || ("deliveryEvidenceId" in finalReview && (typeof deliveryEvidenceId !== "string" || !/^[a-f0-9]{64}$/.test(deliveryEvidenceId)))) return undefined;
  return [...context.decisions].reverse().find((decision) => (
    decision.action === "approve"
    && decision.interventionId === intervention.id
    && (deliveryEvidenceId !== undefined ? decision.reviewEvidenceId === deliveryEvidenceId && decision.acceptIncomplete === true
      : evidenceId !== undefined ? decision.reviewEvidenceId === evidenceId
      : decision.reviewEvidenceId == null)
  ));
}

function prepareLocalRelayoutApprovalRun(
  run: WorkflowRun<ProductionBrief>,
  definition: WorkflowDefinition,
): WorkflowRun<ProductionBrief> {
  const prepared = structuredClone(run);
  const descendants = new Set<string>();
  const queue = ["voice"];
  while (queue.length) {
    const parent = queue.shift()!;
    for (const node of definition.nodes) {
      if (!node.dependsOn?.includes(parent) || descendants.has(node.id)) continue;
      descendants.add(node.id);
      queue.push(node.id);
    }
  }
  for (const node of prepared.nodeRuns) {
    if (!descendants.has(node.nodeId) || node.status !== "stale") continue;
    if (node.outcomeUncertain) {
      throw new HumanDecisionConflictError(
        `声音调整后的步骤 '${node.nodeId}' 仍有未核实的付费结果，不能直接重跑。`,
      );
    }
    node.status = "pending";
    node.artifactIds = [];
    node.qualityGateResults = [];
    delete node.output;
    delete node.finishedAt;
    delete node.error;
    delete node.errorCode;
    delete node.intervention;
    delete node.executionReceipt;
    delete node.spendPlan;
    delete node.spendAuthorizationId;
    delete node.operationRequestId;
    delete node.interrupted;
  }
  prepared.interventions = prepared.interventions.filter((intervention) => !descendants.has(intervention.nodeId));
  return prepared;
}

// 节点当前有效输出：与 UI 的解析语义一致，先取 outputState 的有效版本，再回落 raw output。
function effectiveNodeOutput(node: WorkflowRun<ProductionBrief>["nodeRuns"][number]): Record<string, unknown> | null {
  const output = node.outputState?.versions.find(
    (version) => version.id === node.outputState?.effectiveVersionId,
  )?.output ?? node.output;
  return isObjectRecord(output) ? output : null;
}

function finalReviewEvidenceId(node: WorkflowRun<ProductionBrief>["nodeRuns"][number]): string | null {
  if (node.nodeId !== "final-review") return null;
  const output = effectiveNodeOutput(node);
  if (!output) return null;
  // 完整机器复核绑定成片证据摘要；内部交付绑定宿主无结论快照 ID。二者只能有一个。
  for (const field of ["reviewEvidenceId", "deliveryEvidenceId"] as const) {
    const value = output[field];
    if (typeof value === "string" && /^[a-f0-9]{64}$/.test(value)) return value;
  }
  return null;
}

function sourceReviewEvidenceId(node: WorkflowRun<ProductionBrief>["nodeRuns"][number]): string | null {
  if (!node.intervention) return null;
  const output = effectiveNodeOutput(node);
  if (!output) return null;
  const sourceReview = output.sourceReview;
  if (!isObjectRecord(sourceReview)
    || (sourceReview.kind !== "complete_negative" && sourceReview.kind !== "incomplete")) return null;
  const evidenceId = sourceReview.evidenceId;
  return typeof evidenceId === "string" && /^[a-f0-9]{64}$/.test(evidenceId) ? evidenceId : null;
}

// 视觉审片证据只认成片域（rendered_video）的当前有效报告范围：与 UI 的解析、
// 补查接口（dispatchVisualReinspection）读取的是同一份交付。
function visualReviewScopeEvidenceId(delivery: unknown): string | null {
  if (!isObjectRecord(delivery)) return null;
  const report = delivery.report;
  if (!isObjectRecord(report)) return null;
  const scope = report.reviewScope;
  // 只认成片域证据：source_assets 阶段的试片报告不属于 rendered 停点的绑定对象。
  if (!isObjectRecord(scope) || scope.reviewStage !== "rendered_video") return null;
  const evidenceId = scope.evidenceId;
  return typeof evidenceId === "string" && /^[a-f0-9]{64}$/.test(evidenceId) ? evidenceId : null;
}

/**
 * Worker 的 sourceReview 不是浏览器提交的建议，而是会影响「继续未完成素材」的服务端证据。
 * 即使 worker 协议已经校验字段形状，也要在编排边界确认它确实对应本次操作内已校验的媒体和
 * 报告；否则一个无关响应也可能获得质量承担出口。
 */
function assertSourceReviewWorkerBinding(options: {
  capability: Capability;
  response: WorkerResponse;
  sourceReview: NonNullable<WorkerResponse["sourceReview"]>;
  context: WorkflowContext;
}): void {
  const { capability, response, sourceReview, context } = options;
  if (capability !== "asset.prepare") {
    throw new Error("Only asset preparation may return a source review outcome.");
  }
  if (!context.operationRequestId || sourceReview.operationId !== context.operationRequestId) {
    throw new Error("Source review outcome is not bound to the current asset operation.");
  }
  const hasArtifact = (kind: string, sha256: string) => response.artifacts.some((artifact) => (
    artifact.kind === kind
    && artifact.sha256.toLowerCase() === sha256
    && artifact.provenance.scenePosition === sourceReview.scenePosition
  ));
  if (!hasArtifact("media_asset", sourceReview.mediaSha256)) {
    throw new Error("Source review outcome is missing its materialized pilot media artifact.");
  }
  if (sourceReview.kind === "incomplete") {
    if (response.status !== "failed") {
      throw new Error("An incomplete source review must keep the asset operation failed for dedicated retry.");
    }
    const expectedEvidenceId = createHash("sha256").update(JSON.stringify({
      version: "video-factory/source-pilot-incomplete-v1",
      kind: "incomplete",
      mediaSha256: sourceReview.mediaSha256,
      inputFingerprint: sourceReview.inputFingerprint,
      operationId: sourceReview.operationId,
      scenePosition: sourceReview.scenePosition,
    })).digest("hex");
    if (sourceReview.evidenceId !== expectedEvidenceId) {
      throw new Error("Incomplete source review evidence does not match its materialized pilot media and operation.");
    }
    return;
  }
  if (response.status !== "rejected") {
    throw new Error("A complete negative source review must keep the asset operation rejected pending a user decision.");
  }
  if (!sourceReview.reviewArtifactSha256 || !sourceReview.evidenceId
    || !hasArtifact("review_report", sourceReview.reviewArtifactSha256)) {
    throw new Error("Complete negative source review is missing its materialized report artifact.");
  }
  const report = response.output?.sourceVisualReview;
  if (!isObjectRecord(report)) {
    throw new Error("Complete negative source review is missing its report payload.");
  }
  const expectedEvidenceId = createHash("sha256").update(JSON.stringify({
    version: "video-factory/source-pilot-evidence-v1",
    report,
    reviewArtifactSha256: sourceReview.reviewArtifactSha256,
    mediaSha256: sourceReview.mediaSha256,
    inputFingerprint: sourceReview.inputFingerprint,
    operationId: sourceReview.operationId,
    scenePosition: sourceReview.scenePosition,
  })).digest("hex");
  if (sourceReview.evidenceId !== expectedEvidenceId) {
    throw new Error("Complete negative source review evidence does not match its materialized report and pilot media.");
  }
}

/**
 * 规划节点回执里记着的那一条独立复核的编号。规划状态整份落在节点输出里，所以"他看到的是哪一条"
 * 在命令边界上就能查到，不必等到图里才知道。
 */
function recordedCreativeCheckIdentity(
  node: WorkflowRun<ProductionBrief>["nodeRuns"][number],
  stage: string,
): string | undefined {
  if (!isObjectRecord(node.output) || !isObjectRecord(node.output.creativeReview)) return undefined;
  const stages = node.output.creativeReview.stages;
  if (!isObjectRecord(stages) || !isObjectRecord(stages[stage])) return undefined;
  const checkResult = stages[stage].checkResult;
  if (!isObjectRecord(checkResult) || typeof checkResult.checkIdentity !== "string") return undefined;
  return checkResult.checkIdentity;
}

function scriptReworkGlobalIntent(document: unknown) {
  if (!isObjectRecord(document)) return undefined;
  return { viewerPromise: document.viewerPromise ?? null, narrativeArc: document.narrativeArc ?? null,
    canonFacts: document.canonFacts ?? [] };
}

function creativeReviewOperationDetail(run: WorkflowRun<ProductionBrief>, resume: CreativeReviewResume): { detail?: string } {
  const planning = run.nodeRuns.find(node => node.nodeId === "creative-planning");
  const review = isObjectRecord(planning?.output) ? planning.output.creativeReview as CreativeReviewState | undefined : undefined;
  const continuation = review?.stages[resume.stage]?.continuation;
  // 待核原因仍随原请求查询；只冻结已结清诊断，避免成功恢复后残留旧 unknown 提示。
  return continuation?.commandId === resume.commandId && continuation.status !== "unknown" ? { detail: continuation.detail } : {};
}

/**
 * F03（2026-10-02 执行包）：审计命令状态与 run 状态分开。needs_human 不等于原审计
 * operation 已完成——audit_current 落在续接诊断 status:"unknown" 时，原请求仍未核清，
 * 回执必须保持 unknown（可查询、不可宣称 completed）；已核清失败按原操作事实投影。
 * DG-UX-04（2026-10-03 执行包）：discuss/revise 同理——咨询失败让主 run 回到人工停点后，
 * 回执必须按该命令的续接诊断落 failed / not_accepted / unknown，不能被默认 completed 覆盖。
 */
function creativeReviewOperationStatus(
  run: WorkflowRun<ProductionBrief>,
  resume: CreativeReviewResume,
): "completed" | "failed" | "not_accepted" | "unknown" {
  if (run.status === "failed") return "failed";
  if (resume.action === "discuss" || resume.action === "revise") {
    const outcome = creativeConsultationOutcome(run, resume);
    if (outcome !== undefined) return outcome;
    // C1：原请求完成但结果被迟到隔离（未应用到当前稿）——命令事实是 completed，
    // 结果处置单独投影，不能让 completed 冒称当前稿已修改。
    const disposition = creativeConsultationResultDisposition(run, resume);
    if (disposition === "recorded_not_applied") return "completed";
  }
  if (resume.action === "audit_current") {
    const planning = run.nodeRuns.find((node) => node.nodeId === "creative-planning");
    const review = isObjectRecord(planning?.output) && isObjectRecord(planning.output.creativeReview)
      ? planning.output.creativeReview : undefined;
    const stages = review && isObjectRecord(review.stages) ? review.stages : undefined;
    const current = stages ? stages[resume.stage] : undefined;
    const diagnostic = isObjectRecord(current) && isObjectRecord(current.continuation) ? current.continuation : undefined;
    if (diagnostic?.commandId === resume.commandId) {
      if (diagnostic.reasonCode === "audit_not_accepted") return "not_accepted";
      if (diagnostic.reasonCode === "audit_provider_failed") return "failed";
    }
    for (const stage of ["treatment", "script", "director"]) {
      const stageState = stages ? stages[stage] : undefined;
      const continuation = isObjectRecord(stageState) && isObjectRecord(stageState.continuation)
        ? stageState.continuation : undefined;
      if (continuation?.status === "unknown") return "unknown";
    }
  }
  return "completed";
}

/** C1：原命令结果是否被迟到隔离（未应用到当前稿）。 */
function creativeConsultationResultDisposition(
  run: WorkflowRun<ProductionBrief>,
  resume: CreativeReviewResume & { action: "discuss" | "revise"; commandId: string },
): "applied" | "recorded_not_applied" | undefined {
  const planning = run.nodeRuns.find((node) => node.nodeId === "creative-planning");
  const review = isObjectRecord(planning?.output) && isObjectRecord(planning.output.creativeReview)
    ? planning.output.creativeReview : undefined;
  const stages = review && isObjectRecord(review.stages) ? review.stages : undefined;
  const stageState = stages ? stages[resume.stage] : undefined;
  const continuation = isObjectRecord(stageState) && isObjectRecord(stageState.continuation)
    ? stageState.continuation : undefined;
  if (!continuation || continuation.commandId !== resume.commandId) return undefined;
  if (continuation.status === "completed_not_applied") return "recorded_not_applied";
  return undefined;
}

/** discuss/revise 的续接诊断 → 命令回执状态；诊断不属于这条命令时返回 undefined。 */
function creativeConsultationOutcome(
  run: WorkflowRun<ProductionBrief>,
  resume: CreativeReviewResume & { action: "discuss" | "revise"; commandId: string },
): "failed" | "not_accepted" | "unknown" | undefined {
  const planning = run.nodeRuns.find((node) => node.nodeId === "creative-planning");
  const review = isObjectRecord(planning?.output) && isObjectRecord(planning.output.creativeReview)
    ? planning.output.creativeReview : undefined;
  const stages = review && isObjectRecord(review.stages) ? review.stages : undefined;
  const stageState = stages ? stages[resume.stage] : undefined;
  const continuation = isObjectRecord(stageState) && isObjectRecord(stageState.continuation)
    ? stageState.continuation : undefined;
  if (!continuation || continuation.commandId !== resume.commandId) return undefined;
  if (continuation.status === "unknown") return "unknown";
  if (continuation.status === "rejected_operation") return "not_accepted";
  if (continuation.status === "error") return "failed";
  return undefined;
}

function recoverableCreativeReviewCommand(run: WorkflowRun<ProductionBrief>, nodeId: string) {
  if (nodeId !== "creative-planning") return undefined;
  const node = run.nodeRuns.find((candidate) => candidate.nodeId === nodeId);
  const metadata = isObjectRecord(node?.output) ? node.output.continuationOperation : undefined;
  if (!isObjectRecord(metadata)) return undefined;
  const operation = run.creativeReviewOperations?.find((candidate) => candidate.commandId === metadata.commandId);
  if (!operation || operation.status === "completed" || operation.resume === undefined
    || operation.requestDigest !== metadata.requestDigest || operation.action !== metadata.action) {
    throw new Error("Creative review recovery cannot match the original command receipt.");
  }
  const resume = parseCreativeReviewResume(operation.resume);
  if (resume.commandId !== operation.commandId || resume.action !== operation.action || resume.stage !== operation.stage) {
    throw new Error("Creative review recovery has inconsistent command evidence.");
  }
  return { commandId: operation.commandId, resume };
}

function currentCreativeCheck(
  node: WorkflowRun<ProductionBrief>["nodeRuns"][number],
  stage: string,
  draftSha256: string,
): Record<string, unknown> | undefined {
  if (!isObjectRecord(node.output) || !isObjectRecord(node.output.creativeReview)) return undefined;
  const stages = node.output.creativeReview.stages;
  if (!isObjectRecord(stages) || !isObjectRecord(stages[stage])) return undefined;
  const stageState = stages[stage];
  const check = stageState.checkResult;
  const draft = stageState.currentDraft;
  if (!isObjectRecord(check) || !isObjectRecord(draft)) return undefined;
  if (check.draftSha256 !== draftSha256 || draft.sha256 !== draftSha256) return undefined;
  if (typeof check.versionId === "string" && check.versionId !== draft.versionId) return undefined;
  return check;
}

function currentVisualReviewDelivery(run: WorkflowRun<ProductionBrief>): unknown {
  const node = run.nodeRuns.find((candidate) => candidate.nodeId === "visual-review");
  return node?.outputState?.versions.find((version) => version.id === node.outputState?.effectiveVersionId)?.output ?? node?.output;
}

class WorkerProvider implements Provider<Record<string, unknown>, WorkerResponse> {
  readonly id: string;
  readonly capability: Capability;

  constructor(
    private readonly config: ProviderConfig,
    private readonly worker: WorkerClient,
    private readonly runsRoot: string,
    private readonly voiceManifestRecovery?: VoiceManifestRecovery,
    private readonly withSourceRunSnapshot?: SourceRunSnapshot,
    private readonly assetOperationRecoveryId?: string,
  ) {
    this.id = config.id;
    this.capability = config.capability;
  }

  get label(): string { return this.config.metadata?.label ?? this.id; }
  get modelId(): string { return this.config.metadata?.modelId ?? this.id; }
  get transport(): ProductionProviderRuntimeMetadata["transport"] { return this.config.metadata?.transport ?? "local_process"; }
  get billing(): ProductionProviderRuntimeMetadata["billing"] { return this.config.metadata?.billing ?? "local_compute"; }
  get approvalPolicy(): ApprovalPolicy { return this.config.metadata?.approvalPolicy ?? (this.billing === "metered" ? "manual" : "none"); }
  get configurationSource(): ExecutionConfigurationSource { return this.config.configurationSource; }
  get parameters(): Record<string, ExecutionParameterValue> { return receiptParameters(this.config.parameters); }
  get estimatedCostCny(): number { return this.config.metadata?.estimatedCostCny ?? 0; }
  get maxCostCny(): number {
    if (this.config.metadata?.billing !== "metered") return 0;
    const configuredLimit = this.config.parameters.maxCostCny;
    if (typeof configuredLimit === "number" && Number.isFinite(configuredLimit) && configuredLimit > 0) {
      return configuredLimit;
    }
    return roundCurrency((this.config.metadata.estimatedCostCny ?? 0) * this.maxAttempts);
  }
  get maxAttempts(): number {
    return this.config.metadata?.billing === "metered" && typeof this.config.metadata.maxAttempts === "number"
      ? this.config.metadata.maxAttempts
      : 1;
  }

  /**
   * 花费报价前先问执行器：这次还会不会真的向 provider 买新素材。
   * 报价只按脚本指纹判断复用，任何脚本字节变化（例如"换一版这一镜素材"）都会让全部付费镜头
   * 重新计入报价，于是四个一分钱都不用花的镜头被算成 ¥17 并撞上次数上限，闸门要求改方案——
   * 而执行期其实全部按请求身份携带复用。这里把执行期的判据前移到报价，闸门才与事实一致。
   */
  private async forecastReusableAssetQuoteItemIds(
    input: Record<string, unknown>,
    context: WorkflowContext,
  ): Promise<ReadonlySet<string>> {
    const forecast = this.worker.forecastPaidAssetSpend;
    if (!forecast) return new Set();
    const request = forecast.call(this.worker, {
      input,
      parameters: { ...this.config.parameters, providerId: this.id },
      nodeDirectory: path.join(this.runsRoot, context.runId, "nodes", this.config.nodeId),
    });
    // 原生请求在报价前完成声音与模式校验，不能先吞错授权、执行时才拒绝。
    const result = await request.catch((error: unknown) => {
      if (error instanceof PaidAssetSafetyError || this.config.parameters.audioMode === "native_av") throw error;
      return undefined;
    });
    return new Set(result?.reusableQuoteItemIds ?? []);
  }

  async quoteSpend(input: Record<string, unknown>, context: WorkflowContext): Promise<SpendQuote> {
    if (this.capability === "asset.prepare" && this.assetOperationRecoveryId) {
      // 仅核对原任务，不为新输入报价；worker另校验原operation并硬禁create。
      return { estimatedCostCny: 0, maxCostCny: 0, requiresAuthorization: false };
    }
    await verifyExecutablePlanInput(input, context, this.runsRoot);
    if (this.config.capability === "voice.synthesize" && this.voiceManifestRecovery) {
      return { estimatedCostCny: 0, maxCostCny: 0, requiresAuthorization: false };
    }
    if (this.capability === "voice.synthesize" && typeof input.narrationPlanPath === "string") {
      const quote = await this.worker.forecastPaidVoiceSpend?.({ runId: context.runId,
        nodeDirectory: path.join(this.runsRoot, context.runId, "nodes", "voice"),
        input: { ...input, narrationPlan: JSON.parse(await readFile(input.narrationPlanPath, "utf8")) },
        parameters: { ...this.config.parameters, providerId: this.id, modelId: this.modelId } });
      if (quote) return { estimatedCostCny: quote.estimatedCostCny, maxCostCny: quote.maxCostCny,
        ...(quote.maxCostCny === 0 ? { requiresAuthorization: false } : {}) };
    }
    if (this.capability !== "asset.prepare") {
      return { estimatedCostCny: this.estimatedCostCny, maxCostCny: this.maxCostCny };
    }
    const modelSelections = stringRecord(this.config.parameters.modelSelections, "modelSelections");
    if (this.id === "ai-shot-router-v1") {
      const scriptPath = requiredOutputString(input, "scriptPath");
      const directorPlanPath = requiredOutputString(input, "directorPlanPath");
      const sceneDurations = await readScriptSceneDurations(scriptPath);
      const directorPlan = requireOutputRecord(JSON.parse(await readFile(directorPlanPath, "utf8")), "director plan");
      if (!Array.isArray(directorPlan.shots)) throw new Error("Director plan shots must be an array before quoting assets.");
      const quoteShots = directorPlan.shots.map((entry, index) => {
        const shot = requireOutputRecord(entry, `director plan shot ${index + 1}`);
        const scenePosition = Number(shot.scenePosition);
        if (!Number.isInteger(scenePosition) || scenePosition < 1) {
          throw new Error(`Director plan shot ${index + 1} has an invalid scene position.`);
        }
        const sourceInSeconds = shot.sourceInSeconds === undefined ? 0 : Number(shot.sourceInSeconds);
        const reuseFromScenePosition = typeof shot.reuseFromScenePosition === "number"
          ? shot.reuseFromScenePosition
          : undefined;
        return {
          shot,
          scenePosition,
          sourceInSeconds,
          ...(reuseFromScenePosition !== undefined ? { reuseFromScenePosition } : {}),
          query: typeof shot.query === "string" ? shot.query : "",
        };
      });
      const requiredDurationByRoot = requiredGeneratedAssetDurationSecondsByRoot(
        [...sceneDurations].map(([position, duration]) => ({ position, duration })),
        quoteShots,
      );
      // 原生是否复用必须由下方完整请求预测确认；同型号旧无声母片通过初筛不等于声音请求相同。
      const carriedScenePositions = new Set(this.config.parameters.audioMode === "native_av" ? [] : await inspectReworkCarriedAssetScenePositions({
        runsRoot: this.runsRoot,
        input,
        currentScript: requireOutputRecord(JSON.parse(await readFile(scriptPath, "utf8")), "script"),
        currentDirectorPlan: directorPlan,
        modelSelections,
      }));
      const excludedNotes = new Map<number, string>();
      const pricedItems: Array<{ scenePosition: number; item: NonNullable<SpendQuote["items"]>[number] }> = [];
      const items = quoteShots.flatMap(({ shot, scenePosition, reuseFromScenePosition }) => {
        const directorEstimatedCostCny = Number(shot.estimatedCostCny);
        if (!Number.isFinite(directorEstimatedCostCny) || directorEstimatedCostCny < 0) {
          throw new Error(`Director plan shot ${scenePosition} has an invalid server cost.`);
        }
        // 报价只列付费条目，因此"不花钱的镜头"必须在确认页上单独交代：否则操作员无法
        // 区分"这镜头免费"和"这镜头被漏算"，只能靠事后追问。
        const reuseSourceScenePosition = assetReuseSourceScenePosition({
          ...(reuseFromScenePosition !== undefined ? { reuseFromScenePosition } : {}),
          query: typeof shot.query === "string" ? shot.query : "",
        });
        const excludedNote = carriedScenePositions.has(scenePosition)
          ? "沿用返修前已生成的画面，不重复购买"
          : reuseSourceScenePosition !== undefined
            ? `复用镜头 ${reuseSourceScenePosition} 的画面，不重复购买`
            : directorEstimatedCostCny === 0 && this.config.parameters.audioMode !== "native_av"
              ? "免费素材，不需要购买"
              : undefined;
        if (excludedNote !== undefined) {
          excludedNotes.set(scenePosition, excludedNote);
          return [];
        }
        const providerId = requiredOutputString(shot, "preferredProviderId");
        const modelId = modelSelections[providerId];
        if (!modelId) throw new Error(`Paid asset provider '${providerId}' has no resolved model for quoting.`);
        const sceneDuration = sceneDurations.get(scenePosition);
        if (sceneDuration === undefined) {
          throw new Error(`Director plan shot ${scenePosition} has no matching script scene for quoting.`);
        }
        const requiredDuration = requiredDurationByRoot.get(scenePosition) ?? sceneDuration;
        const item = {
          id: `scene-${scenePosition}`,
          label: `镜头 ${scenePosition}`,
          providerId,
          modelId,
          estimatedCostCny: this.assetEstimatedCostCny(
            providerId,
            modelId,
            requiredDuration,
            directorEstimatedCostCny,
          ),
        };
        pricedItems.push({ scenePosition, item });
        return [item];
      });
      const reconciledItems = await this.incrementalAssetQuoteItems(
        items,
        [scriptPath, directorPlanPath],
        context,
        await this.forecastReusableAssetQuoteItemIds(input, context),
      );
      if (reconciledItems.reconciliationRequired) {
        return { estimatedCostCny: 0, maxCostCny: 0, requiresAuthorization: false };
      }
      for (const { scenePosition, item } of pricedItems) {
        if (!reconciledItems.items.some((candidate) => candidate.id === item.id)) {
          excludedNotes.set(scenePosition, "本 run 已有可用画面，不重复购买");
        }
      }
      if (reconciledItems.items.length === 0) {
        return { estimatedCostCny: 0, maxCostCny: 0, requiresAuthorization: false, ...excludedItemsField(excludedNotes) };
      }
      const estimatedCostCny = roundCurrency(reconciledItems.items.reduce((sum, item) => sum + item.estimatedCostCny, 0));
      return {
        estimatedCostCny,
        maxCostCny: roundCurrency(estimatedCostCny * this.maxAttempts),
        items: reconciledItems.items,
        ...excludedItemsField(excludedNotes),
      };
    }

    const scriptPath = requiredOutputString(input, "scriptPath");
    const sceneDurations = await readScriptSceneDurations(scriptPath);
    const script = requireOutputRecord(JSON.parse(await readFile(scriptPath, "utf8")), "script");
    if (!Array.isArray(script.scenes)) throw new Error("Script scenes must be an array before quoting assets.");
    const excludedNotes = new Map<number, string>();
    const pricedItems: Array<{ scenePosition: number; item: NonNullable<SpendQuote["items"]>[number] }> = [];
    const items = script.scenes.flatMap((entry, index) => {
      const scene = requireOutputRecord(entry, `script scene ${index + 1}`);
      const scenePosition = Number(scene.position);
      if (scene.visual_strategy === "local") {
        if (!Number.isInteger(scenePosition) || scenePosition < 1) throw new Error(`Script scene ${index + 1} has an invalid position.`);
        excludedNotes.set(scenePosition, "免费素材，不需要购买");
        return [];
      }
      if (!Number.isInteger(scenePosition) || scenePosition < 1) throw new Error(`Script scene ${index + 1} has an invalid position.`);
      const sceneDuration = sceneDurations.get(scenePosition);
      if (sceneDuration === undefined) throw new Error(`Script scene ${index + 1} has no valid duration.`);
      const item = {
        id: `scene-${scenePosition}`,
        label: `镜头 ${scenePosition}`,
        providerId: this.id,
        modelId: this.modelId,
        estimatedCostCny: this.assetEstimatedCostCny(
          this.id,
          this.modelId,
          sceneDuration,
          this.estimatedCostCny,
        ),
      };
      pricedItems.push({ scenePosition, item });
      return [item];
    });
    const reconciledItems = await this.incrementalAssetQuoteItems(items, [scriptPath], context);
    if (reconciledItems.reconciliationRequired) {
      return { estimatedCostCny: 0, maxCostCny: 0, requiresAuthorization: false };
    }
    for (const { scenePosition, item } of pricedItems) {
      if (!reconciledItems.items.some((candidate) => candidate.id === item.id)) {
        excludedNotes.set(scenePosition, "本 run 已有可用画面，不重复购买");
      }
    }
    if (reconciledItems.items.length === 0) {
      return { estimatedCostCny: 0, maxCostCny: 0, requiresAuthorization: false, ...excludedItemsField(excludedNotes) };
    }
    const estimatedCostCny = roundCurrency(reconciledItems.items.reduce((sum, item) => sum + item.estimatedCostCny, 0));
    return {
      estimatedCostCny,
      maxCostCny: roundCurrency(estimatedCostCny * this.maxAttempts),
      items: reconciledItems.items,
      ...excludedItemsField(excludedNotes),
    };
  }

  private async incrementalAssetQuoteItems(
    items: NonNullable<SpendQuote["items"]>,
    sourcePaths: string[],
    context: WorkflowContext,
    /**
     * 执行器按逐素材请求身份证明"本次不会新增花费"的素材键。它覆盖 sourceFingerprint 口径
     * 覆盖不到的情形：脚本因某一镜改动而换字节时，其余镜头的付费请求逐字未变、本就不该重买。
     */
    provenReusableItemIds: ReadonlySet<string> = new Set(),
  ): Promise<{ items: NonNullable<SpendQuote["items"]>; reconciliationRequired: boolean }> {
    const sourceFingerprint = await paidAssetSourceFingerprint(sourcePaths);
    const ledgerItems = paidAssetLedgerLeaves(await inspectPaidAssetLedger(
      path.join(this.runsRoot, context.runId, "nodes", this.config.nodeId),
    )).filter((item) => item.sourceFingerprint === sourceFingerprint);
    const reusableMaterializedItemIds = new Set((await Promise.all(ledgerItems.map(async (candidate) => (
      candidate.state === "materialized" && await materializedAssetFileMatchesLedger(candidate)
        ? candidate.itemRequestId
        : undefined
    )))).filter((itemRequestId): itemRequestId is string => itemRequestId !== undefined));
    const matches = (item: NonNullable<SpendQuote["items"]>[number]) => ledgerItems.filter((candidate) => (
      candidate.quoteItemId === item.id
      && candidate.providerId === item.providerId
      && candidate.modelId === item.modelId
    ));
    const reusableIds = new Set(items.filter((item) => (
      provenReusableItemIds.has(item.id)
      || matches(item).some((candidate) => (
        candidate.state === "materialized" && reusableMaterializedItemIds.has(candidate.itemRequestId)
        || candidate.state === "provider_succeeded" && Boolean(candidate.taskId) && Boolean(candidate.resultUrl)
      ))
    )).map((item) => item.id));
    const reconciliationRequired = items.some((item) => !reusableIds.has(item.id) && matches(item).some((candidate) => (
      candidate.state === "submitted"
      || candidate.state === "unknown"
      || candidate.state === "provider_succeeded"
    )));
    return {
      items: items.filter((item) => !reusableIds.has(item.id)),
      reconciliationRequired,
    };
  }

  private assetEstimatedCostCny(
    providerId: string,
    modelId: string,
    sceneDurationSeconds: number,
    fallbackEstimatedCostCny: number,
  ): number {
    const metadata = providerId === this.id
      ? this.config.metadata
      : this.config.assetRuntimeMetadata?.get(providerId);
    const profile = metadata?.modelProfiles?.find((candidate) => candidate.modelId === modelId);
    if (profile?.aspectRatios && !profile.aspectRatios.includes("9:16")) {
      throw new Error(`Video model '${modelId}' does not support the required 9:16 aspect ratio.`);
    }
    const estimatedCnyPerClip = profile?.estimatedCostCny ?? metadata?.estimatedCostCny ?? fallbackEstimatedCostCny;
    return estimateVideoGenerationCostCny(
      sceneDurationSeconds,
      estimatedCnyPerClip,
      videoPricingProfile(profile),
    );
  }

  async run(input: Record<string, unknown>, context: WorkflowContext): Promise<WorkerResponse> {
    if (this.assetOperationRecoveryId && context.operationRequestId !== this.assetOperationRecoveryId) {
      throw new PaidAssetSafetyError("Paid recovery does not match the original operation identity.");
    }
    if ((this.capability === "video.render" || this.capability === "audio.prepare_native")
      && parsePersistedBrief(context.initialInput).audioMode === "native_av"
      && (input.audioMode !== "native_av" || input.voiceoverPlanPath !== undefined || input.narrationPlanPath !== undefined)) {
      throw new Error("原生音画不能改用独立TTS或历史配音计划。");
    }
    await verifyExecutablePlanInput(input, context, this.runsRoot);
    if (this.capability === "audio.prepare_native" || this.capability === "video.render" && input.audioMode === "native_av") {
      input = await bindNativeAudioInputs(input, context, this.runsRoot);
    }
    if (this.config.capability === "asset.prepare") {
      // 复用描述只能由已登记产物派生，不能接受客户端伪造的路径或 SHA。
      const { reusableStockAssets: _untrusted, ...assetInput } = input;
      input = assetInput;
      if (input.reuseAssetPlanArtifactId !== undefined) {
        input = { ...input, reusableStockAssets: await verifiedReusableStockAssets(input.reuseAssetPlanArtifactId, context, this.runsRoot) };
      }
    }
    if (this.config.capability === "voice.synthesize" && this.voiceManifestRecovery) {
      input = {
        ...input,
        rebuild_manifest: true,
        sourceOperationId: this.voiceManifestRecovery.sourceOperationId,
        ...(this.voiceManifestRecovery.manifestPath
          ? { manifestPath: this.voiceManifestRecovery.manifestPath }
          : {}),
      };
    }
    const attempt = await reserveAttemptDirectory(path.join(this.runsRoot, context.runId, "nodes", this.config.nodeId));
    const outputDir = attempt.directory;
    const parameters: Record<string, unknown> = { ...this.config.parameters, providerId: this.config.id };
    if (this.capability === "audio.prepare_native" || this.capability === "video.render" && input.audioMode === "native_av") {
      parameters.mediaRoot = path.join(this.runsRoot, context.runId);
    }
    if (this.config.capability === "asset.prepare") {
      const acceptedEvidenceIds = [...new Set(context.decisions
        .filter((decision) => decision.action === "approve")
        .map((decision) => decision.reviewEvidenceId)
        .filter((evidenceId): evidenceId is string => typeof evidenceId === "string" && /^[a-f0-9]{64}$/i.test(evidenceId)))];
      if (acceptedEvidenceIds.length) parameters.acceptedSourceReviewEvidenceIds = acceptedEvidenceIds;
    }
    if (this.billing === "metered") {
      const authorization = context.spendAuthorization;
      const noSpendExecution = context.spendAuthorizationExemptProviderId === this.id;
      if (!authorization && noSpendExecution) {
        const quote = await this.quoteSpend(input, context);
        if (quote.requiresAuthorization !== false) {
          throw new Error(`Metered provider '${this.id}' no-spend execution no longer matches its current quote.`);
        }
        parameters.maxCostCny = 0;
        parameters.maxAttempts = 0;
        parameters.estimatedCostCny = 0;
      } else if (!authorization && this.approvalPolicy === "automatic") {
        parameters.maxCostCny = this.maxCostCny;
        parameters.maxAttempts = this.maxAttempts;
        parameters.estimatedCostCny = this.estimatedCostCny;
      } else if (!authorization || authorization.providerId !== this.id || authorization.modelId !== this.modelId) {
        throw new Error(`Metered provider '${this.id}' has no matching active authorization.`);
      } else {
        parameters.maxCostCny = authorization.maxCostCny;
        parameters.maxAttempts = authorization.maxAttempts;
        parameters.estimatedCostCny = this.estimatedCostCny;
        // C1：scope 派生的逐素材 create 预算随子凭证下发；worker 在每个 create 边界执行，
        // 超预算的 create 在越过付费边界前 fail closed（停在可操作状态，不静默降级）。
        if (authorization.itemCreateBudgets) {
          parameters.itemCreateBudgets = { ...authorization.itemCreateBudgets };
        }
      }
    }
    if (this.config.capability === "voice.synthesize" && typeof input.narrationPlanPath === "string") {
      // §4.2.3：来源身份优先取自 input version 固化的 value（不可变、不按 plan SHA 覆盖）；
      // 旧版本没有内嵌身份时回退读取采用时写的 sidecar；两者都没有则由 worker 如实降级处理。
      if (typeof input.voiceInputVersionId === "string") {
        input = { ...input, voiceInputIdentity: {
          voiceInputVersionId: input.voiceInputVersionId,
          ...(typeof input.sourceContextId === "string" ? { sourceContextId: input.sourceContextId } : {}),
          ...(typeof input.scriptArtifactId === "string" ? { scriptArtifactId: input.scriptArtifactId } : {}),
          ...(typeof input.scriptOutputVersionId === "string" ? { scriptOutputVersionId: input.scriptOutputVersionId } : {}),
          ...(typeof input.visualArtifactId === "string" ? { visualArtifactId: input.visualArtifactId } : {}),
          ...(typeof input.visualOutputVersionId === "string" ? { visualOutputVersionId: input.visualOutputVersionId } : {}),
          ...(Array.isArray(input.parentArtifactIds) ? { parentArtifactIds: input.parentArtifactIds } : {}),
          ...(Array.isArray(input.upstreamVersionIds) ? { upstreamVersionIds: input.upstreamVersionIds } : {}),
        } };
      } else {
        try {
          const planPath = path.resolve(String(input.narrationPlanPath));
          const sidecar = JSON.parse(await readFile(`${planPath.slice(0, -".json".length)}.input.json`, "utf8")) as Record<string, unknown>;
          if (isObjectRecord(sidecar) && typeof sidecar.voiceInputVersionId === "string") {
            input = { ...input, voiceInputIdentity: {
              voiceInputVersionId: sidecar.voiceInputVersionId,
              ...(typeof sidecar.sourceContextId === "string" ? { sourceContextId: sidecar.sourceContextId } : {}),
              ...(typeof sidecar.scriptArtifactId === "string" ? { scriptArtifactId: sidecar.scriptArtifactId } : {}),
              ...(typeof sidecar.scriptOutputVersionId === "string" ? { scriptOutputVersionId: sidecar.scriptOutputVersionId } : {}),
              ...(typeof sidecar.visualArtifactId === "string" ? { visualArtifactId: sidecar.visualArtifactId } : {}),
              ...(typeof sidecar.visualOutputVersionId === "string" ? { visualOutputVersionId: sidecar.visualOutputVersionId } : {}),
              ...(Array.isArray(sidecar.parentArtifactIds) ? { parentArtifactIds: sidecar.parentArtifactIds } : {}),
              ...(Array.isArray(sidecar.upstreamVersionIds) ? { upstreamVersionIds: sidecar.upstreamVersionIds } : {}),
            } };
          }
        } catch (error) {
          if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
        }
      }
    }
    const response = await this.worker.run({
      protocolVersion: WORKER_PROTOCOL_VERSION,
      commandId: context.operationRequestId ?? context.nextId("command"),
      runId: context.runId,
      nodeRunId: this.config.nodeId,
      attempt: attempt.attempt,
      capability: this.config.capability,
      input,
      parameters,
      outputDir,
    }, this.withSourceRunSnapshot ? { withSourceRunSnapshot: this.withSourceRunSnapshot,
      ...(this.assetOperationRecoveryId ? { recoverOperationId: this.assetOperationRecoveryId } : {}),
    } : undefined);
    await verifyWorkerArtifacts(response, outputDir);
    if (this.config.capability === "asset.search") {
      await verifyWorkerPrivateOutputPath(response.output?.candidateInventoryPath, outputDir);
    }
    return response;
  }
}

async function materializedAssetFileMatchesLedger(item: PaidAssetLedgerItemSummary): Promise<boolean> {
  const sizeBytes = item.sizeBytes;
  if (!item.localPath
    || !item.sha256
    || !/^[a-f0-9]{64}$/i.test(item.sha256)
    || typeof sizeBytes !== "number"
    || !Number.isInteger(sizeBytes)
    || sizeBytes <= 0) {
    return false;
  }
  try {
    await verifyArtifactBytes(item.localPath, item.sha256, sizeBytes);
    return true;
  } catch {
    return false;
  }
}

async function readScriptSceneDurations(scriptPath: string): Promise<Map<number, number>> {
  const script = requireOutputRecord(JSON.parse(await readFile(scriptPath, "utf8")), "script");
  if (!Array.isArray(script.scenes)) throw new Error("Script scenes must be an array before quoting assets.");
  const durations = new Map<number, number>();
  for (const [index, entry] of script.scenes.entries()) {
    const scene = requireOutputRecord(entry, `script scene ${index + 1}`);
    const position = Number(scene.position);
    const duration = Number(scene.duration);
    if (!Number.isInteger(position) || position < 1 || durations.has(position)) {
      throw new Error(`Script scene ${index + 1} has an invalid or duplicate position.`);
    }
    if (!Number.isFinite(duration) || duration <= 0) {
      throw new Error(`Script scene ${index + 1} has an invalid duration.`);
    }
    durations.set(position, duration);
  }
  return durations;
}

function videoPricingProfile(
  profile: ProductionProviderModelRuntimeMetadata | undefined,
): VideoGenerationRuntimeProfile | undefined {
  if (!profile
    || !profile.taskTypes
    || !profile.resolutions
    || profile.minDurationSeconds === undefined
    || profile.maxDurationSeconds === undefined
    || profile.supportsAudio === undefined) {
    return undefined;
  }
  return {
    taskTypes: [...profile.taskTypes],
    resolutions: [...profile.resolutions],
    ...(profile.aspectRatios ? { aspectRatios: [...profile.aspectRatios] } : {}),
    minDurationSeconds: profile.minDurationSeconds,
    maxDurationSeconds: profile.maxDurationSeconds,
    supportsAudio: profile.supportsAudio,
    ...(profile.allowedDurationsSeconds
      ? { allowedDurationsSeconds: [...profile.allowedDurationsSeconds] }
      : {}),
    ...(profile.estimatedCnyPerSecond !== undefined
      ? { estimatedCnyPerSecond: profile.estimatedCnyPerSecond }
      : {}),
    ...(profile.estimatedCnyPerSecondByResolution
      ? { estimatedCnyPerSecondByResolution: { ...profile.estimatedCnyPerSecondByResolution } }
      : {}),
    ...(profile.estimatedCnyByResolutionAndDuration
      ? { estimatedCnyByResolutionAndDuration: structuredClone(profile.estimatedCnyByResolutionAndDuration) }
      : {}),
  };
}

// 回执里的 promptPack 是"这份输出由哪版合同产生"的证据。它必须与 codex-broker 中
// visual-review 任务定义的 version 一致（apps/codex-broker/src/task-definitions.ts）；
// 两个 workspace 之间没有依赖，只能靠这处常量对齐，改 broker 合同时必须同步这里。
const VISUAL_REVIEW_PROMPT_PACK = "video-factory/visual-review-v20";

class VisualDirectorProvider implements Provider<VisualDirectorAgentInput, CodexTaskExecution<unknown>> {
  readonly capability: Capability = "storyboard.plan";
  readonly label = "Codex 视觉导演";
  readonly transport = "unix_socket" as const;
  readonly billing = "subscription" as const;
  readonly parameters = { promptPack: "video-factory/director-v29" };

  constructor(
    private readonly agent: VisualDirectorAgent,
    private readonly selectedModelId: string | undefined,
    readonly configurationSource: ExecutionConfigurationSource,
  ) {}

  get id(): string {
    return this.agent.id;
  }

  get modelId(): string {
    return this.selectedModelId ?? this.agent.modelId ?? "codex-default";
  }

  async run(input: VisualDirectorAgentInput): Promise<CodexTaskExecution<unknown>> {
    const { selectedModelId: _staleSelectedModelId, ...currentInput } = input;
    const configuredInput = {
      ...currentInput,
      ...(this.selectedModelId ? { selectedModelId: this.selectedModelId } : {}),
    };
    return this.agent.planDetailed
      ? this.agent.planDetailed(configuredInput)
      : { output: await this.agent.plan(configuredInput) };
  }
}

